// Generated from the pinned official warehouse; preserve source attribution.
export default {"GDOUYJ_02":"/**\n * 广东海洋大学阳江校区教务适配（备用通道）\n * @date 2026-9-12\n * @author Yihe-ng，海大百事通\n * @version 1.0\n *\n * 教务系统不可用时的备用通道：数据取自教学质量综合评价系统（jxpj.gdou.edu.cn），\n * 校内外均可直连，无需 VPN 或校园网。\n * 该系统课表与教务同源同步，字段含周次、星期、节次、教室，可直接生成课表。\n * 该方法由海大百事通与20260912发现\n *\n * 接口链路（均为同源请求，复用页面登录态）：\n *   POST /apiservice/University/GetAllSemester          学期列表\n *   POST /mita/prepare/timetable/setting                学期设置（总周数、当前周、当前周周一）\n *   POST /mita/online/message/student/course/list        学生课程列表（含教师工号）\n *   POST /mita/prepare/timetable/timetables              按教师查询全学期排课\n *\n * 两处报文字段沿用服务端约定（非笔误）：学期参数名为 semeter；请求体需加密并追加固定后缀。\n */\n\n(function () {\n\n// ==================== 常量 ====================\n\nconst AES_KEY = \"nfZYwnW2ppQc3CXr\";\nconst AES_SUFFIX = \"d^PrEK&c\";\n\nconst API_SEMESTER_LIST = \"/apiservice/University/GetAllSemester\";\nconst API_TIMETABLE_SETTING = \"/prepare/timetable/setting\";\nconst API_COURSE_LIST = \"/online/message/student/course/list\";\nconst API_TIMETABLE = \"/prepare/timetable/timetables\";\n\nconst DEFAULT_TOTAL_WEEKS = 20;\n\n// 单次请求超时。若服务端不响应，fetch 会一直挂起，流程既无法失败也无法返回。\nconst REQUEST_TIMEOUT_MS = 20000;\n\n// 阳江校区慎思楼上课时间\nconst TimeSlots = [\n    { number: 1, startTime: \"08:10\", endTime: \"08:55\" },\n    { number: 2, startTime: \"09:05\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:05\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:20\", endTime: \"16:05\" },\n    { number: 7, startTime: \"16:20\", endTime: \"17:05\" },\n    { number: 8, startTime: \"17:10\", endTime: \"17:55\" },\n    { number: 9, startTime: \"19:30\", endTime: \"20:15\" },\n    { number: 10, startTime: \"20:25\", endTime: \"21:10\" }\n];\n\n/**\n * 阳江校区其他场地（非慎思楼）的作息。\n * 只有第 3、4 节在校区作息表中是不同的连续时间块，使用自定义时间表示。\n * 貌似无法动态获取时间\n */\nconst OTHER_VENUE_SECTION_3_4_TIME = { startTime: \"10:10\", endTime: \"11:40\" };\n\n// ==================== AES-128-ECB 加密 ====================\n\nfunction utf8Bytes(text) {\n    const bytes = [];\n    for (let i = 0; i < text.length; i++) {\n        let code = text.charCodeAt(i);\n        if (code < 0x80) {\n            bytes.push(code);\n        } else if (code < 0x800) {\n            bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));\n        } else {\n            bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));\n        }\n    }\n    return bytes;\n}\n\nfunction gfMultiply(a, b) {\n    let product = 0;\n    for (let i = 0; i < 8; i++) {\n        if (b & 1) product ^= a;\n        const highBit = a & 0x80;\n        a = (a << 1) & 0xff;\n        if (highBit) a ^= 0x1b;\n        b >>= 1;\n    }\n    return product & 0xff;\n}\n\nfunction gfPower(base, exponent) {\n    let result = 1;\n    while (exponent > 0) {\n        if (exponent & 1) result = gfMultiply(result, base);\n        base = gfMultiply(base, base);\n        exponent >>= 1;\n    }\n    return result;\n}\n\nconst S_BOX = (function () {\n    const box = new Array(256);\n    for (let i = 0; i < 256; i++) {\n        const inverse = i === 0 ? 0 : gfPower(i, 254);\n        let value = 0;\n        for (let bit = 0; bit < 8; bit++) {\n            const b = ((inverse >> bit) & 1)\n                ^ ((inverse >> ((bit + 4) % 8)) & 1)\n                ^ ((inverse >> ((bit + 5) % 8)) & 1)\n                ^ ((inverse >> ((bit + 6) % 8)) & 1)\n                ^ ((inverse >> ((bit + 7) % 8)) & 1)\n                ^ ((0x63 >> bit) & 1);\n            value |= b << bit;\n        }\n        box[i] = value & 0xff;\n    }\n    return box;\n})();\n\nfunction expandKey(keyBytes) {\n    const words = [];\n    for (let i = 0; i < 4; i++) {\n        words[i] = ((keyBytes[4 * i] << 24) | (keyBytes[4 * i + 1] << 16)\n            | (keyBytes[4 * i + 2] << 8) | keyBytes[4 * i + 3]) >>> 0;\n    }\n    let roundConstant = 1;\n    for (let i = 4; i < 44; i++) {\n        let temp = words[i - 1];\n        if (i % 4 === 0) {\n            temp = ((temp << 8) | (temp >>> 24)) >>> 0;\n            temp = ((S_BOX[(temp >>> 24) & 0xff] << 24)\n                | (S_BOX[(temp >>> 16) & 0xff] << 16)\n                | (S_BOX[(temp >>> 8) & 0xff] << 8)\n                | S_BOX[temp & 0xff]) >>> 0;\n            temp = (temp ^ (roundConstant << 24)) >>> 0;\n            roundConstant = gfMultiply(roundConstant, 2);\n        }\n        words[i] = (words[i - 4] ^ temp) >>> 0;\n    }\n    return words;\n}\n\nfunction addRoundKey(state, words, round) {\n    for (let column = 0; column < 4; column++) {\n        const word = words[4 * round + column];\n        state[4 * column] ^= (word >>> 24) & 0xff;\n        state[4 * column + 1] ^= (word >>> 16) & 0xff;\n        state[4 * column + 2] ^= (word >>> 8) & 0xff;\n        state[4 * column + 3] ^= word & 0xff;\n    }\n}\n\nfunction subBytes(state) {\n    for (let i = 0; i < 16; i++) state[i] = S_BOX[state[i]];\n}\n\nfunction shiftRows(state) {\n    let temp = state[1];\n    state[1] = state[5]; state[5] = state[9]; state[9] = state[13]; state[13] = temp;\n    temp = state[2]; state[2] = state[10]; state[10] = temp;\n    temp = state[6]; state[6] = state[14]; state[14] = temp;\n    temp = state[15]; state[15] = state[11]; state[11] = state[7]; state[7] = state[3]; state[3] = temp;\n}\n\nfunction mixColumns(state) {\n    for (let column = 0; column < 4; column++) {\n        const i = 4 * column;\n        const a0 = state[i], a1 = state[i + 1], a2 = state[i + 2], a3 = state[i + 3];\n        const all = a0 ^ a1 ^ a2 ^ a3;\n        state[i] = a0 ^ all ^ gfMultiply(a0 ^ a1, 2);\n        state[i + 1] = a1 ^ all ^ gfMultiply(a1 ^ a2, 2);\n        state[i + 2] = a2 ^ all ^ gfMultiply(a2 ^ a3, 2);\n        state[i + 3] = a3 ^ all ^ gfMultiply(a3 ^ a0, 2);\n    }\n}\n\nfunction encryptBlock(words, input) {\n    const state = input.slice();\n    addRoundKey(state, words, 0);\n    for (let round = 1; round <= 9; round++) {\n        subBytes(state);\n        shiftRows(state);\n        mixColumns(state);\n        addRoundKey(state, words, round);\n    }\n    subBytes(state);\n    shiftRows(state);\n    addRoundKey(state, words, 10);\n    return state;\n}\n\nconst BASE64_CHARS = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\";\n\nfunction bytesToBase64(bytes) {\n    let output = \"\";\n    for (let i = 0; i < bytes.length; i += 3) {\n        const b0 = bytes[i];\n        const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;\n        const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;\n        output += BASE64_CHARS[b0 >> 2];\n        output += BASE64_CHARS[((b0 & 0x03) << 4) | (b1 >> 4)];\n        output += i + 1 < bytes.length ? BASE64_CHARS[((b1 & 0x0f) << 2) | (b2 >> 6)] : \"=\";\n        output += i + 2 < bytes.length ? BASE64_CHARS[b2 & 0x3f] : \"=\";\n    }\n    return output;\n}\n\nfunction encryptPayload(plainText) {\n    const key = utf8Bytes(AES_KEY);\n    const data = utf8Bytes(plainText + AES_SUFFIX);\n\n    const padLength = 16 - (data.length % 16);\n    for (let i = 0; i < padLength; i++) data.push(padLength);\n\n    const words = expandKey(key);\n    const output = [];\n    for (let offset = 0; offset < data.length; offset += 16) {\n        const block = encryptBlock(words, data.slice(offset, offset + 16));\n        for (let i = 0; i < 16; i++) output.push(block[i]);\n    }\n    return bytesToBase64(output);\n}\n\n// ==================== 会话与请求 ====================\n\nfunction readStorageJson(storage, key) {\n    try {\n        return JSON.parse(storage.getItem(key) || \"null\");\n    } catch (error) {\n        return null;\n    }\n}\n\n/**\n * 读取登录用户信息。\n * 该系统的桌面端将 current-user 存于 localStorage，微信/移动端存于 sessionStorage，\n * 应用中打开的是移动端，故两处都必须尝试。\n */\nfunction readCurrentUser() {\n    return readStorageJson(sessionStorage, \"current-user\")\n        || readStorageJson(localStorage, \"current-user\");\n}\n\nfunction readClientId() {\n    const visitor = readStorageJson(localStorage, \"visitorObj\");\n    return visitor && visitor.ClientId ? visitor.ClientId : \"\";\n}\n\nfunction readCachedSemester() {\n    const cached = readStorageJson(sessionStorage, \"semester\")\n        || readStorageJson(localStorage, \"semester\");\n    return cached && cached.key ? String(cached.key) : \"\";\n}\n\n/**\n * 解析用户标识。移动端以 realCode 作为实际账号，桌面端仅提供 Code，故需回退。\n */\nfunction resolveUserCode(user) {\n    return String((user && (user.realCode || user.Code)) || \"\");\n}\n\nfunction formatNow() {\n    const date = new Date();\n    const pad = (value) => String(value).padStart(2, \"0\");\n    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} `\n        + `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;\n}\n\nfunction buildSystemParams(user, clientId, apiName, semester) {\n    return {\n        DegreeLevel: 0,\n        Token: user.Token,\n        UserCode: resolveUserCode(user),\n        UniversityCode: user.UniversityCode,\n        ApiName: apiName,\n        ClientTime: formatNow(),\n        ClientId: clientId,\n        ClientType: 0,\n        Semester: semester,\n        RequestOriginPageAddress: window.location.href\n    };\n}\n\n/**\n * 带超时的 fetch。旧版 WebView 可能没有 AbortController，此时退化为普通请求。\n */\nasync function fetchWithTimeout(url, options) {\n    if (typeof AbortController === \"undefined\") {\n        return await fetch(url, options);\n    }\n\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);\n    try {\n        return await fetch(url, Object.assign({}, options, { signal: controller.signal }));\n    } finally {\n        clearTimeout(timer);\n    }\n}\n\nasync function postApi(user, clientId, path, apiName, semester, requestParams) {\n    const payload = {\n        SystemParams: buildSystemParams(user, clientId, apiName, semester),\n        RequestParams: requestParams || {}\n    };\n\n    const response = await fetchWithTimeout(path, {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/json; charset=utf-8\",\n            \"Accept\": \"application/json\",\n            \"token\": user.Token\n        },\n        body: encryptPayload(JSON.stringify(payload)),\n        credentials: \"include\"\n    });\n\n    if (!response.ok) {\n        throw new Error(`HTTP ${response.status}`);\n    }\n    return await response.json();\n}\n\nasync function postMita(user, clientId, path, semester, params) {\n    const userCode = resolveUserCode(user);\n    const merged = Object.assign(\n        {\n            teacherCode: userCode,\n            teacherName: user.Name,\n            semeter: semester,\n            schoolCode: user.UniversityCode,\n            currentUser: userCode,\n            Token: user.Token,\n            ClientId: clientId\n        },\n        params || {},\n        { RequestOriginPageAddress: window.location.href }\n    );\n\n    const response = await fetchWithTimeout(\"/mita\" + path, {\n        method: \"POST\",\n        headers: {\n            \"Content-Type\": \"application/json\",\n            \"token\": user.Token\n        },\n        body: encryptPayload(JSON.stringify(merged)),\n        credentials: \"include\"\n    });\n\n    if (!response.ok) {\n        throw new Error(`HTTP ${response.status}`);\n    }\n    return await response.json();\n}\n\n// ==================== 数据转换 ====================\n\nfunction padTwo(value) {\n    return String(value).padStart(2, \"0\");\n}\n\n/**\n * 由「当前周」与「当前周周一日期」反推学期第一周的周一日期。\n * 服务端返回的 firstOfWeek 是当前周的周一，需按已过周数向前回退。\n */\nfunction deriveSemesterStartDate(firstOfWeek, currentWeek) {\n    const text = String(firstOfWeek || \"\").trim();\n    const matched = text.match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})/);\n    if (!matched) return null;\n\n    const week = Number(currentWeek);\n    const offsetDays = Number.isInteger(week) && week > 0 ? (week - 1) * 7 : 0;\n\n    const date = new Date(Date.UTC(Number(matched[1]), Number(matched[2]) - 1, Number(matched[3])));\n    if (isNaN(date.getTime())) return null;\n    date.setUTCDate(date.getUTCDate() - offsetDays);\n\n    return `${date.getUTCFullYear()}-${padTwo(date.getUTCMonth() + 1)}-${padTwo(date.getUTCDate())}`;\n}\n\nfunction getOtherVenueCustomTime(position, startSection, endSection) {\n    const positionText = position == null ? \"\" : String(position);\n    if (!positionText || positionText.includes(\"慎思楼\")) return null;\n    if (startSection !== 3 || endSection !== 4) return null;\n    return OTHER_VENUE_SECTION_3_4_TIME;\n}\n\nfunction normalizeWeek(value) {\n    const week = Number(value);\n    return Number.isInteger(week) && week > 0 ? week : null;\n}\n\nfunction normalizeSection(value) {\n    const section = Number(value);\n    return Number.isInteger(section) && section >= 1 ? section : null;\n}\n\nfunction splitClassNames(value) {\n    return String(value == null ? \"\" : value)\n        .split(/[,，]/)\n        .map((item) => item.trim())\n        .filter(Boolean);\n}\n\n/**\n * 从教师排课记录中筛选属于该学生的课程。\n * 评价系统的 classCode 与排课系统可能不同源，故先按 classCode 精确匹配，\n * 未命中时退回按班级名称匹配。\n */\nfunction pickStudentEntries(entries, course) {\n    const sameCourse = entries.filter((entry) => entry.courseCode === course.courseCode);\n    if (sameCourse.length === 0) return [];\n\n    const byClassCode = sameCourse.filter((entry) => entry.classCode === course.classCode);\n    if (byClassCode.length > 0) return byClassCode;\n\n    const classNames = splitClassNames(course.className);\n    if (classNames.length === 0) return [];\n\n    return sameCourse.filter((entry) => (entry.reTimetableClasses || []).some((item) =>\n        splitClassNames(item.className).some((name) => classNames.indexOf(name) !== -1)\n    ));\n}\n\nfunction toCourseKey(course) {\n    return [course.name, course.teacher, course.position, course.day,\n        course.startSection, course.endSection].join(\"\\u0001\");\n}\n\n/**\n * 节次与周次合并去重。\n * 取自官方 wiki《课程合并与去重函数》的参考实现，未作改动；\n * 用于把服务端可能返回的「逐节」或「分段周次」记录归一为连续区间。\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    list.sort((a, b) =>\n        a.name.localeCompare(b.name) ||\n        a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) ||\n        (a.day || 0) - (b.day || 0) ||\n        a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n        (a.startSection || 0) - (b.startSection || 0)\n    );\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    step1Merged.sort((a, b) =>\n        a.name.localeCompare(b.name) ||\n        a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) ||\n        (a.day || 0) - (b.day || 0) ||\n        (a.startSection || 0) - (b.startSection || 0) ||\n        (a.endSection || 0) - (b.endSection || 0)\n    );\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 为其他场地第 3-4 节补充自定义时间。\n * 必须在合并之后调用：只有先合并成完整的 3-4 节，才满足自定义时间的匹配条件。\n */\nfunction applyOtherVenueCustomTime(course) {\n    const customTime = getOtherVenueCustomTime(\n        course.position,\n        course.startSection,\n        course.endSection\n    );\n    if (!customTime) return course;\n\n    return Object.assign({}, course, {\n        isCustomTime: true,\n        customStartTime: customTime.startTime,\n        customEndTime: customTime.endTime\n    });\n}\n\nfunction aggregateCourses(entries, course) {\n    const merged = new Map();\n\n    entries.forEach((entry) => {\n        const week = normalizeWeek(entry.onweek);\n        const startSection = normalizeSection(entry.seqStart);\n        const endSection = normalizeSection(entry.seqEnd);\n        const day = normalizeSection(entry.dayOfWeek);\n\n        if (week === null || startSection === null || endSection === null || day === null) return;\n        if (day < 1 || day > 7 || endSection < startSection) return;\n\n        const position = entry.address == null ? \"\" : String(entry.address).trim();\n        const item = {\n            name: String(entry.courseName || course.courseName || \"\").trim(),\n            teacher: String(entry.teacherName || course.teacherName || \"\").trim(),\n            position: position,\n            day: day,\n            startSection: startSection,\n            endSection: endSection\n        };\n\n        const key = toCourseKey(item);\n        if (!merged.has(key)) {\n            merged.set(key, Object.assign({}, item, { weeks: [] }));\n        }\n\n        const target = merged.get(key);\n        if (target.weeks.indexOf(week) === -1) target.weeks.push(week);\n    });\n\n    return mergeAndDistinctCourses(Array.from(merged.values()))\n        .map(applyOtherVenueCustomTime);\n}\n\nfunction sortCourses(courses) {\n    return courses.sort((a, b) =>\n        a.day - b.day\n        || a.startSection - b.startSection\n        || a.name.localeCompare(b.name, \"zh-Hans-CN\")\n    );\n}\n\n// ==================== 数据获取 ====================\n\nfunction describeError(error) {\n    return error && error.message ? error.message : String(error);\n}\n\nasync function fetchSemesters(user, clientId) {\n    const data = await postApi(user, clientId, API_SEMESTER_LIST,\n        \"University/GetAllSemester\", user.CurrentSemester, {});\n\n    if (!data || data.Success !== true || !Array.isArray(data.Value)) return [];\n\n    return data.Value\n        .map((item) => ({\n            key: String(item.key || \"\").trim(),\n            name: String(item.name || item.key || \"\").trim(),\n            selected: item.selected === true\n        }))\n        .filter((item) => item.key);\n}\n\nasync function fetchSemesterSetting(user, clientId, semester) {\n    try {\n        const data = await postMita(user, clientId, API_TIMETABLE_SETTING, semester, {});\n        if (!data || data.success !== true || !data.result) return null;\n\n        return {\n            currentWeek: Number(data.result.currentWeek) || null,\n            firstOfWeek: data.result.firstOfWeek || null\n        };\n    } catch (error) {\n        console.warn(\"JS: 读取学期设置失败:\", error);\n        return null;\n    }\n}\n\nasync function fetchCourseList(user, clientId, semester) {\n    const data = await postMita(user, clientId, API_COURSE_LIST, semester, {\n        pageNum: \"1\",\n        pageSize: \"999\",\n        studentCode: resolveUserCode(user),\n        isAdmin: \"0\"\n    });\n\n    if (!data || data.success !== true || !data.result) return [];\n    return Array.isArray(data.result.result) ? data.result.result : [];\n}\n\nasync function fetchTeacherTimetable(user, clientId, semester, teacherCode) {\n    const data = await postMita(user, clientId, API_TIMETABLE, semester, {\n        onweek: null,\n        teacherCode: teacherCode\n    });\n\n    if (!data || data.success !== true) return [];\n    return Array.isArray(data.result) ? data.result : [];\n}\n\nasync function collectCourses(user, clientId, semester) {\n    const courseList = await fetchCourseList(user, clientId, semester);\n    if (courseList.length === 0) return null;\n\n    const byTeacher = new Map();\n    courseList.forEach((course) => {\n        const teacherCode = String(course.teacherCode || \"\").trim();\n        if (!teacherCode) return;\n        if (!byTeacher.has(teacherCode)) byTeacher.set(teacherCode, []);\n        byTeacher.get(teacherCode).push(course);\n    });\n\n    const teacherCodes = Array.from(byTeacher.keys());\n    const timetables = await Promise.all(teacherCodes.map((teacherCode) =>\n        fetchTeacherTimetable(user, clientId, semester, teacherCode)\n            .catch((error) => {\n                console.warn(`JS: 读取教师 ${teacherCode} 排课失败:`, error);\n                return [];\n            })\n    ));\n\n    const courses = [];\n    teacherCodes.forEach((teacherCode, index) => {\n        const entries = timetables[index];\n        if (!entries.length) return;\n\n        byTeacher.get(teacherCode).forEach((course) => {\n            const picked = pickStudentEntries(entries, course);\n            if (picked.length === 0) return;\n            courses.push.apply(courses, aggregateCourses(picked, course));\n        });\n    });\n\n    return sortCourses(courses);\n}\n\n// ==================== 用户交互 ====================\n\nfunction showToast(message) {\n    window.shiguangBridge.showToast(message);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"广东海洋大学阳江校区课表导入（备用通道）\",\n        \"本适配器通过接口直接获取课表，无需停留在课表页面。\\n\\n\"\n        + \"导入步骤：\\n\"\n        + \"1. 确认已登录教学质量综合评价系统（未登录请先完成统一认证）\\n\"\n        + \"2. 停留在任意页面即可，无需切换\\n\"\n        + \"3. 点击「执行导入」\\n\\n\"\n        + \"说明：数据取自教学评价系统，部分课程可能缺失，可手动补录。\",\n        \"我已登录，开始导入\"\n    );\n}\n\nasync function promptUserToLogin() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"需要先登录\",\n        \"未检测到登录状态，请先在本页面完成登录：\\n\\n\"\n        + \"1. 页面若显示登录框，输入账号密码登录\\n\"\n        + \"2. 若已登录但提示本消息，请稍候几秒后重新点击「执行导入」\\n\\n\"\n        + \"登录成功后无需切换页面，直接点击「执行导入」即可。\",\n        \"我知道了\"\n    );\n}\n\nasync function selectSemester(user, clientId) {\n    let semesters = [];\n    try {\n        semesters = await fetchSemesters(user, clientId);\n    } catch (error) {\n        console.warn(\"JS: 读取学期列表失败:\", error);\n    }\n\n    const fallback = String(user.CurrentSemester || \"\").trim() || readCachedSemester();\n    if (semesters.length === 0) {\n        if (!fallback) return null;\n        return { key: fallback, name: fallback };\n    }\n\n    const labels = semesters.map((item) => item.name);\n    let defaultIndex = semesters.findIndex((item) => item.selected);\n    if (defaultIndex === -1) defaultIndex = semesters.findIndex((item) => item.key === fallback);\n    if (defaultIndex === -1) defaultIndex = 0;\n\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(labels),\n        defaultIndex\n    );\n\n    if (selectedIndex === null || selectedIndex === -1 || !semesters[selectedIndex]) return null;\n    return semesters[selectedIndex];\n}\n\nasync function saveCourseConfig(config) {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        return true;\n    } catch (error) {\n        showToast(`课表配置保存失败: ${describeError(error)}`);\n        return false;\n    }\n}\n\nasync function saveCourses(courses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        return true;\n    } catch (error) {\n        showToast(`课程保存失败: ${describeError(error)}`);\n        return false;\n    }\n}\n\nasync function importPresetTimeSlots() {\n    if (TimeSlots.length === 0) return;\n\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TimeSlots));\n    } catch (error) {\n        console.warn(\"JS: 预设时间段导入失败:\", error);\n        showToast(\"预设时间段导入失败，可稍后手动设置。\");\n    }\n}\n\n// ==================== 流程编排 ====================\n\n/**\n * 识别是否停留在统一认证相关页面。\n * 学校统一认证存在缺陷：认证完成后偶发不回跳到本应用，而落到统一认证自身的页面，\n * 此时登录其实已成功，但本应用读不到登录态，需引导用户退回后再导入。\n *\n * 认证平台对桌面端与移动端提供不同页面，两者都要覆盖：\n *   个人信息中心  桌面 /personalInfo/personCenter/，移动 /personalInfo/personalMobile/\n *   密码找回页面  桌面 /retrieve-password/retrievePassword/，移动 /retrieve-password/passwordMobile/\n * 故按目录前缀匹配而非具体页面名。\n *\n * 各路径验证程度：\n *   个人信息中心    移动版路径由实机反馈确认；桌面版复现路径为\n *                  已认证 + 无 service 访问认证入口 → /authserver/index.do → /personalInfo/personCenter/。\n *   密码找回页面    移动版 /retrieve-password/passwordMobile/ 实测渲染「找回密码」，\n *                  且移动版认证页的「忘记密码」链接正指向该地址并追加 service 参数。\n *\n * 判定依据为 URL 路径：登录态存于评价系统域，认证域与之跨域、读不到，只能靠当前地址判断。\n */\nfunction detectAuthPage() {\n    const href = String(window.location.href);\n    if (href.indexOf(\"/personalInfo/\") !== -1) return \"个人信息中心\";\n    if (href.indexOf(\"/retrieve-password/\") !== -1) return \"密码找回页面\";\n    if (href.indexOf(\"authserver.\") !== -1) return \"统一身份认证页面\";\n    return \"\";\n}\n\nasync function promptWrongPage(pageName) {\n    return await window.shiguangBridgePromise.showAlert(\n        \"请先返回评价系统\",\n        `当前停留在「${pageName}」，无法获取课表数据。\\n\\n`\n        + \"现象说明：学校统一认证平台在认证完成后，偶尔会跳转到自身的个人信息中心或密码找回页面，\"\n        + \"此时登录其实已经成功，只是没有回到应用。\\n\\n\"\n        + \"处理方式：点击左上角「返回」，回到教学质量综合评价系统页面后，再点击「执行导入」即可。\",\n        \"我知道了\"\n    );\n}\n\nasync function runImportFlow() {\n    const authPage = detectAuthPage();\n    if (authPage) {\n        await promptWrongPage(authPage);\n        return;\n    }\n\n    const user = readCurrentUser();\n    if (!user || !user.Token) {\n        await promptUserToLogin();\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const clientId = readClientId();\n\n    const semester = await selectSemester(user, clientId);\n    if (!semester) {\n        showToast(\"导入已取消。\");\n        return;\n    }\n\n    showToast(\"正在获取课程数据...\");\n    let courses = null;\n    try {\n        courses = await collectCourses(user, clientId, semester.key);\n    } catch (error) {\n        showToast(`获取课表失败: ${describeError(error)}`);\n        return;\n    }\n\n    if (courses === null) {\n        showToast(\"未查询到课程列表，请确认该学期有选课记录。\");\n        return;\n    }\n\n    if (courses.length === 0) {\n        showToast(\"未匹配到任何排课记录，可尝试切换其他学期。\");\n        return;\n    }\n\n    const setting = await fetchSemesterSetting(user, clientId, semester.key);\n    const config = {\n        semesterTotalWeeks: DEFAULT_TOTAL_WEEKS,\n        defaultClassDuration: 45,\n        defaultBreakDuration: 10,\n        firstDayOfWeek: 1\n    };\n\n    if (setting) {\n        const startDate = deriveSemesterStartDate(setting.firstOfWeek, setting.currentWeek);\n        if (startDate) config.semesterStartDate = startDate;\n    }\n\n    const configSaved = await saveCourseConfig(config);\n    if (!configSaved) return;\n\n    const coursesSaved = await saveCourses(courses);\n    if (!coursesSaved) return;\n\n    await importPresetTimeSlots();\n\n    const tip = courses.length === 1 ? \"1 门课程\" : `${courses.length} 个课程时段`;\n    showToast(`导入完成，共 ${tip}。部分课程可能缺失，可手动补录。`);\n\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n\n})();\n","GDIT_01":"// 文件: gdit.js\n// 广东科学技术职业学院 课程表导入适配脚本\n\nif (typeof Strings === 'undefined') {\n    var Strings = {\n        BASE_URL: \"https://wbdt.gdit.edu.cn\",\n        GET_STUDENT_SCHEDULE_URL: \"front/extraCard/queryStudentSchedule\"\n    };\n}\n\nasync function stepDescriptionAlert() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"提示\",\n            \"即将执行导入课程操作。请确保你已处于登录状态，并已打开课程表页面。\",\n            \"确认\"\n        );\n        return confirmed;\n    } catch (error) {\n        console.error(\"显示弹窗时发生错误:\", error);\n        return false;\n    }\n}\n\nasync function selectSemesterSelection() {\n    const now = new Date();\n    const currentYear = now.getFullYear();\n    const currentMonth = now.getMonth() + 1;\n    const currentSemester = currentMonth >= 9 || currentMonth <= 2 ? 1 : 2;\n\n    const presetSemesters = [];\n    const presetSemestersName = [];\n\n    for (let year = currentYear; year >= currentYear - 3; year--) {\n        for (let semester = (year === currentYear ? currentSemester : 2); semester >= 1; semester--) {\n            const semesterName = `${year}-${year + 1}学年 第${semester}学期`;\n            presetSemesters.push({\n                name: semesterName,\n                schoolYear: `${year}-${year + 1}`,\n                semester: String(semester)\n            });\n            presetSemestersName.push(semesterName);\n        }\n    }\n\n    try {\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择要导入的学期\",\n            JSON.stringify(presetSemestersName),\n            0\n        );\n\n        if (selectedIndex !== null && selectedIndex >= 0 && selectedIndex < presetSemesters.length) {\n            const selected = presetSemesters[selectedIndex];\n            console.log(\"用户选择了: \" + selected.name);\n            return selected;\n        } else {\n            console.log(\"用户取消了选择。\");\n            return null;\n        }\n    } catch (error) {\n        console.error(\"显示单选列表弹窗时发生错误:\", error);\n        window.shiguangBridge.showToast(\"显示列表出错！\" + error.message);\n        return null;\n    }\n}\n\nasync function fetchCourses(schoolYear, semester) {\n    try {\n        console.log(`正在获取 ${schoolYear} 第${semester}学期 的课程数据...`);\n\n        const timestamp = Date.now();\n        const url = `${Strings.BASE_URL}/${Strings.GET_STUDENT_SCHEDULE_URL}?_t=${timestamp}&semester=${semester}&schoolYear=${schoolYear}`;\n\n        const response = await fetch(url, {\n            method: 'GET',\n            headers: {\n                'Content-Type': 'application/json'\n            },\n            credentials: 'include'\n        });\n\n        if (!response.ok) {\n            throw new Error(`请求失败: ${response.status}`);\n        }\n\n        const result = await response.json();\n        console.log(\"API 返回数据:\", result);\n\n        if (!result.meta || !result.meta.success) {\n            throw new Error(result.meta ? result.meta.message : \"请求失败\");\n        }\n\n        if (!result.data || !Array.isArray(result.data) || result.data.length === 0) {\n            throw new Error(\"该学期没有课程数据\");\n        }\n\n        const courses = parseCourses(result.data);\n        return courses;\n    } catch (error) {\n        console.error('获取课程数据失败:', error);\n        window.shiguangBridge.showToast(\"获取课程失败: \" + error.message);\n        return null;\n    }\n}\n\nfunction parseCourses(rawCourses) {\n    console.log(`正在解析课程数据，共 ${rawCourses.length} 条原始记录...`);\n\n    const courses = [];\n\n    for (const raw of rawCourses) {\n        try {\n            const name = raw.courseName || \"\";\n            const teacher = raw.userName || \"\";\n            const position = raw.placeName || \"\";\n\n            const day = Number(raw.weekDay);\n            if (isNaN(day) || day < 1 || day > 7) continue;\n\n            const sectionStr = raw.festivals || \"\";\n            const sectionMatch = sectionStr.match(/(\\d+)-(\\d+)/);\n            if (!sectionMatch) continue;\n            const startSection = Number(sectionMatch[1]);\n            const endSection = Number(sectionMatch[2]);\n\n            const startWeek = Number(raw.startWeek);\n            const endWeek = Number(raw.endWeek);\n            if (isNaN(startWeek) || isNaN(endWeek)) continue;\n\n            const singleDoubleWeek = raw.singleDoubleWeek || \"0\";\n            const weeks = [];\n            for (let w = startWeek; w <= endWeek; w++) {\n                if (singleDoubleWeek === \"1\" && w % 2 === 0) continue;\n                if (singleDoubleWeek === \"2\" && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n\n            if (name && weeks.length > 0) {\n                courses.push({\n                    name: name.trim(),\n                    teacher: teacher.trim(),\n                    position: position.trim(),\n                    day: day,\n                    startSection: startSection,\n                    endSection: endSection,\n                    weeks: weeks,\n                    isCustomTime: false\n                });\n            }\n        } catch (e) {\n            console.warn(\"解析单条课程数据失败:\", e, raw);\n        }\n    }\n\n    console.log(`成功解析 ${courses.length} 门课程`);\n    return courses;\n}\n\nasync function saveCourses(courses) {\n    try {\n        console.log(\"正在尝试导入课程...\");\n        const result = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (result === true) {\n            console.log(\"课程导入成功！\");\n        } else {\n            console.log(\"课程导入未成功，结果：\" + result);\n            window.shiguangBridge.showToast(\"课程导入失败，请查看日志。\");\n        }\n    } catch (error) {\n        console.error(\"导入课程时发生错误:\", error);\n        window.shiguangBridge.showToast(\"导入课程失败: \" + error.message);\n    }\n}\n\nasync function setPresetTimeSlots() {\n    const presetTimeSlots = [\n        { \"number\": 1, \"startTime\": \"08:10\", \"endTime\": \"08:55\" },\n        { \"number\": 2, \"startTime\": \"09:05\", \"endTime\": \"09:50\" },\n        { \"number\": 3, \"startTime\": \"10:10\", \"endTime\": \"10:55\" },\n        { \"number\": 4, \"startTime\": \"11:05\", \"endTime\": \"11:50\" },\n        { \"number\": 5, \"startTime\": \"14:30\", \"endTime\": \"15:15\" },\n        { \"number\": 6, \"startTime\": \"15:25\", \"endTime\": \"16:10\" },\n        { \"number\": 7, \"startTime\": \"16:30\", \"endTime\": \"17:15\" },\n        { \"number\": 8, \"startTime\": \"17:25\", \"endTime\": \"18:10\" },\n        { \"number\": 9, \"startTime\": \"19:10\", \"endTime\": \"19:55\" },\n        { \"number\": 10, \"startTime\": \"20:05\", \"endTime\": \"20:50\" },\n        { \"number\": 11, \"startTime\": \"21:00\", \"endTime\": \"21:45\" }\n    ];\n\n    try {\n        console.log(\"正在尝试导入预设时间段...\");\n        const result = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n        if (result === true) {\n            console.log(\"预设时间段导入成功！\");\n        } else {\n            console.log(\"预设时间段导入未成功，结果：\" + result);\n        }\n    } catch (error) {\n        console.error(\"导入时间段时发生错误:\", error);\n    }\n}\n\nasync function runImportFlow() {\n    const confirmed = await stepDescriptionAlert();\n    if (!confirmed) {\n        console.log(\"用户取消了操作。\");\n        return;\n    }\n\n    const semester = await selectSemesterSelection();\n    if (!semester) {\n        console.log(\"用户取消了学期选择。\");\n        return;\n    }\n\n    const courses = await fetchCourses(semester.schoolYear, semester.semester);\n    if (!courses || courses.length === 0) {\n        window.shiguangBridge.showToast(\"未找到课程数据，请确认选择了正确的学期\");\n        return;\n    }\n\n    await saveCourses(courses);\n    await setPresetTimeSlots();\n\n    window.shiguangBridge.showToast(`成功导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","GDUST":"// 广东科技学院(gdust.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    // 检查JSON结构：新的数据在 kbList 字段中\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查： kcmc(课名), xm(教师), cdmc(教室), xqj(星期), jcs(节次范围), zcd(周次描述)\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        \n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        // 解析节次范围，例如 \"1-2\"\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n\n        const day = Number(rawCourse.xqj); // xqj: 星期几 (周一为1, 周日为7)\n        \n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            // console.warn(`JS: 课程 ${rawCourse.kcmc} 星期或节次数据无效，跳过。`);\n            continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\n\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\n/**\n * 将选择索引转换为 API 所需的学期码。\n */\nfunction getSemesterCode(semesterIndex) {\n    // semesterIndex 3 (第一学期), 12 (第二学期)\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    const semesterCode = getSemesterCode(semesterIndex);\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    \n    // 定义可能的入口地址：1. WebVPN 穿透地址 2. 内网直连地址\n    // 该学校反馈内网环境下 webvpn的入口会被跳转为内网地址 因此特别调整为存在多个链接获取，没有这个问题的适配参考可以简化逻辑\n    const targetUrls = [\n        \"https://webvpn.gdust.edu.cn/http/77726476706e69737468656265737421a1a013d2766626022b5cc7fd/kbcx/xskbcx_cxXsgrkb.html?vpn-12-o1-172.16.254.1&gnmkdm=N2151\",\n        \"http://172.16.254.1/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\"\n    ];\n\n    for (const url of targetUrls) {\n        try {\n            const response = await fetch(url, {\n                method: \"POST\",\n                headers: { \n                    \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" \n                },\n                body: requestBody,\n                credentials: \"include\"\n            });\n\n            if (response.ok) {\n                const jsonText = await response.text();\n                const jsonData = JSON.parse(jsonText);\n                if (jsonData && jsonData.kbList) {\n                    const parsedCourses = parseJsonData(jsonData);\n                    if (parsedCourses.length > 0) {\n                        return {\n                            courses: parsedCourses,\n                            config: {\n                                semesterStartDate: null,\n                                semesterTotalWeeks: 20\n                            }\n                        };\n                    }\n                }\n            }\n        } catch (e) {\n            console.error(`Entry failed: ${url}`);\n        }\n    }\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n// 统一作息时间\nconst TimeSlots = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:20\", endTime: \"10:05\" },\n    { number: 3, startTime: \"10:25\", endTime: \"11:10\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n    { number: 5, startTime: \"14:40\", endTime: \"15:25\" },\n    { number: 6, startTime: \"15:30\", endTime: \"16:15\" },\n    { number: 7, startTime: \"16:30\", endTime: \"17:15\" },\n    { number: 8, startTime: \"17:20\", endTime: \"18:05\" },\n    { number: 9, startTime: \"19:30\", \"endTime\": \"20:15\" },\n    { number: 10, startTime: \"20:20\", \"endTime\": \"21:05\" },\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\n\nasync function runImportFlow() {\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`课表配置更新成功！总周数：${config.semesterTotalWeeks}周。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n\n\n    await importPresetTimeSlots(TimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","GDKM":"//https://jw.gdkm.edu.cn/jsxsd/xskb/xskb_list.do\n// 广东科贸职业学院(gdkm.edu.cn) 拾光课程表适配脚本\n// 参考南昌航空大学科技学院(stcnchu.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 工具函数\n\nwindow.validateYearInput = function (input) {\n    return /^[0-9]{4}$/.test(input) ? false : \"请输入四位数字的学年喵~\";\n};\n\n/**\n * 节次合并与去重\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (courses.length <= 1) return courses;\n\n    courses.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.day - b.day ||\n            a.startSection - b.startSection ||\n            a.weeks.join(',').localeCompare(b.weeks.join(','));\n    });\n\n    const merged = [];\n    let current = courses[0];\n\n    for (let i = 1; i < courses.length; i++) {\n        const next = courses[i];\n        const isSameCourse =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n\n        if (isSameCourse && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourse && current.startSection === next.startSection && current.endSection === next.endSection) {\n            continue;\n        } else {\n            merged.push(current);\n            current = next;\n        }\n    }\n    merged.push(current);\n    return merged;\n}\n\n// 核心解析逻辑\n\nfunction parseTimetableToModel(doc) {\n    let timetable = doc.querySelector('table.qz-weeklyTable');\n    if (!timetable) {\n        const tables = Array.from(doc.querySelectorAll('table'));\n        timetable = tables.sort((a, b) =>\n            b.querySelectorAll('td').length - a.querySelectorAll('td').length\n        )[0];\n    }\n    if (!timetable) return [];\n\n    const rawCourses = [];\n    const rows = Array.from(timetable.querySelectorAll('tbody tr'));\n\n    // rowspan 占位表：key = 行下标，value = 该行被上方 rowspan 占用的列集合\n    // 列号从 1 开始（1 = 周一）\n    const occupied = {}; // { [rowIndex]: Set<col> }\n\n    rows.forEach((row, rowIndex) => {\n        const timeTd = row.querySelector('td[name=\"timeTd\"]');\n        const sectionText = timeTd ? timeTd.innerText : '';\n        const rowSection = parseSectionFromLabel(sectionText);\n\n        const courseTds = Array.from(row.querySelectorAll('td[name=\"kbDataTd\"]'));\n\n        // 本行被占用的列\n        const occupiedCols = occupied[rowIndex] || new Set();\n\n        let col = 1;          // 从第 1 列（周一）开始\n        let tdIndex = 0;      // courseTds 的下标\n\n        while (tdIndex < courseTds.length) {\n            // 跳过被上方 rowspan 占用的列\n            while (occupiedCols.has(col)) col++;\n\n            const td = courseTds[tdIndex];\n            const day = col;  // 这个 td 真正对应的星期几\n\n            // 处理这个 td 里的课程\n            const items = td.querySelectorAll('li.courselists-item');\n            items.forEach(li => {\n                const name = li.querySelector('.qz-hasCourse-title')?.innerText.trim() || '';\n                if (!name) return;\n\n                const abbr = li.querySelector('.qz-hasCourse-abbrinfo')?.innerText || '';\n                const teacher = extractField(abbr, '老师') || '未知教师';\n                const position = extractField(abbr, '地点') || '未知地点';\n                const weekStr = extractField(abbr, '时间') || '';\n\n                const parsed = parseSectionFromWeekStr(weekStr);\n                const finalStart = parsed.startSection || rowSection.startSection;\n                const finalEnd = parsed.endSection || rowSection.endSection;\n\n                if (finalStart > 0) {\n                    rawCourses.push({\n                        name,\n                        teacher,\n                        weeks: parseWeeks(weekStr),\n                        position,\n                        day,\n                        startSection: finalStart,\n                        endSection: finalEnd\n                    });\n                }\n            });\n\n            // 看这个 td 有没有 rowspan\n            const rowspan = parseInt(td.getAttribute('rowspan') || '1', 10);\n            if (rowspan > 1) {\n                // 它占用的列：接下来的 rowspan-1 行，这一列都不出现 td\n                for (let r = rowIndex + 1; r < rowIndex + rowspan; r++) {\n                    if (!occupied[r]) occupied[r] = new Set();\n                    occupied[r].add(col);\n                }\n            }\n\n            col++;\n            tdIndex++;\n        }\n    });\n\n    return mergeAndDistinctCourses(rawCourses);\n}\n\n//工具\n\n// 从 \"老师:张三;时间:3周[1-6节];地点:xxx\" 里取某个字段\nfunction extractField(text, key) {\n    if (!text) return '';\n\n    // 1. 找到 \"老师:\" 或 \"老师：\" 的位置\n    let startIdx = -1;\n    const colonVariants = [key + ':', key + '：'];\n    for (let i = 0; i < colonVariants.length; i++) {\n        startIdx = text.indexOf(colonVariants[i]);\n        if (startIdx !== -1) {\n            startIdx += colonVariants[i].length; // 跳过 key 和冒号\n            break;\n        }\n    }\n    if (startIdx === -1) return '';\n\n    // 2. 从 startIdx 往后找第一个 ; 或 ；或换行\n    let endIdx = text.length;\n    for (let i = startIdx; i < text.length; i++) {\n        const ch = text[i];\n        if (ch === ';' || ch === '；' || ch === '\\n') {\n            endIdx = i;\n            break;\n        }\n    }\n\n    return text.substring(startIdx, endIdx).trim();\n}\n\n// 从 \"第一大节 (01、02小节)\" 里取节次\nfunction parseSectionFromLabel(text) {\n    let startSection = 0, endSection = 0;\n    if (!text) return { startSection, endSection };\n\n    // 找 \"(\" 和 \"小节\"\n    const openIdx = Math.max(text.indexOf('('), text.indexOf('（'));\n    const closeIdx = text.indexOf('小节', openIdx);\n    if (openIdx === -1 || closeIdx === -1) return { startSection, endSection };\n\n    const inside = text.substring(openIdx + 1, closeIdx); // 例如 \"01、02\"\n    // 用 、 或 , 切开\n    const parts = inside.split(/[、,，]/);\n    const nums = [];\n    parts.forEach(p => {\n        const n = parseInt(p.trim(), 10);\n        if (!isNaN(n)) nums.push(n);\n    });\n\n    if (nums.length > 0) {\n        startSection = nums[0];\n        endSection = nums[nums.length - 1];\n    }\n    return { startSection, endSection };\n}\n\n// 从 \"3周[1-6节]\" 里取节次\nfunction parseSectionFromWeekStr(weekStr) {\n    let startSection = 0, endSection = 0;\n    if (!weekStr) return { startSection, endSection };\n\n    // 找 [ 和 节]\n    const openIdx = weekStr.indexOf('[');\n    const closeIdx = weekStr.indexOf('节]', openIdx);\n    if (openIdx === -1 || closeIdx === -1) return { startSection, endSection };\n\n    const inside = weekStr.substring(openIdx + 1, closeIdx); // 例如 \"1-6\" 或 \"5-8\"\n    const dashIdx = inside.indexOf('-');\n    if (dashIdx === -1) {\n        // 只有一个数字\n        const n = parseInt(inside.trim(), 10);\n        if (!isNaN(n)) {\n            startSection = n;\n            endSection = n;\n        }\n    } else {\n        const a = parseInt(inside.substring(0, dashIdx).trim(), 10);\n        const b = parseInt(inside.substring(dashIdx + 1).trim(), 10);\n        if (!isNaN(a)) startSection = a;\n        if (!isNaN(b)) endSection = b;\n    }\n    return { startSection, endSection };\n}\n\n// 从 \"3-4,9-18周\" 里解析出所有周次\n// 返回 [3,4,9,10,11,...,18] 这样的数组\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    // 1. 去掉 \"周\" 之后的内容，比如 \"3-4,9-18周[1-2节]\" -> \"3-4,9-18\"\n    let endIdx = weekStr.indexOf('周');\n    let core = endIdx === -1 ? weekStr : weekStr.substring(0, endIdx);\n\n    // 2. 去掉 \"[\" 之前可能残留的东西（保险）\n    const bracketIdx = core.indexOf('[');\n    if (bracketIdx !== -1) core = core.substring(0, bracketIdx);\n\n    const weeks = [];\n\n    // 3. 按逗号切开，每段可能是 \"3\" 或 \"9-18\"\n    const segments = core.split(/[,，]/);\n    segments.forEach(seg => {\n        seg = seg.trim();\n        if (!seg) return;\n\n        const dashIdx = seg.indexOf('-');\n        if (dashIdx === -1) {\n            // 单个周\n            const n = parseInt(seg, 10);\n            if (!isNaN(n)) weeks.push(n);\n        } else {\n            // 范围周\n            const a = parseInt(seg.substring(0, dashIdx).trim(), 10);\n            const b = parseInt(seg.substring(dashIdx + 1).trim(), 10);\n            if (!isNaN(a) && !isNaN(b)) {\n                for (let i = a; i <= b; i++) weeks.push(i);\n            }\n        }\n    });\n\n    // 4. 去重 + 排序\n    const unique = [];\n    weeks.forEach(w => {\n        if (unique.indexOf(w) === -1) unique.push(w);\n    });\n    unique.sort((a, b) => a - b);\n\n    return unique;\n}\n\n// 配置与流程\n\nasync function saveAppConfig(semesterStartDate, semesterTotalWeeks) {\n    const config = { \"semesterTotalWeeks\": semesterTotalWeeks, \"firstDayOfWeek\": 1, \"semesterStartDate\": semesterStartDate };\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n/**\n * 返回作息\n */\nasync function saveAppTimeSlots() {\n    const slots = [\n        { \"number\": 1, \"startTime\": \"08:30\", \"endTime\": \"09:10\" },\n        { \"number\": 2, \"startTime\": \"09:20\", \"endTime\": \"10:00\" },\n        { \"number\": 3, \"startTime\": \"10:20\", \"endTime\": \"11:00\" },\n        { \"number\": 4, \"startTime\": \"11:10\", \"endTime\": \"11:50\" },\n        { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:40\" },\n        { \"number\": 6, \"startTime\": \"14:50\", \"endTime\": \"15:20\" },\n        { \"number\": 7, \"startTime\": \"15:30\", \"endTime\": \"16:10\" },\n        { \"number\": 8, \"startTime\": \"16:20\", \"endTime\": \"16:50\" },\n        { \"number\": 9, \"startTime\": \"18:30\", \"endTime\": \"19:10\" },\n        { \"number\": 10, \"startTime\": \"19:20\", \"endTime\": \"19:50\" },\n        { \"number\": 11, \"startTime\": \"20:00\", \"endTime\": \"20:40\" },\n        { \"number\": 12, \"startTime\": \"20:50\", \"endTime\": \"21:20\" },\n    ]\n\n\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(slots));\n}\n\n//拿开学日期\nfunction getSchoolStartDate(htmlText) {\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(htmlText, 'text/html');\n\n    // 找到第1周那一行\n    const rows = doc.querySelectorAll('tr.qz-weeklyTable-tr');\n    let firstWeekRow = null;\n    for (const row of rows) {\n        const label = row.querySelector('.qz-weeklyTable-label .td-cell');\n        if (label && label.textContent.trim() === '第1周') {\n            firstWeekRow = row;\n            break;\n        }\n    }\n    if (!firstWeekRow) throw new Error('未找到第1周的数据');\n\n    // 取日期单元格：cells[0]=星期一，cells[5]=星期六\n    const cells = firstWeekRow.querySelectorAll('td.qz-weeklyTable-normalDay');\n    const mondayText = cells[0].textContent.trim();   // 例如 \"31\"\n    const saturdayText = cells[5].textContent.trim(); // 例如 \"09月05日\"\n\n    // 从星期六的文本里提取月份和日号\n    const satMatch = saturdayText.match(/(\\d{1,2})月(\\d{1,2})日/);\n    if (!satMatch) throw new Error('无法从周末日期中解析出月日');\n    const month = parseInt(satMatch[1], 10);\n    const satDay = parseInt(satMatch[2], 10);\n\n    // 星期一那格可能只有日号，也可能带“月日”\n    let day;\n    const dayMatch = mondayText.match(/(\\d{1,2})日/);\n    day = dayMatch ? parseInt(dayMatch[1], 10) : parseInt(mondayText, 10);\n    if (isNaN(day)) throw new Error('无法解析星期一的日期');\n\n    // 取学年起始年（如 \"2026-2027-1\" → 2026）\n    let year = new Date().getFullYear();\n    const yearSelect = doc.querySelector('#xnxq01id');\n    if (yearSelect) {\n        const selected = yearSelect.querySelector('option[selected]');\n        const value = selected ? selected.value : yearSelect.options[0].value;\n        year = parseInt(value.split('-')[0], 10);\n    }\n\n    // 跨月修正：若周一日期数字 > 周六日期数字，说明周一在上一个月\n    let finalMonth = month;\n    let finalDay = day;\n    if (day > satDay) {\n        finalMonth = month - 1;\n        if (finalMonth === 0) finalMonth = 12;\n    }\n\n    // 格式化为 YYYY-MM-DD\n    const mm = String(finalMonth).padStart(2, '0');\n    const dd = String(finalDay).padStart(2, '0');\n    return `${year}-${mm}-${dd}`;\n}\n\n//拿总周数\nfunction getTotalWeeks(htmlText) {\n    if (!htmlText || typeof htmlText !== 'string') return null;\n\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(htmlText, 'text/html');\n\n    // 优先用 .qz-weeklyTable-label 精确匹配\n    const labels = doc.querySelectorAll('.qz-weeklyTable-label .td-cell');\n    let maxWeek = 0;\n\n    labels.forEach(el => {\n        const text = el.textContent.trim();\n        const match = text.match(/^第\\s*(\\d+)\\s*周$/);\n        if (match) {\n            const n = parseInt(match[1], 10);\n            if (n > maxWeek) maxWeek = n;\n        }\n    });\n\n    // 如果精确选择器没找到，退回全表扫描\n    if (maxWeek === 0) {\n        const allText = doc.body ? doc.body.innerText : '';\n        const re = /第\\s*(\\d+)\\s*周/g;\n        let m;\n        while ((m = re.exec(allText)) !== null) {\n            const n = parseInt(m[1], 10);\n            if (n > maxWeek) maxWeek = n;\n        }\n    }\n\n    // 解析失败返回 null，成功返回最大周数\n    return maxWeek > 0 ? maxWeek : null;\n}\n\n// 拿学年\n\nfunction getAcademicYearInfo(htmlText) {\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(htmlText, 'text/html');\n\n    const results = [];\n\n    // 从下拉框取所有选项\n    const select = doc.querySelector('#xnxq01id');\n    if (select) {\n        const options = select.querySelectorAll('option');\n        options.forEach(opt => {\n            const value = (opt.value || '').trim(); // 例如 \"2026-2027-1\"\n            if (!value) return;\n\n            // 只做格式校验：起始年-结束年-学期\n            if (/^\\d{4}-\\d{4}-\\d+$/.test(value)) {\n                results.push(value);\n            }\n        });\n    }\n    return results.length > 0 ? results : null;\n}\n\nwindow.isYMD = function (str) {\n    // 1. 格式匹配：4位-2位-2位\n    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(str)) return \"开始日期格式错误了喵~。请再次输入喵~\";\n\n    // 2. 校验是否是真实存在的日期（防止 2024-02-30）\n    const [y, m, d] = str.split('-').map(Number);\n    const date = new Date(y, m - 1, d);\n\n    if (!(date.getFullYear() === y && date.getMonth() === m - 1 && date.getDate() === d)) {\n        return \"开始日期格式错误了喵~。请再次输入喵~\"\n    }\n    return false\n}\n\nwindow.isAcademicYear = function (str) {\n    if (typeof str !== 'string') {\n        return \"请输入学年学期喵~（例如 2025-2026-1）\";\n    }\n\n    // 1. 格式匹配：4位-4位-1到2位\n    if (!/^\\d{4}-\\d{4}-\\d{1,2}$/.test(str.trim())) {\n        return \"学年学期格式错误喵~。正确格式为:2025-2026-1\";\n    }\n\n    const parts = str.trim().split('-');\n    const startYear = parseInt(parts[0], 10);\n    const endYear = parseInt(parts[1], 10);\n    const semester = parseInt(parts[2], 10);\n\n    // 2. 结束学年必须比起始学年大 1\n    if (endYear !== startYear + 1) {\n        return \"结束学年必须是起始学年的下一年喵~（例如 2025-2026）\";\n    }\n\n    // 3. 学期只能是 1 或 2（如学校有小学期可自行放宽）\n    if (semester !== 1 && semester !== 2) {\n        return \"学期只能是 1 或 2 喵~\";\n    }\n\n    return false;\n};\n\n// ================= 流程编排 =================\n\nwindow.semesterTotalWeeksInput = function (str) {\n    return /^-?\\d+$/.test(str) ? false : \"请输入周数喵~只要数字喵~\"\n}\n\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\"提示喵~\", \"请确保已成功登录教务系统喵~。是否开始导入？\", \"开始\");\n        if (!confirmed) return;\n\n        const response_calendar = await fetch(\"https://jw.gdkm.edu.cn/jsxsd/jxzl/jxzl_query\", {\n            \"headers\": {\n                \"accept\": \"text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7\",\n                \"accept-language\": \"zh-CN,zh;q=0.9\",\n                \"priority\": \"u=0, i\",\n                \"upgrade-insecure-requests\": \"1\"\n            },\n            \"body\": null,\n            \"method\": \"GET\",\n            \"mode\": \"cors\",\n            \"credentials\": \"include\"\n        })\n        const html_calendar = await response_calendar.text();\n\n\n        /*\n        // 1. 获取就读校区\n        const campusIndex = await window.shiguangBridgePromise.showSingleSelection(\"选择所在校区喵~\", JSON.stringify([\"清远校区\", \"广州白云校区\",\"广州天河校区\"]), -1);\n        if (campusIndex === null) return;\n\n        */\n        // 2. 获取学年\n        var semesterId_array = getAcademicYearInfo(html_calendar)\n        var semesterId_index = await window.shiguangBridgePromise.showSingleSelection(\"选择学年学期喵~\", JSON.stringify(semesterId_array), 0);\n        var semesterId = semesterId_array[semesterId_index]\n        if (!semesterId) return;\n\n\n\n\n        var semesterStartDate = getSchoolStartDate(html_calendar);\n\n        if (window.isYMD(semesterStartDate)) {\n            semesterStartDate = await window.shiguangBridgePromise.showPrompt(\"选择开始日期喵~\" + \"errror \" + semesterStartDate + window.isYMD(semesterStartDate), \"请输入要导入课程的开始日期喵~ 格式为:YYYY-MM-DD,例如1145-01-04\", \"\", \"isYMD\");\n        }\n        if (!semesterStartDate) return;\n\n        var semesterTotalWeeks = getTotalWeeks(html_calendar)\n\n        if (window.semesterTotalWeeksInput(semesterTotalWeeks)) {\n            semesterTotalWeeks = await window.shiguangBridgePromise.showPrompt(\"选择周数喵~\" + \"errror \" + semesterTotalWeeks + window.semesterTotalWeeksInput(semesterStartDate), \"请输入要导入课程的周数喵~（例如 20):\", \"\", \"semesterTotalWeeksInput\");\n        }\n\n        if (!semesterTotalWeeks) return;\n\n        window.shiguangBridge.showToast(\"正在请求数据喵~\");\n        const url = `https://jw.gdkm.edu.cn/jsxsd/xskb/xskb_list.do?viweType=0&xnxq01id=${semesterId}&zc=`;\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\",\n            headers: {\n                \"Referer\": \"https://jw.gdkm.edu.cn/jsxsd/\"\n            }\n        });\n\n\n        const html = await response.text();\n\n        const finalCourses = parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"));\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现课程，请检查学期选择或登录状态喵~\");\n            return;\n        }\n\n        // 保存全局设置\n        await saveAppConfig(semesterStartDate, parseInt(semesterTotalWeeks));\n        // 传入作息\n        await saveAppTimeSlots();\n        // 保存课程\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n\n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程喵~`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(\"异常喵~ \" + error.message);\n    }\n}\n\n// 启动\nrunImportFlow();\n","GDPU_01":"// 广东药科大学 (gdpu.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) continue;\n        \n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n        const day = Number(rawCourse.xqj);\n        \n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    return finalCourseList;\n}\n\n/**\n * 检查是否在登录页面。\n */\nfunction isLoginPage() {\n    return window.location.href.indexOf(\"lyuapServer/login\") > -1; \n}\n\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input)) {\n        return false;\n    } else {\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中登录广东药科大学教务系统并进入课表页面\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\nfunction getSemesterCode(semesterIndex) {\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n/**\n * 选择校区\n */\nasync function selectCampus() {\n    const campusKeys = [\"campus_1\", \"campus_2\"];\n    const campusDisplayNames = [\"广州、云浮校区\", \"中山校区\"];\n    \n    const campusIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择校区\",\n        JSON.stringify(campusDisplayNames),\n        0\n    );\n    \n    if (campusIndex === null || campusIndex === -1) return null;\n    return campusKeys[campusIndex];\n}\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n    const semesterCode = getSemesterCode(semesterIndex);\n    const xnmXqmBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`; \n    const url = \"https://webvpn.gdpu.edu.cn/http/77726476706e69737468656265737421fae05285347e6f546e1dc7a99c406d36fe/kbcx/xskbcx_cxXsgrkb.html?vpn-12-o1-jwsys.gdpu.edu.cn&gnmkdm=N2151\";\n\n    const requestOptions = {\n        \"headers\": {\n            \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\", \n        },\n        \"body\": xnmXqmBody,\n        \"method\": \"POST\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n        \n        const jsonText = await response.text();\n        let jsonData;\n        try {\n            jsonData = JSON.parse(jsonText);\n        } catch (e) {\n            window.shiguangBridge.showToast(\"数据解析失败，请检查是否登录过期。\");\n            return null;\n        }\n\n        const courses = parseJsonData(jsonData); \n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到课程数据，请检查学年学期。\");\n            return null;\n        }\n        \n        const config = {\n            semesterTotalWeeks: 20,\n            defaultClassDuration: 45,\n            defaultBreakDuration: 10,\n            firstDayOfWeek: 1 \n        };\n\n        return { courses: courses, config: config }; \n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求失败: ${error.message}`);\n        console.error(error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error(error);\n        return false;\n    }\n}\n\n// 多校区作息时间表定义\nconst CampusTimeSlots = {\n    // 广州、云浮校区\n    \"campus_1\": [\n        { number: 1, startTime: \"08:30\", endTime: \"09:10\" },\n        { number: 2, startTime: \"09:20\", endTime: \"10:00\" },\n        { number: 3, startTime: \"10:10\", endTime: \"10:50\" },\n        { number: 4, startTime: \"11:00\", endTime: \"11:40\" },\n        { number: 5, startTime: \"11:50\", endTime: \"12:30\" },\n        { number: 6, startTime: \"12:40\", endTime: \"13:20\" },\n        { number: 7, startTime: \"14:00\", endTime: \"14:40\" },\n        { number: 8, startTime: \"14:50\", endTime: \"15:30\" },\n        { number: 9, startTime: \"15:40\", endTime: \"16:20\" },\n        { number: 10, startTime: \"16:30\", endTime: \"17:10\" },\n        { number: 11, startTime: \"17:20\", endTime: \"18:00\" },\n        { number: 12, startTime: \"18:10\", endTime: \"18:50\" },\n        { number: 13, startTime: \"19:00\", endTime: \"19:40\" },\n        { number: 14, startTime: \"19:50\", endTime: \"20:30\" },\n        { number: 15, startTime: \"20:40\", endTime: \"21:20\" }\n    ],\n    // 中山校区 \n    \"campus_2\": [\n        { number: 1, startTime: \"08:30\", endTime: \"09:10\" },\n        { number: 2, startTime: \"09:20\", endTime: \"10:00\" },\n        { number: 3, startTime: \"10:10\", endTime: \"10:50\" },\n        { number: 4, startTime: \"11:00\", endTime: \"11:40\" },\n        { number: 5, startTime: \"11:50\", endTime: \"12:30\" },\n        { number: 6, startTime: \"12:40\", endTime: \"13:20\" },\n        { number: 7, startTime: \"13:30\", endTime: \"14:10\" },\n        { number: 8, startTime: \"14:20\", endTime: \"15:00\" },\n        { number: 9, startTime: \"15:10\", endTime: \"15:50\" },\n        { number: 10, startTime: \"16:00\", endTime: \"16:40\" },\n        { number: 11, startTime: \"16:50\", endTime: \"17:30\" },\n        { number: 12, startTime: \"17:40\", endTime: \"18:20\" },\n        { number: 13, startTime: \"18:30\", endTime: \"19:10\" },\n        { number: 14, startTime: \"19:20\", endTime: \"20:00\" },\n        { number: 15, startTime: \"20:10\", endTime: \"20:50\" }\n    ]\n};\n\nasync function importPresetTimeSlots(campusKey) {\n    const timeSlots = CampusTimeSlots[campusKey];\n    if (timeSlots && timeSlots.length > 0) {\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        } catch (error) {\n            console.error(error);\n        }\n    }\n}\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先在浏览器登录教务系统！\");\n        return;\n    }\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) return;\n\n    const campusKey = await selectCampus();\n    if (campusKey === null) return;\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) return;\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) return;\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) return;\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) return;\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    } catch (error) {\n        console.error(error);\n    }\n\n    await importPresetTimeSlots(campusKey);\n    window.shiguangBridge.showToast(`导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","GDIPU_01":"// 广东轻工职业技术大学教务适配器\n// 适配器ID: GDIPU_01\n\n// 提示用户输入学期开始日期\nconst promptForStartDate = async () => {\n    try {\n        const today = new Date();\n        const defaultDate = today.toISOString().split('T')[0];\n        \n        const startDate = await window.shiguangBridgePromise.showPrompt(\n            \"请输入学期开始日期\",\n            \"格式：YYYY-MM-DD（例如：2026-02-24）\",\n            defaultDate,\n            \"validateDate\"\n        );\n        \n        if (startDate === null) {\n            throw new Error(\"用户取消了输入\");\n        }\n        \n        if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(startDate)) {\n            window.shiguangBridge.showToast(\"日期格式不正确，请使用YYYY-MM-DD格式\");\n            throw new Error(\"日期格式不正确\");\n        }\n        \n        return startDate;\n    } catch (error) {\n        console.error(\"获取开始日期失败:\", error);\n        throw error;\n    }\n};\n\n// 日期验证函数（供AndroidBridge调用）\nfunction validateDate(dateStr) {\n    if (!dateStr) {\n        return \"日期不能为空\";\n    }\n    \n    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(dateStr)) {\n        return \"日期格式不正确，请使用YYYY-MM-DD格式\";\n    }\n    \n    const date = new Date(dateStr);\n    if (isNaN(date.getTime())) {\n        return \"无效的日期\";\n    }\n    \n    return false;\n}\n\n// 获取课程表数据\nconst fetchTimetable = async (date) => {\n    try {\n        const response = await fetch('https://jw.gdipu.edu.cn/jsxsd/framework/main_index_loadkb.jsp', {\n            method: 'POST',\n            headers: {\n                'Accept': 'text/html, */*; q=0.01',\n                'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8,en-GB;q=0.7,en-US;q=0.6',\n                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',\n                'Origin': 'https://jw.gdipu.edu.cn',\n                'Referer': window.location.href,\n                'X-Requested-With': 'XMLHttpRequest'\n            },\n            credentials: 'include',\n            body: `rq=${date}`\n        });\n        \n        if (!response.ok) {\n            throw new Error(`HTTP错误: ${response.status}`);\n        }\n        \n        const html = await response.text();\n        \n        // 检查是否有课程\n        const hasCourses = checkIfHasCourses(html);\n        \n        return { html, hasCourses };\n    } catch (error) {\n        console.error('获取课程表失败:', error);\n        throw error;\n    }\n};\n\n// 检查HTML中是否有课程\nconst checkIfHasCourses = (html) => {\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(html, 'text/html');\n    \n    const table = doc.querySelector('form table.kb_table');\n    if (!table) {\n        return false;\n    }\n    \n    const courseCells = table.querySelectorAll('td p[title]');\n    return courseCells.length > 0;\n};\n\n// 从HTML字符串解析课程表\nconst parseTimetableFromHTML = (html, date) => {\n    const courses = [];\n    \n    const parser = new DOMParser();\n    const doc = parser.parseFromString(html, 'text/html');\n    \n    const table = doc.querySelector('form table.kb_table');\n    if (!table) {\n        console.error('未找到课程表表格');\n        return courses;\n    }\n    \n    const rows = table.querySelectorAll('tbody tr');\n    \n    rows.forEach((row) => {\n        const sectionCell = row.querySelector('td:first-child');\n        if (!sectionCell) return;\n        \n        const sectionText = sectionCell.textContent.trim().split('\\n')[0];\n        const sectionInfo = parseSection(sectionText);\n        \n        // 遍历星期几的列（从第2列到第8列）\n        for (let colIndex = 1; colIndex <= 7; colIndex++) {\n            const dayCell = row.querySelector(`td:nth-child(${colIndex + 1})`);\n            if (!dayCell) continue;\n            \n            const courseP = dayCell.querySelector('p[title]');\n            if (!courseP) continue;\n            \n            const title = courseP.getAttribute('title');\n            const courseInfo = parseCourseFromTitle(title);\n            \n            const timeInfo = parseTimeInfo(courseInfo.time || '');\n            \n            let dayOfWeek;\n            if (timeInfo.day && timeInfo.day > 0) {\n                dayOfWeek = timeInfo.day;\n            } else {\n                // 列索引映射：1->星期一(1), 2->星期二(2), 3->星期三(3), 4->星期四(4), 5->星期五(5), 6->星期六(6), 7->星期日(7)\n                dayOfWeek = colIndex;\n            }\n            \n            // 将跨节课程拆分为多个单节课程\n            const startSection = sectionInfo.startSection;\n            const endSection = sectionInfo.endSection;\n            \n            for (let section = startSection; section <= endSection; section++) {\n                const course = {\n                    name: courseInfo.name || '',\n                    teacher: '', // 这个系统似乎没有教师信息\n                    position: courseInfo.location || '',\n                    day: dayOfWeek,\n                    startSection: section,\n                    endSection: section, // 单节课，开始和结束节次相同\n                    weeks: timeInfo.weeks.length > 0 ? timeInfo.weeks : [1] // 暂时使用第1周\n                };\n                \n                courses.push(course);\n            }\n        }\n    });\n    \n    return courses;\n};\n\n// 从title属性解析课程信息\nconst parseCourseFromTitle = (title) => {\n    const info = {};\n    \n    const creditMatch = title.match(/课程学分：([\\d.]+)/);\n    const propertyMatch = title.match(/课程属性：([^<]+)/);\n    const nameMatch = title.match(/课程名称：([^<]+)/);\n    const timeMatch = title.match(/上课时间：([^<]+)/);\n    const locationMatch = title.match(/上课地点：([^<]+)/);\n    const campusMatch = title.match(/上课校区：([^<]+)/);\n    const groupMatch = title.match(/分组名：([^<]+)/);\n    \n    if (creditMatch) info.credit = creditMatch[1];\n    if (propertyMatch) info.property = propertyMatch[1].trim();\n    if (nameMatch) info.name = nameMatch[1].trim();\n    if (timeMatch) info.time = timeMatch[1].trim();\n    if (locationMatch) info.location = locationMatch[1].trim();\n    if (campusMatch) info.campus = campusMatch[1].trim();\n    if (groupMatch) info.group = groupMatch[1].trim();\n    \n    return info;\n};\n\n// 解析上课时间字符串\nconst parseTimeInfo = (timeStr) => {\n    const result = {\n        weeks: [],\n        day: 0,\n        startSection: 0,\n        endSection: 0\n    };\n    \n    // 解析周数范围\n    const weekMatch = timeStr.match(/第(\\d+)(?:-(\\d+))?周/);\n    if (weekMatch) {\n        const startWeek = parseInt(weekMatch[1], 10);\n        if (weekMatch[2]) {\n            const endWeek = parseInt(weekMatch[2], 10);\n            for (let week = startWeek; week <= endWeek; week++) {\n                result.weeks.push(week);\n            }\n        } else {\n            result.weeks.push(startWeek);\n        }\n    }\n    \n    // 解析星期几\n    const dayMap = {\n        '星期一': 1,\n        '星期二': 2,\n        '星期三': 3,\n        '星期四': 4,\n        '星期五': 5,\n        '星期六': 6,\n        '星期日': 7\n    };\n    \n    for (const [dayStr, dayNum] of Object.entries(dayMap)) {\n        if (timeStr.includes(dayStr)) {\n            result.day = dayNum;\n            break;\n        }\n    }\n    \n    // 解析节次\n    const sectionMatch = timeStr.match(/\\[(\\d+)-(\\d+)\\]/);\n    if (sectionMatch) {\n        result.startSection = parseInt(sectionMatch[1], 10);\n        result.endSection = parseInt(sectionMatch[2], 10);\n    }\n    \n    return result;\n};\n\n// 解析节次字符串\nconst parseSection = (sectionStr) => {\n    const result = {\n        startSection: 0,\n        endSection: 0\n    };\n    \n    if (sectionStr.includes('-')) {\n        const parts = sectionStr.split('-');\n        result.startSection = parseInt(parts[0], 10);\n        result.endSection = parseInt(parts[1], 10);\n    } else {\n        result.startSection = parseInt(sectionStr, 10);\n        result.endSection = parseInt(sectionStr, 10);\n    }\n    \n    return result;\n};\n\n// 获取学期配置\nconst getSemesterConfig = (startDate, totalWeeks) => {\n    return {\n        semesterStartDate: startDate,\n        totalWeeks: totalWeeks\n    };\n};\n\n// 获取时间段配置\nconst getTimeSlots = (html) => {\n    // 北区有14节课，使用准确时间配置\n    return [\n        { number: 1, startTime: \"08:30\", endTime: \"09:10\" },\n        { number: 2, startTime: \"09:15\", endTime: \"09:55\" },\n        { number: 3, startTime: \"10:15\", endTime: \"10:55\" },\n        { number: 4, startTime: \"11:00\", endTime: \"11:40\" },\n        { number: 5, startTime: \"11:45\", endTime: \"12:25\" },\n        { number: 6, startTime: \"13:15\", endTime: \"13:55\" },\n        { number: 7, startTime: \"14:00\", endTime: \"14:40\" },\n        { number: 8, startTime: \"14:45\", endTime: \"15:25\" },\n        { number: 9, startTime: \"15:45\", endTime: \"16:25\" },\n        { number: 10, startTime: \"16:30\", endTime: \"17:10\" },\n        { number: 11, startTime: \"17:15\", endTime: \"17:55\" },\n        { number: 12, startTime: \"19:30\", endTime: \"20:10\" },\n        { number: 13, startTime: \"20:15\", endTime: \"20:55\" },\n        { number: 14, startTime: \"21:00\", endTime: \"21:40\" },\n    ];\n};\n\n// 保存课程数据\nconst saveSchedule = async (courses, courseConfig, timeSlots) => {\n    try {\n        await Promise.allSettled([\n            window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(courseConfig)),\n            window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses)),\n            window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots))\n        ]);\n        \n        window.shiguangBridge.showToast(\"课程表导入成功！\");\n        return true;\n    } catch (error) {\n        console.error(\"保存课程数据时出错:\", error);\n        window.shiguangBridge.showToast(\"课程表导入失败：\" + error.message);\n        return false;\n    }\n};\n\n// 日期增加指定天数\nconst addDays = (dateStr, days) => {\n    const date = new Date(dateStr);\n    date.setDate(date.getDate() + days);\n    return date.toISOString().split('T')[0];\n};\n\n// 判断日期是否是周日（0=周日，1=周一，...，6=周六）\nconst isSunday = (dateStr) => {\n    const date = new Date(dateStr);\n    return date.getDay() === 0; // 0表示周日\n};\n\n// 获取多周课程表\nconst fetchMultiWeekTimetable = async (startDate) => {\n    const allCourses = [];\n    \n    //如果起始日期是周日，请求日期就-1\n    let requestDate = startDate;\n    if (isSunday(startDate)) {\n        requestDate = addDays(startDate, -1);\n    }\n    \n    let weekCount = 0;\n    let timeSlots = null;\n    \n    window.shiguangBridge.showToast(\"正在获取课程表数据，请稍候...\");\n    \n    while (true) {\n        weekCount++;\n        \n        try {\n            const { html, hasCourses } = await fetchTimetable(requestDate);\n            \n            if (weekCount === 1) {\n                timeSlots = getTimeSlots(html);\n            }\n            \n            const weekCourses = parseTimetableFromHTML(html, requestDate);\n            \n            if (weekCourses.length > 0) {\n                allCourses.push(...weekCourses);\n                console.log(`第${weekCount}周: 找到 ${weekCourses.length} 门课程`);\n            }\n            \n            if (!hasCourses) {\n                console.log(`第${weekCount}周: 没有课程，停止获取`);\n                break;\n            }\n            \n            requestDate = addDays(requestDate, 7);\n            \n            if (weekCount >= 20) {\n                console.log(\"达到最大周数限制（20周），停止获取\");\n                break;\n            }\n        } catch (error) {\n            console.error(`获取第${weekCount}周课程表失败:`, error);\n            window.shiguangBridge.showToast(`第${weekCount}周获取失败，继续下一周`);\n            requestDate = addDays(requestDate, 7);\n            continue;\n        }\n    }\n    \n    return {\n        courses: allCourses,\n        totalWeeks: weekCount,\n        timeSlots: timeSlots || getTimeSlots('')\n    };\n};\n\n// 主函数\n(async () => {\n    try {\n        window.shiguangBridge.showToast(\"正在启动GDIPU课程表导入...\");\n        \n        const startDate = await promptForStartDate();\n        \n        const { courses, totalWeeks, timeSlots } = await fetchMultiWeekTimetable(startDate);\n        \n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程信息\");\n            throw new Error(\"未找到课程信息\");\n        }\n        \n        console.log(`总共找到 ${courses.length} 门课程，共 ${totalWeeks} 周`);\n        \n        const courseConfig = getSemesterConfig(startDate, totalWeeks);\n        \n        const success = await saveSchedule(courses, courseConfig, timeSlots);\n        \n        if (success) {\n            window.shiguangBridge.notifyTaskCompletion();\n        } else {\n            throw new Error(\"保存课程数据失败\");\n        }\n        \n    } catch (error) {\n        console.error(\"导入课程表时出错:\", error);\n        window.shiguangBridge.showToast(\"导入课程表失败：\" + error.message);\n    }\n})();","HUALIXY_01":"// 广州华立学院(jw.hualixy.edu.cn) 拾光课程表适配脚本\n// 基于正方新一代教务系统接口适配\n// 维护者：小漫君(xiaomanjun233)\n// 出现问题请提issues或者提交pr更改,这更加快速\n//\n// 通过正方接口 xskbcx_cxXsgrkb 拉取个人课表 JSON（kbList），解析课程名、教师、教室、\n// 星期、节次和周次（含单双周）。集中实践课（军训、毕业设计等）无星期节次，直接忽略不导入。\n// 交互上自动读取教务系统的学年/学期下拉列表，用户只需依次点选即可，无需手动输入。\n// 通过 xskbcx_cxXskbcxIndex 读取学年学期选项、xskbcxZccx_cxZcByXnxq 取所选学期开学日期，\n// 并优先从 xskbcx_cxRjc 动态读取该校真实节次作息时间，读取失败时跳过作息导入。\n//\n// 使用方式：通过统一认证(https://jw.hualixy.edu.cn/sso/ddlogin)或正方直登\n// (https://jw.hualixy.edu.cn/jwglxt/xtgl/login_slogin.html)登录后，\n// 在教务系统(jw.hualixy.edu.cn/jwglxt)任意页面（如首页）直接执行导入即可，\n// 无需进入课表查询页面。脚本通过接口自动读取学年学期并获取课表与节次作息。\n\n// 正方新一代教务部分学校接口模块号可能不同，依次尝试常见模块号\nconst GNMKDMS = [\"N2151\", \"N253508\"];\n\n/**\n * 拼接教务系统接口地址。\n * 正方新一代部署在 /jwglxt 子路径下，接口路径必须带上该前缀；\n * 校外经 WebVPN 访问时路径还带有 /http/<hex> 前缀，需保留。\n */\nfunction buildApiUrl(modulePath, gnmkdm) {\n    const prefixMatch = window.location.pathname.match(/^\\/http\\/[0-9a-f]+/i);\n    const webvpnPrefix = prefixMatch ? prefixMatch[0] : \"\";\n    const gnmkdmQuery = gnmkdm ? \"?gnmkdm=\" + gnmkdm : \"\";\n    return window.location.origin + webvpnPrefix + \"/jwglxt\" + modulePath + gnmkdmQuery;\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n\n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return [];\n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) {\n            continue;\n        }\n\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n\n        const day = Number(rawCourse.xqj);\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        const course = {\n            name: String(rawCourse.kcmc).trim(),\n            teacher: String(rawCourse.xm || \"\").trim(),\n            position: String(rawCourse.cdmc || \"\").trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        };\n\n        finalCourseList.push(course);\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n\n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"广州华立学院课表导入\",\n        \"导入前请确保您已通过统一认证(jw.hualixy.edu.cn/sso/ddlogin)或正方直登登录教务系统；在任意页面直接执行导入即可，无需进入课表查询页面。\",\n        \"好的，开始导入\"\n    );\n}\n\n/**\n * 从教务系统课表查询页读取学年与学期下拉选项（多个模块号依次尝试）。\n */\nasync function fetchAcademicOptions() {\n    for (const gnmkdm of GNMKDMS) {\n        const url = buildApiUrl(\"/kbcx/xskbcx_cxXskbcxIndex.html\", gnmkdm);\n        try {\n            const response = await fetch(url, { method: \"GET\", credentials: \"include\" });\n            if (!response.ok) continue;\n            const htmlText = await response.text();\n            const doc = new DOMParser().parseFromString(htmlText, \"text/html\");\n\n            const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n                .filter((opt) => opt.value !== \"\")\n                .map((opt) => ({\n                    value: opt.value,\n                    text: opt.textContent.trim(),\n                    selected: opt.selected\n                }));\n            const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n                .filter((opt) => opt.value !== \"\")\n                .map((opt) => ({\n                    value: opt.value,\n                    text: opt.textContent.trim(),\n                    selected: opt.selected\n                }));\n\n            if (allYearOptions.length === 0 || semesterOptions.length === 0) continue;\n\n            const defaultSemesterIndex = (() => {\n                const i = semesterOptions.findIndex((opt) => opt.selected);\n                return i !== -1 ? i : 0;\n            })();\n\n            const selectedIndex = allYearOptions.findIndex((opt) => opt.selected);\n            if (selectedIndex === -1) {\n                return {\n                    yearOptions: allYearOptions.slice(0, 5),\n                    semesterOptions,\n                    defaultYearIndex: 0,\n                    defaultSemesterIndex\n                };\n            }\n\n            const start = Math.max(0, selectedIndex - 2);\n            const end = Math.min(allYearOptions.length, selectedIndex + 3);\n            return {\n                yearOptions: allYearOptions.slice(start, end),\n                semesterOptions,\n                defaultYearIndex: selectedIndex - start,\n                defaultSemesterIndex\n            };\n        } catch (e) {\n            console.warn(`JS: 读取学年学期失败(gnmkdm=${gnmkdm}):`, e);\n        }\n    }\n    return null;\n}\n\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确认登录状态有效。\");\n        return null;\n    }\n\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(yearOptions.map((item) => item.text)),\n        defaultYearIndex\n    );\n    if (yearIndex === null || yearIndex === -1) return null;\n    const academicYear = yearOptions[yearIndex].value;\n\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterOptions.map((item) => item.text)),\n        defaultSemesterIndex\n    );\n    if (semesterIndex === null || semesterIndex === -1) return null;\n\n    return {\n        academicYear,\n        semesterCode: semesterOptions[semesterIndex].value\n    };\n}\n\n/**\n * 获取所选学期的开学日期（第 1 周的日期）。\n */\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    for (const gnmkdm of GNMKDMS) {\n        const url = buildApiUrl(\"/kbcx/xskbcxZccx_cxZcByXnxq.html\", gnmkdm);\n        try {\n            const response = await fetch(url, {\n                method: \"POST\",\n                headers: { \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\" },\n                body: `xnm=${academicYear}&xqm=${semesterCode}`,\n                credentials: \"include\"\n            });\n\n            if (response.ok) {\n                const json = await response.json();\n                if (Array.isArray(json) && json.length > 0) {\n                    const firstWeekObj = json.find((item) => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n                    const matchStr = String(firstWeekObj.rq || firstWeekObj.zcrq || firstWeekObj.ksrq || \"\").match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (matchStr) return matchStr[1];\n                }\n            }\n        } catch (e) {\n            console.warn(`JS: 获取开学日期失败(gnmkdm=${gnmkdm}):`, e);\n        }\n    }\n    return null;\n}\n\n/**\n * 从正方系统动态获取该学期真实节次作息时间。\n * 读取失败返回 null，由调用方跳过作息导入（不写死未知作息）。\n */\nasync function fetchAndParseTimeSlots(academicYear, semesterCode) {\n    const requestBody = \"xnm=\" + encodeURIComponent(academicYear) +\n        \"&xqm=\" + encodeURIComponent(semesterCode) +\n        \"&kzlx=ck&xsdm=&kclbdm=&kclxdm=\";\n    let lastError = null;\n\n    for (const gnmkdm of GNMKDMS) {\n        const url = buildApiUrl(\"/kbcx/xskbcx_cxRjc.html\", gnmkdm);\n        try {\n            const response = await fetch(url, {\n                headers: {\n                    \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                    \"X-Requested-With\": \"XMLHttpRequest\",\n                },\n                body: requestBody,\n                method: \"POST\",\n                credentials: \"include\"\n            });\n            if (!response.ok) {\n                lastError = \"HTTP \" + response.status;\n                console.warn(`JS: 节次时间接口请求失败(gnmkdm=${gnmkdm})：HTTP ${response.status}`);\n                continue;\n            }\n\n            const responseText = await response.text();\n            const responsePreview = responseText.replace(/\\s+/g, \" \").trim().slice(0, 200) || \"<空响应>\";\n\n            let data;\n            try {\n                data = JSON.parse(responseText);\n            } catch (e) {\n                lastError = \"非 JSON：响应=\" + responsePreview;\n                console.warn(`JS: 节次时间接口未返回 JSON(gnmkdm=${gnmkdm}):`, e);\n                continue;\n            }\n\n            if (data && !Array.isArray(data) && Array.isArray(data.data)) {\n                data = data.data;\n            }\n            if (!Array.isArray(data)) {\n                lastError = \"格式异常：响应=\" + responsePreview;\n                console.warn(`JS: 节次时间接口返回格式异常(gnmkdm=${gnmkdm}): ${responsePreview}`);\n                continue;\n            }\n\n            const timeSlots = [];\n            for (const item of data) {\n                if (!item || typeof item !== \"object\") continue;\n                const number = Number(item.jcdm != null ? item.jcdm : item.jcmc);\n                let startTime = \"\";\n                let endTime = \"\";\n                if (item.qssj != null && item.jssj != null) {\n                    startTime = String(item.qssj).trim();\n                    endTime = String(item.jssj).trim();\n                } else if (item.sksj) {\n                    const sksjParts = String(item.sksj).split(/[~\\-—至到]/);\n                    if (sksjParts.length >= 2) {\n                        startTime = sksjParts[0].trim();\n                        endTime = sksjParts[1].trim();\n                    }\n                }\n                startTime = startTime.slice(0, 5);\n                endTime = endTime.slice(0, 5);\n                if (!(number > 0) || !startTime || !endTime) continue;\n\n                timeSlots.push({ number, startTime, endTime });\n            }\n\n            timeSlots.sort((a, b) => a.number - b.number);\n            if (timeSlots.length === 0) {\n                lastError = \"无有效数据：响应=\" + responsePreview;\n                console.warn(`JS: 节次时间接口未返回有效作息时间(gnmkdm=${gnmkdm}): ${responsePreview}`);\n                continue;\n            }\n\n            console.log(`JS: 获取到真实节次作息 ${timeSlots.length} 条(gnmkdm=${gnmkdm})，第1节 ${timeSlots[0].startTime}-${timeSlots[0].endTime}`);\n            return timeSlots;\n        } catch (error) {\n            lastError = error.message || String(error);\n            console.warn(`JS: 获取节次作息时间失败(gnmkdm=${gnmkdm}):`, error);\n        }\n    }\n\n    console.warn(\"JS: 所有节次时间接口尝试均失败，最后原因：\" + lastError);\n    return null;\n}\n\n/**\n * 计算课表配置。只在能拿到真实开学日期时返回配置，否则返回 null 由调用方跳过。\n */\nfunction buildCourseConfig(courses, startDate, firstDayOfWeek) {\n    if (!startDate) return null;\n\n    let maxWeek = 0;\n    for (const course of courses) {\n        for (const week of course.weeks) {\n            if (week > maxWeek) maxWeek = week;\n        }\n    }\n\n    return {\n        semesterStartDate: startDate,\n        semesterTotalWeeks: Math.max(maxWeek, 20),\n        firstDayOfWeek: firstDayOfWeek\n    };\n}\n\n/**\n * 请求和解析课程数据。并行拉取课表 JSON 与所选学期开学日期。\n */\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    const body = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    let lastError = null;\n\n    for (const gnmkdm of GNMKDMS) {\n        const url = buildApiUrl(\"/kbcx/xskbcx_cxXsgrkb.html\", gnmkdm);\n        try {\n            const [courseResponse, startDate] = await Promise.all([\n                fetch(url, {\n                    method: \"POST\",\n                    headers: { \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\" },\n                    body,\n                    credentials: \"include\"\n                }),\n                fetchSemesterStartDate(academicYear, semesterCode)\n            ]);\n\n            if (!courseResponse.ok) {\n                lastError = `网络请求失败。状态码: ${courseResponse.status} (${courseResponse.statusText})`;\n                console.warn(`JS: 课程请求失败(gnmkdm=${gnmkdm})：${lastError}`);\n                continue;\n            }\n\n            const jsonText = await courseResponse.text();\n            if (jsonText.indexOf(\"登录\") !== -1 && jsonText.indexOf(\"密码\") !== -1) {\n                lastError = \"课表接口返回了登录页面，登录会话已失效\";\n                console.warn(`JS: ${lastError}(gnmkdm=${gnmkdm})`);\n                continue;\n            }\n\n            let jsonData;\n            try {\n                jsonData = JSON.parse(jsonText);\n            } catch (e) {\n                lastError = \"数据返回格式错误\";\n                console.warn(`JS: JSON 解析失败(gnmkdm=${gnmkdm}):`, e);\n                continue;\n            }\n\n            const courses = parseJsonData(jsonData);\n            if (courses.length === 0) {\n                window.shiguangBridge.showToast(\"未找到任何课程数据，请确认登录状态有效（非停留在登录页）、所选学年学期正确，或本学期无课。\");\n                return null;\n            }\n\n            console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程(gnmkdm=${gnmkdm})。`);\n\n            const rawFirstDay = Number(jsonData.qsxqj);\n            const firstDayOfWeek = (rawFirstDay >= 1 && rawFirstDay <= 7) ? rawFirstDay : 1;\n\n            return { courses, startDate, firstDayOfWeek };\n        } catch (error) {\n            lastError = error.message;\n            console.warn(`JS: Fetch/Parse Error(gnmkdm=${gnmkdm}):`, error);\n        }\n    }\n\n    window.shiguangBridge.showToast(`请求或解析失败: ${lastError}`);\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\nasync function saveCourseConfigIfPossible(courses, startDate, firstDayOfWeek) {\n    const config = buildCourseConfig(courses, startDate, firstDayOfWeek);\n    if (!config) {\n        window.shiguangBridge.showToast(\"未取到本学期开学日期，已跳过课表配置，请在应用内手动设置开学日期。\");\n        return;\n    }\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`开学日期 ${config.semesterStartDate}，总周数 ${config.semesterTotalWeeks} 周。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n}\n\nasync function importPresetTimeSlots(timeSlots) {\n    if (!timeSlots || timeSlots.length === 0) {\n        window.shiguangBridge.showToast(\"未能读取该校真实作息时间，已跳过作息导入，请手动设置节次时间或其他节次时段。\");\n        return;\n    }\n    window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        console.error('JS: Save Time Slots Error:', error);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (selection === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n    console.log(`JS: 已选择学年学期: ${selection.academicYear}/${selection.semesterCode}`);\n\n    const result = await fetchAndParseCourses(selection.academicYear, selection.semesterCode);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, startDate, firstDayOfWeek } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n\n    await saveCourseConfigIfPossible(courses, startDate, firstDayOfWeek);\n\n    const timeSlots = await fetchAndParseTimeSlots(selection.academicYear, selection.semesterCode);\n    await importPresetTimeSlots(timeSlots);\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","XHSYSU_01":"// 广州新华学院 (xhsysu.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统V9标准接口适配（CAS SSO版）\n// 课表 POST /kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151   校历 POST /kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\n// 校内直连前缀为空；经 WebVPN 时路径带 /http/<hex> 前缀，需保留\n\n// 校内统一作息（14 节，40 分钟一节，08:20 起），来源：教务处「上课时间段一览表」\nconst XHSYSU_TIME_SLOTS = [\n    { number: 1, startTime: \"08:20\", endTime: \"09:00\" },\n    { number: 2, startTime: \"09:10\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:50\" },\n    { number: 4, startTime: \"11:00\", endTime: \"11:40\" },\n    { number: 5, startTime: \"11:50\", endTime: \"12:30\" },\n    { number: 6, startTime: \"12:40\", endTime: \"13:20\" },\n    { number: 7, startTime: \"13:30\", endTime: \"14:10\" },\n    { number: 8, startTime: \"14:20\", endTime: \"15:00\" },\n    { number: 9, startTime: \"15:10\", endTime: \"15:50\" },\n    { number: 10, startTime: \"16:10\", endTime: \"16:50\" },\n    { number: 11, startTime: \"17:00\", endTime: \"17:40\" },\n    { number: 12, startTime: \"19:00\", endTime: \"19:40\" },\n    { number: 13, startTime: \"19:50\", endTime: \"20:30\" },\n    { number: 14, startTime: \"20:40\", endTime: \"21:20\" }\n];\n\n// 校内直连前缀为空，WebVPN 需保留 /http/<hex>，否则变成跨域请求\nfunction apiUrl(path) {\n    const prefix = window.location.pathname.match(/^\\/http\\/[0-9a-f]+/i);\n    return window.location.origin + (prefix ? prefix[0] : \"\") + path;\n}\n\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n    // 排序键里 weeks 必须先于 startSection，否则同节次不同周次的记录会插进来打断连续节次\n    list.sort((a, b) => a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) || (a.day || 0) - (b.day || 0) ||\n        a.weeks.join(',').localeCompare(b.weeks.join(',')) || (a.startSection || 0) - (b.startSection || 0));\n    const step1 = [];\n    let cur = list[0];\n    for (let i = 1; i < list.length; i++) {\n        const nxt = list[i];\n        const same = cur.name === nxt.name && cur.teacher === nxt.teacher && cur.position === nxt.position &&\n            cur.day === nxt.day && cur.weeks.join(',') === nxt.weeks.join(',');\n        if (same && cur.endSection + 1 === nxt.startSection) cur.endSection = nxt.endSection;\n        else if (same && cur.startSection === nxt.startSection && cur.endSection === nxt.endSection) continue;\n        else { step1.push(cur); cur = nxt; }\n    }\n    step1.push(cur);\n    // 再按节次排序，把同节次不同周次的记录并到一起\n    step1.sort((a, b) => a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n        a.position.localeCompare(b.position) || (a.day || 0) - (b.day || 0) ||\n        (a.startSection || 0) - (b.startSection || 0) || (a.endSection || 0) - (b.endSection || 0));\n    const step2 = [];\n    cur = step1[0];\n    for (let i = 1; i < step1.length; i++) {\n        const nxt = step1[i];\n        if (cur.name === nxt.name && cur.teacher === nxt.teacher && cur.position === nxt.position &&\n            cur.day === nxt.day && cur.startSection === nxt.startSection && cur.endSection === nxt.endSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else { step2.push(cur); cur = nxt; }\n    }\n    step2.push(cur);\n    return step2.sort((a, b) => a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name));\n}\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    const text = String(weekStr);\n    const keepOdd = text.includes(\"单\");\n    const keepEven = text.includes(\"双\");\n    const weeks = [];\n    // \"周/单/双/第\"与括号统一换成分隔符，剩下的就是纯数字或\"起-止\"\n    for (const part of text.replace(/[单双第周()（）]/g, \",\").split(\",\")) {\n        const [from, to] = part.split(\"-\").map(Number);\n        if (!from) continue;\n        for (let w = from; w <= (to || from); w++) {\n            if (keepOdd && w % 2 === 0) continue;\n            if (keepEven && w % 2 !== 0) continue;\n            weeks.push(w);\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) return [];\n    const list = [];\n    for (const c of jsonData.kbList) {\n        if (!c.kcmc || !c.xqj || !c.jcs || !c.zcd) continue;\n        const weeks = parseWeeks(c.zcd);\n        if (!weeks.length) continue;\n        const parts = c.jcs.split('-');\n        const startSection = Number(parts[0]);\n        const endSection = Number(parts[parts.length - 1]);\n        const day = Number(c.xqj);\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) continue;\n        // cdmc 返回\"未排地点\"时不是真实教室，置空\n        const position = String(c.cdmc || \"\").trim();\n        list.push({\n            name: c.kcmc.trim(),\n            teacher: String(c.xm || \"\").trim(),\n            position: position === \"未排地点\" ? \"\" : position,\n            day, startSection, endSection, weeks\n        });\n    }\n    return mergeAndDistinctCourses(list);\n}\n\n// CAS 入口为 /lyuapServer/login，登录后跳 /sso/lyiotlogin，WebVPN 下路径含 /http/<hex>\nfunction isLoginPage() {\n    return window.location.href.includes(\"lyuapServer/login\") ||\n        window.location.pathname.endsWith(\"/sso/lyiotlogin\");\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\", \"导入前请确保您已在浏览器中成功登录广州新华学院教务系统\", \"好的，开始导入\");\n}\n\nasync function fetchAcademicOptions() {\n    try {\n        const resp = await fetch(apiUrl(\"/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151\"), { method: \"GET\", credentials: \"include\" });\n        if (!resp.ok) return null;\n        const doc = new DOMParser().parseFromString(await resp.text(), \"text/html\");\n        const read = sel => Array.from(doc.querySelectorAll(sel + \" option\")).filter(o => o.value !== \"\")\n            .map(o => ({ value: o.value, text: o.textContent.trim(), selected: o.hasAttribute(\"selected\") }));\n        const years = read(\"#xnm\"), semesters = read(\"#xqm\");\n        if (!years.length || !semesters.length) return null;\n        // 学年过多，只取当前选中项前后各 2 项\n        const selIdx = years.findIndex(o => o.selected);\n        const start = Math.max(0, (selIdx === -1 ? 0 : selIdx) - 2);\n        return {\n            yearOptions: years.slice(start, Math.min(years.length, (selIdx === -1 ? 0 : selIdx) + 3)),\n            semesterOptions: semesters,\n            defaultYearIndex: selIdx === -1 ? 0 : selIdx - start,\n            defaultSemesterIndex: Math.max(0, semesters.findIndex(o => o.selected))\n        };\n    } catch (e) { return null; }\n}\n\nasync function selectAcademicYearAndSemester() {\n    const data = await fetchAcademicOptions();\n    if (!data) { window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保已登录。\"); return null; }\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = data;\n    const yearIdx = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\", JSON.stringify(yearOptions.map(o => o.text)), defaultYearIndex);\n    if (yearIdx === null || yearIdx === -1) return null;\n    const semIdx = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify(semesterOptions.map(o => o.text)), defaultSemesterIndex);\n    if (semIdx === null || semIdx === -1) return null;\n    return { academicYear: yearOptions[yearIdx].value, semesterCode: semesterOptions[semIdx].value };\n}\n\n// 校历接口：按周返回数组，zs=周次，rq=该周起止(\"2026-08-31/2026-09-06\")\n// 第 1 周周一即开学日期，数组长度为该学期总周数\nasync function fetchSemesterWeeks(academicYear, semesterCode) {\n    try {\n        const resp = await fetch(apiUrl(\"/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\"), {\n            method: \"POST\",\n            headers: {\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: `xnm=${academicYear}&xqm=${semesterCode}`,\n            credentials: \"include\"\n        });\n        if (!resp.ok) return null;\n        const json = JSON.parse(await resp.text());\n        if (!Array.isArray(json) || !json.length) return null;\n        const first = json.find(i => Number(i.zs) === 1) || json[0];\n        const startDate = String(first.rq || \"\").split(\"/\")[0].trim();\n        if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(startDate)) return null;\n        return { startDate, totalWeeks: json.length };\n    } catch (e) { return null; }\n}\n\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n    const [resp, weeks] = await Promise.all([\n        fetch(apiUrl(\"/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\"), {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" },\n            body: `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`,\n            credentials: \"include\"\n        }),\n        fetchSemesterWeeks(academicYear, semesterCode)\n    ]);\n    try {\n        if (!resp.ok) throw new Error(\"状态码 \" + resp.status);\n        const courses = parseJsonData(JSON.parse(await resp.text()));\n        if (!courses.length) throw new Error(\"未找到课程数据，请确认所选学年学期正确或教务需要二次登录。\");\n        // 校历周数可能少于课程实际最大周次（实测达 18 周），取较大者避免高位周次被截断\n        const maxWeek = Math.max(...courses.flatMap(c => c.weeks));\n        return {\n            courses,\n            config: weeks ? {\n                semesterStartDate: weeks.startDate,\n                semesterTotalWeeks: Math.max(weeks.totalWeeks, maxWeek)\n            } : null\n        };\n    } catch (e) {\n        window.shiguangBridge.showToast(\"导入失败：\" + e.message);\n        console.error(\"JS: Import Error\", e);\n        return null;\n    }\n}\n\nasync function saveCourses(courses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        return true;\n    } catch (e) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + e.message);\n        return false;\n    }\n}\n\n// 应用侧 saveCourseConfig 是整体覆盖，不传 semesterStartDate 会清空用户已设的开学日期，所以只在拿到校历时写入\nasync function saveConfig(config) {\n    if (!config) {\n        window.shiguangBridge.showToast(\"未取到开学日期，已跳过课表配置，请在应用内手动设置。\");\n        return;\n    }\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`开学日期 ${config.semesterStartDate}，共 ${config.semesterTotalWeeks} 周。`);\n    } catch (e) {\n        window.shiguangBridge.showToast(\"课表配置保存失败: \" + e.message);\n    }\n}\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        return;\n    }\n    if (!await promptUserToStart()) { window.shiguangBridge.showToast(\"用户取消了导入。\"); return; }\n    const sel = await selectAcademicYearAndSemester();\n    if (!sel) { window.shiguangBridge.showToast(\"未选择学年学期，导入终止。\"); return; }\n    const result = await fetchAndParseCourses(sel.academicYear, sel.semesterCode);\n    if (!result) return;\n    if (!await saveCourses(result.courses)) return;\n    await saveConfig(result.config);\n    try { await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(XHSYSU_TIME_SLOTS)); } catch (e) {}\n    window.shiguangBridge.showToast(\"课程导入成功，共导入 \" + result.courses.length + \" 门课程！\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","GZST":"// 广州松田职业技术学院(gzst.edu.cn)拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 预设节次时间\nconst TimeSlots = [\n    { \"number\": 1, \"startTime\": \"08:20\", \"endTime\": \"09:00\" },\n    { \"number\": 2, \"startTime\": \"09:05\", \"endTime\": \"09:45\" }, \n    { \"number\": 3, \"startTime\": \"09:55\", \"endTime\": \"10:35\" }, \n    { \"number\": 4, \"startTime\": \"10:45\", \"endTime\": \"11:25\" },\n    { \"number\": 5, \"startTime\": \"11:30\", \"endTime\": \"12:10\" }, \n    { \"number\": 6, \"startTime\": \"14:20\", \"endTime\": \"15:00\" },\n    { \"number\": 7, \"startTime\": \"15:05\", \"endTime\": \"15:45\" }, \n    { \"number\": 8, \"startTime\": \"15:55\", \"endTime\": \"16:35\" },\n    { \"number\": 9, \"startTime\": \"16:45\", \"endTime\": \"17:25\" }, \n    { \"number\": 10, \"startTime\": \"17:30\", \"endTime\": \"18:10\" }, \n    { \"number\": 11, \"startTime\": \"19:30\", \"endTime\": \"20:35\" }, \n    { \"number\": 12, \"startTime\": \"20:35\", \"endTime\": \"21:40\" }\n];\n\n// 课表配置\nconst CourseConfig = {\n    \"semesterTotalWeeks\": 20 \n};\n\n/**\n * 验证周次字符串并转换为数字数组\n * 同时移除周次字符串中的节次信息，因为它可能会干扰周次解析。\n * @param {string} weeksStr 课表中的周次字符串，如 \"5-15,17(周)[02-03节]\"\n * @returns {number[]} 周数数组\n */\nfunction parseWeeks(weeksStr) {\n    const weeks = [];\n    if (!weeksStr) return weeks;\n    // 移除括号内的内容（如 (周)）、[节次] 和 HTML 标签\n    const cleanedStr = weeksStr.replace(/\\(周\\)|\\[.*?节\\]|<\\/?[a-z]+[^>]*>/ig, '').trim(); \n    if (cleanedStr === '') return weeks;\n\n    cleanedStr.split(',').forEach(part => {\n        const rangeMatch = part.match(/^(\\d+)-(\\d+)$/);\n        if (rangeMatch) {\n            const start = parseInt(rangeMatch[1]);\n            const end = parseInt(rangeMatch[2]);\n            for (let i = start; i <= end; i++) {\n                weeks.push(i);\n            }\n        } else {\n            const singleWeek = parseInt(part);\n            if (!isNaN(singleWeek)) {\n                weeks.push(singleWeek);\n            }\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 从周次/节次字符串中提取节次范围\n * 修正了多节连排（如 [07-08-09-10节]）只识别到中间节次的问题。\n * @param {string} weeksSectionStr 包含节次信息的字符串\n * @returns {{start: number, end: number} | null} 节次范围对象\n */\nfunction parseSectionsFromStr(weeksSectionStr) {\n    // 匹配 [XX-XX节] 或 [XX节] 或 [XX-XX-XX节] 的完整内容\n    const fullContentMatch = weeksSectionStr.match(/\\[(\\d+(?:-\\d+)*)节\\]/i); \n    \n    if (fullContentMatch) {\n        const numberString = fullContentMatch[1]; // 例如: \"07-08-09-10\" 或 \"09-10\" 或 \"10\"\n        \n        // 分割所有数字\n        const numbers = numberString.split('-').map(n => parseInt(n));\n        \n        // 确保数字是有效的\n        if (numbers.length > 0 && !isNaN(numbers[0])) {\n            const start = numbers[0];\n            // 结束节次是数组中的最后一个有效数字\n            const end = numbers[numbers.length - 1]; \n\n            if (start > 0 && end > 0) {\n                // 确保 end >= start\n                return {\n                    start: Math.min(start, end),\n                    end: Math.max(start, end)\n                };\n            }\n        }\n    }\n    return null;\n}\n\n\n// 核心解析函数 (parseCourseTable)\nfunction parseCourseTable(htmlContent) {\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(htmlContent, \"text/html\");\n    const courseList = [];\n\n    const table = doc.getElementById('kbtable');\n    if (!table) {\n        window.shiguangBridge.showToast(\"错误：未找到课表表格 (id=kbtable)。\");\n        return [];\n    }\n    \n    const rows = table.querySelectorAll('tr');\n    \n    for (let i = 1; i < rows.length; i++) {\n        const row = rows[i];\n        \n        const cells = row.querySelectorAll('td');\n\n        for (let j = 0; j < cells.length; j++) {\n            const cell = cells[j];\n            const dayOfWeek = j + 1;\n            \n            const detailDiv = cell.querySelector('div[class*=\"kbcontent\"][style*=\"display: none\"]'); \n            \n            if (!detailDiv) continue; \n\n            const rawContent = detailDiv.innerHTML.trim();\n            // 过滤空内容\n            if (rawContent === '' || rawContent.replace(/&nbsp;|<[^>]*>/ig, '').trim() === '') continue; \n\n            // 多个课程块以分隔符处理\n            const courseBlocks = rawContent.split('---------------------<br>');\n            \n            courseBlocks.forEach(blockHtml => {\n                if (blockHtml.trim() === '') return;\n                \n                const cleanedBlock = blockHtml.replace(/<br\\/?>/gi, '\\n').trim(); \n                \n                // 提取课程名 (第一行)\n                const nameMatch = cleanedBlock.match(/^(.*?)(?:\\<span.*?\\/span\\>)?\\n/i); \n                let name = (nameMatch && nameMatch[1].trim()) || \"未知课程\";\n                // 移除课程名中的 span 或其他标签\n                name = name.replace(/<span[^>]*>.*?<\\/span>|<\\/?[a-z]+[^>]*>/ig, '').trim(); \n                \n                // 提取教师\n                const teacherMatch = cleanedBlock.match(/<font title=\"老师\">([^<]+?)<\\/font>/i);\n                const teacher = (teacherMatch && teacherMatch[1].trim()) || \"暂无教师\";\n\n                // 提取地点\n                const positionMatch = cleanedBlock.match(/<font title=\"教室\">([^<]+?)<\\/font>/i);\n                const position = (positionMatch && positionMatch[1].trim()) || \"暂无教室\";\n\n                // 提取周次和节次字符串\n                const weeksSectionMatch = cleanedBlock.match(/<font title=\"周次\\(节次\\)\">([^<]+?)<\\/font>/i);\n                const weeksSectionStr = (weeksSectionMatch && weeksSectionMatch[1].trim()) || \"\";\n\n                const sections = parseSectionsFromStr(weeksSectionStr);\n                if (!sections) {\n                    return; \n                }\n                \n                // 解析周次数组\n                const weeksArray = parseWeeks(weeksSectionStr);\n                if (weeksArray.length === 0) {\n                    return; // 周次为空，跳过\n                }\n\n                const course = {\n                    name: name,\n                    teacher: teacher,\n                    position: position,\n                    day: dayOfWeek,             // 周几 (1-7)\n                    startSection: sections.start, // 准确的开始节次\n                    endSection: sections.end,   // 准确的结束节次\n                    weeks: weeksArray           // 周次数组\n                };\n                \n                courseList.push(course);\n            });\n        }\n    }\n    \n    return courseList;\n}\n\n/**\n * 修正后的合并逻辑：先进行精确去重，再合并连续的课程节次。\n * @param {Array} courses 课程列表\n * @returns {Array} 去重并合并后的课程列表\n */\nfunction mergeCourses(courses) {\n    if (!courses || courses.length === 0) {\n        return [];\n    }\n    \n    // 1. 排序：确保同一天、同一周次、完全相同的课程和连续的课程都排在一起\n    courses.sort((a, b) => {\n        if (a.day !== b.day) return a.day - b.day;\n        const weekA = JSON.stringify(a.weeks);\n        const weekB = JSON.stringify(b.weeks);\n        if (weekA !== weekB) return weekA.localeCompare(weekB);\n        return a.startSection - b.startSection;\n    });\n    \n    // 2. 精确去重\n    const uniqueCourses = [];\n    const courseSet = new Set(); \n    \n    for (const course of courses) {\n        // 创建一个包含所有关键属性的唯一 Key\n        const key = `${course.name}|${course.teacher}|${course.position}|${course.day}|${course.startSection}|${course.endSection}|${JSON.stringify(course.weeks)}`;\n        \n        if (!courseSet.has(key)) {\n            courseSet.add(key);\n            uniqueCourses.push(course);\n        }\n    }\n\n    if (uniqueCourses.length <= 1) {\n        return uniqueCourses;\n    }\n\n    // 3. 连续课程合并逻辑\n    const mergedCourses = [];\n    let currentMergedCourse = { ...uniqueCourses[0] }; \n\n    for (let i = 1; i < uniqueCourses.length; i++) {\n        const nextCourse = uniqueCourses[i];\n\n        const isSameDay = nextCourse.day === currentMergedCourse.day;\n        const isSameWeeks = JSON.stringify(nextCourse.weeks) === JSON.stringify(currentMergedCourse.weeks);\n        const isSameName = nextCourse.name === currentMergedCourse.name;\n        const isSameTeacher = nextCourse.teacher === currentMergedCourse.teacher;\n        const isSamePosition = nextCourse.position === currentMergedCourse.position;\n        \n        // 检查是否连续 (下一节的开始 = 当前节的结束 + 1)\n        const isConsecutive = nextCourse.startSection === currentMergedCourse.endSection + 1;\n\n        const canMerge = isSameDay && isSameWeeks && isSameName && isSameTeacher && isSamePosition && isConsecutive;\n\n        if (canMerge) {\n            // 合并：更新结束节次\n            currentMergedCourse.endSection = nextCourse.endSection;\n        } else {\n            // 无法合并：推入当前合并结果，并开始新的合并\n            mergedCourses.push(currentMergedCourse);\n            currentMergedCourse = { ...nextCourse };\n        }\n    }\n    // 推入最后一次合并的结果\n    mergedCourses.push(currentMergedCourse);\n    \n    return mergedCourses;\n}\n\n\n// 网络请求函数\nasync function fetchCourseHtml() {\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    const URL = \"https://jw.educationgroup.cn/gzstzyxy_jsxsd/xskb/xskb_list.do\";\n    try {\n        const response = await fetch(URL, {\n            \"method\": \"GET\",\n            \"credentials\": \"include\"\n        });\n        \n        if (!response.ok) {\n            throw new Error(`网络请求失败，状态码: ${response.status}`);\n        }\n        \n        const text = await response.text();\n        \n        window.shiguangBridge.showToast(\"课表数据获取成功，开始解析...\");\n        return text;\n    } catch (error) {\n        window.shiguangBridge.showToast(`网络请求异常: ${error.message}`);\n        return null;\n    }\n}\n\n\nasync function importPresetTimeSlots() {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TimeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        return false; \n    }\n}\n\nasync function saveConfig() {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(CourseConfig));\n        window.shiguangBridge.showToast(\"课表配置更新成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存配置失败: \" + error.message);\n        return false;\n    }\n}\n\nasync function saveCourses(parsedCourses, originalCount, mergedCount) {\n    if (parsedCourses.length === 0) {\n        window.shiguangBridge.showToast(\"未解析到任何课程数据，跳过保存。\");\n        return true;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        if (originalCount !== undefined && mergedCount !== undefined) {\n             window.shiguangBridge.showToast(`课程导入成功！原始 ${originalCount} 条，去重合并 ${mergedCount} 条，最终导入 ${parsedCourses.length} 条。`);\n        } else {\n             window.shiguangBridge.showToast(`成功导入 ${parsedCourses.length} 条课程！`);\n        }\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`保存失败: ${error.message}`);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    \n    const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n        \"开始导入\",\n        \"请确保您已登录教务系统，即将获取课表数据并进行课程去重和合并。\",\n        \"确定\"\n    );\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    // 获取 HTML\n    const htmlContent = await fetchCourseHtml();\n    if (htmlContent === null) {\n        window.shiguangBridge.showToast(\"导入终止。\");\n        return; \n    }\n    \n    // 解析课程数据\n    let parsedCourses = parseCourseTable(htmlContent);\n    \n    if (parsedCourses.length === 0) {\n        window.shiguangBridge.showToast(\"解析失败或未发现有效课程。导入终止。\");\n        return;\n    }\n    \n    const originalCourseCount = parsedCourses.length;\n\n    // 课程去重和合并\n    parsedCourses = mergeCourses(parsedCourses);\n    const mergedCount = originalCourseCount - parsedCourses.length; \n\n    // 导入时间段数据\n    await importPresetTimeSlots(); \n\n    // 导入课表配置\n    if (!await saveConfig()) return;\n\n    // 课程数据保存，并传入合并信息\n    if (!await saveCourses(parsedCourses, originalCourseCount, mergedCount)) return;\n\n    // 流程成功\n    window.shiguangBridge.showToast(\"所有任务已完成！课表已导入成功！\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动导入流程\nrunImportFlow();","GZMTU_01":"// 广州航海学院(gzmtu.edu.cn) 拾光课程表适配脚本\n\n\n/**\n * 节次与周次合并去重函数 \n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n    const step1Merged = [];\n    let current = list[0];\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n        const isSameCourseAndWeeks =\n            current.name === next.name && current.teacher === next.teacher &&\n            current.position === next.position && current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n    const step2Merged = [];\n    let cur = step1Merged[0];\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n        const isSameCourseAndSection =\n            cur.name === nxt.name && cur.teacher === nxt.teacher &&\n            cur.position === nxt.position && cur.day === nxt.day &&\n            cur.startSection === nxt.startSection && cur.endSection === nxt.endSection;\n        if (isSameCourseAndSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n    return step2Merged;\n}\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    const weekSets = weekStr.split(/[,，]/);\n    let weeks = [];\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周?/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周?/);\n        let start = 0, end = 0, processed = false;\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) return [];\n    const initialCourseList = [];\n    for (const rawCourse of jsonData.kbList) {\n        const courseName = rawCourse.kcmc || rawCourse.kcmc_raw;\n        const teacher = rawCourse.xm || \"\";\n        const position = rawCourse.cdmc || rawCourse.cd_id || \"\";\n        const day = Number(rawCourse.xqj);\n        const zcd = rawCourse.zcd;\n        const jcStr = rawCourse.jcor || rawCourse.jcs || rawCourse.jc;\n        if (!courseName || !day || !zcd || !jcStr) continue;\n        const weeksArray = parseWeeks(zcd);\n        if (weeksArray.length === 0) continue;\n        const sectionParts = jcStr.split('-').map(Number).filter(n => !isNaN(n));\n        if (sectionParts.length === 0) continue;\n        const startSection = Math.min(...sectionParts);\n        const endSection = Math.max(...sectionParts);\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) continue;\n        initialCourseList.push({\n            name: courseName.trim(),\n            teacher: teacher.trim(),\n            position: position.trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n    return mergeAndDistinctCourses(initialCourseList);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"广州航海学院教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function fetchAcademicOptions() {\n    // 移动端强化：增加 layout=default 强制正方返回 PC 版结构，避免移动版精简页面丢失选项\n    const url = window.location.origin + \"/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default\";\n    try {\n        const response = await fetch(url, { method: \"GET\", credentials: \"include\" });\n        if (!response.ok) return null;\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n        \n        const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({ value: opt.value, text: opt.textContent.trim(), selected: opt.selected }));\n        \n        const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({ value: opt.value, text: opt.textContent.trim(), selected: opt.selected }));\n            \n        if (allYearOptions.length === 0 || semesterOptions.length === 0) return null;\n        \n        const selectedIndex = allYearOptions.findIndex(opt => opt.selected);\n        if (selectedIndex === -1) {\n            return {\n                yearOptions: allYearOptions.slice(0, 5),\n                semesterOptions,\n                defaultYearIndex: 0,\n                defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1 ? semesterOptions.findIndex(opt => opt.selected) : 0\n            };\n        }\n        \n        const start = Math.max(0, selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex + 3);\n        const yearOptions = allYearOptions.slice(start, end);\n        const newDefaultIndex = selectedIndex - start;\n        const defaultSemesterIndex = semesterOptions.findIndex(opt => opt.selected);\n        \n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: newDefaultIndex,\n            defaultSemesterIndex: defaultSemesterIndex !== -1 ? defaultSemesterIndex : 0\n        };\n    } catch (e) {\n        return null;\n    }\n}\n\nasync function selectAcademicYearAndSemester() {\n    let optionsData = await fetchAcademicOptions();\n    \n    // 移动端强化兜底：如果 API 被移动端拦截或页面解析失败，智能生成本学年的默认选项\n    if (!optionsData) {\n        const d = new Date();\n        const year = d.getMonth() >= 7 ? d.getFullYear() : d.getFullYear() - 1;\n        const isFirstSemester = d.getMonth() >= 7;\n        optionsData = {\n            yearOptions: [\n                { value: (year - 1).toString(), text: `${year - 1}-${year}` },\n                { value: year.toString(), text: `${year}-${year + 1}` },\n                { value: (year + 1).toString(), text: `${year + 1}-${year + 2}` }\n            ],\n            semesterOptions: [\n                { value: \"3\", text: \"第一学期\" },\n                { value: \"12\", text: \"第二学期\" }\n            ],\n            defaultYearIndex: 1,\n            defaultSemesterIndex: isFirstSemester ? 0 : 1\n        };\n        window.shiguangBridge.showToast(\"页面获取失败，已切换为智能学年预测\");\n    }\n\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\", JSON.stringify(yearOptions.map(item => item.text)), defaultYearIndex\n    );\n    if (yearIndex === null || yearIndex === -1) return null;\n    \n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify(semesterOptions.map(item => item.text)), defaultSemesterIndex\n    );\n    if (semesterIndex === null || semesterIndex === -1) return null;\n    \n    return {\n        academicYear: yearOptions[yearIndex].value,\n        semesterCode: semesterOptions[semesterIndex].value\n    };\n}\n\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = window.location.origin + \"/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\";\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}`;\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n        if (response.ok) {\n            const jsonText = await response.text();\n            let json;\n            try { json = JSON.parse(jsonText); } catch(e) { return null; }\n            if (Array.isArray(json) && json.length > 0) {\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) return startDateStr;\n                }\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n                if (firstWeekObj.ksrq) {\n                    const match = firstWeekObj.ksrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {}\n    return null;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const targetUrl = window.location.origin + \"/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n    const backupUrl = window.location.origin + \"/jwglxt/kbcx/xskbcx_cxXsKb.html?gnmkdm=N2151\";\n\n    const [courseResponse, semesterStartDate] = await Promise.all([\n        fetch(targetUrl, {\n            method: \"POST\",\n            headers: {\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        }).catch(() => null),\n        fetchSemesterStartDate(academicYear, semesterCode)\n    ]);\n\n    try {\n        let resp = courseResponse;\n        if (!resp || !resp.ok) {\n            resp = await fetch(backupUrl, {\n                method: \"POST\",\n                headers: {\n                    \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                    \"x-requested-with\": \"XMLHttpRequest\"\n                },\n                body: requestBody,\n                credentials: \"include\"\n            });\n        }\n        if (resp && resp.ok) {\n            const jsonText = await resp.text();\n            const jsonData = JSON.parse(jsonText);\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    let maxWeek = 0;\n                    for (const c of parsedCourses) {\n                        for (const w of c.weeks) {\n                            if (w > maxWeek) maxWeek = w;\n                        }\n                    }\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: semesterStartDate,\n                            semesterTotalWeeks: 20\n                        }\n                    };\n                }\n            }\n        }\n    } catch (e) {}\n\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或确认页面状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        return false;\n    }\n}\n\nconst TimeSlots = [\n    { number: 1, startTime: \"08:10\", endTime: \"08:55\" },\n    { number: 2, startTime: \"09:05\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"16:00\", endTime: \"16:45\" },\n    { number: 8, startTime: \"16:55\", endTime: \"17:40\" },\n    { number: 9, startTime: \"18:40\", endTime: \"19:25\" },\n    { number: 10, startTime: \"19:35\", endTime: \"20:20\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    if (timeSlots.length === 0) return;\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) {\n        window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\");\n        return;\n    }\n\n    const { academicYear, semesterCode } = selection;\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (result === null) return;\n\n    const { courses, config } = result;\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) return;\n\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        let configMsg = \"课表配置更新成功！\";\n        if (config.semesterStartDate) {\n            configMsg += ` 开学日期：${config.semesterStartDate}`;\n        }\n        window.shiguangBridge.showToast(configMsg);\n    } catch (error) {}\n\n    await importPresetTimeSlots(TimeSlots);\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","GXMU_01":"/**\n * 广西医科大学智慧教务系统课表导入适配脚本\n * 通过 getCalendarWeekDatas 接口获取课表数据（POST，返回 JSON、全学期）\n * 课程节次直接由接口字段 ps(起始节次) / pe(结束节次) 提供\n */\n\n// 广西医科大学作息时间表（第1-12节）\nconst GXMU_TIME_SLOTS = [\n    { number: 1,  startTime: \"08:20\", endTime: \"09:00\" },\n    { number: 2,  startTime: \"09:05\", endTime: \"09:45\" },\n    { number: 3,  startTime: \"10:05\", endTime: \"10:45\" },\n    { number: 4,  startTime: \"10:50\", endTime: \"11:30\" },\n    { number: 5,  startTime: \"11:35\", endTime: \"12:15\" },\n    { number: 6,  startTime: \"14:30\", endTime: \"15:10\" },\n    { number: 7,  startTime: \"15:15\", endTime: \"15:55\" },\n    { number: 8,  startTime: \"16:15\", endTime: \"16:55\" },\n    { number: 9,  startTime: \"17:00\", endTime: \"17:40\" },\n    { number: 10, startTime: \"19:00\", endTime: \"19:40\" },\n    { number: 11, startTime: \"19:45\", endTime: \"20:25\" },\n    { number: 12, startTime: \"20:30\", endTime: \"21:10\" }\n];\n\nfunction parseWeeks(weekStr) {\n    // 兼容逗号分段的周次；数字按数值排序去重\n    const weeks = [];\n    weekStr.split(',').forEach(part => {\n        part = part.trim();\n        const n = Number(part);\n        if (!isNaN(n) && n >= 1) weeks.push(n);\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析接口返回的单条课程记录，映射为课表所需结构\n */\nfunction mapCourseRecord(record) {\n    const weeks = parseWeeks(record.zc || \"\");\n    if (weeks.length === 0) return null;\n\n    const day = parseInt(record.xq, 10);\n    const startSection = parseInt(record.ps, 10);\n    const endSection = parseInt(record.pe, 10);\n    if (!day || day < 1 || day > 7) return null;\n    if (!startSection || isNaN(startSection)) return null;\n\n    return {\n        name: record.kcmc || \"\",\n        teacher: record.teaxms || \"未知教师\",\n        position: record.jxcdmc || \"未知地点\",\n        day: day,\n        startSection: startSection,\n        endSection: isNaN(endSection) ? startSection : endSection,\n        weeks: weeks\n    };\n}\n\n/**\n * 从接口返回的 JSON 数据中提取并映射全部课程\n */\nfunction transformSchedule(jsonData) {\n    console.log(\"JS: transformSchedule 正在解析课时数据...\");\n\n    const data = jsonData && Array.isArray(jsonData.data) ? jsonData.data : [];\n    console.log(`JS: 接口返回 ${data.length} 条课程记录`);\n\n    const rawCourses = data\n        .map(mapCourseRecord)\n        .filter(Boolean);\n\n    console.log(`JS: 解析出 ${rawCourses.length} 条课程记录`);\n\n    // 同一门课会因周次分段生成多个课时记录，按组合键去重\n    const seen = new Set();\n    const courses = [];\n    for (const c of rawCourses) {\n        const key = `${c.name}|${c.day}|${c.startSection}|${c.endSection}|${c.weeks.join(',')}|${c.teacher}|${c.position}`;\n        if (seen.has(key)) continue;\n        seen.add(key);\n        courses.push(c);\n    }\n\n    console.log(`JS: 去重后剩 ${courses.length} 门课程`);\n    return courses;\n}\n\nfunction isLoginPage() {\n    const url = window.location.href;\n    return url.includes('login') || url.includes('lyuapServer');\n}\n\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input)) return false;\n    return \"请输入四位数字的学年！\";\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025，将匹配 202501 学期）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期 (0)\", \"第二学期 (1)\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    const semesterCode = semesterIndex === 0 ? \"01\" : \"02\";\n    const xnxqdm = `${academicYear}${semesterCode}`;\n\n    // zc 传空表示全部周；d1/d2 为参考周起止日期，zc 为空时服务端返回全学期\n    const today = new Date();\n    const startOfWeek = new Date(today);\n    startOfWeek.setDate(today.getDate() - today.getDay() + 1);\n    const endOfWeek = new Date(startOfWeek);\n    endOfWeek.setDate(startOfWeek.getDate() + 6);\n\n    const pad = n => String(n).padStart(2, '0');\n    const fmtDate = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} 00:00:00`;\n    const body = `xnxqdm=${xnxqdm}&zc=&d1=${encodeURIComponent(fmtDate(startOfWeek))}&d2=${encodeURIComponent(fmtDate(endOfWeek))}`;\n\n    const url = \"https://jwxt.gxmu.edu.cn/new/student/xsgrkb/getCalendarWeekDatas\";\n    console.log(`JS: 请求课表接口: ${url}`);\n    console.log(`JS: 请求体: ${body}`);\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\" },\n            credentials: \"include\",\n            body: body\n        });\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n\n        const jsonData = await response.json();\n        const courses = transformSchedule(jsonData);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程。`);\n        return { courses };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\nasync function saveTimeSlots(timeSlots) {\n    if (!timeSlots || timeSlots.length === 0) return;\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        console.log(\"JS: 作息时间保存成功\");\n    } catch (error) {\n        console.error('JS: Save TimeSlots Error:', error);\n    }\n}\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        return;\n    }\n    const { courses } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    await saveTimeSlots(GXMU_TIME_SLOTS);\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","GXCME":"// 广西机电职业技术学院(gxcme.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统Mobile版接口适配\n\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n        if (isSameCourseAndSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n        let start = 0, end = 0, processed = false;\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) return [];\n    const initialCourseList = [];\n    for (const rawCourse of jsonData.kbList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc ||\n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) continue;\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) continue;\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n        const day = Number(rawCourse.xqj);\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) ||\n            day < 1 || day > 7 || startSection > endSection) continue;\n        initialCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n    return mergeAndDistinctCourses(initialCourseList);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function fetchAcademicOptions() {\n    const url = \"/jwglxt/kbcx/xskbcxZccx_cxXskbcxIndex.html?gnmkdm=N2154&layout=default\";\n    try {\n        const response = await fetch(url, { method: \"GET\", credentials: \"include\" });\n        if (!response.ok) return null;\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n\n        const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.hasAttribute(\"selected\")\n            }));\n\n        const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.hasAttribute(\"selected\")\n            }));\n\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) return null;\n\n        const selectedIndex = allYearOptions.findIndex(opt => opt.selected);\n        if (selectedIndex === -1) {\n            return {\n                yearOptions: allYearOptions.slice(0, 5),\n                semesterOptions,\n                defaultYearIndex: 0,\n                defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1\n                    ? semesterOptions.findIndex(opt => opt.selected) : 0\n            };\n        }\n\n        const start = Math.max(0, selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex + 3);\n        return {\n            yearOptions: allYearOptions.slice(start, end),\n            semesterOptions,\n            defaultYearIndex: selectedIndex - start,\n            defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1\n                ? semesterOptions.findIndex(opt => opt.selected) : 0\n        };\n    } catch (e) {\n        return null;\n    }\n}\n\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保登录状态。\");\n        return null;\n    }\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(yearOptions.map(item => item.text)),\n        defaultYearIndex\n    );\n    if (yearIndex === null || yearIndex === -1) return null;\n\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterOptions.map(item => item.text)),\n        defaultSemesterIndex\n    );\n    if (semesterIndex === null || semesterIndex === -1) return null;\n\n    return {\n        academicYear: yearOptions[yearIndex].value,\n        semesterCode: semesterOptions[semesterIndex].value\n    };\n}\n\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = \"/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\";\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: `xnm=${academicYear}&xqm=${semesterCode}`,\n            credentials: \"include\"\n        });\n        if (response.ok) {\n            const json = await response.json();\n            if (Array.isArray(json) && json.length > 0) {\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) return startDateStr;\n                }\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {}\n    return null;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const targetUrl = \"/jwglxt/kbcx/xskbcxMobile_cxXsKb.html?gnmkdm=N2154\";\n    const [courseResponse, semesterStartDate] = await Promise.all([\n        fetch(targetUrl, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" },\n            body: `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck`,\n            credentials: \"include\"\n        }),\n        fetchSemesterStartDate(academicYear, semesterCode)\n    ]);\n\n    try {\n        if (courseResponse.ok) {\n            const jsonData = await courseResponse.json();\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: semesterStartDate,\n                            semesterTotalWeeks: 20\n                        }\n                    };\n                }\n            }\n        }\n    } catch (e) {}\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + error.message);\n        return false;\n    }\n}\n\nconst TimeSlots = [\n    { number: 1, startTime: \"08:10\", endTime: \"08:50\" },\n    { number: 2, startTime: \"09:00\", endTime: \"09:40\" },\n    { number: 3, startTime: \"09:40\", endTime: \"10:20\" },\n    { number: 4, startTime: \"10:30\", endTime: \"11:10\" },\n    { number: 5, startTime: \"11:20\", endTime: \"12:00\" },\n    { number: 6, startTime: \"12:10\", endTime: \"12:50\" },\n    { number: 7, startTime: \"14:40\", endTime: \"15:20\" },\n    { number: 8, startTime: \"15:30\", endTime: \"16:10\" },\n    { number: 9, startTime: \"16:10\", endTime: \"16:50\" },\n    { number: 10, startTime: \"17:00\", endTime: \"17:40\" },\n    { number: 11, startTime: \"17:50\", endTime: \"18:30\" },\n    { number: 12, startTime: \"19:30\", endTime: \"20:10\" },\n    { number: 13, startTime: \"20:20\", endTime: \"21:00\" },\n    { number: 14, startTime: \"21:00\", endTime: \"21:40\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    if (timeSlots.length === 0) return;\n    try { await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots)); } catch (e) {}\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) {\n        window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\");\n        return;\n    }\n\n    const { academicYear, semesterCode } = selection;\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (result === null) return;\n\n    const { courses, config } = result;\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) return;\n\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    } catch (error) {}\n\n    await importPresetTimeSlots(TimeSlots);\n\n    window.shiguangBridge.showToast(\"课程导入成功，共导入 \" + courses.length + \" 门课程！\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","GXDLXY_01":"// 广西电力职业技术学院(gxdlxy.com) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n\nwindow.validateYearInput = function (input) {\n    if (/^[0-9]{4}$/.test(input)) {\n        return false; // 验证通过\n    } else {\n        return \"请输入四位数字的起始学年（如 2025）\";\n    }\n};\n\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n\n    const pureWeekData = weekStr.replace(/周|\\(.*?\\)/g, '');\n\n    const segments = pureWeekData.split(',');\n    segments.forEach(seg => {\n        if (seg.includes('-')) {\n            const range = seg.split('-').map(Number);\n            const start = range[0];\n            const end = range[1];\n            if (!isNaN(start) && !isNaN(end)) {\n                for (let i = start; i <= end; i++) {\n                    weeks.push(i);\n                }\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) {\n                weeks.push(w);\n            }\n        }\n    });\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction mergeAndDistinctCourses(courses) {\n    if (courses.length <= 1) return courses;\n    courses.sort((a, b) => {\n        if (a.name !== b.name) return a.name.localeCompare(b.name);\n        if (a.day !== b.day) return a.day - b.day;\n        if (a.startSection !== b.startSection) return a.startSection - b.startSection;\n        if (a.teacher !== b.teacher) return a.teacher.localeCompare(b.teacher);\n        if (a.position !== b.position) return a.position.localeCompare(b.position);\n        return a.weeks.join(',').localeCompare(b.weeks.join(','));\n    });\n\n    const merged = [];\n    let current = courses[0];\n\n    for (let i = 1; i < courses.length; i++) {\n        const next = courses[i];\n\n        const isSameCourse =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = (current.endSection + 1 === next.startSection);\n\n        if (isSameCourse && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourse && current.startSection === next.startSection && current.endSection === next.endSection) {\n            continue;\n        } else {\n            merged.push(current);\n            current = next;\n        }\n    }\n    merged.push(current);\n    return merged;\n}\n\n/**\n * 将 HTML 源码解析为课程模型\n */\nfunction parseTimetableToModel(htmlString) {\n    const doc = new DOMParser().parseFromString(htmlString, \"text/html\");\n    const timetable = doc.getElementById('kbtable');\n    if (!timetable) return [];\n\n    let rawCourses = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).filter(r => r.querySelector('td'));\n\n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1; // 星期\n            const detailDiv = cell.querySelector('div.kbcontent');\n            if (!detailDiv) return;\n\n            const rawHtml = detailDiv.innerHTML.trim();\n            if (!rawHtml || rawHtml === \"&nbsp;\" || detailDiv.innerText.trim().length < 2) return;\n\n            // 分割同一个格子内的多门课程\n            const blocks = rawHtml.split(/---------------------|----------------------/);\n\n            blocks.forEach(block => {\n                if (!block.trim()) return;\n                const tempDiv = document.createElement('div');\n                tempDiv.innerHTML = block;\n\n                // 1. 提取课程名\n                let name = \"\";\n                for (let node of tempDiv.childNodes) {\n                    if (node.nodeType === 3 && node.textContent.trim() !== \"\") {\n                        name = node.textContent.trim();\n                        break;\n                    }\n                }\n\n                // 2. 提取教师\n                const teacher = tempDiv.querySelector('font[title=\"老师\"]')?.innerText.trim() || \"未知教师\";\n\n                // 3. 提取地点与精准节次 (关键点)\n                const locationFull = tempDiv.querySelector('font[title=\"教室\"]')?.innerText || \"未知地点\";\n                let startSection = 0;\n                let endSection = 0;\n\n                // 匹配内部的 [01-02]节 格式\n                const sectionMatch = locationFull.match(/\\[(\\d+)-(\\d+)\\]节/);\n                if (sectionMatch) {\n                    startSection = parseInt(sectionMatch[1], 10);\n                    endSection = parseInt(sectionMatch[2], 10);\n                }\n\n                // 清洗教室名\n                const position = locationFull.replace(/\\[\\d+-\\d+\\]节$/, \"\").trim();\n\n                // 4. 提取周次\n                const weekStr = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText || \"\";\n\n                if (name && startSection > 0) {\n                    rawCourses.push({\n                        \"name\": name,\n                        \"teacher\": teacher,\n                        \"weeks\": parseWeeks(weekStr),\n                        \"position\": position,\n                        \"day\": day,\n                        \"startSection\": startSection,\n                        \"endSection\": endSection\n                    });\n                }\n            });\n        });\n    });\n\n    // 调用合并函数\n    return mergeAndDistinctCourses(rawCourses);\n}\n\n// 交互封装模块\n\nasync function showWelcomeAlert() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"导入提示\",\n        \"请确保已在内置浏览器中成功登录广西电力职业技术学院教务系统。\",\n        \"开始导入\"\n    );\n}\n\nasync function getSemesterParamsFromUser() {\n    const currentYear = new Date().getFullYear();\n    const year = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入起始学年（如2025代表2025-2026学年）:\",\n        String(currentYear),\n        \"validateYearInput\"\n    );\n    if (!year) return null;\n\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify([\"第一学期\", \"第二学期\"]),\n        0\n    );\n    if (semesterIndex === null) return null;\n\n    // 拼接教务系统识别码\n    return `${year}-${parseInt(year) + 1}-${semesterIndex + 1}`;\n}\n\n// 网络与存储封装模块\n\nasync function fetchCourseHtml(semesterId) {\n    window.shiguangBridge.showToast(\"正在请求课表数据，请稍候...\");\n    const response = await fetch(\"https://jw.vpn.gxdlxy.com/jsxsd/xskb/xskb_list.do\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `cj0701id=&zc=&demo=&xnxq01id=${semesterId}`,\n        credentials: \"include\"\n    });\n    return await response.text();\n}\n\nasync function saveCourseDataToApp(courses) {\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n        \"semesterTotalWeeks\": 20,\n        \"firstDayOfWeek\": 1\n    }));\n\n    const timeSlots = [\n        { \"number\": 1, \"startTime\": \"08:30\", \"endTime\": \"09:10\" },\n        { \"number\": 2, \"startTime\": \"09:20\", \"endTime\": \"10:00\" },\n        { \"number\": 3, \"startTime\": \"10:20\", \"endTime\": \"11:00\" },\n        { \"number\": 4, \"startTime\": \"11:10\", \"endTime\": \"11:50\" },\n        { \"number\": 5, \"startTime\": \"14:30\", \"endTime\": \"15:10\" },\n        { \"number\": 6, \"startTime\": \"15:20\", \"endTime\": \"16:00\" },\n        { \"number\": 7, \"startTime\": \"16:10\", \"endTime\": \"16:50\" },\n        { \"number\": 8, \"startTime\": \"16:50\", \"endTime\": \"17:30\" },\n        { \"number\": 9, \"startTime\": \"19:40\", \"endTime\": \"20:20\" },\n        { \"number\": 10, \"startTime\": \"20:30\", \"endTime\": \"21:10\" }\n    ];\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n\n    // 保存最终课程\n    return await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n}\n\n// 流程控制模块\n\nasync function runImportFlow() {\n    try {\n        const start = await showWelcomeAlert();\n        if (!start) return;\n\n        const semesterId = await getSemesterParamsFromUser();\n        if (!semesterId) return;\n\n        const html = await fetchCourseHtml(semesterId);\n\n        const finalCourses = parseTimetableToModel(html);\n\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现课程，请检查学期选择或登录状态。\");\n            return;\n        }\n\n        await saveCourseDataToApp(finalCourses);\n\n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        console.error(error);\n        window.shiguangBridge.showToast(\"导入异常: \" + error.message);\n    }\n}\n\n// 启动执行\nrunImportFlow();","GUIT_01":"const PRIMARY_TIME_SLOTS = [\n    { number: 1, startTime: \"09:00\", endTime: \"09:40\" },\n    { number: 2, startTime: \"09:45\", endTime: \"10:25\" },\n    { number: 3, startTime: \"11:10\", endTime: \"11:50\" },\n    { number: 4, startTime: \"11:55\", endTime: \"12:35\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:10\" },\n    { number: 6, startTime: \"15:15\", endTime: \"15:55\" },\n    { number: 7, startTime: \"16:15\", endTime: \"16:55\" },\n    { number: 8, startTime: \"17:00\", endTime: \"17:40\" },\n    { number: 9, startTime: \"19:00\", endTime: \"19:40\" },\n    { number: 10, startTime: \"19:45\", endTime: \"20:25\" },\n    { number: 11, startTime: \"20:30\", endTime: \"21:10\" }\n];\n\nconst SCHEDULE_TIME_MAP = {\n    \"一\": [\n        { number: 1, startTime: \"09:00\", endTime: \"09:40\" },\n        { number: 2, startTime: \"09:45\", endTime: \"10:25\" },\n        { number: 3, startTime: \"10:40\", endTime: \"11:20\" },\n        { number: 4, startTime: \"11:25\", endTime: \"12:05\" },\n        { number: 5, startTime: \"14:30\", endTime: \"15:10\" },\n        { number: 6, startTime: \"15:15\", endTime: \"15:55\" },\n        { number: 7, startTime: \"16:15\", endTime: \"16:55\" },\n        { number: 8, startTime: \"17:00\", endTime: \"17:40\" },\n        { number: 9, startTime: \"19:00\", endTime: \"19:40\" },\n        { number: 10, startTime: \"19:45\", endTime: \"20:25\" },\n        { number: 11, startTime: \"20:30\", endTime: \"21:10\" }\n    ],\n    \"二\": [\n        { number: 1, startTime: \"09:00\", endTime: \"09:40\" },\n        { number: 2, startTime: \"09:45\", endTime: \"10:25\" },\n        { number: 3, startTime: \"10:55\", endTime: \"11:20\" },\n        { number: 4, startTime: \"11:40\", endTime: \"12:20\" },\n        { number: 5, startTime: \"14:30\", endTime: \"15:10\" },\n        { number: 6, startTime: \"15:15\", endTime: \"15:55\" },\n        { number: 7, startTime: \"16:15\", endTime: \"16:55\" },\n        { number: 8, startTime: \"17:00\", endTime: \"17:40\" },\n        { number: 9, startTime: \"19:00\", endTime: \"19:40\" },\n        { number: 10, startTime: \"19:45\", endTime: \"20:25\" },\n        { number: 11, startTime: \"20:30\", endTime: \"21:10\" }\n    ],\n    \"三\": PRIMARY_TIME_SLOTS\n};\n\nconst BUILDING_SCHEDULE_MAP = {\n    C: \"一\",\n    E: \"一\",\n    G: \"一\",\n    D: \"二\",\n    F: \"二\",\n    H: \"二\",\n    A: \"三\",\n    B: \"三\",\n    J: \"三\",\n    K: \"三\",\n    L: \"三\",\n    M: \"三\"\n};\n\nconst DAY_FIELD_MAP = {\n    mon: 1,\n    tu: 2,\n    wes: 3,\n    tur: 4,\n    fri: 5,\n    sat: 6,\n    sun: 7\n};\n\nfunction showToast(message) {\n    if (typeof window.shiguangBridge !== \"undefined\" && window.shiguangBridge.showToast) {\n        window.shiguangBridge.showToast(message);\n    } else {\n        console.log(message);\n    }\n}\n\nfunction getBaseOrigin() {\n    return window.location.origin;\n}\n\nfunction getTodayString() {\n    const now = new Date();\n    const year = now.getFullYear();\n    const month = String(now.getMonth() + 1).padStart(2, \"0\");\n    const day = String(now.getDate()).padStart(2, \"0\");\n    return `${year}-${month}-${day}`;\n}\n\nfunction normalizeHtmlLines(html) {\n    return String(html || \"\")\n        .replace(/<br\\s*\\/?>/gi, \"\\n\")\n        .replace(/&nbsp;/gi, \" \")\n        .replace(/<[^>]+>/g, \"\")\n        .split(\"\\n\")\n        .map((line) => line.trim())\n        .filter(Boolean);\n}\n\nfunction parseWeeks(rawText) {\n    const text = String(rawText || \"\")\n        .replace(/\\s+/g, \"\")\n        .replace(/周/g, \"\")\n        .replace(/，/g, \",\")\n        .replace(/、/g, \",\");\n\n    if (!text) return [];\n\n    const weeks = new Set();\n    text.split(\",\").forEach((segment) => {\n        if (!segment) return;\n\n        const isOdd = /单/.test(segment);\n        const isEven = /双/.test(segment);\n        const cleaned = segment.replace(/[单双]/g, \"\");\n        const match = cleaned.match(/^(\\d+)(?:-(\\d+))?$/);\n        if (!match) return;\n\n        const start = Number(match[1]);\n        const end = Number(match[2] || match[1]);\n        for (let week = start; week <= end; week++) {\n            if (isOdd && week % 2 === 0) continue;\n            if (isEven && week % 2 !== 0) continue;\n            weeks.add(week);\n        }\n    });\n\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\nfunction parseSectionAndRoom(rawLocation) {\n    const value = String(rawLocation || \"\").trim();\n    const match = value.match(/^(\\d{2})(\\d{2})(.*)$/);\n    if (!match) return null;\n\n    return {\n        startSection: Number(match[1]),\n        endSection: Number(match[2]),\n        position: match[3].trim() || \"待定\"\n    };\n}\n\nfunction getBuildingCode(position) {\n    const match = String(position || \"\").trim().match(/^([A-Z])/i);\n    return match ? match[1].toUpperCase() : \"\";\n}\n\nfunction getScheduleTypeByPosition(position) {\n    const buildingCode = getBuildingCode(position);\n    return BUILDING_SCHEDULE_MAP[buildingCode] || \"三\";\n}\n\nfunction getTimeSlotMap(scheduleType) {\n    const map = new Map();\n    (SCHEDULE_TIME_MAP[scheduleType] || PRIMARY_TIME_SLOTS).forEach((slot) => {\n        map.set(slot.number, slot);\n    });\n    return map;\n}\n\nfunction fillCustomTime(course) {\n    const scheduleType = getScheduleTypeByPosition(course.position);\n    if (scheduleType === \"三\") {\n        return course;\n    }\n\n    if (course.startSection >= 5 && course.endSection <= 11) {\n        return course;\n    }\n\n    const timeSlotMap = getTimeSlotMap(scheduleType);\n    const startSlot = timeSlotMap.get(course.startSection);\n    const endSlot = timeSlotMap.get(course.endSection);\n    if (!startSlot || !endSlot) {\n        return course;\n    }\n\n    const primaryTimeSlotMap = new Map(PRIMARY_TIME_SLOTS.map((slot) => [slot.number, slot]));\n    const primaryStartSlot = primaryTimeSlotMap.get(course.startSection);\n    const primaryEndSlot = primaryTimeSlotMap.get(course.endSection);\n    if (\n        primaryStartSlot &&\n        primaryEndSlot &&\n        primaryStartSlot.startTime === startSlot.startTime &&\n        primaryEndSlot.endTime === endSlot.endTime\n    ) {\n        return course;\n    }\n\n    return {\n        ...course,\n        isCustomTime: true,\n        customStartTime: startSlot.startTime,\n        customEndTime: endSlot.endTime\n    };\n}\n\nfunction parseCellCourses(cellHtml, day, row, totalWeeks) {\n    const lines = normalizeHtmlLines(cellHtml);\n    if (!lines.length) return [];\n\n    const courses = [];\n    for (let index = 0; index < lines.length; index += 2) {\n        const locationLine = lines[index];\n        const weekLine = lines[index + 1] || \"\";\n        const sectionInfo = parseSectionAndRoom(locationLine);\n        if (!sectionInfo) continue;\n\n        const weeks = parseWeeks(weekLine);\n        courses.push(fillCustomTime({\n            name: String(row.cname || \"\").trim(),\n            teacher: String(row.TeacherName || row.assteachername || \"\").trim() || \"未知教师\",\n            position: sectionInfo.position || \"待定\",\n            day,\n            startSection: sectionInfo.startSection,\n            endSection: sectionInfo.endSection,\n            weeks: weeks.length ? weeks : Array.from({ length: totalWeeks }, (_, i) => i + 1)\n        }));\n    }\n\n    return courses;\n}\n\nfunction deduplicateCourses(courses) {\n    const seen = new Map();\n    courses.forEach((course) => {\n        const key = [\n            course.name,\n            course.teacher,\n            course.position,\n            course.day,\n            course.startSection,\n            course.endSection,\n            course.weeks.join(\",\")\n        ].join(\"|\");\n        if (!seen.has(key)) {\n            seen.set(key, course);\n        }\n    });\n    return Array.from(seen.values());\n}\n\nasync function requestJson(path, options = {}) {\n    const response = await fetch(`${getBaseOrigin()}${path}`, {\n        credentials: \"include\",\n        ...options\n    });\n\n    const text = await response.text();\n    let data;\n    try {\n        data = JSON.parse(text);\n    } catch (error) {\n        throw new Error(`接口 ${path} 返回了非 JSON 内容，请确认已登录并位于正确页面。`);\n    }\n\n    if (!response.ok) {\n        throw new Error(`接口 ${path} 请求失败，HTTP ${response.status}`);\n    }\n\n    return data;\n}\n\nasync function requestText(path, options = {}) {\n    const response = await fetch(`${getBaseOrigin()}${path}`, {\n        credentials: \"include\",\n        ...options\n    });\n\n    if (!response.ok) {\n        throw new Error(`接口 ${path} 请求失败，HTTP ${response.status}`);\n    }\n\n    return response.text();\n}\n\nfunction parseStudentIdFromHtml(html) {\n    const idMatch = String(html || \"\").match(/name=[\"']stid[\"'][^>]*value=[\"']([^\"']+)[\"']/i);\n    return idMatch ? idMatch[1].trim() : \"\";\n}\n\nasync function fetchStudentProfile() {\n    const html = await requestText(\"/Admin_Areas/StInfo/studentInfo\");\n    const studentId = parseStudentIdFromHtml(html);\n    if (!studentId) {\n        throw new Error(\"未能从个人信息页面解析出学号。\");\n    }\n\n    const body = new URLSearchParams({ stid: studentId });\n    const profile = await requestJson(\"/Admin_Areas/StInfo/getStInfo\", {\n        method: \"POST\",\n        headers: {\n            Accept: \"application/json, text/javascript, */*; q=0.01\",\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: body.toString()\n    });\n\n    return {\n        studentId,\n        enrolldate: String(profile?.enrolldate || \"\").trim(),\n        grade: String(profile?.grade || \"\").trim()\n    };\n}\n\nfunction getEnrollmentThreshold(profile) {\n    const enrollmentDate = String(profile?.enrolldate || \"\").trim();\n    if (enrollmentDate) {\n        return enrollmentDate;\n    }\n\n    const grade = Number(profile?.grade || 0);\n    if (grade >= 1900 && grade <= 2100) {\n        return `${grade}-01-01`;\n    }\n\n    return \"\";\n}\n\nasync function fetchTermList() {\n    const terms = await requestJson(\"/Admin_Areas/Res/GetTermInfoAll\", {\n        method: \"POST\",\n        headers: {\n            Accept: \"application/json, text/javascript, */*; q=0.01\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        }\n    });\n\n    if (!Array.isArray(terms) || !terms.length) {\n        throw new Error(\"未获取到学期信息。\");\n    }\n\n    const filteredTerms = terms.filter((term) => {\n        if (!term || !term.term || !term.startdate) return false;\n        const name = String(term.termname || \"\");\n        return /学年第[一二三四五六七八九十]+学期/.test(name);\n    });\n\n    return filteredTerms.length ? filteredTerms : terms.filter((term) => term && term.term && term.startdate);\n}\n\nfunction filterTermsByEnrollment(terms, enrollmentThreshold) {\n    if (!enrollmentThreshold) return terms;\n\n    const filtered = terms.filter((term) => {\n        return String(term.enddate || term.startdate || \"\") >= enrollmentThreshold;\n    });\n\n    return filtered.length ? filtered : terms;\n}\n\nfunction getDefaultTermIndex(terms) {\n    const today = getTodayString();\n    const currentIndex = terms.findIndex((term) => {\n        return term.startdate <= today && today <= String(term.enddate || \"9999-12-31\");\n    });\n    if (currentIndex >= 0) return currentIndex;\n\n    const regularIndex = terms.findIndex((term) => /学期/.test(String(term.termname || \"\")));\n    return regularIndex >= 0 ? regularIndex : 0;\n}\n\nasync function selectTerm(terms) {\n    const items = terms.map((term) => {\n        return String(term.termname || term.term);\n    });\n    const defaultIndex = getDefaultTermIndex(terms);\n\n    if (typeof window.shiguangBridgePromise === \"undefined\") {\n        return terms[defaultIndex];\n    }\n\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择要导入的学期\",\n        JSON.stringify(items),\n        defaultIndex\n    );\n\n    if (selectedIndex === null || selectedIndex === -1) {\n        throw new Error(\"已取消导入。\");\n    }\n\n    return terms[selectedIndex];\n}\n\nasync function fetchCoursePage(termCode, page, rowsPerPage) {\n    const body = new URLSearchParams({\n        term: termCode,\n        page: String(page),\n        rows: String(rowsPerPage)\n    });\n\n    const data = await requestJson(\"/Admin_Areas/StInfo/GetCourseQuery\", {\n        method: \"POST\",\n        headers: {\n            Accept: \"application/json, text/javascript, */*; q=0.01\",\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: body.toString()\n    });\n\n    if (!data || !Array.isArray(data.rows)) {\n        throw new Error(\"课表接口未返回有效数据。\");\n    }\n\n    return data;\n}\n\nasync function fetchAllCourseRows(termCode) {\n    const rowsPerPage = 50;\n    const firstPage = await fetchCoursePage(termCode, 1, rowsPerPage);\n    const allRows = [...firstPage.rows];\n    const total = Number(firstPage.total || allRows.length);\n    const totalPages = Math.max(1, Math.ceil(total / rowsPerPage));\n\n    for (let page = 2; page <= totalPages; page++) {\n        const pageData = await fetchCoursePage(termCode, page, rowsPerPage);\n        allRows.push(...pageData.rows);\n    }\n\n    return allRows;\n}\n\nfunction buildCourses(rows, totalWeeks) {\n    const courses = [];\n\n    rows.forEach((row) => {\n        Object.entries(DAY_FIELD_MAP).forEach(([field, day]) => {\n            const cellValue = row[field];\n            if (!cellValue) return;\n            courses.push(...parseCellCourses(cellValue, day, row, totalWeeks));\n        });\n    });\n\n    return deduplicateCourses(courses);\n}\n\nasync function saveConfig(term) {\n    const config = {\n        semesterStartDate: String(term.startdate),\n        semesterTotalWeeks: Number(term.weeknum || 20),\n        firstDayOfWeek: 1\n    };\n\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\nasync function saveTimeSlots() {\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(PRIMARY_TIME_SLOTS));\n}\n\nasync function saveCourses(courses) {\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n}\n\nasync function runImportFlow() {\n    try {\n        showToast(\"正在获取个人信息...\");\n        const studentProfile = await fetchStudentProfile();\n        const enrollmentThreshold = getEnrollmentThreshold(studentProfile);\n\n        showToast(\"正在获取学期信息...\");\n        const terms = filterTermsByEnrollment(await fetchTermList(), enrollmentThreshold);\n        const selectedTerm = await selectTerm(terms);\n\n        showToast(`正在获取 ${selectedTerm.termname || selectedTerm.term} 课表...`);\n        const rows = await fetchAllCourseRows(String(selectedTerm.term));\n        const totalWeeks = Number(selectedTerm.weeknum || 20);\n        const courses = buildCourses(rows, totalWeeks);\n\n        if (!courses.length) {\n            throw new Error(\"未解析到课程，请确认当前账号已在教务系统中可查看课表。\");\n        }\n\n        if (typeof window.shiguangBridgePromise === \"undefined\") {\n            console.log(\"Selected term:\", selectedTerm);\n            console.log(\"Courses:\", courses);\n            console.log(\"Time slots:\", PRIMARY_TIME_SLOTS);\n            alert(`解析完成，共 ${courses.length} 门课程。请查看控制台输出。`);\n            return;\n        }\n\n        await saveConfig(selectedTerm);\n        await saveTimeSlots();\n        await saveCourses(courses);\n\n        showToast(`导入完成，共 ${courses.length} 门课程`);\n        if (typeof window.shiguangBridge !== \"undefined\" && window.shiguangBridge.notifyTaskCompletion) {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (error) {\n        console.error(error);\n        showToast(`导入失败: ${error.message}`);\n    }\n}\n\nrunImportFlow();\n","GLMU_01":"// 文件: guilin_medical.js\r\n// 功能：从桂医教务系统获取课程表，通过桥接 API 导入到拾光课程表\r\n\r\n// ---------- 全局验证函数 ----------\r\nfunction validateYearInput(input) {\r\n    if (/^\\d{4}$/.test(input)) {\r\n        return false; // 验证通过\r\n    } else {\r\n        return \"请输入四位数字的年份（例如 2024）\";\r\n    }\r\n}\r\n\r\n// ---------- 工具函数 ----------\r\nfunction parseWeeks(weeksStr) {\r\n    weeksStr = weeksStr.replace('周', '');\r\n    const parts = weeksStr.split(',');\r\n    const weeks = [];\r\n    for (const part of parts) {\r\n        if (part.includes('-')) {\r\n            const [start, end] = part.split('-').map(Number);\r\n            for (let i = start; i <= end; i++) weeks.push(i);\r\n        } else {\r\n            weeks.push(Number(part));\r\n        }\r\n    }\r\n    return weeks;\r\n}\r\n\r\nfunction parseSections(jcdm) {\r\n    const str = String(jcdm);\r\n    const sections = [];\r\n    if (str.includes('-')) {\r\n        const [start, end] = str.split('-').map(Number);\r\n        for (let i = start; i <= end; i++) sections.push(i);\r\n    } else if (/^\\d+$/.test(str)) {\r\n        for (let i = 0; i < str.length; i += 2) {\r\n            const sec = parseInt(str.substring(i, i + 2), 10);\r\n            if (!isNaN(sec)) sections.push(sec);\r\n        }\r\n    } else {\r\n        sections.push(parseInt(str));\r\n    }\r\n    return sections;\r\n}\r\n\r\nfunction parseRawCourses(rawData) {\r\n    const courseInfos = [];\r\n    for (const course of rawData) {\r\n        const name = course.kcmc;\r\n        const teacher = course.teaxms;\r\n        const position = course.jxcdmc;\r\n        const weeks = parseWeeks(course.zc);\r\n        const day = parseInt(course.xq);\r\n        const sections = parseSections(course.jcdm);\r\n        courseInfos.push({ name, teacher, position, weeks, day, sections });\r\n    }\r\n    return courseInfos;\r\n}\r\n\r\nfunction convertToTargetCourses(middleCourses) {\r\n    return middleCourses.map(c => ({\r\n        name: c.name,\r\n        teacher: c.teacher,\r\n        position: c.position,\r\n        day: c.day,\r\n        startSection: c.sections[0],\r\n        endSection: c.sections[c.sections.length - 1],\r\n        weeks: c.weeks,\r\n        isCustomTime: false\r\n    }));\r\n}\r\n\r\nfunction getTimeSlots() {\r\n    return [\r\n        { number: 1, startTime: \"08:30\", endTime: \"09:10\" },\r\n        { number: 2, startTime: \"09:20\", endTime: \"10:00\" },\r\n        { number: 3, startTime: \"10:10\", endTime: \"10:50\" },\r\n        { number: 4, startTime: \"11:00\", endTime: \"11:40\" },\r\n        { number: 5, startTime: \"11:50\", endTime: \"12:30\" },\r\n        { number: 6, startTime: \"14:30\", endTime: \"15:10\" },\r\n        { number: 7, startTime: \"15:20\", endTime: \"16:00\" },\r\n        { number: 8, startTime: \"16:10\", endTime: \"16:50\" },\r\n        { number: 9, startTime: \"17:00\", endTime: \"17:40\" },\r\n        { number: 10, startTime: \"19:00\", endTime: \"19:40\" },\r\n        { number: 11, startTime: \"19:50\", endTime: \"20:30\" },\r\n        { number: 12, startTime: \"20:40\", endTime: \"21:20\" }\r\n    ];\r\n}\r\n\r\n// ---------- 网络请求 ----------\r\nasync function fetchCourseData(xnxqdm) {\r\n    let page = 1;\r\n    const rowsPerPage = 100;\r\n    let allRows = [];\r\n    let total = 0;\r\n\r\n    while (true) {\r\n        const res = await fetch(\"https://ejwc.glmc.edu.cn/xsgrkbcx!getDataList.action\", {\r\n            headers: {\r\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\r\n                \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\r\n                \"x-requested-with\": \"XMLHttpRequest\"\r\n            },\r\n            body: `xnxqdm=${xnxqdm}&page=${page}&rows=${rowsPerPage}`,\r\n            method: \"POST\",\r\n            credentials: \"include\"\r\n        });\r\n        if (!res.ok) {\r\n            throw new Error(`HTTP ${res.status}: ${res.statusText}`);\r\n        }\r\n        const ret = await res.json();\r\n        if (!ret.rows || !Array.isArray(ret.rows)) {\r\n            throw new Error(\"返回数据格式不正确\");\r\n        }\r\n        total = ret.total;\r\n        allRows = allRows.concat(ret.rows);\r\n        if (allRows.length >= total) break;\r\n        page++;\r\n        if (page > 10) break;\r\n    }\r\n    return allRows;\r\n}\r\n\r\n// ---------- 用户交互 ----------\r\nasync function promptUserToStart() {\r\n    return await window.shiguangBridgePromise.showAlert(\r\n        \"重要提醒\",\r\n        \"请确保您已登录桂医教务系统，且当前页面为教务系统内任意页面。\\n\\n点击确定继续。\",\r\n        \"确定\"\r\n    );\r\n}\r\n\r\nasync function getAcademicYear() {\r\n    return await window.shiguangBridgePromise.showPrompt(\r\n        \"学年设置\",\r\n        \"请输入本学年开始的年份\\n（例如 2024，代表 2024-2025 学年）\",\r\n        \"2024\",\r\n        \"validateYearInput\"  // 传入验证函数名\r\n    );\r\n}\r\n\r\nasync function selectSemester() {\r\n    const semesterOptions = [\"上学期\", \"下学期\", \"短学期\"];\r\n    const index = await window.shiguangBridgePromise.showSingleSelection(\r\n        \"选择学期\",\r\n        JSON.stringify(semesterOptions),\r\n        0\r\n    );\r\n    if (index === null || index < 0) return null;\r\n    return index;\r\n}\r\n\r\n// ---------- 主流程 ----------\r\nasync function run() {\r\n    try {\r\n        // 1. 公告\r\n        const confirmed = await promptUserToStart();\r\n        if (!confirmed) {\r\n            window.shiguangBridge.showToast(\"用户取消了导入流程。\");\r\n            return;\r\n        }\r\n\r\n        // 2. 获取学年\r\n        const yearInput = await getAcademicYear();\r\n        if (yearInput === null) {\r\n            window.shiguangBridge.showToast(\"导入已取消。\");\r\n            return;\r\n        }\r\n        const yearNum = parseInt(yearInput);\r\n        if (isNaN(yearNum) || yearNum < 2000 || yearNum > 2100) {\r\n            await window.shiguangBridgePromise.showAlert(\"错误\", \"学年输入无效，请输入2000-2100之间的数字。\", \"确定\");\r\n            return;\r\n        }\r\n\r\n        // 3. 获取学期\r\n        const semesterIndex = await selectSemester();\r\n        if (semesterIndex === null) {\r\n            window.shiguangBridge.showToast(\"导入已取消。\");\r\n            return;\r\n        }\r\n        const termCode = semesterIndex === 0 ? \"01\" : (semesterIndex === 1 ? \"02\" : \"03\");\r\n        const xnxqdm = `${yearNum}${termCode}`;\r\n\r\n        // 4. 请求课表\r\n        window.shiguangBridge.showToast(\"正在获取课表，请稍候...\");\r\n        let rawData;\r\n        try {\r\n            rawData = await fetchCourseData(xnxqdm);\r\n        } catch (fetchErr) {\r\n            await window.shiguangBridgePromise.showAlert(\r\n                \"网络请求失败\",\r\n                `请求教务系统失败：${fetchErr.message}\\n\\n请检查网络连接和登录状态。`,\r\n                \"确定\"\r\n            );\r\n            return;\r\n        }\r\n\r\n        if (!rawData.length) {\r\n            await window.shiguangBridgePromise.showAlert(\"提示\", \"未获取到任何课程数据。请确认已登录教务系统并选择正确的学年学期。\", \"确定\");\r\n            return;\r\n        }\r\n\r\n        // 5. 解析并转换\r\n        const middleCourses = parseRawCourses(rawData);\r\n        const targetCourses = convertToTargetCourses(middleCourses);\r\n\r\n        // 6. 保存课程\r\n        try {\r\n            await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(targetCourses));\r\n            window.shiguangBridge.showToast(`课程数据已导入（共 ${targetCourses.length} 条）`);\r\n        } catch (saveErr) {\r\n            await window.shiguangBridgePromise.showAlert(\"保存课程失败\", saveErr.message, \"确定\");\r\n            return;\r\n        }\r\n\r\n        // 7. 保存时间段\r\n        const timeSlots = getTimeSlots();\r\n        try {\r\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\r\n            window.shiguangBridge.showToast(\"时间段数据已导入\");\r\n        } catch (slotErr) {\r\n            // 时间段保存失败不终止流程，只提示\r\n            window.shiguangBridge.showToast(`时间段保存失败：${slotErr.message}`);\r\n        }\r\n\r\n        // 8. 完成通知\r\n        window.shiguangBridge.showToast(\"导入完成！\");\r\n        window.shiguangBridge.notifyTaskCompletion();\r\n\r\n    } catch (err) {\r\n        // 捕获所有未预料的错误\r\n        console.error(\"run error:\", err);\r\n        await window.shiguangBridgePromise.showAlert(\r\n            \"导入失败\",\r\n            `未知错误：${err.message || err}\\n\\n请联系开发者。`,\r\n            \"确定\"\r\n        );\r\n        // 仍然通知完成，但可能不会生成有效文件\r\n        window.shiguangBridge.notifyTaskCompletion();\r\n    }\r\n}\r\n\r\n// 启动\r\nrun();\r\n","GSMC_01":"// 甘肃医学院(gsmc.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    // 检查JSON结构：新的数据在 kbList 字段中\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查： kcmc(课名), xm(教师), cdmc(教室), xqj(星期), jcs(节次范围), zcd(周次描述)\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        \n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        // 解析节次范围，例如 \"1-2\"\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n\n        const day = Number(rawCourse.xqj); // xqj: 星期几 (周一为1, 周日为7)\n        \n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            // console.warn(`JS: 课程 ${rawCourse.kcmc} 星期或节次数据无效，跳过。`);\n            continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\n/**\n * 检查是否在登录页面。\n * 只有当 URL 精确匹配时，才返回 true。\n */\nfunction isLoginPage() {\n    const url = window.location.href;\n    const loginUrl = \"https://jw.gsmc.edu.cn/jwglxt/xtgl/login_slogin.html\";\n    \n    // 如果当前 URL 与指定的登录 URL 完全一致，则返回 true (是登录页)\n    return url === loginUrl; \n}\n\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（如2025-2026 应该填2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\n/**\n * 将选择索引转换为 API 所需的学期码。\n */\nfunction getSemesterCode(semesterIndex) {\n    // semesterIndex 3 (第一学期), 12 (第二学期)\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    const semesterCode = getSemesterCode(semesterIndex);\n    \n    // API URL 和请求体\n    const xnmXqmBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`; \n    const url = \"https://jw.gsmc.edu.cn/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n\n    console.log(`JS: 发送请求到 ${url}, body: ${xnmXqmBody}`);\n\n    const requestOptions = {\n        \"headers\": {\n            \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\", \n        },\n        \"body\": xnmXqmBody,\n        \"method\": \"POST\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status} (${response.statusText})`);\n        }\n        \n        const jsonText = await response.text();\n        let jsonData;\n        try {\n            jsonData = JSON.parse(jsonText);\n        } catch (e) {\n            console.error('JS: JSON 解析失败，可能是会话过期:', e);\n            window.shiguangBridge.showToast(\"数据返回格式错误，可能是您未成功登录或会话已过期。\");\n            return null;\n        }\n\n        const courses = parseJsonData(jsonData); \n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确或本学期无课，或教务系统需要二次登录。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程。`);\n        \n        // 默认总周数为 20，周一为一周第一天。\n        const config = {\n            semesterTotalWeeks: 20,\n            firstDayOfWeek: 1 \n        };\n\n        // 返回课程列表和配置信息\n        return { courses: courses, config: config }; \n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n// 统一作息时间\nconst TimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 7, startTime: \"16:30\", endTime: \"17:15\" },\n    { number: 8, startTime: \"17:25\", endTime: \"18:10\" },\n    { number: 9, startTime: \"18:20\", \"endTime\": \"19:05\" },\n    { number: 10, startTime: \"19:30\", \"endTime\": \"20:15\" },\n    { number: 11, startTime: \"20:25\", \"endTime\": \"21:10\" },\n    { number: 12, startTime: \"21:20\", \"endTime\": \"22:05\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        console.log(\"JS: 检测到当前在登录页面，终止导入。\");\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`课表配置更新成功！总周数：${config.semesterTotalWeeks}周。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n\n\n    await importPresetTimeSlots(TimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","GSCMXY_01":"// 甘肃财贸职业学院教务系统(gscmxy.edu.cn) 拾光课程表适配脚本\n\nfunction parseWeeksFromSkzc(skzc) {\n    const weeks = [];\n    const rawSkzc = skzc || '';\n    for (let i = 0; i < rawSkzc.length; i++) {\n        if (rawSkzc[i] === '1') {\n            weeks.push(i + 1);\n        }\n    }\n    return weeks;\n}\n\nfunction parseSingleCourse(rawCourse) {\n    const courseName = rawCourse.KCM;\n    const teacherName = rawCourse.SKJS ? rawCourse.SKJS.split('/')[0] : '';\n    const position = rawCourse.JASMC;\n    const day = rawCourse.SKXQ;\n    const startSection = rawCourse.KSJC;\n    const endSection = rawCourse.JSJC;\n    const weeks = parseWeeksFromSkzc(rawCourse.SKZC);\n\n    if (!courseName || !day || !startSection || !endSection || weeks.length === 0) {\n        return null;\n    }\n\n    const campus = rawCourse.XXXQDM_DISPLAY ? String(rawCourse.XXXQDM_DISPLAY).trim() : \"\";\n    const classroom = position ? String(position).trim() : \"\";\n    const finalPosition = campus && classroom ? `${classroom}(${campus})` : (classroom || '待定');\n\n    const course = {\n        \"name\": courseName,\n        \"teacher\": teacherName,\n        \"position\": finalPosition,\n        \"day\": parseInt(day),\n        \"startSection\": parseInt(startSection),\n        \"endSection\": parseInt(endSection),\n        \"weeks\": weeks\n    };\n\n    course._kbId = rawCourse.KBID;\n    course._day = course.day;\n    course._startSection = course.startSection;\n    course._endSection = course.endSection;\n    course._position = classroom;\n    course._campus = campus;\n\n    return course;\n}\n\nfunction applyCourseChanges(parsedCourses, rawChanges) {\n    let successCount = 0;\n\n    for (const change of rawChanges) {\n        const kbID = change.KBID;\n        const originalTeacher = change.YSKJS ? change.YSKJS.split('/')[0] : '';\n\n        const weeksToRemove = parseWeeksFromSkzc(change.SKZC);\n\n        let changeApplied = false;\n\n        const affectedOriginalCourses = parsedCourses.filter(c =>\n            c._kbId === kbID &&\n            c._day === parseInt(change.SKXQ) &&\n            c._startSection === parseInt(change.KSJC) &&\n            c._endSection === parseInt(change.JSJC)\n        );\n\n        if (affectedOriginalCourses.length === 0) {\n            continue;\n        }\n\n        if (weeksToRemove.length > 0) {\n            affectedOriginalCourses.forEach(originalCourse => {\n                const beforeLength = originalCourse.weeks.length;\n                originalCourse.weeks = originalCourse.weeks.filter(w => !weeksToRemove.includes(w));\n                if (originalCourse.weeks.length < beforeLength) {\n                    changeApplied = true;\n                }\n            });\n        }\n\n        const isTimeLocationChange = (change.TKLXDM === '01' || change.TKLXDM === '03');\n\n        if (isTimeLocationChange && change.XSKZC && change.XSKXQ && change.XKSJC && change.XJSJC) {\n            const newWeeks = parseWeeksFromSkzc(change.XSKZC);\n\n            if (newWeeks.length > 0) {\n                const newCampus = change.XXXQDM_DISPLAY ? String(change.XXXQDM_DISPLAY).trim() : \"\";\n                const newClassroom = change.XJASMC ? String(change.XJASMC).trim() : (change.JASMC ? String(change.JASMC).trim() : \"\");\n                const newPosition = newCampus && newClassroom ? `${newClassroom}(${newCampus})` : (newClassroom || '待定');\n\n                const newCourse = {\n                    \"name\": change.KCM,\n                    \"teacher\": change.XSKJS ? change.XSKJS.split('/')[0] : originalTeacher,\n                    \"position\": newPosition,\n                    \"day\": parseInt(change.XSKXQ),\n                    \"startSection\": parseInt(change.XKSJC),\n                    \"endSection\": parseInt(change.XJSJC),\n                    \"weeks\": newWeeks,\n                    \"_kbId\": kbID,\n                    \"_day\": parseInt(change.XSKXQ),\n                    \"_startSection\": parseInt(change.XKSJC),\n                    \"_endSection\": parseInt(change.XJSJC)\n                };\n                parsedCourses.push(newCourse);\n                changeApplied = true;\n            }\n        }\n\n        if (changeApplied) {\n            successCount++;\n        }\n    }\n\n    if (successCount > 0) {\n        window.shiguangBridge.showToast(`已应用 ${successCount} 条调课/停课变更，获得实际课表。`);\n    }\n\n    return parsedCourses.map(c => {\n        delete c._kbId;\n        delete c._day;\n        delete c._startSection;\n        delete c._endSection;\n        delete c._position;\n        delete c._campus;\n        return c;\n    }).filter(c => c.weeks.length > 0);\n}\n\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input) && parseInt(input) > 2000) {\n        return false;\n    } else {\n        return \"请输入有效的四位数字学年（例如：2026）！\";\n    }\n}\n\nasync function promptUserToStart() {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"甘肃财贸职业学院课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统，确认当前页面有显示课表。\",\n        \"好的，开始导入\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return null;\n    }\n    return true;\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear();\n    const yearSelection = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2026-2027 应输入2026）:\",\n        String(currentYear),\n        \"validateYearInput\"\n    );\n    return yearSelection;\n}\n\nasync function selectSemester() {\n    const semesters = [\"1 (秋季学期/上学期)\", \"2 (春季学期/下学期)\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n\n    if (semesterIndex === null) return null;\n    return String(semesterIndex + 1);\n}\n\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const XNXQDM = `${academicYear}-${parseInt(academicYear) + 1}-${semesterCode}`;\n    const headers = {\n        \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n        \"x-requested-with\": \"XMLHttpRequest\",\n    };\n\n    const courseUrl = \"https://jwxt.gscmxy.edu.cn/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\";\n    const courseBody = `XNXQDM=${XNXQDM}`;\n    let rawCourseData;\n    try {\n        const response = await fetch(courseUrl, { \"headers\": headers, \"body\": courseBody, \"method\": \"POST\", \"credentials\": \"include\" });\n        rawCourseData = JSON.parse(await response.text());\n    } catch (e) {\n        window.shiguangBridge.showToast(\"请求课表 API 失败，请检查网络和登录状态。\");\n        return null;\n    }\n\n    const rawCourses = rawCourseData?.datas?.cxxszhxqkb?.rows || [];\n    if (rawCourses.length === 0) {\n        window.shiguangBridge.showToast(\"该学期未查询到您的课程数据。\");\n        return null;\n    }\n    let parsedCourses = rawCourses.map(c => parseSingleCourse(c)).filter(c => c !== null);\n\n    const changeUrl = \"https://jwxt.gscmxy.edu.cn/jwapp/sys/wdkb/modules/xskcb/xsdkkc.do\";\n    const changeBody = `XNXQDM=${XNXQDM}&*order=-SQSJ`;\n    let rawChangeData;\n    try {\n        const response = await fetch(changeUrl, { \"headers\": headers, \"body\": changeBody, \"method\": \"POST\", \"credentials\": \"include\" });\n        rawChangeData = JSON.parse(await response.text());\n    } catch (e) {\n        window.shiguangBridge.showToast(\"请求调课 API 失败，将使用未调整的课表数据。\");\n    }\n\n    const rawChanges = rawChangeData?.datas?.xsdkkc?.rows || [];\n\n    if (rawChanges.length > 0) {\n        parsedCourses = applyCourseChanges(parsedCourses, rawChanges);\n    }\n\n    const courseConfig = {\n        semesterTotalWeeks: 20\n    };\n\n    return {\n        courses: parsedCourses,\n        config: courseConfig\n    };\n}\n\nasync function saveCourses(parsedCourses) {\n    if (parsedCourses.length === 0) {\n        window.shiguangBridge.showToast(\"没有有效的课程数据可供保存。\");\n        return true;\n    }\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        window.shiguangBridge.showToast(`成功导入 ${parsedCourses.length} 门课程！`);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`保存课程数据失败: ${error.message}`);\n        return false;\n    }\n}\n\nasync function importPresetTimeSlots() {\n    window.shiguangBridge.showToast(\"正在导入预设节次时间...\");\n\n    const presetTimeSlots = [\n        { \"number\": 1, \"startTime\": \"08:50\", \"endTime\": \"09:30\" },\n        { \"number\": 2, \"startTime\": \"09:40\", \"endTime\": \"10:20\" },\n        { \"number\": 3, \"startTime\": \"10:50\", \"endTime\": \"11:30\" },\n        { \"number\": 4, \"startTime\": \"11:40\", \"endTime\": \"12:20\" },\n        { \"number\": 5, \"startTime\": \"14:30\", \"endTime\": \"15:10\" },\n        { \"number\": 6, \"startTime\": \"15:20\", \"endTime\": \"16:00\" },\n        { \"number\": 7, \"startTime\": \"16:20\", \"endTime\": \"17:00\" },\n        { \"number\": 8, \"startTime\": \"17:10\", \"endTime\": \"17:50\" },\n        { \"number\": 9, \"startTime\": \"19:30\", \"endTime\": \"20:10\" },\n        { \"number\": 10, \"startTime\": \"20:20\", \"endTime\": \"21:00\" }\n    ];\n\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        return false;\n    }\n}\n\nasync function saveConfig(configData) {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(configData));\n        window.shiguangBridge.showToast(\"课表配置更新成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存配置失败: \" + error.message);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"甘肃财贸职业学院课程导入流程启动...\");\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) return;\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    const semesterCode = await selectSemester();\n    if (semesterCode === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    await importPresetTimeSlots();\n\n    const courseData = await fetchAndParseCourses(academicYear, semesterCode);\n    if (courseData === null) return;\n\n    const configSaveResult = await saveConfig(courseData.config);\n    if (!configSaveResult) return;\n\n    const saveResult = await saveCourses(courseData.courses);\n    if (!saveResult) return;\n\n    window.shiguangBridge.showToast(\"所有任务已完成！课表导入成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","GZU":"// 贵州大学 (gzu.edu.cn) 拾光课程表适配脚本\r\n// 基于正方教务系统 v9.2 接口适配\r\n\r\n/**\r\n * 解析周次字符串，处理单双周和周次范围。\r\n * 格式: \"1-16周\", \"1-15周(单)\", \"2-16周(双)\", \"8周\"\r\n */\r\nfunction parseWeeks(weekStr) {\r\n    if (!weekStr) return [];\r\n\r\n    const weekSets = weekStr.split(',');\r\n    let weeks = [];\r\n\r\n    for (const set of weekSets) {\r\n        const trimmedSet = set.trim();\r\n\r\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\r\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\r\n\r\n        let start = 0;\r\n        let end = 0;\r\n        let processed = false;\r\n\r\n        if (rangeMatch) {\r\n            start = Number(rangeMatch[1]);\r\n            end = Number(rangeMatch[2]);\r\n            processed = true;\r\n        } else if (singleMatch) {\r\n            start = end = Number(singleMatch[1]);\r\n            processed = true;\r\n        }\r\n\r\n        if (processed) {\r\n            const isSingle = trimmedSet.includes('(单)');\r\n            const isDouble = trimmedSet.includes('(双)');\r\n\r\n            for (let w = start; w <= end; w++) {\r\n                if (isSingle && w % 2 === 0) continue;\r\n                if (isDouble && w % 2 !== 0) continue;\r\n                weeks.push(w);\r\n            }\r\n        }\r\n    }\r\n\r\n    return [...new Set(weeks)].sort((a, b) => a - b);\r\n}\r\n\r\n/**\r\n * 解析节次范围，例如 \"1-2\", \"3-4\", \"7-8\", \"1-4\"\r\n */\r\nfunction parseSection(jcsStr) {\r\n    if (!jcsStr) return { startSection: 1, endSection: 2 };\r\n    const parts = jcsStr.split('-');\r\n    const start = Number(parts[0]);\r\n    const end = Number(parts[parts.length - 1]);\r\n    return {\r\n        startSection: isNaN(start) ? 1 : start,\r\n        endSection: isNaN(end) ? start || 1 : end\r\n    };\r\n}\r\n\r\n/**\r\n * 解析 API 返回的 JSON 数据。\r\n */\r\nfunction parseJsonData(jsonData) {\r\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\r\n        console.warn(\"JSON 数据结构错误或缺少 kbList 字段。\");\r\n        return [];\r\n    }\r\n\r\n    const rawCourseList = jsonData.kbList;\r\n    const finalCourseList = [];\r\n\r\n    for (const rawCourse of rawCourseList) {\r\n        if (!rawCourse.kcmc || !rawCourse.xm ||\r\n            !rawCourse.cdmc || !rawCourse.xqj ||\r\n            !rawCourse.jcs || !rawCourse.zcd) {\r\n            continue;\r\n        }\r\n\r\n        const weeksArray = parseWeeks(rawCourse.zcd);\r\n        if (weeksArray.length === 0) continue;\r\n\r\n        const { startSection, endSection } = parseSection(rawCourse.jcs);\r\n        const day = Number(rawCourse.xqj);\r\n\r\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) ||\r\n            day < 1 || day > 7 || startSection > endSection) {\r\n            continue;\r\n        }\r\n\r\n        finalCourseList.push({\r\n            name: rawCourse.kcmc.trim(),\r\n            teacher: rawCourse.xm.trim(),\r\n            position: rawCourse.cdmc.trim(),\r\n            day: day,\r\n            startSection: startSection,\r\n            endSection: endSection,\r\n            weeks: weeksArray\r\n        });\r\n    }\r\n\r\n    finalCourseList.sort((a, b) =>\r\n        a.day - b.day ||\r\n        a.startSection - b.startSection ||\r\n        a.name.localeCompare(b.name)\r\n    );\r\n\r\n    return finalCourseList;\r\n}\r\n\r\nfunction validateYearInput(input) {\r\n    if (/^[0-9]{4}$/.test(input)) {\r\n        return false;\r\n    } else {\r\n        return \"请输入四位数字的学年！\";\r\n    }\r\n}\r\n\r\nasync function promptUserToStart() {\r\n    return await window.shiguangBridgePromise.showAlert(\r\n        \"教务系统课表导入\",\r\n        \"导入前请确保您已登录教务系统并进入课表查询页面\",\r\n        \"好的，开始导入\"\r\n    );\r\n}\r\n\r\nasync function getAcademicYear() {\r\n    const currentYear = new Date().getFullYear().toString();\r\n    return await window.shiguangBridgePromise.showPrompt(\r\n        \"选择学年\",\r\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\r\n        currentYear,\r\n        \"validateYearInput\"\r\n    );\r\n}\r\n\r\nasync function selectSemester() {\r\n    const semesters = [\"第一学期\", \"第二学期\"];\r\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\r\n        \"选择学期\",\r\n        JSON.stringify(semesters),\r\n        0\r\n    );\r\n    return semesterIndex;\r\n}\r\n\r\nfunction getSemesterCode(semesterIndex) {\r\n    return semesterIndex === 0 ? \"3\" : \"12\";\r\n}\r\n\r\n/**\r\n * 请求和解析课程数据\r\n */\r\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\r\n    const semesterCode = getSemesterCode(semesterIndex);\r\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\r\n\r\n    const url = \"/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\r\n\r\n    try {\r\n        const response = await fetch(url, {\r\n            method: \"POST\",\r\n            headers: {\r\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\"\r\n            },\r\n            body: requestBody,\r\n            credentials: \"include\"\r\n        });\r\n\r\n        if (response.ok) {\r\n            const jsonText = await response.text();\r\n            const jsonData = JSON.parse(jsonText);\r\n            if (jsonData && jsonData.kbList) {\r\n                const parsedCourses = parseJsonData(jsonData);\r\n                if (parsedCourses.length > 0) {\r\n                    return {\r\n                        courses: parsedCourses,\r\n                        config: {\r\n                            semesterStartDate: null,\r\n                            semesterTotalWeeks: 20\r\n                        }\r\n                    };\r\n                }\r\n            }\r\n        }\r\n    } catch (e) {\r\n        console.error(\"获取课表失败: \" + e);\r\n    }\r\n\r\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查是否已登录并进入课表页面。\");\r\n    return null;\r\n}\r\n\r\nasync function saveCourses(parsedCourses) {\r\n    window.shiguangBridge.showToast(\"正在保存 \" + parsedCourses.length + \" 门课程...\");\r\n    try {\r\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\r\n        return true;\r\n    } catch (error) {\r\n        window.shiguangBridge.showToast(\"课程保存失败: \" + error.message);\r\n        return false;\r\n    }\r\n}\r\n\r\n// 贵州大学作息时间表\r\nconst TimeSlots = [\r\n    { number: 1,  startTime: \"08:00\", endTime: \"08:50\" },\r\n    { number: 2,  startTime: \"09:00\", endTime: \"09:50\" },\r\n    { number: 3,  startTime: \"10:10\", endTime: \"11:00\" },\r\n    { number: 4,  startTime: \"11:10\", endTime: \"12:00\" },\r\n    { number: 5,  startTime: \"14:30\", endTime: \"15:20\" },\r\n    { number: 6,  startTime: \"15:30\", endTime: \"16:20\" },\r\n    { number: 7,  startTime: \"16:40\", endTime: \"17:30\" },\r\n    { number: 8,  startTime: \"17:40\", endTime: \"18:30\" },\r\n    { number: 9,  startTime: \"19:30\", endTime: \"20:20\" },\r\n    { number: 10, startTime: \"20:30\", endTime: \"21:20\" },\r\n    { number: 11, startTime: \"21:30\", endTime: \"22:20\" }\r\n];\r\n\r\nasync function importPresetTimeSlots(timeSlots) {\r\n    if (timeSlots.length > 0) {\r\n        window.shiguangBridge.showToast(\"正在导入 \" + timeSlots.length + \" 个预设时间段...\");\r\n        try {\r\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\r\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\r\n        } catch (error) {\r\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\r\n        }\r\n    }\r\n}\r\n\r\nasync function runImportFlow() {\r\n    const alertConfirmed = await promptUserToStart();\r\n    if (!alertConfirmed) {\r\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\r\n        return;\r\n    }\r\n\r\n    const academicYear = await getAcademicYear();\r\n    if (academicYear === null) {\r\n        window.shiguangBridge.showToast(\"导入已取消。\");\r\n        return;\r\n    }\r\n\r\n    const semesterIndex = await selectSemester();\r\n    if (semesterIndex === null || semesterIndex === -1) {\r\n        window.shiguangBridge.showToast(\"导入已取消。\");\r\n        return;\r\n    }\r\n\r\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\r\n    if (result === null) return;\r\n    const { courses, config } = result;\r\n\r\n    const saveResult = await saveCourses(courses);\r\n    if (!saveResult) return;\r\n\r\n    try {\r\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\r\n        window.shiguangBridge.showToast(\"课表配置更新成功！总周数：\" + config.semesterTotalWeeks + \"周。\");\r\n    } catch (error) {\r\n        window.shiguangBridge.showToast(\"课表配置保存失败: \" + error.message);\r\n    }\r\n\r\n    await importPresetTimeSlots(TimeSlots);\r\n\r\n    window.shiguangBridge.showToast(\"课程导入成功，共导入 \" + courses.length + \" 门课程！\");\r\n    window.shiguangBridge.notifyTaskCompletion();\r\n}\r\n\r\nrunImportFlow();","ECJTU_01":"const BASE = window.location.origin;\nconst SCHEDULE_PATHS = [\n  '/Schedule/Schedule_getUserSchedume.action?item=0207',\n  '/Schedule/Schedule_getUserSchedume.action?item=0205',\n  '/Schedule/Schedule_getUserSchedume.action'\n];\n\nconst TIME_SLOTS = [\n  { number: 1, startTime: '08:00', endTime: '08:45' },\n  { number: 2, startTime: '08:55', endTime: '09:40' },\n  { number: 3, startTime: '10:05', endTime: '10:50' },\n  { number: 4, startTime: '10:55', endTime: '11:40' },\n  { number: 5, startTime: '14:30', endTime: '15:15' },\n  { number: 6, startTime: '15:25', endTime: '16:10' },\n  { number: 7, startTime: '16:40', endTime: '17:25' },\n  { number: 8, startTime: '17:35', endTime: '18:20' },\n  { number: 9, startTime: '19:00', endTime: '19:45' },\n  { number: 10, startTime: '19:55', endTime: '20:40' },\n];\n\nfunction cleanText(value) {\n  return String(value || '')\n    .replace(/[​-‍﻿]/g, '')\n    .replace(/ /g, ' ')\n    .trim();\n}\n\nfunction parseWeeks(weekStr) {\n  const weeks = [];\n  String(weekStr || '')\n    .replace(/\\s+/g, '')\n    .split(/[,，]/)\n    .forEach((part) => {\n      if (!part) return;\n      const isSingle = part.includes('单');\n      const isDouble = part.includes('双');\n      const rangeMatch = part.match(/(\\d+)-(\\d+)/);\n      if (rangeMatch) {\n        const start = parseInt(rangeMatch[1], 10);\n        const end = parseInt(rangeMatch[2], 10);\n        for (let i = start; i <= end; i++) {\n          if (isSingle && i % 2 === 0) continue;\n          if (isDouble && i % 2 !== 0) continue;\n          weeks.push(i);\n        }\n      } else {\n        const num = parseInt(part.replace(/[^\\d]/g, ''), 10);\n        if (!Number.isNaN(num)) weeks.push(num);\n      }\n    });\n  return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseSections(sectionStr) {\n  const sections = String(sectionStr || '')\n    .split(',')\n    .map(s => parseInt(s.trim(), 10))\n    .filter(n => !Number.isNaN(n));\n  if (!sections.length) return null;\n  return {\n    startSection: sections[0],\n    endSection: sections[sections.length - 1]\n  };\n}\n\nfunction parseTeacherPosition(line) {\n  const raw = cleanText(line);\n  const atIndex = raw.indexOf('@');\n  if (atIndex === -1) {\n    return { teacher: raw, position: '' };\n  }\n  return {\n    teacher: cleanText(raw.slice(0, atIndex)),\n    position: cleanText(raw.slice(atIndex + 1))\n  };\n}\n\nfunction parseCourseLines(lines, day) {\n  const items = [];\n  for (let i = 2; i < lines.length; i++) {\n    const line = cleanText(lines[i]);\n    const match = line.match(/^([\\d,，\\-单双()]+)\\s+(\\d+(?:,\\d+)*)$/);\n    if (!match) continue;\n\n    const name = cleanText(lines[i - 2]);\n    const teacherPosition = parseTeacherPosition(lines[i - 1]);\n    const weekText = match[1];\n    const sectionText = match[2];\n    const weeks = parseWeeks(weekText);\n    const sections = parseSections(sectionText);\n\n    if (!name || !weeks.length || !sections) continue;\n\n    items.push({\n      name,\n      teacher: teacherPosition.teacher || '未知教师',\n      position: teacherPosition.position || '未排地点',\n      day,\n      startSection: sections.startSection,\n      endSection: sections.endSection,\n      weeks\n    });\n  }\n  return items;\n}\n\nfunction mergeCourses(rawItems) {\n  const groupMap = new Map();\n  rawItems.forEach((item) => {\n    const key = `${item.name}|${item.teacher}|${item.position}|${item.day}`;\n    if (!groupMap.has(key)) groupMap.set(key, {});\n    const weekMap = groupMap.get(key);\n    item.weeks.forEach((week) => {\n      if (!weekMap[week]) weekMap[week] = new Set();\n      for (let section = item.startSection; section <= item.endSection; section++) {\n        weekMap[week].add(section);\n      }\n    });\n  });\n\n  const finalCourses = [];\n  groupMap.forEach((weekMap, key) => {\n    const [name, teacher, position, day] = key.split('|');\n    const patternMap = new Map();\n\n    Object.keys(weekMap).forEach((weekStr) => {\n      const week = parseInt(weekStr, 10);\n      const sections = Array.from(weekMap[week]).sort((a, b) => a - b);\n      if (!sections.length) return;\n      let start = sections[0];\n      for (let i = 0; i < sections.length; i++) {\n        if (i === sections.length - 1 || sections[i + 1] !== sections[i] + 1) {\n          const pKey = `${start}-${sections[i]}`;\n          if (!patternMap.has(pKey)) patternMap.set(pKey, []);\n          patternMap.get(pKey).push(week);\n          if (i < sections.length - 1) start = sections[i + 1];\n        }\n      }\n    });\n\n    patternMap.forEach((weeks, patternKey) => {\n      const [startSection, endSection] = patternKey.split('-').map(Number);\n      finalCourses.push({\n        name,\n        teacher,\n        position,\n        day: parseInt(day, 10),\n        startSection,\n        endSection,\n        weeks: weeks.sort((a, b) => a - b)\n      });\n    });\n  });\n\n  return finalCourses.sort((a, b) => (\n    a.day - b.day\n    || a.startSection - b.startSection\n    || a.name.localeCompare(b.name, 'zh-CN')\n  ));\n}\n\nfunction parseScheduleTable(doc) {\n  const table = doc.getElementById('courseSche');\n  if (!table) return [];\n\n  const rows = Array.from(table.rows);\n  if (rows.length < 2) return [];\n\n  const rawItems = [];\n  for (let r = 1; r < rows.length; r++) {\n    const cells = Array.from(rows[r].cells);\n    if (cells.length < 2) continue;\n\n    const dayCells = cells.slice(1, 8);\n    dayCells.forEach((cell, index) => {\n      const rawText = cleanText(cell.innerText);\n      if (!rawText || !rawText.includes('@')) return;\n      const lines = cell.innerText\n        .split(/\\n+/)\n        .map(cleanText)\n        .filter(Boolean);\n      rawItems.push(...parseCourseLines(lines, index + 1));\n    });\n  }\n\n  return mergeCourses(rawItems);\n}\n\nfunction getCurrentTermInfo(doc) {\n  const select = doc.querySelector('#term');\n  if (!select) return null;\n  const selected = select.querySelector('option:checked') || select.options[select.selectedIndex];\n  return {\n    value: String(select.value || '').trim(),\n    text: selected ? cleanText(selected.textContent) : ''\n  };\n}\n\nfunction isScheduleDoc(doc) {\n  return !!(doc && (doc.getElementById('courseSche') || doc.querySelector('#term')));\n}\n\nfunction findScheduleDoc(win) {\n  try {\n    if (isScheduleDoc(win.document)) return win.document;\n  } catch (_) {}\n  for (let i = 0; i < win.frames.length; i++) {\n    try {\n      const found = findScheduleDoc(win.frames[i]);\n      if (found) return found;\n    } catch (_) {}\n  }\n  return null;\n}\n\nasync function fetchScheduleDoc() {\n  for (const path of SCHEDULE_PATHS) {\n    try {\n      const res = await fetch(`${BASE}${path}`, { credentials: 'include' });\n      if (!res.ok) continue;\n      const html = await res.text();\n      const doc = new DOMParser().parseFromString(html, 'text/html');\n      if (isScheduleDoc(doc)) return doc;\n    } catch (_) {}\n  }\n  return null;\n}\n\nasync function loadScheduleDoc() {\n  const currentDoc = findScheduleDoc(window);\n  if (currentDoc && currentDoc.getElementById('courseSche')) return currentDoc;\n  const fetched = await fetchScheduleDoc();\n  if (fetched) return fetched;\n  throw new Error('未找到课表页面，请先登录后进入“我的课表/个人课表”页面');\n}\n\nasync function runImportFlow() {\n  try {\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n      '华东交通大学教务导入',\n      '请确认你已经登录教务系统；如需导入其他学期，请先在页面上切换到目标学期后再导入。',\n      '确定，开始导入'\n    );\n    if (!confirmed) return;\n\n    const doc = await loadScheduleDoc();\n    const termInfo = getCurrentTermInfo(doc);\n    window.shiguangBridge.showToast(termInfo?.text ? `正在导入 ${termInfo.text} 课表...` : '正在解析课表数据...');\n\n    const courses = parseScheduleTable(doc);\n    if (!courses.length) {\n      throw new Error('未解析到课程，请确认当前课表已正常显示');\n    }\n\n    const allWeeks = courses.flatMap(course => course.weeks);\n    const semesterTotalWeeks = allWeeks.length ? Math.max(...allWeeks) : 20;\n\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n      semesterTotalWeeks,\n      semesterStartDate: null,\n      firstDayOfWeek: 1\n    }));\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TIME_SLOTS));\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n    window.shiguangBridge.showToast(`导入成功：共 ${courses.length} 门课程`);\n    window.shiguangBridge.notifyTaskCompletion();\n  } catch (error) {\n    console.error(error);\n    window.shiguangBridge.showToast(`导入失败: ${error.message}`);\n  }\n}\n\nrunImportFlow();\n","HUST_01":"/**\n * 华中科技大学 HUB 系统课表适配器。\n *\n * 接口与解析规则参考 StayUP-Calendar 的 HUST importer：\n * https://github.com/Lucas04-nhr/StayUP-Calendar/blob/main/lib/src/pages/crawler/hust.dart\n */\n\nconst HUST_COURSE_API = new URL(\"/LsController/findNameCourse\", location.origin).toString();\nconst HUST_DEFAULT_SEMESTER_WEEKS = 20;\n\nfunction getDefaultTerm(now = new Date()) {\n    return {\n        academicYear: now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear(),\n        semester: now.getMonth() >= 1 && now.getMonth() <= 6 ? 2 : 1\n    };\n}\n\n/**\n * 生成与原 importer 相同范围的学期：当前年份前 4 年至后 1 年，共 12 个。\n * semester=1 为秋季，semester=2 为春季；倒序排列便于优先选择近期学期。\n */\nfunction buildTermOptions(now = new Date()) {\n    const currentYear = now.getFullYear();\n    const terms = [];\n\n    for (let year = currentYear + 1; year >= currentYear - 4; year--) {\n        terms.push({ academicYear: year, semester: 1, label: `${year} 年秋季学期` });\n        terms.push({ academicYear: year, semester: 2, label: `${year} 年春季学期` });\n    }\n\n    return terms;\n}\n\nasync function selectTerm() {\n    const terms = buildTermOptions();\n    const defaultTerm = getDefaultTerm();\n    const defaultIndex = Math.max(0, terms.findIndex((term) =>\n        term.academicYear === defaultTerm.academicYear &&\n        term.semester === defaultTerm.semester\n    ));\n\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(terms.map((term) => term.label)),\n        defaultIndex\n    );\n\n    if (selectedIndex === null || selectedIndex === -1) {\n        return null;\n    }\n    if (!Number.isInteger(selectedIndex) || selectedIndex < 0 || selectedIndex >= terms.length) {\n        throw new Error(\"学期选择结果无效\");\n    }\n\n    return terms[selectedIndex];\n}\n\nfunction parsePositiveInteger(value) {\n    const parsed = Number.parseInt(String(value), 10);\n    return Number.isInteger(parsed) && parsed > 0 ? parsed : null;\n}\n\nfunction expandWeeks(startWeek, endWeek) {\n    const weeks = [];\n    for (let week = startWeek; week <= endWeek; week++) {\n        weeks.push(week);\n    }\n    return weeks;\n}\n\n/**\n * HUST 的一门课程可包含多个 tr 时段。本项目没有 extraSlots 字段，\n * 因此每个有效时段转换成一个标准课程块。\n */\nfunction parseCourses(payload) {\n    if (!payload || String(payload.code) !== \"200\" || !Array.isArray(payload.data)) {\n        throw new Error(`课表接口返回异常（code: ${payload?.code ?? \"未知\"}）`);\n    }\n\n    const courses = [];\n\n    for (const item of payload.data) {\n        const name = String(item?.KCMC ?? \"\").trim();\n        if (!name || !Array.isArray(item?.tr)) {\n            continue;\n        }\n\n        for (const slot of item.tr) {\n            if (slot?.XQS === \"<待定>\" || slot?.QSJC === \"<待定>\") {\n                continue;\n            }\n\n            const day = parsePositiveInteger(slot?.XQS);\n            const startSection = parsePositiveInteger(slot?.QSJC);\n            const endSection = parsePositiveInteger(slot?.JSJC);\n            const startWeek = parsePositiveInteger(slot?.QSZC);\n            const endWeek = parsePositiveInteger(slot?.JSZC);\n\n            if (\n                day === null || day > 7 ||\n                startSection === null || endSection === null || endSection < startSection ||\n                startWeek === null || endWeek === null || endWeek < startWeek\n            ) {\n                console.warn(\"跳过无法解析的 HUST 课程时段:\", name, slot);\n                continue;\n            }\n\n            courses.push({\n                name,\n                teacher: String(slot?.XM ?? \"\").trim(),\n                position: String(slot?.JSMC ?? \"\").trim(),\n                day,\n                startSection,\n                endSection,\n                weeks: expandWeeks(startWeek, endWeek)\n            });\n        }\n    }\n\n    return courses;\n}\n\nasync function fetchCourses(term) {\n    const termCode = `${term.academicYear}${term.semester}`;\n    const response = await fetch(`${HUST_COURSE_API}?kcbxqh=${encodeURIComponent(termCode)}`, {\n        method: \"GET\",\n        credentials: \"include\",\n        headers: {\n            Accept: \"application/json, text/plain, */*\"\n        }\n    });\n\n    if (!response.ok) {\n        throw new Error(`课表请求失败（HTTP ${response.status}）`);\n    }\n\n    const raw = await response.text();\n    if (!raw.trim() || raw.trim().startsWith(\"<\")) {\n        throw new Error(\"未读取到课表数据，请确认已登录 HUB 系统并选择了正确的学期\");\n    }\n\n    try {\n        return parseCourses(JSON.parse(raw));\n    } catch (error) {\n        if (error instanceof SyntaxError) {\n            throw new Error(\"课表接口未返回有效 JSON，请重新登录后再试\");\n        }\n        throw error;\n    }\n}\n\nasync function saveCourses(courses) {\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n    const semesterTotalWeeks = courses.reduce((maximum, course) => {  \n        const courseMaximum = course.weeks.length > 0 ? Math.max(...course.weeks) : 0;  \n        return Math.max(maximum, courseMaximum);  \n    }, HUST_DEFAULT_SEMESTER_WEEKS);  \n\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({ semesterTotalWeeks }));  \n}\n\nasync function runImportFlow() {\n    try {\n        const term = await selectTerm();\n        if (term === null) {\n            window.shiguangBridge.showToast(\"已取消导入\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(`正在获取 ${term.label} 课表...`);\n        const courses = await fetchCourses(term);\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"该学期未查询到有效课程，请检查学期或登录状态\");\n            return;\n        }\n\n        await saveCourses(courses);\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 个课程时段，请按校历设置开学日期`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        console.error(\"课表导入失败:\", error);\n        window.shiguangBridge.showToast(`导入失败：${error?.message ?? error}`);\n    }\n}\n\nrunImportFlow();\n","HQU":"/**\n * 华侨大学 (HQU) 教务系统课程导入脚本\n * 版本：2026 春季学期\n * 还有待解决的问题：课程合并 \n */\n\n// 1. 全局验证函数 (由 showPrompt 调用)\nfunction validateTermInput(input) {\n    if (/^\\d{4}-\\d{4}-\\d$/.test(input)) {\n        return false; // 校验通过\n    } else {\n        return \"格式错误！请输入如 2025-2026-2\";\n    }\n}\n\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"正在启动华大教务同步程序...\");\n\n    try {\n        // --- 1. 获取学期代码 ---\n        const termQuery = [\n            { name: \"CSDM\", linkOpt: \"AND\", builderList: \"cbl_String\", builder: \"equal\", value: \"PK\" },\n            { name: \"ZCSDM\", linkOpt: \"AND\", builderList: \"cbl_String\", builder: \"equal\", value: \"XSDXNXQDM\" }\n        ];\n        \n        const termResp = await fetch(\"https://jwapp-hqu-edu-cn-s.atrust.hqu.edu.cn:9443/jwapp/sys/wdkb/modules/xskcb/xtcscx.do?sf_request_type=ajax\", {\n            method: \"POST\",\n            headers: { \"content-type\": \"application/x-www-form-urlencoded\" },\n            body: `querySetting=${encodeURIComponent(JSON.stringify(termQuery))}`\n        });\n        const termJson = await termResp.json();\n        const currentXNXQ = termJson.datas.xtcscx.CSZA || \"2025-2026-2\";\n\n        const parts = currentXNXQ.split('-');\n        const currentXN = `${parts}-${parts}`;\n        const currentXQ = parts;\n\n        // --- 2. 获取配置与开学日期 ---\n        let startDate = \"2026-03-02\";\n        let totalWeeks = 18;\n        try {\n            const configResp = await fetch(\"https://jwapp-hqu-edu-cn-s.atrust.hqu.edu.cn:9443/jwapp/sys/wdkb/modules/jshkcb/cxjcs.do?sf_request_type=ajax\", {\n                method: \"POST\",\n                headers: { \"content-type\": \"application/x-www-form-urlencoded\" },\n                body: `XN=${currentXN}&XQ=${currentXQ}`\n            });\n            const configJson = await configResp.json();\n            const schoolConfig = configJson.datas.cxjcs.rows;\n            if (schoolConfig && schoolConfig.XQKSRQ) {\n                startDate = schoolConfig.XQKSRQ.split(' ');\n                totalWeeks = parseInt(schoolConfig.ZZC) || 18;\n            }\n        } catch (e) { console.log(\"配置抓取跳过\"); }\n\n        // --- 3. 抓取课表详情 ---\n        const kbResp = await fetch(\"https://jwapp-hqu-edu-cn-s.atrust.hqu.edu.cn:9443/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do?sf_request_type=ajax\", {\n            method: \"POST\",\n            headers: { \"content-type\": \"application/x-www-form-urlencoded\" },\n            body: `XNXQDM=${currentXNXQ}&XNXQDM2=${currentXNXQ}&XNXQDM3=${currentXNXQ}`\n        });\n        const kbJson = await kbResp.json();\n        const rawRows = kbJson.datas.cxxszhxqkb.rows;\n\n        //转换数据结构\n        const parsedCourses = rawRows.map(item => {\n    // 1. 周次解析：从位图获取最硬核的数据\n        const weeks = [];\n        const bitMap = item.SKZC || \"\";\n            \n\n    // 华大逻辑：如果位图索引1是1，那就是第一周有课  你看它里面  \"SKZC\": \"011111111111111100\",\n    for (let i = 0; i < bitMap.length; i++) {\n        if (bitMap[i] === '1') {\n            weeks.push(i + 1); \n        }\n    }\n            \n    // 体育课的标题：体育课加上具体的项目（如：篮球）\n    let courseName = item.KCM;\n    if (item.TYXMDM_DISPLAY) {\n        courseName = `${courseName}(${item.TYXMDM_DISPLAY})`;\n    }\n\n    // 地点兜底：优先取具体教室，没有则取教学楼，再没有则标记操场\n    const position = item.JASMC || item.JXLDM_DISPLAY || \"操场/待定\";\n\n    // 2. YPSJDD \n    let note = `原始安排：${item.YPSJDD || '无'}`;\n    if (item.XF) note += `\\n学分：${item.XF}`;\n    if (item.KCXZDM_DISPLAY) note += `\\n性质：${item.KCXZDM_DISPLAY}`;\n\n    return {\n        name: item.KCM,\n        teacher: item.SKJS || item.JSM || \"未知\",\n        position: position,\n        day: parseInt(item.SKXQ),\n        startSection: parseInt(item.KSJC),\n        endSection: parseInt(item.JSJC),\n        weeks: weeks,\n    };\n});\n\n        // --- 5. 提交数据 ---\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n            semesterStartDate: startDate,\n            semesterTotalWeeks: totalWeeks\n        }));\n\n        const timeSlots = [\n            { number: 1, startTime: \"08:00\", endTime: \"08:45\" }, { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n            { number: 3, startTime: \"10:00\", endTime: \"10:45\" }, { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n            { number: 5, startTime: \"11:45\", endTime: \"12:30\" }, { number: 6, startTime: \"14:30\", endTime: \"15:15\" },\n            { number: 7, startTime: \"15:25\", endTime: \"16:10\" }, { number: 8, startTime: \"16:20\", endTime: \"17:05\" },\n            { number: 9, startTime: \"17:15\", endTime: \"18:00\" }, { number: 10, startTime: \"18:20\", endTime: \"19:05\" },\n            { number: 11, startTime: \"19:10\", endTime: \"19:55\" }, { number: 12, startTime: \"20:05\", endTime: \"20:50\" },\n            { number: 13, startTime: \"20:55\", endTime: \"21:40\" }\n        ];\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n\n        window.shiguangBridge.showToast(`${currentXNXQ} 导入成功！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (e) {\n        await window.shiguangBridgePromise.showAlert(\"导入失败\", \"错误: \" + e.message, \"重试\");\n    }\n}\n\nrunImportFlow();","SCNU_01":"// 华南师范大学本科教务系统。登录后，在教务系统内任意页面执行；学年学期在弹窗中确认，默认为当前学期。\n// 主接口包含部分实验课；独立实验预约系统的安排不在本脚本的导入范围内。\n(async function () {\n    const bridge = window.shiguangBridgePromise;\n    const native = window.shiguangBridge;\n    if (!bridge || !native) throw new Error('请通过拾光课程表或适配测试器运行此脚本。');\n    if (window.__scnuImportRunning) {\n        native.showToast('华师课表正在导入，请勿重复点击。');\n        return;\n    }\n    window.__scnuImportRunning = true;\n    let saving = false;\n\n    // 华师教务页面（zftal-ui 的 jquery.extends.contact）改写了部分原型方法：\n    // Array.prototype.filter/some 的回调实参变成 (下标, 元素, 数组)，every 恒为 true，\n    // String.prototype.trim 会删除所有空白而非仅首尾。本脚本只使用原生安全的写法：\n    // 用 replace 实现 trim，不用 filter/some/every 做数组过滤。\n    const text = value => String(value == null ? '' : value).replace(/^\\s+|\\s+$/g, '');\n\n    // 整段匹配，遇到未知格式就停止，避免部分解析造成漏课或多排课。\n    function parseNumbers(value, unit, limit, allowParity) {\n        const normalized = text(value).replace(/\\s/g, '').replace(/，|、/g, ',')\n            .replace(/（/g, '(').replace(/）/g, ')');\n        const numbers = new Set();\n        for (const part of normalized.split(',')) {\n            const match = part.match(/^(\\d+)(?:-(\\d+))?(?:周|节)?(?:\\(([单双])(?:周)?\\))?$/);\n            if (!match || (match[3] && !allowParity) || (unit === '周' ? part.includes('节') : part.includes('周'))) {\n                throw new Error(`无法识别${unit}次：${value}`);\n            }\n            const start = Number(match[1]);\n            const end = Number(match[2] || match[1]);\n            if (start < 1 || end < start || end > limit) throw new Error(`${unit}次范围无效：${value}`);\n            for (let n = start; n <= end; n++) {\n                if (match[3] === '单' && n % 2 === 0) continue;\n                if (match[3] === '双' && n % 2 !== 0) continue;\n                numbers.add(n);\n            }\n        }\n        if (!numbers.size) throw new Error(`${unit}次为空：${value}`);\n        return [...numbers].sort((a, b) => a - b);\n    }\n\n    function parseCourses(rows) {\n        const entries = [];\n        for (const raw of rows) {\n            const name = text(raw.kcmc);\n            try {\n                const day = Number(raw.xqj);\n                if (!name || !Number.isInteger(day) || day < 1 || day > 7) throw new Error('缺少课程名称或有效星期');\n                const campusId = text(raw.xqh_id);\n                if (!campusId) throw new Error('缺少校区编号，无法确定作息时间');\n                const weeks = parseNumbers(raw.zcd, '周', 100, true);\n                const sections = parseNumbers(raw.jcs, '节', 30, false);\n                const type = { '*': '理论', '&': '实验', '#': '实践' }[text(raw.xslxbj)];\n                // 当前 App 的此导入路径不保存 remark，课程类型直接写入名称。\n                const courseName = type && type !== '理论' && !name.includes(type) ? `${name}（${type}）` : name;\n                for (let i = 0; i < sections.length; i++) {\n                    const startSection = sections[i];\n                    while (i + 1 < sections.length && sections[i + 1] === sections[i] + 1) i++;\n                    entries.push({\n                        campusId,\n                        campusName: text(raw.xqmc) || campusId,\n                        course: {\n                            name: courseName,\n                            teacher: text(raw.xm),\n                            // 页面的 Array.prototype.filter 已被污染，拼接后统一去空白。\n                            position: text(`${text(raw.xqmc)} ${text(raw.cdmc)}`),\n                            day, startSection, endSection: sections[i], weeks\n                        }\n                    });\n                }\n            } catch (error) {\n                throw new Error(`${name || '未命名课程'}：${error.message}`);\n            }\n        }\n        return entries;\n    }\n\n    function parseTimeSlots(rows) {\n        if (!Array.isArray(rows) || !rows.length) throw new Error('没有取得校区作息时间');\n        const slots = rows.map(row => ({\n            number: Number(row.jcmc), startTime: text(row.qssj), endTime: text(row.jssj)\n        })).sort((a, b) => a.number - b.number);\n        let previousEnd = '';\n        slots.forEach((slot, index) => {\n            const validTime = value => /^([01]\\d|2[0-3]):[0-5]\\d$/.test(value);\n            if (slot.number !== index + 1 || !validTime(slot.startTime) || !validTime(slot.endTime)\n                || slot.startTime >= slot.endTime || slot.startTime < previousEnd) {\n                throw new Error('校区作息时间格式无效、节次不连续或时间重叠');\n            }\n            previousEnd = slot.endTime;\n        });\n        return slots;\n    }\n\n    // 周次校历接口（xskbcxZccx_cxZcByXnxq）返回每周的起止日期，可推导开学日期、总周数与每周起始日。\n    function parseWeekCalendar(rows) {\n        if (!Array.isArray(rows) || !rows.length) throw new Error('没有取得学期周次校历');\n        const weeks = rows.map(row => {\n            const number = Number(row.zs);\n            const start = text(row.rq).split('/')[0];\n            if (!Number.isInteger(number) || number < 1 || !/^\\d{4}-\\d{2}-\\d{2}$/.test(start)) {\n                throw new Error('学期周次校历格式无效');\n            }\n            const date = new Date(`${start}T00:00:00Z`);\n            if (Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== start) {\n                throw new Error(`学期周次校历包含无效日期：${start}`);\n            }\n            return { number, start };\n        }).sort((a, b) => a.number - b.number);\n        weeks.forEach((week, index) => {\n            if (week.number !== index + 1) throw new Error('学期周次校历的周次不连续');\n        });\n        // App 的 firstDayOfWeek 约定为 ISO 星期（1=周一 … 7=周日），由开学日当天推算。\n        const firstDayOfWeek = (new Date(`${weeks[0].start}T00:00:00Z`).getUTCDay() + 6) % 7 + 1;\n        return { startDate: weeks[0].start, totalWeeks: weeks.length, firstDayOfWeek };\n    }\n\n    function toMinutes(value) {\n        const [hours, minutes] = value.split(':').map(Number);\n        return hours * 60 + minutes;\n    }\n\n    // 同一课程可能被教务拆成多条记录（如 1-8周 与 9-16周、1-2节 与 3-4节），参考 QQHRIT 适配做两阶段合并：\n    // 先并相接/重复的节次，再并同节次的周次，减少课表里的重复卡片。\n    // 判等键包含自定义时间，作息不同的记录不会被错误合并。\n    function mergeCourses(courses) {\n        if (courses.length <= 1) return courses;\n        const keyOf = c => [c.name, c.teacher, c.position, c.day,\n            c.isCustomTime ? `${c.customStartTime}-${c.customEndTime}` : ''].join('\\u0001');\n        const compareKey = (a, b) => {\n            const ka = keyOf(a), kb = keyOf(b);\n            return ka < kb ? -1 : ka > kb ? 1 : 0;\n        };\n        const compareText = (x, y) => x < y ? -1 : x > y ? 1 : 0;\n        const byStart = [...courses].sort((a, b) => compareKey(a, b)\n            || compareText(a.weeks.join(','), b.weeks.join(','))\n            || a.startSection - b.startSection);\n        const step1 = [];\n        for (const c of byStart) {\n            const prev = step1[step1.length - 1];\n            if (prev && compareKey(prev, c) === 0 && prev.weeks.join(',') === c.weeks.join(',')\n                && c.startSection <= prev.endSection + 1) {\n                if (c.endSection > prev.endSection) prev.endSection = c.endSection;\n                continue;\n            }\n            step1.push({ ...c, weeks: [...c.weeks] });\n        }\n        step1.sort((a, b) => compareKey(a, b) || a.startSection - b.startSection || a.endSection - b.endSection);\n        const step2 = [];\n        for (const c of step1) {\n            const prev = step2[step2.length - 1];\n            if (prev && compareKey(prev, c) === 0\n                && prev.startSection === c.startSection && prev.endSection === c.endSection) {\n                prev.weeks = [...new Set([...prev.weeks, ...c.weeks])].sort((a, b) => a - b);\n                continue;\n            }\n            step2.push(c);\n        }\n        return step2;\n    }\n\n    // 参考 QQHRIT 适配：抓取课表查询页 HTML，读出学年学期下拉框的选项与默认选中项，\n    // 让用户在弹窗里确认或修改，无需事先停留在课表页面。\n    async function fetchAcademicOptions() {\n        // 课表查询页地址必须带其菜单功能代码，否则服务端直接报错；N253508 为个人课表查询页面的菜单代码。\n        const response = await fetch('/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N253508&layout=default', { credentials: 'same-origin' });\n        if (!response.ok) throw new Error(`读取学年学期选项失败（HTTP ${response.status}）`);\n        const doc = new DOMParser().parseFromString(await response.text(), 'text/html');\n        const readOptions = selector => {\n            const select = doc.querySelector(selector);\n            if (!select) return [];\n            const options = [];\n            for (const option of select.querySelectorAll('option')) {\n                if (!option.value) continue;\n                options.push({ value: option.value, label: text(option.textContent), selected: option.selected || option.hasAttribute('selected') });\n            }\n            return options;\n        };\n        const years = readOptions('#xnm');\n        const semesters = readOptions('#xqm');\n        if (!years.length || !semesters.length) throw new Error('读取学年学期选项失败，请确认登录未过期');\n        return { years, semesters };\n    }\n\n    async function selectYearSemester() {\n        const { years, semesters } = await fetchAcademicOptions();\n        const selectedYear = years.findIndex(o => o.selected);\n        // 学年选项跨度通常很大，以当前学年为中心截取前后各两年，默认选中原学年。\n        const start = Math.max(0, (selectedYear === -1 ? 0 : selectedYear) - 2);\n        const yearChoices = years.slice(start, start + 5);\n        const pickedYear = await bridge.showSingleSelection('选择学年', JSON.stringify(yearChoices.map(o => o.label)), selectedYear === -1 ? 0 : selectedYear - start);\n        if (pickedYear === null || pickedYear === -1) return null;\n        if (!Number.isInteger(pickedYear) || !yearChoices[pickedYear]) throw new Error('学年选择无效');\n        const selectedSemester = semesters.findIndex(o => o.selected);\n        const pickedSemester = await bridge.showSingleSelection('选择学期', JSON.stringify(semesters.map(o => `第 ${o.label} 学期`)), selectedSemester === -1 ? 0 : selectedSemester);\n        if (pickedSemester === null || pickedSemester === -1) return null;\n        if (!Number.isInteger(pickedSemester) || !semesters[pickedSemester]) throw new Error('学期选择无效');\n        return { xnm: yearChoices[pickedYear].value, xnmText: yearChoices[pickedYear].label, xqm: semesters[pickedSemester].value, xqmText: semesters[pickedSemester].label };\n    }\n\n    async function requestJson(path, params) {\n        const controller = new AbortController();\n        const timer = setTimeout(() => controller.abort(), 20000);\n        try {\n            const response = await fetch(path, {\n                method: 'POST', credentials: 'same-origin',\n                headers: {\n                    'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',\n                    'X-Requested-With': 'XMLHttpRequest'\n                },\n                body: new URLSearchParams(params).toString(), signal: controller.signal\n            });\n            if (!response.ok) throw new Error(`教务请求失败（HTTP ${response.status}）`);\n            let data;\n            try {\n                data = await response.json();\n            } catch (_) {\n                throw new Error('教务系统没有返回 JSON，请确认登录未过期后重试');\n            }\n            if (!data || typeof data !== 'object') throw new Error('教务系统未返回有效数据，请检查登录状态及查询权限');\n            return data;\n        } catch (error) {\n            if (error.name === 'AbortError') throw new Error('教务请求超时，请稍后重试');\n            throw error;\n        } finally {\n            clearTimeout(timer);\n        }\n    }\n\n    async function save(method, value) {\n        const result = await bridge[method](JSON.stringify(value));\n        if (result !== true) throw new Error(`${method} 未确认保存成功`);\n    }\n\n    try {\n        if (window.location.hostname !== 'jwxt.scnu.edu.cn') {\n            throw new Error('请先登录华师教务系统，停留在教务系统内任意页面后再导入');\n        }\n        const selection = await selectYearSemester();\n        if (!selection) return;\n        const { xnm, xnmText, xqm, xqmText } = selection;\n        if (!/^\\d{4}$/.test(xnm) || !xqm) throw new Error('学年学期选项无效');\n        native.showToast('正在获取华师课表、校区作息与学期校历…');\n        const data = await requestJson('/kbcx/xskbcx_cxXsgrkb.html', {\n            xnm, xqm, kzlx: 'ck', xsdm: '', kclbdm: '', kclxdm: ''\n        });\n        if (!Array.isArray(data.kbList)) throw new Error('响应缺少课表数据，请确认登录未过期');\n        if (data.sjkList != null && !Array.isArray(data.sjkList)) throw new Error('未排课数据格式异常');\n        const other = (data.sjkList || []).map(c => text(`${text(c.kcmc) || '未命名课程'} ${text(c.qsjsz)}`));\n        if (!data.kbList.length) {\n            await bridge.showAlert('没有已排课程', ['所选学期没有可导入的已排课程，原课表未改动。', ...other].join('\\n'), '确定');\n            return;\n        }\n        const entries = parseCourses(data.kbList);\n        const campuses = [...new Map(entries.map(e => [e.campusId, e.campusName])).entries()];\n        // 校区作息与学期周次校历互不依赖，并行获取。\n        const schedules = new Map();\n        const fetchSchedule = async (id, name) => {\n            try {\n                schedules.set(id, parseTimeSlots(await requestJson('/kbcx/xskbcx_cxRjc.html', { xnm, xqm, xqh_id: id })));\n            } catch (error) {\n                throw new Error(`${name}校区：${error.message}`);\n            }\n        };\n        const fetchCalendar = async () => {\n            try {\n                return parseWeekCalendar(await requestJson('/kbcx/xskbcxZccx_cxZcByXnxq.html', { xnm, xqm }));\n            } catch (error) {\n                throw new Error(`学期周次校历：${error.message}`);\n            }\n        };\n        const [calendar] = await Promise.all([fetchCalendar(), ...campuses.map(([id, name]) => fetchSchedule(id, name))]);\n        let presetIndex = 0;\n        if (campuses.length > 1) {\n            presetIndex = await bridge.showSingleSelection('默认作息校区', JSON.stringify(campuses.map(c => c[1])), 0);\n            if (presetIndex === null || presetIndex === -1) return;\n            if (!Number.isInteger(presetIndex) || !campuses[presetIndex]) throw new Error('校区选择无效');\n        }\n        const [presetCampus, presetName] = campuses[presetIndex];\n        const timeSlots = schedules.get(presetCampus);\n        const courses = entries.map(({ course, campusId }) => {\n            const slots = schedules.get(campusId);\n            const first = slots[course.startSection - 1];\n            const last = slots[course.endSection - 1];\n            if (!first || !last) throw new Error(`${course.name} 的节次超出校区作息范围`);\n            if (campusId !== presetCampus && JSON.stringify(slots) !== JSON.stringify(timeSlots)) {\n                return { ...course, isCustomTime: true, customStartTime: first.startTime, customEndTime: last.endTime };\n            }\n            return course;\n        });\n        const merged = mergeCourses(courses);\n        const config = {\n            semesterStartDate: calendar.startDate,\n            semesterTotalWeeks: calendar.totalWeeks,\n            defaultClassDuration: toMinutes(timeSlots[0].endTime) - toMinutes(timeSlots[0].startTime),\n            defaultBreakDuration: timeSlots.length > 1 ? toMinutes(timeSlots[1].startTime) - toMinutes(timeSlots[0].endTime) : 10,\n            firstDayOfWeek: calendar.firstDayOfWeek\n        };\n        const summary = [\n            `${xnmText} 学年第 ${xqmText} 学期`,\n            `${merged.length} 条排课记录；默认作息：${presetName}。`,\n            `开学日期：${calendar.startDate}，共 ${calendar.totalWeeks} 周。`,\n            '将覆盖所选目标课表的课程、作息与学期配置',\n            '本次仅导入个人课表主接口中的安排；独立实验预约安排请另行核对。'\n        ];\n        if (other.length) summary.push(`以下 ${other.length} 门课程未提供星期和节次，不会导入，请按实际安排手动添加：`, ...other);\n        if (!await bridge.showAlert('确认导入华师课表', summary.join('\\n\\n'), '确认导入')) return;\n\n        // 三个 Bridge 保存操作彼此独立，失败后不能宣称已全部完成或已回滚。\n        saving = true;\n        await save('saveImportedCourses', merged);\n        await save('savePresetTimeSlots', timeSlots);\n        await save('saveCourseConfig', config);\n        await bridge.showAlert('华师课表导入完成', [\n            `已导入 ${merged.length} 条排课记录及校区作息。`,\n            `开学日期 ${calendar.startDate}，共 ${calendar.totalWeeks} 周，已写入课表配置。`,\n            '课程周次已按教务系统返回的数据导入。'\n        ].join('\\n\\n'), '确定');\n        native.notifyTaskCompletion();\n    } catch (error) {\n        const suffix = saving ? '\\n保存已经开始，目标课表可能已部分更新。请检查后重新导入。' : '\\n尚未写入目标课表。';\n        await bridge.showAlert('华师课表导入失败', `${error.message}${suffix}`, '确定');\n    } finally {\n        delete window.__scnuImportRunning;\n    }\n})();\n","SCUT_01":"/**\n * 解析正方教务系统的周次字符串\n */\nfunction parseZhengFangWeeks(weekStr) {\n    if (!weekStr) return [];\n    let weeks = [];\n    let isOdd = weekStr.includes('单');\n    let isEven = weekStr.includes('双');\n    let cleanStr = weekStr.replace(/周|\\(单\\)|\\(双\\)|单|双/g, '').replace(/\\s+/g, '');\n\n    let parts = cleanStr.split(',');\n    for (let part of parts) {\n        if (part.includes('-')) {\n            let [start, end] = part.split('-');\n            for (let i = parseInt(start); i <= parseInt(end); i++) {\n                if (isOdd && i % 2 === 0) continue;\n                if (isEven && i % 2 !== 0) continue;\n                if (!weeks.includes(i)) weeks.push(i);\n            }\n        } else {\n            let w = parseInt(part);\n            if (!isNaN(w) && !weeks.includes(w)) {\n                if (isOdd && w % 2 === 0) continue;\n                if (isEven && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 封装兼容 WebVPN 的原生 AJAX 请求\n */\nfunction requestData(url, method = 'GET', data = null) {\n    return new Promise((resolve, reject) => {\n        let xhr = new XMLHttpRequest();\n        xhr.open(method, url, true);\n        if (method === 'POST') {\n            xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded;charset=UTF-8');\n            xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');\n        }\n        xhr.onreadystatechange = function() {\n            if (xhr.readyState === 4) {\n                if (xhr.status >= 200 && xhr.status < 300) {\n                    resolve(xhr.responseText);\n                } else {\n                    reject(new Error(\"网络请求失败，状态码：\" + xhr.status));\n                }\n            }\n        };\n        xhr.onerror = function() {\n            reject(new Error(\"网络请求发生错误，请检查网络连接。\"));\n        };\n        xhr.send(data);\n    });\n}\n\n/**\n * 用正则从 HTML 文本中硬核提取 select 选项\n */\nfunction extractOptionsByRegex(html, selectId) {\n    let selectRegex = new RegExp(`<select[^>]*id=\"${selectId}\"[^>]*>(.*?)<\\/select>`, 'is');\n    let selectMatch = html.match(selectRegex);\n    if (!selectMatch) return [];\n    \n    let optionsHtml = selectMatch[1];\n    let optionRegex = /<option\\s+value=\"([^\"]+)\"([^>]*)>([^<]+)<\\/option>/gi;\n    let options = [];\n    let match;\n    while ((match = optionRegex.exec(optionsHtml)) !== null) {\n        if (match[1].trim() !== \"\") {\n            options.push({\n                value: match[1].trim(),\n                text: match[3].trim(),\n                selected: match[2].includes('selected')\n            });\n        }\n    }\n    return options;\n}\n\n/**\n * 异步编排流程\n */\nasync function runImportFlow() {\n    try {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"正在通过 WebVPN 通道读取数据...\");\n        } else {\n            console.log(\"【1/4】正在获取学期选项...\");\n        }\n\n        let sysPath = typeof _path !== 'undefined' ? _path : '/jwglxt';\n        let semesters = [];\n        let semesterValues = [];\n        let defaultIndex = 0;\n\n        // 1. 尝试直接通过正则表达式，去后台请求并提取页面中的下拉框\n        console.log(\"正在后台请求页面源码...\");\n        const indexHtml = await requestData(`${sysPath}/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default`, 'GET');\n        \n        let yearOpts = extractOptionsByRegex(indexHtml, 'xnm');\n        let termOpts = extractOptionsByRegex(indexHtml, 'xqm');\n\n        if (yearOpts.length === 0 || termOpts.length === 0) {\n            throw new Error(\"源码提取学期信息失败，可能是 WebVPN 会话过期，请重新登录教务系统！\");\n        }\n\n        let count = 0;\n        yearOpts.forEach(y => {\n            termOpts.forEach(t => {\n                semesters.push(`${y.text} 第${t.text}学期`);\n                semesterValues.push({ xnm: y.value, xqm: t.value });\n                if (y.selected && t.selected) {\n                    defaultIndex = count;\n                }\n                count++;\n            });\n        });\n\n        // 2. 弹出选择框\n        let selectedIdx = defaultIndex;\n        if (typeof window.shiguangBridgePromise !== 'undefined') {\n            let userChoice = await window.shiguangBridgePromise.showSingleSelection(\n                \"请选择要导入的学期\", \n                JSON.stringify(semesters), \n                defaultIndex\n            );\n            if (userChoice === null) {\n                window.shiguangBridge.showToast(\"已取消导入\");\n                return;\n            }\n            selectedIdx = userChoice;\n        } else {\n            let msg = \"【浏览器测试】请选择学期对应的序号：\\n\\n\";\n            semesters.forEach((s, idx) => {\n                if (Math.abs(idx - defaultIndex) <= 4) msg += `[ ${idx} ] : ${s}\\n`;\n            });\n            msg += \"\\n请输入方括号中的数字：\";\n            let userInput = prompt(msg, defaultIndex);\n            if (userInput === null) return;\n            selectedIdx = parseInt(userInput);\n            if (isNaN(selectedIdx) || selectedIdx < 0 || selectedIdx >= semesters.length) {\n                alert(\"输入无效，使用默认学期！\");\n                selectedIdx = defaultIndex;\n            }\n        }\n\n        const targetData = semesterValues[selectedIdx];\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(`正在获取 [${semesters[selectedIdx]}] 数据...`);\n        } else {\n            console.log(`【2/4】正在向服务器请求 [${semesters[selectedIdx]}] 的 JSON 数据...`);\n        }\n\n        // 3. 发送 Ajax 请求获取真实的课表和作息时间\n        const postBody = `xnm=${targetData.xnm}&xqm=${targetData.xqm}&kzlx=ck&xsdm=&kclbdm=&kclxdm=`;\n        \n        const [kbResText, timeResText] = await Promise.all([\n            requestData(`${sysPath}/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151`, 'POST', postBody),\n            requestData(`${sysPath}/kbcx/xskbcx_cxRjc.html?gnmkdm=N2151`, 'POST', postBody)\n        ]);\n\n        const kbJson = JSON.parse(kbResText);\n        const timeJson = JSON.parse(timeResText);\n\n        // 4. 解析作息时间 (拦截 21:35 之后的时间)\n        let timeSlots = [];\n        if (Array.isArray(timeJson)) {\n            timeJson.forEach(t => {\n                if (t.jssj > \"21:35\") return; \n                timeSlots.push({\n                    number: parseInt(t.jcmc, 10),\n                    startTime: t.qssj,\n                    endTime: t.jssj\n                });\n            });\n            timeSlots.sort((a, b) => a.number - b.number);\n        }\n\n        // 5. 解析课程数据\n        let parsedCourses = [];\n        if (kbJson && kbJson.kbList) {\n            kbJson.kbList.forEach(c => {\n                let courseObj = {\n                    name: c.kcmc || \"未知课程\",\n                    teacher: c.xm || \"未知\",\n                    position: c.cdmc || \"待定\",\n                    day: parseInt(c.xqj),\n                    isCustomTime: false\n                };\n\n                courseObj.weeks = parseZhengFangWeeks(c.zcd);\n\n                if (c.jcs) {\n                    let secParts = c.jcs.split('-');\n                    courseObj.startSection = parseInt(secParts[0]);\n                    courseObj.endSection = parseInt(secParts[secParts.length - 1] || secParts[0]);\n                }\n\n                if (courseObj.name && courseObj.weeks.length > 0 && courseObj.startSection) {\n                    parsedCourses.push(courseObj);\n                }\n            });\n        }\n\n        if (parsedCourses.length === 0) {\n            const errMsg = \"该学期暂无排课数据。\";\n            if (typeof window.shiguangBridgePromise !== 'undefined') {\n                await window.shiguangBridgePromise.showAlert(\"提示\", errMsg, \"好的\");\n            } else alert(errMsg);\n            return;\n        }\n\n        // 6. 去重\n        let uniqueCourses = [];\n        let courseSet = new Set();\n        parsedCourses.forEach(course => {\n            let uniqueKey = `${course.day}-${course.startSection}-${course.endSection}-${course.name}-${course.weeks.join(',')}`;\n            if (!courseSet.has(uniqueKey)) {\n                courseSet.add(uniqueKey);\n                uniqueCourses.push(course);\n            }\n        });\n\n        const config = {\n            \"defaultClassDuration\": 45,\n            \"defaultBreakDuration\": 5\n        };\n\n        // 7. 打印并保存\n        if (typeof window.shiguangBridgePromise === 'undefined') {\n            console.log(\"【测试成功】被 21:35 规则过滤后的作息时间表：\\n\", timeSlots);\n            console.log(`【测试成功】共获取到 ${uniqueCourses.length} 门课程：\\n`, JSON.stringify(uniqueCourses, null, 2));\n            alert(`解析成功！获取到 ${uniqueCourses.length} 门课程及过滤后的作息时间。\\n请打开F12控制台查看。`);\n            return;\n        }\n\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        if (timeSlots.length > 0) {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        }\n        \n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(uniqueCourses));\n        if (!saveResult) {\n            window.shiguangBridge.showToast(\"保存失败，请重试！\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(`成功导入 ${uniqueCourses.length} 节课程！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"导入异常: \" + error.message);\n        } else {\n            console.error(\"【导入异常】\", error);\n            alert(\"导入异常: \" + error.message);\n        }\n    }\n}\n\nrunImportFlow();","SCUT_02":"/**\n * 解析正方教务系统的周次字符串\n */\nfunction parseZhengFangWeeks(weekStr) {\n    if (!weekStr) return [];\n    let weeks = [];\n    let isOdd = weekStr.includes('单');\n    let isEven = weekStr.includes('双');\n    let cleanStr = weekStr.replace(/周|\\(单\\)|\\(双\\)|单|双/g, '').replace(/\\s+/g, '');\n\n    let parts = cleanStr.split(',');\n    for (let part of parts) {\n        if (part.includes('-')) {\n            let [start, end] = part.split('-');\n            for (let i = parseInt(start); i <= parseInt(end); i++) {\n                if (isOdd && i % 2 === 0) continue;\n                if (isEven && i % 2 !== 0) continue;\n                if (!weeks.includes(i)) weeks.push(i);\n            }\n        } else {\n            let w = parseInt(part);\n            if (!isNaN(w) && !weeks.includes(w)) {\n                if (isOdd && w % 2 === 0) continue;\n                if (isEven && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 封装兼容 WebVPN 的原生 AJAX 请求\n */\nfunction requestData(url, method = 'GET', data = null) {\n    return new Promise((resolve, reject) => {\n        let xhr = new XMLHttpRequest();\n        xhr.open(method, url, true);\n        if (method === 'POST') {\n            xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded;charset=UTF-8');\n            xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');\n        }\n        xhr.onreadystatechange = function() {\n            if (xhr.readyState === 4) {\n                if (xhr.status >= 200 && xhr.status < 300) {\n                    resolve(xhr.responseText);\n                } else {\n                    reject(new Error(\"网络请求失败，状态码：\" + xhr.status));\n                }\n            }\n        };\n        xhr.onerror = function() {\n            reject(new Error(\"网络请求发生错误，请检查网络连接。\"));\n        };\n        xhr.send(data);\n    });\n}\n\n/**\n * 用正则从 HTML 文本中硬核提取 select 选项\n */\nfunction extractOptionsByRegex(html, selectId) {\n    let selectRegex = new RegExp(`<select[^>]*id=\"${selectId}\"[^>]*>(.*?)<\\/select>`, 'is');\n    let selectMatch = html.match(selectRegex);\n    if (!selectMatch) return [];\n    \n    let optionsHtml = selectMatch[1];\n    let optionRegex = /<option\\s+value=\"([^\"]+)\"([^>]*)>([^<]+)<\\/option>/gi;\n    let options = [];\n    let match;\n    while ((match = optionRegex.exec(optionsHtml)) !== null) {\n        if (match[1].trim() !== \"\") {\n            options.push({\n                value: match[1].trim(),\n                text: match[3].trim(),\n                selected: match[2].includes('selected')\n            });\n        }\n    }\n    return options;\n}\n\n/**\n * 异步编排流程\n */\nasync function runImportFlow() {\n    try {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"正在通过 WebVPN 通道读取数据...\");\n        } else {\n            console.log(\"【1/4】正在获取学期选项...\");\n        }\n\n        let sysPath = typeof _path !== 'undefined' ? _path : '/jwglxt';\n        let semesters = [];\n        let semesterValues = [];\n        let defaultIndex = 0;\n\n        // 1. 尝试直接通过正则表达式，去后台请求并提取页面中的下拉框\n        console.log(\"正在后台请求页面源码...\");\n        const indexHtml = await requestData(`${sysPath}/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default`, 'GET');\n        \n        let yearOpts = extractOptionsByRegex(indexHtml, 'xnm');\n        let termOpts = extractOptionsByRegex(indexHtml, 'xqm');\n\n        if (yearOpts.length === 0 || termOpts.length === 0) {\n            throw new Error(\"源码提取学期信息失败，可能是 WebVPN 会话过期，请重新登录教务系统！\");\n        }\n\n        let count = 0;\n        yearOpts.forEach(y => {\n            termOpts.forEach(t => {\n                semesters.push(`${y.text} 第${t.text}学期`);\n                semesterValues.push({ xnm: y.value, xqm: t.value });\n                if (y.selected && t.selected) {\n                    defaultIndex = count;\n                }\n                count++;\n            });\n        });\n\n        // 2. 弹出选择框\n        let selectedIdx = defaultIndex;\n        if (typeof window.shiguangBridgePromise !== 'undefined') {\n            let userChoice = await window.shiguangBridgePromise.showSingleSelection(\n                \"请选择要导入的学期\", \n                JSON.stringify(semesters), \n                defaultIndex\n            );\n            if (userChoice === null) {\n                window.shiguangBridge.showToast(\"已取消导入\");\n                return;\n            }\n            selectedIdx = userChoice;\n        } else {\n            let msg = \"【浏览器测试】请选择学期对应的序号：\\n\\n\";\n            semesters.forEach((s, idx) => {\n                if (Math.abs(idx - defaultIndex) <= 4) msg += `[ ${idx} ] : ${s}\\n`;\n            });\n            msg += \"\\n请输入方括号中的数字：\";\n            let userInput = prompt(msg, defaultIndex);\n            if (userInput === null) return;\n            selectedIdx = parseInt(userInput);\n            if (isNaN(selectedIdx) || selectedIdx < 0 || selectedIdx >= semesters.length) {\n                alert(\"输入无效，使用默认学期！\");\n                selectedIdx = defaultIndex;\n            }\n        }\n\n        const targetData = semesterValues[selectedIdx];\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(`正在获取 [${semesters[selectedIdx]}] 数据...`);\n        } else {\n            console.log(`【2/4】正在向服务器请求 [${semesters[selectedIdx]}] 的 JSON 数据...`);\n        }\n\n        // 3. 发送 Ajax 请求获取真实的课表和作息时间\n        const postBody = `xnm=${targetData.xnm}&xqm=${targetData.xqm}&kzlx=ck&xsdm=&kclbdm=&kclxdm=`;\n        \n        const [kbResText, timeResText] = await Promise.all([\n            requestData(`${sysPath}/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151`, 'POST', postBody),\n            requestData(`${sysPath}/kbcx/xskbcx_cxRjc.html?gnmkdm=N2151`, 'POST', postBody)\n        ]);\n\n        const kbJson = JSON.parse(kbResText);\n        const timeJson = JSON.parse(timeResText);\n\n        // 4. 解析作息时间 (拦截 21:35 之后的时间)\n        let timeSlots = [];\n        if (Array.isArray(timeJson)) {\n            timeJson.forEach(t => {\n                if (t.jssj > \"21:35\") return; \n                timeSlots.push({\n                    number: parseInt(t.jcmc, 10),\n                    startTime: t.qssj,\n                    endTime: t.jssj\n                });\n            });\n            timeSlots.sort((a, b) => a.number - b.number);\n        }\n\n        // 5. 解析课程数据\n        let parsedCourses = [];\n        if (kbJson && kbJson.kbList) {\n            kbJson.kbList.forEach(c => {\n                let courseObj = {\n                    name: c.kcmc || \"未知课程\",\n                    teacher: c.xm || \"未知\",\n                    position: c.cdmc || \"待定\",\n                    day: parseInt(c.xqj),\n                    isCustomTime: false\n                };\n\n                courseObj.weeks = parseZhengFangWeeks(c.zcd);\n\n                if (c.jcs) {\n                    let secParts = c.jcs.split('-');\n                    courseObj.startSection = parseInt(secParts[0]);\n                    courseObj.endSection = parseInt(secParts[secParts.length - 1] || secParts[0]);\n                }\n\n                if (courseObj.name && courseObj.weeks.length > 0 && courseObj.startSection) {\n                    parsedCourses.push(courseObj);\n                }\n            });\n        }\n\n        if (parsedCourses.length === 0) {\n            const errMsg = \"该学期暂无排课数据。\";\n            if (typeof window.shiguangBridgePromise !== 'undefined') {\n                await window.shiguangBridgePromise.showAlert(\"提示\", errMsg, \"好的\");\n            } else alert(errMsg);\n            return;\n        }\n\n        // 6. 去重\n        let uniqueCourses = [];\n        let courseSet = new Set();\n        parsedCourses.forEach(course => {\n            let uniqueKey = `${course.day}-${course.startSection}-${course.endSection}-${course.name}-${course.weeks.join(',')}`;\n            if (!courseSet.has(uniqueKey)) {\n                courseSet.add(uniqueKey);\n                uniqueCourses.push(course);\n            }\n        });\n\n        const config = {\n            \"defaultClassDuration\": 45,\n            \"defaultBreakDuration\": 5\n        };\n\n        // 7. 打印并保存\n        if (typeof window.shiguangBridgePromise === 'undefined') {\n            console.log(\"【测试成功】被 21:35 规则过滤后的作息时间表：\\n\", timeSlots);\n            console.log(`【测试成功】共获取到 ${uniqueCourses.length} 门课程：\\n`, JSON.stringify(uniqueCourses, null, 2));\n            alert(`解析成功！获取到 ${uniqueCourses.length} 门课程及过滤后的作息时间。\\n请打开F12控制台查看。`);\n            return;\n        }\n\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        if (timeSlots.length > 0) {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        }\n        \n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(uniqueCourses));\n        if (!saveResult) {\n            window.shiguangBridge.showToast(\"保存失败，请重试！\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(`成功导入 ${uniqueCourses.length} 节课程！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"导入异常: \" + error.message);\n        } else {\n            console.error(\"【导入异常】\", error);\n            alert(\"导入异常: \" + error.message);\n        }\n    }\n}\n\nrunImportFlow();","HFNU_01":"// 合肥师范学院(hfnu.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\nfunction powerSplit(paramsRaw) {\n    const args = [];\n    let current = \"\";\n    let depth = 0; \n    let inQuote = false;\n    let quoteChar = \"\";\n\n    for (let i = 0; i < paramsRaw.length; i++) {\n        let char = paramsRaw[i];\n        if ((char === '\"' || char === \"'\") && (i === 0 || paramsRaw[i - 1] !== '\\\\')) {\n            if (!inQuote) { inQuote = true; quoteChar = char; }\n            else if (char === quoteChar) { inQuote = false; }\n        }\n        if (!inQuote) {\n            if (char === '(' || char === '[' || char === '{') depth++;\n            if (char === ')' || char === ']' || char === '}') depth--;\n        }\n        if (char === ',' && depth === 0 && !inQuote) {\n            args.push(cleanArg(current));\n            current = \"\";\n        } else {\n            current += char;\n        }\n    }\n    args.push(cleanArg(current)); \n    return args;\n}\n\nfunction cleanArg(s) {\n    s = s.trim();\n    if (s === \"null\") return null;\n    return s.replace(/^[\"']|[\"']$/g, \"\");\n}\n\n/**\n * 全局课程合并逻辑\n */\nfunction mergeContinuousLessons(lessons) {\n    if (!lessons || lessons.length === 0) return [];\n\n    // 1. 建立基于 (课程名|教师|地点|星期几) 的分组\n    const groups = {};\n    lessons.forEach(l => {\n        const key = `${l.name}|${l.teacher}|${l.position}|${l.day}`;\n        if (!groups[key]) {\n            groups[key] = {\n                name: l.name,\n                teacher: l.teacher,\n                position: l.position,\n                day: l.day,\n                // 假设大学最多 50 周，构建一个：第 N 周对应哪些节次的矩阵\n                weeksMatrix: Array.from({ length: 50 }, () => new Set())\n            };\n        }\n        // 将系统传来的凌乱数据彻底打散，按“周”填入对应的“节”中，Set自动去重\n        if (l.weeks && Array.isArray(l.weeks)) {\n            l.weeks.forEach(w => {\n                if (w >= 0 && w < 50) {\n                    for (let s = l.startSection; s <= l.endSection; s++) {\n                        groups[key].weeksMatrix[w].add(s);\n                    }\n                }\n            });\n        }\n    });\n\n    const merged = [];\n\n    // 2. 根据矩阵重新组装绝对精确的课程块\n    for (const key in groups) {\n        const group = groups[key];\n        const matrix = group.weeksMatrix;\n        \n        // 用于记录相同的“连续节次块”分布在哪些周次\n        // 例如 blockMap[\"1-2\"] = [1, 2, 3, 4, 5, 6, 7, 8, 9]\n        // 例如 blockMap[\"2-2\"] = [10]\n        const blockMap = {};\n\n        for (let w = 0; w < matrix.length; w++) {\n            const sections = Array.from(matrix[w]).sort((a, b) => a - b);\n            if (sections.length === 0) continue;\n\n            // 寻找当前周的连续节次块\n            let start = sections[0];\n            let prev = sections[0];\n\n            for (let i = 1; i < sections.length; i++) {\n                const curr = sections[i];\n                if (curr === prev + 1) {\n                    prev = curr; // 节次连续，继续延伸\n                } else {\n                    // 节次断开，结算上一个块\n                    const blockKey = `${start}-${prev}`;\n                    if (!blockMap[blockKey]) blockMap[blockKey] = [];\n                    blockMap[blockKey].push(w);\n                    \n                    // 开启新块\n                    start = curr;\n                    prev = curr;\n                }\n            }\n            // 结算每周最后一个块\n            const blockKey = `${start}-${prev}`;\n            if (!blockMap[blockKey]) blockMap[blockKey] = [];\n            blockMap[blockKey].push(w);\n        }\n\n        // 3. 将聚合好的 blockMap 转换为最终的 JSON 对象\n        for (const blockKey in blockMap) {\n            const [startSec, endSec] = blockKey.split('-').map(Number);\n            merged.push({\n                name: group.name,\n                teacher: group.teacher,\n                position: group.position,\n                day: group.day,\n                startSection: startSec,\n                endSection: endSec,\n                weeks: blockMap[blockKey]\n            });\n        }\n    }\n\n    // 4. 排序以便输出整洁美观\n    merged.sort((a, b) => {\n        if (a.day !== b.day) return a.day - b.day;\n        if (a.startSection !== b.startSection) return a.startSection - b.startSection;\n        return a.name.localeCompare(b.name);\n    });\n\n    return merged;\n}\n\nfunction parseTaskActivities(html) {\n    const rawResults = [];\n    const blocks = html.split(/var\\s+teachers\\s*=/);\n\n    for (let i = 1; i < blocks.length; i++) {\n        const block = blocks[i];\n        let teacherName = \"未知教师\";\n        const tMatch = block.match(/actTeachers\\s*=\\s*\\[\\s*\\{[\\s\\S]*?name:\\s*\"(.*?)\"/);\n        if (tMatch) teacherName = tMatch[1];\n\n        const activityMatch = block.match(/new\\s+TaskActivity\\(([\\s\\S]*?)\\);/);\n        if (!activityMatch) continue;\n\n        const args = powerSplit(activityMatch[1]);\n        const courseName = (args[3] || \"未知课程\").split('(')[0];\n        const position = (args[5] || \"未知地点\").replace(/\\(.*?\\)/g, \"\");\n        const weeksBitmap = args[6] || \"\";\n        \n        const weeks = [];\n        for (let j = 0; j < weeksBitmap.length; j++) {\n            if (weeksBitmap[j] === '1') weeks.push(j);\n        }\n\n        const unitCountMatch = html.match(/unitCount\\s*=\\s*(\\d+)/);\n        const unitCount = unitCountMatch ? parseInt(unitCountMatch[1]) : 14;\n\n        const idxRegex = /index\\s*=\\s*(\\d+)\\s*\\*\\s*unitCount\\s*\\+\\s*(\\d+);/g;\n        let m;\n        while ((m = idxRegex.exec(block)) !== null) {\n            const day = parseInt(m[1]) + 1; \n            const section = parseInt(m[2]) + 1;\n\n            rawResults.push({\n                \"name\": courseName,\n                \"teacher\": teacherName,\n                \"position\": position,\n                \"day\": day,\n                \"startSection\": section,\n                \"endSection\": section,\n                \"weeks\": weeks\n            });\n        }\n    }\n\n    // 执行全局合并逻辑\n    return mergeContinuousLessons(rawResults);\n}\n\nasync function request(url, options = {}) {\n    const res = await fetch(url, { credentials: \"include\", ...options });\n    if (!res.ok) throw new Error(`网络请求失败: ${res.status}`);\n    return await res.text();\n}\n\nasync function detectParameters() {\n    const html = await request(\"https://jw.hfnu.edu.cn/eams/courseTableForStd.action?sf_request_type=ajax\");\n    const idsMatch = html.match(/bg\\.form\\.addInput\\(form,\"ids\",\"(\\d+)\"\\)/);\n    const tagIdMatch = html.match(/id=\"(semesterBar\\d+Semester)\"/);\n    if (!idsMatch || !tagIdMatch) return null;\n    return { ids: idsMatch[1], tagId: tagIdMatch[1] };\n}\n\nasync function getSelectedSemester(tagId) {\n    const raw = await request(`https://jw.hfnu.edu.cn/eams/dataQuery.action?sf_request_type=ajax`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `tagId=${encodeURIComponent(tagId)}&dataType=semesterCalendar`\n    });\n    const data = Function(`return (${raw});`)();\n    const list = [];\n    for (let key in data.semesters) {\n        data.semesters[key].forEach(s => list.push({ id: s.id, name: `${s.schoolYear} ${s.name}学期` }));\n    }\n    const idx = await window.shiguangBridgePromise.showSingleSelection(\"选择学期\", JSON.stringify(list.map(s => s.name)), -1);\n    return idx !== null ? list[idx] : null;\n}\n\nasync function fetchAndParseCourses(semesterId, ids) {\n    const html = await request(`https://jw.hfnu.edu.cn/eams/courseTableForStd!courseTable.action?sf_request_type=ajax`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `ignoreHead=1&setting.kind=std&semester.id=${semesterId}&ids=${ids}`\n    });\n    return parseTaskActivities(html);\n}\n\nasync function applyTimeSlots() {\n    // 锦绣校区\n    const timeSlot1 = [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n        { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n        { \"number\": 3, \"startTime\": \"09:55\", \"endTime\": \"10:40\" },\n        { \"number\": 4, \"startTime\": \"10:50\", \"endTime\": \"11:35\" },\n        { \"number\": 5, \"startTime\": \"14:10\", \"endTime\": \"14:55\" },\n        { \"number\": 6, \"startTime\": \"15:05\", \"endTime\": \"15:50\" },\n        { \"number\": 7, \"startTime\": \"16:05\", \"endTime\": \"16:50\" },\n        { \"number\": 8, \"startTime\": \"17:00\", \"endTime\": \"17:45\" },\n        { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n        { \"number\": 10, \"startTime\": \"19:50\", \"endTime\": \"20:35\" },\n        { \"number\": 11, \"startTime\": \"20:40\", \"endTime\": \"21:25\" }\n    ];\n    // 滨湖校区\n    const timeSlot2 = [\n        { \"number\": 1, \"startTime\": \"08:20\", \"endTime\": \"09:05\" },\n        { \"number\": 2, \"startTime\": \"09:10\", \"endTime\": \"09:55\" },\n        { \"number\": 3, \"startTime\": \"10:05\", \"endTime\": \"10:50\" },\n        { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\" },\n        { \"number\": 5, \"startTime\": \"13:40\", \"endTime\": \"14:25\" },\n        { \"number\": 6, \"startTime\": \"14:30\", \"endTime\": \"15:15\" },\n        { \"number\": 7, \"startTime\": \"15:25\", \"endTime\": \"16:10\" },\n        { \"number\": 8, \"startTime\": \"16:15\", \"endTime\": \"17:00\" },\n        { \"number\": 9, \"startTime\": \"18:30\", \"endTime\": \"19:15\" },\n        { \"number\": 10, \"startTime\": \"19:20\", \"endTime\": \"20:05\" },\n        { \"number\": 11, \"startTime\": \"20:10\", \"endTime\": \"20:55\" }\n    ];\n\n    const configs = [timeSlot1, timeSlot2];\n    const campusNames = [\"锦绣校区\", \"滨湖校区\"];\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择校区\", \n        JSON.stringify(campusNames), \n        -1\n    );\n    if (selectedIndex === null) return false;\n\n    const target = configs[selectedIndex];\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(target));\n    return true;\n}\n\n\nasync function runImportFlow() {\n    try {\n        window.shiguangBridge.showToast(\"开始探测教务参数...\");\n        const params = await detectParameters();\n        if (!params) throw new Error(\"未能识别教务参数，请确认已登录\");\n\n        const semester = await getSelectedSemester(params.tagId);\n        if (!semester) return; \n\n        window.shiguangBridge.showToast(\"正在同步课表...\");\n        const courses = await fetchAndParseCourses(semester.id, params.ids);\n        \n        if (!courses || courses.length === 0) throw new Error(\"未解析到课程数据\");\n\n        const success = await applyTimeSlots();\n        if (!success) return;\n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        \n        if (saveResult) {\n            window.shiguangBridge.showToast(`成功导入 ${courses.length} 个课程条目`);\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (e) {\n        console.error(`[异常] ${e.message}`);\n        window.shiguangBridge.showToast(e.message);\n    }\n}\n\nrunImportFlow();","IMNC_01":"/**\n * 呼和浩特民族学院 (IMNC) 课表解析脚本-通过 WebVPN 登录\n * 目标页面：教务系统【本学期课表】（\"本学期课程安排\"页面）\n * 从课程主表读取课程号、课程序号、学分、选课属性，写入课程备注 remark\n * 桥接 API 使用 v2：window.shiguangBridge(同步) / window.shiguangBridgePromise(异步)\n * 导入时一并写入默认时间表（10 节）与默认学期总周数（16 周）\n */\n\n// 清理 <wbr> 标签\nfunction cleanWbr(str) {\n    return str ? str.replace(/<wbr\\s*\\/?>/gi, '') : str;\n}\n\n// 默认时间表（TimeSlotJsonModel：number 从 1 递增，HH:mm 格式）\nconst TIME_SLOTS = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:25\", endTime: \"10:10\" },\n    { number: 3, startTime: \"10:30\", endTime: \"11:15\" },\n    { number: 4, startTime: \"11:25\", endTime: \"12:10\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 7, startTime: \"16:30\", endTime: \"17:15\" },\n    { number: 8, startTime: \"17:25\", endTime: \"18:10\" },\n    { number: 9, startTime: \"19:30\", endTime: \"20:15\" },\n    { number: 10, startTime: \"20:25\", endTime: \"21:10\" }\n];\n\n// 默认本学期总周数（CourseConfigJsonModel.semesterTotalWeeks，未传入的字段使用应用默认值）\nconst SEMESTER_TOTAL_WEEKS = 16;\n\n// 周次解析函数\nfunction parseWeeks(weekStr) {\n    let weeks = [];\n    if (!weekStr) return weeks;\n    let isSingle = weekStr.includes('单');\n    let isDouble = weekStr.includes('双');\n\n    // 匹配 \"1-16\", \"第1-9周\", \"全周（1-16）\"\n    let match = weekStr.match(/(\\d+)-(\\d+)/);\n    if (match) {\n        let start = parseInt(match[1]);\n        let end = parseInt(match[2]);\n        for (let i = start; i <= end; i++) {\n            if (isSingle && i % 2 === 0) continue;\n            if (isDouble && i % 2 !== 0) continue;\n            weeks.push(i);\n        }\n    } else {\n        // 匹配 \"第13周\"\n        let singleMatch = weekStr.match(/(\\d+)/);\n        if (singleMatch) {\n            weeks.push(parseInt(singleMatch[1]));\n        }\n    }\n    return weeks;\n}\n\n// 星期映射（星期一~星期日 -> 1~7）\nconst DAY_NAME_MAP = {\n    '星期一': 1, '星期二': 2, '星期三': 3, '星期四': 4,\n    '星期五': 5, '星期六': 6, '星期日': 7, '星期天': 7\n};\n\nfunction parseDay(dayStr) {\n    if (!dayStr) return 0;\n    let normalized = dayStr.replace(/\\s+/g, '');\n    if (DAY_NAME_MAP[normalized]) return DAY_NAME_MAP[normalized];\n    let match = normalized.match(/星期([一二三四五六日天])/);\n    if (!match) match = normalized.match(/周([一二三四五六日天])/);\n    if (match) {\n        let index = '一二三四五六日天'.indexOf(match[1]);\n        return index >= 0 ? index + 1 : 0;\n    }\n    return 0;\n}\n\n// 节次解析：\"第1-2节\" -> {start:1, end:2}；\"第3节\" -> {start:3, end:3}\nfunction parseSections(sectionStr) {\n    if (!sectionStr) return null;\n    let rangeMatch = sectionStr.match(/第\\s*(\\d+)\\s*[-—~至]\\s*(\\d+)\\s*节/);\n    if (rangeMatch) {\n        return { start: parseInt(rangeMatch[1]), end: parseInt(rangeMatch[2]) };\n    }\n    let singleMatch = sectionStr.match(/第\\s*(\\d+)\\s*节/);\n    if (singleMatch) {\n        let section = parseInt(singleMatch[1]);\n        return { start: section, end: section };\n    }\n    return null;\n}\n\nfunction cleanCellText(cell) {\n    return cell.textContent.replace(/\\u00a0/g, ' ').replace(/\\s+/g, ' ').trim();\n}\n\n// 教师单元格解析：任课教师以链接列表展示，用\"、\"拼接\nfunction parseTeacherCell(cell) {\n    let links = cell.querySelectorAll('a');\n    if (links.length > 0) {\n        let names = [];\n        for (let i = 0; i < links.length; i++) {\n            let name = cleanWbr(links[i].textContent).replace(/\\s+/g, ' ').trim();\n            if (name) names.push(name);\n        }\n        if (names.length > 0) return names.join('、');\n    }\n    return cleanCellText(cell);\n}\n\n// 解析\"上课时间、地点\"单元格内的嵌套表格，每行：周次 / 星期 / 节次 / 地点\nfunction parseScheduleCell(cell) {\n    let slots = [];\n    let rows = cell.querySelectorAll('table tr');\n    for (let i = 0; i < rows.length; i++) {\n        let tds = rows[i].querySelectorAll('td');\n        if (tds.length < 3) continue;\n\n        let weekStr = cleanCellText(tds[0]);\n        let dayStr = cleanCellText(tds[1]);\n        let sectionStr = cleanCellText(tds[2]);\n        let position = tds.length > 3 ? cleanCellText(tds[3]) : '';\n\n        // 无星期或节次的子行（仅有周次的课程安排）跳过\n        let day = parseDay(dayStr);\n        let section = parseSections(sectionStr);\n        if (!day || !section) continue;\n\n        slots.push({\n            weeks: parseWeeks(weekStr),\n            weeksText: weekStr,\n            day: day,\n            startSection: section.start,\n            endSection: section.end,\n            position: cleanWbr(position)\n        });\n    }\n    return slots;\n}\n\n// 在单个文档中定位课程主表：table.infolist_tab 且表头含\"课程号\"（排除\"上课大节\"对照表）\nfunction findCourseTableInDoc(doc) {\n    let tables = doc.querySelectorAll('table.infolist_tab');\n    for (let i = 0; i < tables.length; i++) {\n        let headerCells = tables[i].rows[0] ? tables[i].rows[0].cells : [];\n        for (let j = 0; j < headerCells.length; j++) {\n            if (cleanCellText(headerCells[j]).replace(/\\s+/g, '') === '课程号') {\n                return tables[i];\n            }\n        }\n    }\n    return null;\n}\n\n// 收集文档内所有可访问的同源框架文档（教务系统为 frameset 结构，课表位于 mainFrame 内）\nfunction collectFrameDocs(doc, docs, depth) {\n    if (depth > 3) return;\n    let frames = doc.querySelectorAll('frame, iframe');\n    for (let i = 0; i < frames.length; i++) {\n        try {\n            let frameDoc = frames[i].contentDocument ||\n                (frames[i].contentWindow ? frames[i].contentWindow.document : null);\n            if (frameDoc && docs.indexOf(frameDoc) < 0) {\n                docs.push(frameDoc);\n                collectFrameDocs(frameDoc, docs, depth + 1);\n            }\n        } catch (e) { /* 跨域框架无法访问，忽略 */ }\n    }\n    return docs;\n}\n\nfunction findCourseTable() {\n    // 优先在当前文档查找\n    let table = findCourseTableInDoc(document);\n    if (table) return table;\n    // 当前文档没有（如处于 index_frame 顶层框架），遍历同源框架查找\n    let frameDocs = collectFrameDocs(document, [], 0);\n    for (let i = 0; i < frameDocs.length; i++) {\n        let tableInFrame = findCourseTableInDoc(frameDocs[i]);\n        if (tableInFrame) return tableInFrame;\n    }\n    return null;\n}\n\n// 组装课程备注（官方 ImportCourseJsonModel 字段 remark，字符数限制 300）\nfunction buildRemark(courseId, sequence, credit, electiveAttr) {\n    let lines = [];\n    if (courseId) lines.push('课程号：' + courseId);\n    if (sequence) lines.push('课程序号：' + sequence);\n    if (credit) lines.push('学分：' + credit);\n    if (electiveAttr) lines.push('选课属性：' + electiveAttr);\n    let remark = lines.join('\\n');\n    if (remark.length > 300) remark = remark.substring(0, 300);\n    return remark;\n}\n\n// 核心解析函数：在\"本学期课程安排\"页面按表头定位列并逐行解析\nfunction fetchCurrentSemesterCourses() {\n    let table = findCourseTable();\n    if (!table) return null;\n\n    // 按表头文本建立列索引（表头文本去除空白，兼容\"课程<br>序号\"、\"学 分\"等换行写法）\n    let indexMap = {};\n    let headerCells = table.rows[0] ? table.rows[0].cells : [];\n    for (let i = 0; i < headerCells.length; i++) {\n        indexMap[cleanCellText(headerCells[i]).replace(/\\s+/g, '')] = i;\n    }\n\n    function columnIndex(keys) {\n        for (let i = 0; i < keys.length; i++) {\n            if (indexMap[keys[i]] !== undefined) return indexMap[keys[i]];\n        }\n        return -1;\n    }\n\n    let courseIdIdx = columnIndex(['课程号']);\n    let sequenceIdx = columnIndex(['课程序号']);\n    let nameIdx = columnIndex(['课程名称']);\n    let teacherIdx = columnIndex(['任课教师']);\n    let creditIdx = columnIndex(['学分']);\n    let electiveAttrIdx = columnIndex(['选课属性']);\n    let scheduleIdx = columnIndex(['上课时间、地点', '上课时间地点']);\n\n    if (nameIdx < 0 || scheduleIdx < 0) return null;\n\n    let courses = [];\n    let skipped = [];\n\n    // 第 0 行是表头，从第 1 行开始遍历课程\n    for (let i = 1; i < table.rows.length; i++) {\n        let cells = table.rows[i].cells;\n        function cellAt(index) {\n            return index >= 0 && index < cells.length ? cells[index] : null;\n        }\n\n        let nameCell = cellAt(nameIdx);\n        let name = nameCell ? cleanWbr(cleanCellText(nameCell)) : '';\n        if (!name) continue;\n\n        let courseIdCell = cellAt(courseIdIdx);\n        let sequenceCell = cellAt(sequenceIdx);\n        let creditCell = cellAt(creditIdx);\n        let electiveAttrCell = cellAt(electiveAttrIdx);\n        let teacherCell = cellAt(teacherIdx);\n\n        let courseId = courseIdCell ? cleanCellText(courseIdCell) : '';\n        let sequence = sequenceCell ? cleanCellText(sequenceCell) : '';\n        let credit = creditCell ? cleanCellText(creditCell) : '';\n        let electiveAttr = electiveAttrCell ? cleanCellText(electiveAttrCell) : '';\n        let teacher = teacherCell ? parseTeacherCell(teacherCell) : '';\n\n        let remark = buildRemark(courseId, sequence, credit, electiveAttr);\n\n        let scheduleCell = cellAt(scheduleIdx);\n        let slots = scheduleCell ? parseScheduleCell(scheduleCell) : [];\n\n        if (slots.length === 0) {\n            // 无任何有效排课位的课程（如仅有周次的\"形势与政策（三）\"、无时间安排的\"体能测试Ⅱ\"）\n            let weeksText = '未填写周次';\n            if (scheduleCell) {\n                let firstTd = scheduleCell.querySelector('table td');\n                if (firstTd) {\n                    let text = cleanCellText(firstTd);\n                    if (text) weeksText = text;\n                }\n            }\n            skipped.push({\n                name: name,\n                teacher: teacher || '未填写教师',\n                weeks: weeksText\n            });\n            continue;\n        }\n\n        for (let k = 0; k < slots.length; k++) {\n            let slot = slots[k];\n            let courseBlock = {\n                name: name,\n                teacher: teacher,\n                position: slot.position,\n                day: slot.day,\n                startSection: slot.startSection,\n                endSection: slot.endSection,\n                weeks: slot.weeks,\n                remark: remark\n            };\n\n            // 查找同一天、同名、同老师、同地点、同周次、同备注，且正好是上一节的课程（合并连上的课）\n            let existingCourse = courses.find(c =>\n                c.name === courseBlock.name &&\n                c.day === courseBlock.day &&\n                c.teacher === courseBlock.teacher &&\n                c.position === courseBlock.position &&\n                JSON.stringify(c.weeks) === JSON.stringify(courseBlock.weeks) &&\n                c.remark === courseBlock.remark &&\n                c.endSection === courseBlock.startSection - 1\n            );\n\n            if (existingCourse) {\n                existingCourse.endSection = courseBlock.endSection;\n            } else {\n                courses.push(courseBlock);\n            }\n        }\n    }\n\n    return { courses: courses, skipped: skipped };\n}\n\nfunction formatNoArrangementMessage(courses) {\n    let lines = courses.map((course, index) => {\n        let teacher = course.teacher || '未填写教师';\n        let weeks = course.weeks || '未填写周次';\n        return `${index + 1}. ${course.name} / ${teacher} / ${weeks}`;\n    });\n\n    return `检测到 ${courses.length} 门课程没有具体上课时间或地点，无法自动放入课表：\\n\\n${lines.join('\\n')}\\n\\n请在确认课程时间后重新导入，点击【继续】将导入已知课程。`;\n}\n\n// 保存课表配置（默认学期总周数；失败不阻断课程导入）\nasync function saveCourseConfigData() {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n            semesterTotalWeeks: SEMESTER_TOTAL_WEEKS\n        }));\n        window.shiguangBridge.showToast(`已设置默认学期总周数：${SEMESTER_TOTAL_WEEKS} 周`);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存课表配置失败: \" + error.message);\n        return false;\n    }\n}\n\n// 导入预设时间段（默认时间表；失败不阻断课程导入）\nasync function importPresetTimeSlots() {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TIME_SLOTS));\n        window.shiguangBridge.showToast(`预设时间段导入成功（${TIME_SLOTS.length} 节）！`);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        return false;\n    }\n}\n\n// 调度流程\nasync function runImportFlow() {\n    try {\n        window.shiguangBridge.showToast(\"开始解析课表...\");\n\n        const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n            \"导入确认\",\n            \"请确保您目前处于教务系统的“本学期课表”显示页面（页面标题为“本学期课程安排”）。\\n是否立即提取并导入课表？\",\n            \"开始提取\"\n        );\n\n        if (!alertConfirmed) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        const result = fetchCurrentSemesterCourses();\n\n        if (!result || result.courses.length === 0) {\n            await window.shiguangBridgePromise.showAlert(\"错误\", \"未在当前页面找到可导入的课程数据，请确认是否处于“本学期课表”页面，或联系适配开发者。\", \"好的\");\n            return;\n        }\n\n        if (result.skipped.length > 0) {\n            await window.shiguangBridgePromise.showAlert(\n                \"存在未安排课程\",\n                formatNoArrangementMessage(result.skipped),\n                \"继续\"\n            );\n        }\n\n        // 课表配置（学期总周数），失败不阻断\n        await saveCourseConfigData();\n\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(result.courses));\n        window.shiguangBridge.showToast(`成功导入 ${result.courses.length} 门课程块！`);\n\n        // 默认时间表，失败不阻断\n        await importPresetTimeSlots();\n\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入发生错误: \" + error.message);\n    }\n}\n\n// 启动执行\nrunImportFlow();\n","IMNC_02":"/**\n * 呼和浩特民族学院 (IMNC) 课表解析脚本-通过 WebVPN 登录\n * 目标页面：教务系统【本学期课表】（\"本学期课程安排\"页面）\n * 从课程主表读取课程号、课程序号、学分、选课属性，写入课程备注 remark\n * 桥接 API 使用 v2：window.shiguangBridge(同步) / window.shiguangBridgePromise(异步)\n * 导入时一并写入默认时间表（10 节）与默认学期总周数（16 周）\n */\n\n// 清理 <wbr> 标签\nfunction cleanWbr(str) {\n    return str ? str.replace(/<wbr\\s*\\/?>/gi, '') : str;\n}\n\n// 默认时间表（TimeSlotJsonModel：number 从 1 递增，HH:mm 格式）\nconst TIME_SLOTS = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:25\", endTime: \"10:10\" },\n    { number: 3, startTime: \"10:30\", endTime: \"11:15\" },\n    { number: 4, startTime: \"11:25\", endTime: \"12:10\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 7, startTime: \"16:30\", endTime: \"17:15\" },\n    { number: 8, startTime: \"17:25\", endTime: \"18:10\" },\n    { number: 9, startTime: \"19:30\", endTime: \"20:15\" },\n    { number: 10, startTime: \"20:25\", endTime: \"21:10\" }\n];\n\n// 默认本学期总周数（CourseConfigJsonModel.semesterTotalWeeks，未传入的字段使用应用默认值）\nconst SEMESTER_TOTAL_WEEKS = 16;\n\n// 周次解析函数\nfunction parseWeeks(weekStr) {\n    let weeks = [];\n    if (!weekStr) return weeks;\n    let isSingle = weekStr.includes('单');\n    let isDouble = weekStr.includes('双');\n\n    // 匹配 \"1-16\", \"第1-9周\", \"全周（1-16）\"\n    let match = weekStr.match(/(\\d+)-(\\d+)/);\n    if (match) {\n        let start = parseInt(match[1]);\n        let end = parseInt(match[2]);\n        for (let i = start; i <= end; i++) {\n            if (isSingle && i % 2 === 0) continue;\n            if (isDouble && i % 2 !== 0) continue;\n            weeks.push(i);\n        }\n    } else {\n        // 匹配 \"第13周\"\n        let singleMatch = weekStr.match(/(\\d+)/);\n        if (singleMatch) {\n            weeks.push(parseInt(singleMatch[1]));\n        }\n    }\n    return weeks;\n}\n\n// 星期映射（星期一~星期日 -> 1~7）\nconst DAY_NAME_MAP = {\n    '星期一': 1, '星期二': 2, '星期三': 3, '星期四': 4,\n    '星期五': 5, '星期六': 6, '星期日': 7, '星期天': 7\n};\n\nfunction parseDay(dayStr) {\n    if (!dayStr) return 0;\n    let normalized = dayStr.replace(/\\s+/g, '');\n    if (DAY_NAME_MAP[normalized]) return DAY_NAME_MAP[normalized];\n    let match = normalized.match(/星期([一二三四五六日天])/);\n    if (!match) match = normalized.match(/周([一二三四五六日天])/);\n    if (match) {\n        let index = '一二三四五六日天'.indexOf(match[1]);\n        return index >= 0 ? index + 1 : 0;\n    }\n    return 0;\n}\n\n// 节次解析：\"第1-2节\" -> {start:1, end:2}；\"第3节\" -> {start:3, end:3}\nfunction parseSections(sectionStr) {\n    if (!sectionStr) return null;\n    let rangeMatch = sectionStr.match(/第\\s*(\\d+)\\s*[-—~至]\\s*(\\d+)\\s*节/);\n    if (rangeMatch) {\n        return { start: parseInt(rangeMatch[1]), end: parseInt(rangeMatch[2]) };\n    }\n    let singleMatch = sectionStr.match(/第\\s*(\\d+)\\s*节/);\n    if (singleMatch) {\n        let section = parseInt(singleMatch[1]);\n        return { start: section, end: section };\n    }\n    return null;\n}\n\nfunction cleanCellText(cell) {\n    return cell.textContent.replace(/\\u00a0/g, ' ').replace(/\\s+/g, ' ').trim();\n}\n\n// 教师单元格解析：任课教师以链接列表展示，用\"、\"拼接\nfunction parseTeacherCell(cell) {\n    let links = cell.querySelectorAll('a');\n    if (links.length > 0) {\n        let names = [];\n        for (let i = 0; i < links.length; i++) {\n            let name = cleanWbr(links[i].textContent).replace(/\\s+/g, ' ').trim();\n            if (name) names.push(name);\n        }\n        if (names.length > 0) return names.join('、');\n    }\n    return cleanCellText(cell);\n}\n\n// 解析\"上课时间、地点\"单元格内的嵌套表格，每行：周次 / 星期 / 节次 / 地点\nfunction parseScheduleCell(cell) {\n    let slots = [];\n    let rows = cell.querySelectorAll('table tr');\n    for (let i = 0; i < rows.length; i++) {\n        let tds = rows[i].querySelectorAll('td');\n        if (tds.length < 3) continue;\n\n        let weekStr = cleanCellText(tds[0]);\n        let dayStr = cleanCellText(tds[1]);\n        let sectionStr = cleanCellText(tds[2]);\n        let position = tds.length > 3 ? cleanCellText(tds[3]) : '';\n\n        // 无星期或节次的子行（仅有周次的课程安排）跳过\n        let day = parseDay(dayStr);\n        let section = parseSections(sectionStr);\n        if (!day || !section) continue;\n\n        slots.push({\n            weeks: parseWeeks(weekStr),\n            weeksText: weekStr,\n            day: day,\n            startSection: section.start,\n            endSection: section.end,\n            position: cleanWbr(position)\n        });\n    }\n    return slots;\n}\n\n// 在单个文档中定位课程主表：table.infolist_tab 且表头含\"课程号\"（排除\"上课大节\"对照表）\nfunction findCourseTableInDoc(doc) {\n    let tables = doc.querySelectorAll('table.infolist_tab');\n    for (let i = 0; i < tables.length; i++) {\n        let headerCells = tables[i].rows[0] ? tables[i].rows[0].cells : [];\n        for (let j = 0; j < headerCells.length; j++) {\n            if (cleanCellText(headerCells[j]).replace(/\\s+/g, '') === '课程号') {\n                return tables[i];\n            }\n        }\n    }\n    return null;\n}\n\n// 收集文档内所有可访问的同源框架文档（教务系统为 frameset 结构，课表位于 mainFrame 内）\nfunction collectFrameDocs(doc, docs, depth) {\n    if (depth > 3) return;\n    let frames = doc.querySelectorAll('frame, iframe');\n    for (let i = 0; i < frames.length; i++) {\n        try {\n            let frameDoc = frames[i].contentDocument ||\n                (frames[i].contentWindow ? frames[i].contentWindow.document : null);\n            if (frameDoc && docs.indexOf(frameDoc) < 0) {\n                docs.push(frameDoc);\n                collectFrameDocs(frameDoc, docs, depth + 1);\n            }\n        } catch (e) { /* 跨域框架无法访问，忽略 */ }\n    }\n    return docs;\n}\n\nfunction findCourseTable() {\n    // 优先在当前文档查找\n    let table = findCourseTableInDoc(document);\n    if (table) return table;\n    // 当前文档没有（如处于 index_frame 顶层框架），遍历同源框架查找\n    let frameDocs = collectFrameDocs(document, [], 0);\n    for (let i = 0; i < frameDocs.length; i++) {\n        let tableInFrame = findCourseTableInDoc(frameDocs[i]);\n        if (tableInFrame) return tableInFrame;\n    }\n    return null;\n}\n\n// 组装课程备注（官方 ImportCourseJsonModel 字段 remark，字符数限制 300）\nfunction buildRemark(courseId, sequence, credit, electiveAttr) {\n    let lines = [];\n    if (courseId) lines.push('课程号：' + courseId);\n    if (sequence) lines.push('课程序号：' + sequence);\n    if (credit) lines.push('学分：' + credit);\n    if (electiveAttr) lines.push('选课属性：' + electiveAttr);\n    let remark = lines.join('\\n');\n    if (remark.length > 300) remark = remark.substring(0, 300);\n    return remark;\n}\n\n// 核心解析函数：在\"本学期课程安排\"页面按表头定位列并逐行解析\nfunction fetchCurrentSemesterCourses() {\n    let table = findCourseTable();\n    if (!table) return null;\n\n    // 按表头文本建立列索引（表头文本去除空白，兼容\"课程<br>序号\"、\"学 分\"等换行写法）\n    let indexMap = {};\n    let headerCells = table.rows[0] ? table.rows[0].cells : [];\n    for (let i = 0; i < headerCells.length; i++) {\n        indexMap[cleanCellText(headerCells[i]).replace(/\\s+/g, '')] = i;\n    }\n\n    function columnIndex(keys) {\n        for (let i = 0; i < keys.length; i++) {\n            if (indexMap[keys[i]] !== undefined) return indexMap[keys[i]];\n        }\n        return -1;\n    }\n\n    let courseIdIdx = columnIndex(['课程号']);\n    let sequenceIdx = columnIndex(['课程序号']);\n    let nameIdx = columnIndex(['课程名称']);\n    let teacherIdx = columnIndex(['任课教师']);\n    let creditIdx = columnIndex(['学分']);\n    let electiveAttrIdx = columnIndex(['选课属性']);\n    let scheduleIdx = columnIndex(['上课时间、地点', '上课时间地点']);\n\n    if (nameIdx < 0 || scheduleIdx < 0) return null;\n\n    let courses = [];\n    let skipped = [];\n\n    // 第 0 行是表头，从第 1 行开始遍历课程\n    for (let i = 1; i < table.rows.length; i++) {\n        let cells = table.rows[i].cells;\n        function cellAt(index) {\n            return index >= 0 && index < cells.length ? cells[index] : null;\n        }\n\n        let nameCell = cellAt(nameIdx);\n        let name = nameCell ? cleanWbr(cleanCellText(nameCell)) : '';\n        if (!name) continue;\n\n        let courseIdCell = cellAt(courseIdIdx);\n        let sequenceCell = cellAt(sequenceIdx);\n        let creditCell = cellAt(creditIdx);\n        let electiveAttrCell = cellAt(electiveAttrIdx);\n        let teacherCell = cellAt(teacherIdx);\n\n        let courseId = courseIdCell ? cleanCellText(courseIdCell) : '';\n        let sequence = sequenceCell ? cleanCellText(sequenceCell) : '';\n        let credit = creditCell ? cleanCellText(creditCell) : '';\n        let electiveAttr = electiveAttrCell ? cleanCellText(electiveAttrCell) : '';\n        let teacher = teacherCell ? parseTeacherCell(teacherCell) : '';\n\n        let remark = buildRemark(courseId, sequence, credit, electiveAttr);\n\n        let scheduleCell = cellAt(scheduleIdx);\n        let slots = scheduleCell ? parseScheduleCell(scheduleCell) : [];\n\n        if (slots.length === 0) {\n            // 无任何有效排课位的课程（如仅有周次的\"形势与政策（三）\"、无时间安排的\"体能测试Ⅱ\"）\n            let weeksText = '未填写周次';\n            if (scheduleCell) {\n                let firstTd = scheduleCell.querySelector('table td');\n                if (firstTd) {\n                    let text = cleanCellText(firstTd);\n                    if (text) weeksText = text;\n                }\n            }\n            skipped.push({\n                name: name,\n                teacher: teacher || '未填写教师',\n                weeks: weeksText\n            });\n            continue;\n        }\n\n        for (let k = 0; k < slots.length; k++) {\n            let slot = slots[k];\n            let courseBlock = {\n                name: name,\n                teacher: teacher,\n                position: slot.position,\n                day: slot.day,\n                startSection: slot.startSection,\n                endSection: slot.endSection,\n                weeks: slot.weeks,\n                remark: remark\n            };\n\n            // 查找同一天、同名、同老师、同地点、同周次、同备注，且正好是上一节的课程（合并连上的课）\n            let existingCourse = courses.find(c =>\n                c.name === courseBlock.name &&\n                c.day === courseBlock.day &&\n                c.teacher === courseBlock.teacher &&\n                c.position === courseBlock.position &&\n                JSON.stringify(c.weeks) === JSON.stringify(courseBlock.weeks) &&\n                c.remark === courseBlock.remark &&\n                c.endSection === courseBlock.startSection - 1\n            );\n\n            if (existingCourse) {\n                existingCourse.endSection = courseBlock.endSection;\n            } else {\n                courses.push(courseBlock);\n            }\n        }\n    }\n\n    return { courses: courses, skipped: skipped };\n}\n\nfunction formatNoArrangementMessage(courses) {\n    let lines = courses.map((course, index) => {\n        let teacher = course.teacher || '未填写教师';\n        let weeks = course.weeks || '未填写周次';\n        return `${index + 1}. ${course.name} / ${teacher} / ${weeks}`;\n    });\n\n    return `检测到 ${courses.length} 门课程没有具体上课时间或地点，无法自动放入课表：\\n\\n${lines.join('\\n')}\\n\\n请在确认课程时间后重新导入，点击【继续】将导入已知课程。`;\n}\n\n// 保存课表配置（默认学期总周数；失败不阻断课程导入）\nasync function saveCourseConfigData() {\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n            semesterTotalWeeks: SEMESTER_TOTAL_WEEKS\n        }));\n        window.shiguangBridge.showToast(`已设置默认学期总周数：${SEMESTER_TOTAL_WEEKS} 周`);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存课表配置失败: \" + error.message);\n        return false;\n    }\n}\n\n// 导入预设时间段（默认时间表；失败不阻断课程导入）\nasync function importPresetTimeSlots() {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TIME_SLOTS));\n        window.shiguangBridge.showToast(`预设时间段导入成功（${TIME_SLOTS.length} 节）！`);\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        return false;\n    }\n}\n\n// 调度流程\nasync function runImportFlow() {\n    try {\n        window.shiguangBridge.showToast(\"开始解析课表...\");\n\n        const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n            \"导入确认\",\n            \"请确保您目前处于教务系统的“本学期课表”显示页面（页面标题为“本学期课程安排”）。\\n是否立即提取并导入课表？\",\n            \"开始提取\"\n        );\n\n        if (!alertConfirmed) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        const result = fetchCurrentSemesterCourses();\n\n        if (!result || result.courses.length === 0) {\n            await window.shiguangBridgePromise.showAlert(\"错误\", \"未在当前页面找到可导入的课程数据，请确认是否处于“本学期课表”页面，或联系适配开发者。\", \"好的\");\n            return;\n        }\n\n        if (result.skipped.length > 0) {\n            await window.shiguangBridgePromise.showAlert(\n                \"存在未安排课程\",\n                formatNoArrangementMessage(result.skipped),\n                \"继续\"\n            );\n        }\n\n        // 课表配置（学期总周数），失败不阻断\n        await saveCourseConfigData();\n\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(result.courses));\n        window.shiguangBridge.showToast(`成功导入 ${result.courses.length} 门课程块！`);\n\n        // 默认时间表，失败不阻断\n        await importPresetTimeSlots();\n\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入发生错误: \" + error.message);\n    }\n}\n\n// 启动执行\nrunImportFlow();\n","HIT":"// 哈尔滨工业大学(hit.edu.cn) 研究生课表适配脚本\n// 研究生教育管理系统\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    const cleaned = weekStr.replace(/周/g, '').trim();\n    if (!cleaned) return [];\n    const weeks = [];\n    const parts = cleaned.split(/[,，]/);\n    for (const part of parts) {\n        const trimmed = part.trim();\n        if (!trimmed) continue;\n        const isOdd = trimmed.startsWith('单');\n        const isEven = trimmed.startsWith('双');\n        const rangeStr = isOdd || isEven ? trimmed.substring(1) : trimmed;\n        const rangeMatch = rangeStr.match(/^(\\d+)\\s*[-~]\\s*(\\d+)$/);\n        const singleMatch = rangeStr.match(/^(\\d+)$/);\n        if (rangeMatch) {\n            const start = parseInt(rangeMatch[1], 10);\n            const end = parseInt(rangeMatch[2], 10);\n            for (let w = start; w <= end; w++) {\n                if (isOdd && w % 2 === 0) continue;\n                if (isEven && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        } else if (singleMatch) {\n            const num = parseInt(singleMatch[1], 10);\n            if (isOdd && num % 2 === 0) continue;\n            if (isEven && num % 2 !== 0) continue;\n            weeks.push(num);\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseCourseCell(cellStr, day, sections) {\n    if (!cellStr || cellStr === 'null') return [];\n    const courses = [];\n    const entries = cellStr.split('<br/>');\n    for (const entry of entries) {\n        const trimmed = entry.trim();\n        if (!trimmed) continue;\n        // 格式: 课程名◇教师[周次]教室[节次]节\n        // 先找◇分割课程名和教师\n        const teacherSplit = trimmed.split('\\u25C7');\n        if (teacherSplit.length < 2) {\n            console.log(\"HIT调试: 无◇分隔, text=\" + trimmed.substring(0, 40));\n            continue;\n        }\n        const courseName = teacherSplit[0].trim();\n        const rest = teacherSplit.slice(1).join('\\u25C7').trim();\n\n        // 从rest中提取: 教师[周次]教室[节次]节\n        // 找第一个[之前的是教师\n        const firstBracket = rest.indexOf('[');\n        if (firstBracket === -1) continue;\n        const teacher = rest.substring(0, firstBracket).trim();\n\n        // 提取周次: [周次] 中的内容\n        const weekMatch = rest.match(/\\[(\\d+[-~，,\\d]+)周\\]/);\n        if (!weekMatch) {\n            console.log(\"HIT调试: 无周次, rest=\" + rest.substring(0, 50));\n            continue;\n        }\n        const weeksStr = weekMatch[1];\n        const weeks = parseWeeks(weeksStr);\n        if (weeks.length === 0) continue;\n\n        // 提取节次: 最后一个[节次]节 中的内容\n        const sectionMatch = rest.match(/\\[(.+)\\]节/);\n        if (!sectionMatch) {\n            console.log(\"HIT调试: 无节次, rest=\" + rest.substring(0, 50));\n            continue;\n        }\n        const sectionStr = sectionMatch[1].trim();\n\n        // 提取教室: 周次]和节次[之间的内容\n        const afterWeek = rest.substring(rest.indexOf(']周]') + 3);\n        const beforeSection = afterWeek.substring(0, afterWeek.lastIndexOf('['));\n        const room = beforeSection.trim();\n\n        const sectionParts = sectionStr.split(/[,，\\s]+/);\n        const startSection = parseInt(sectionParts[0], 10);\n        const endSection = sectionParts.length > 1 ? parseInt(sectionParts[sectionParts.length - 1], 10) : startSection;\n        if (isNaN(startSection) || isNaN(endSection)) {\n            console.log(\"HIT调试: 节次解析失败, sectionStr=\" + sectionStr);\n            continue;\n        }\n\n        console.log(\"HIT调试: 解析成功, \" + courseName + \"|\" + teacher + \"|\" + room + \"|d\" + day + \"|s\" + startSection + \"-\" + endSection + \"|w\" + weeks.length);\n        courses.push({\n            name: courseName,\n            teacher: teacher,\n            position: room,\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeks\n        });\n    }\n    return courses;\n}\n\nfunction mergeCourses(courses) {\n    if (courses.length <= 1) return courses;\n    courses.sort((a, b) => {\n        return a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) || (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n    const merged = [];\n    let cur = courses[0];\n    for (let i = 1; i < courses.length; i++) {\n        const nxt = courses[i];\n        if (cur.name === nxt.name && cur.teacher === nxt.teacher && cur.position === nxt.position &&\n            cur.day === nxt.day && cur.startSection === nxt.startSection && cur.endSection === nxt.endSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            merged.push(cur);\n            cur = nxt;\n        }\n    }\n    merged.push(cur);\n    return merged;\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"研究生课表导入\",\n        \"导入前请确保您已在浏览器中成功登录研究生系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function fetchCurrentSchedule() {\n    const url = \"/xs/index/getDqxqkb?sf_request_type=ajax\";\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            credentials: \"include\"\n        });\n        if (!response.ok) return null;\n        const data = await response.json();\n        if (!data.isSuccess || !data.module) return null;\n        return data;\n    } catch (e) {\n        return null;\n    }\n}\n\nasync function fetchSemesterInfo() {\n    const url = \"/xs/index/getZcxx?sf_request_type=ajax\";\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            credentials: \"include\"\n        });\n        if (!response.ok) return null;\n        const data = await response.json();\n        if (!data.isSuccess || !data.module) return null;\n        return data.module;\n    } catch (e) {\n        return null;\n    }\n}\n\nconst dayMap = { mon: 1, tues: 2, wed: 3, thur: 4, fri: 5, sat: 6, sun: 7 };\n\nfunction parseScheduleData(scheduleData) {\n    const allCourses = [];\n    const module = scheduleData.module;\n    console.log(\"HIT调试: module行数=\" + module.length);\n    for (const row of module) {\n        const sections = row.jcmc;\n        for (const [dayKey, dayNum] of Object.entries(dayMap)) {\n            const cellStr = row[dayKey];\n            if (!cellStr || cellStr === 'null') continue;\n            console.log(\"HIT调试: \" + dayKey + \"=\" + cellStr.substring(0, 50));\n            const courses = parseCourseCell(cellStr, dayNum, sections);\n            console.log(\"HIT调试: 解析出\" + courses.length + \"门课\");\n            allCourses.push(...courses);\n        }\n    }\n    return mergeCourses(allCourses);\n}\n\nasync function saveCourses(courses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + error.message);\n        return false;\n    }\n}\n\nasync function setPresetTimeSlots() {\n    const presetTimeSlots = [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:50\" },\n        { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:45\" },\n        { \"number\": 3, \"startTime\": \"10:00\", \"endTime\": \"10:50\" },\n        { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:45\" },\n        { \"number\": 5, \"startTime\": \"13:45\", \"endTime\": \"14:35\" },\n        { \"number\": 6, \"startTime\": \"14:40\", \"endTime\": \"15:30\" },\n        { \"number\": 7, \"startTime\": \"15:45\", \"endTime\": \"16:35\" },\n        { \"number\": 8, \"startTime\": \"16:40\", \"endTime\": \"17:30\" },\n        { \"number\": 9, \"startTime\": \"18:30\", \"endTime\": \"19:20\" },\n        { \"number\": 10, \"startTime\": \"19:25\", \"endTime\": \"20:15\" },\n        { \"number\": 11, \"startTime\": \"20:30\", \"endTime\": \"21:20\" },\n        { \"number\": 12, \"startTime\": \"21:25\", \"endTime\": \"22:15\" }\n    ];\n\n    try {\n        const result = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n        if (result === true) {\n            console.log(\"HIT: 预设时间段导入成功\");\n        }\n    } catch (error) {\n        console.error(\"HIT: 导入时间段失败:\", error);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n\n    const [scheduleData, semesterInfo] = await Promise.all([\n        fetchCurrentSchedule(),\n        fetchSemesterInfo()\n    ]);\n\n    if (!scheduleData) {\n        window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n        return;\n    }\n\n    console.log(\"HIT调试: API返回成功, module长度=\" + scheduleData.module.length);\n    console.log(\"HIT调试: 第一行数据=\" + JSON.stringify(scheduleData.module[0]));\n\n    const courses = parseScheduleData(scheduleData);\n    console.log(\"HIT调试: 总共解析=\" + courses.length + \"门课\");\n    if (courses.length > 0) {\n        console.log(\"HIT调试: 第一门=\" + JSON.stringify(courses[0]));\n    }\n    if (courses.length === 0) {\n        window.shiguangBridge.showToast(\"未找到课程数据\");\n        return;\n    }\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) return;\n\n    await setPresetTimeSlots();\n\n    if (semesterInfo && semesterInfo.ZCJSSJ) {\n        try {\n            await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n                semesterStartDate: null,\n                semesterTotalWeeks: 20\n            }));\n        } catch (e) {}\n    }\n\n    const semesterName = semesterInfo ? semesterInfo.MC : \"当前学期\";\n    window.shiguangBridge.showToast(\"课程导入成功！\" + semesterName + \"，共 \" + courses.length + \" 门课程\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","HRBEU":"// 哈尔滨工程大学(hrbeu.edu.cn) 本科课表适配脚本\n// 金智教务(Wisedu EMAP)平台，参考官方金智适配案例\n// 支持：学期选择、实验课、调课/停课、API作息时间、开学日期\n\nvar HEU_API = {\n    semesterList: \"/jwapp/sys/wdkb/modules/jshkcb/xnxqcx.do\",\n    currentTerm:  \"/jwapp/sys/wdkb/modules/jshkcb/dqxnxq.do\",\n    course:       \"/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\",\n    experiment:   \"/jwapp/sys/wdkb/modules/syjxkcb/cxsyjxxskb.do\",\n    change:       \"/jwapp/sys/wdkb/modules/xskcb/xsdkkc.do\",\n    timeSlots:    \"/jwapp/sys/wdkb/modules/jshkcb/jc.do\",\n    config:       \"/jwapp/sys/wdkb/modules/jshkcb/cxjcs.do\"\n};\n\nvar DEFAULT_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"09:55\", endTime: \"10:40\" },\n    { number: 4, startTime: \"10:45\", endTime: \"11:30\" },\n    { number: 5, startTime: \"11:35\", endTime: \"12:20\" },\n    { number: 6, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 7, startTime: \"14:20\", endTime: \"15:05\" },\n    { number: 8, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 9, startTime: \"16:15\", endTime: \"17:00\" },\n    { number: 10, startTime: \"17:05\", endTime: \"17:50\" },\n    { number: 11, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 12, startTime: \"19:20\", endTime: \"20:05\" },\n    { number: 13, startTime: \"20:10\", endTime: \"20:55\" }\n];\n\nvar HEADERS = {\n    \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n    \"x-requested-with\": \"XMLHttpRequest\"\n};\n\nasync function postApi(url, body) {\n    var options = { headers: HEADERS, method: \"POST\", credentials: \"include\" };\n    if (body) options.body = body;\n    var resp = await fetch(url, options);\n    if (!resp.ok) throw new Error(\"请求失败: \" + resp.status);\n    return await resp.json();\n}\n\nfunction getRows(data, key) {\n    return (data && data.datas && data.datas[key] && Array.isArray(data.datas[key].rows))\n        ? data.datas[key].rows : [];\n}\n\nfunction parseWeeksBitmap(skzc) {\n    var weeks = [];\n    var bits = String(skzc || \"\");\n    for (var i = 0; i < bits.length; i++) {\n        if (bits[i] === \"1\") weeks.push(i + 1);\n    }\n    return weeks;\n}\n\nfunction parseSingleCourse(raw) {\n    var isExperiment = raw.SYXMMC !== undefined && raw.SYXMMC !== null;\n    var name = isExperiment ? raw.KCM + \" - \" + raw.SYXMMC : raw.KCM;\n    if (!isExperiment && raw.TYXMDM_DISPLAY) name += \"(\" + raw.TYXMDM_DISPLAY + \")\";\n\n    var day = parseInt(raw.SKXQ);\n    var startSection = parseInt(raw.KSJC);\n    var endSection = parseInt(raw.JSJC);\n    var weeks = parseWeeksBitmap(raw.SKZC);\n\n    if (!name || !day || !startSection || !endSection || weeks.length === 0) return null;\n\n    return {\n        name: name,\n        teacher: raw.SKJS ? raw.SKJS.split(\"/\")[0] : (raw.JSM || \"\"),\n        position: raw.JASMC || \"待定\",\n        day: day,\n        startSection: startSection,\n        endSection: endSection,\n        weeks: weeks,\n        _kbId: raw.KBID,\n        _day: day,\n        _startSection: startSection,\n        _endSection: endSection\n    };\n}\n\nfunction applyCourseChanges(courses, changes) {\n    var count = 0;\n    for (var i = 0; i < changes.length; i++) {\n        var ch = changes[i];\n        var kbId = ch.KBID;\n        var weeksToRemove = parseWeeksBitmap(ch.SKZC);\n        var applied = false;\n\n        var affected = courses.filter(function(c) {\n            return c._kbId === kbId &&\n                c._day === parseInt(ch.SKXQ) &&\n                c._startSection === parseInt(ch.KSJC) &&\n                c._endSection === parseInt(ch.JSJC);\n        });\n\n        if (affected.length === 0) continue;\n\n        if (weeksToRemove.length > 0) {\n            affected.forEach(function(c) {\n                var before = c.weeks.length;\n                c.weeks = c.weeks.filter(function(w) { return weeksToRemove.indexOf(w) === -1; });\n                if (c.weeks.length < before) applied = true;\n            });\n        }\n\n        var isTimeChange = ch.TKLXDM === \"01\" || ch.TKLXDM === \"03\";\n        if (isTimeChange && ch.XSKZC && ch.XSKXQ && ch.XKSJC && ch.XJSJC) {\n            var newWeeks = parseWeeksBitmap(ch.XSKZC);\n            if (newWeeks.length > 0) {\n                var origTeacher = ch.YSKJS ? ch.YSKJS.split(\"/\")[0] : \"\";\n                courses.push({\n                    name: ch.KCM,\n                    teacher: ch.XSKJS ? ch.XSKJS.split(\"/\")[0] : origTeacher,\n                    position: ch.XJASMC || ch.JASMC || \"待定\",\n                    day: parseInt(ch.XSKXQ),\n                    startSection: parseInt(ch.XKSJC),\n                    endSection: parseInt(ch.XJSJC),\n                    weeks: newWeeks,\n                    _kbId: kbId,\n                    _day: parseInt(ch.XSKXQ),\n                    _startSection: parseInt(ch.XKSJC),\n                    _endSection: parseInt(ch.XJSJC)\n                });\n                applied = true;\n            }\n        }\n        if (applied) count++;\n    }\n    if (count > 0) window.shiguangBridge.showToast(\"已应用 \" + count + \" 条调课/停课变更。\");\n    return courses;\n}\n\nfunction cleanAndMerge(courses) {\n    var list = courses.map(function(c) {\n        return {\n            name: c.name || \"\",\n            teacher: c.teacher || \"\",\n            position: c.position || \"\",\n            day: c.day,\n            startSection: c.startSection,\n            endSection: c.endSection,\n            weeks: Array.isArray(c.weeks) ? c.weeks.slice().sort(function(a,b){return a-b;}) : []\n        };\n    }).filter(function(c) { return c.weeks.length > 0; });\n\n    // 阶段1: 合并连续节次\n    list.sort(function(a, b) {\n        return a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) || (a.day||0)-(b.day||0) ||\n            a.weeks.join(\",\").localeCompare(b.weeks.join(\",\")) ||\n            (a.startSection||0)-(b.startSection||0);\n    });\n\n    var step1 = [];\n    var cur = list[0];\n    for (var i = 1; i < list.length; i++) {\n        var nxt = list[i];\n        var same = cur.name === nxt.name && cur.teacher === nxt.teacher &&\n            cur.position === nxt.position && cur.day === nxt.day &&\n            cur.weeks.join(\",\") === nxt.weeks.join(\",\");\n\n        if (same && cur.endSection + 1 === nxt.startSection) {\n            cur.endSection = nxt.endSection;\n        } else if (same && cur.startSection === nxt.startSection && cur.endSection === nxt.endSection) {\n            continue;\n        } else {\n            step1.push(cur);\n            cur = nxt;\n        }\n    }\n    step1.push(cur);\n\n    // 阶段2: 合并同节次的周次\n    step1.sort(function(a, b) {\n        return a.name.localeCompare(b.name) || a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) || (a.day||0)-(b.day||0) ||\n            (a.startSection||0)-(b.startSection||0) || (a.endSection||0)-(b.endSection||0);\n    });\n\n    var step2 = [];\n    cur = step1[0];\n    for (var j = 1; j < step1.length; j++) {\n        var n = step1[j];\n        if (cur.name === n.name && cur.teacher === n.teacher && cur.position === n.position &&\n            cur.day === n.day && cur.startSection === n.startSection && cur.endSection === n.endSection) {\n            var set = {};\n            cur.weeks.concat(n.weeks).forEach(function(w) { set[w] = true; });\n            cur.weeks = Object.keys(set).map(Number).sort(function(a,b){return a-b;});\n        } else {\n            step2.push(cur);\n            cur = n;\n        }\n    }\n    step2.push(cur);\n    return step2;\n}\n\nasync function selectSemester() {\n    var semesterList = [];\n    try {\n        var data = await postApi(HEU_API.semesterList, \"*order=-DM\");\n        semesterList = getRows(data, \"xnxqcx\");\n    } catch (e) {\n        window.shiguangBridge.showToast(\"获取学期列表失败，请检查登录状态。\");\n        return null;\n    }\n    if (semesterList.length === 0) {\n        window.shiguangBridge.showToast(\"未查询到学期数据。\");\n        return null;\n    }\n\n    var defaultDM = null;\n    try {\n        var dqData = await postApi(HEU_API.currentTerm);\n        var dqRows = getRows(dqData, \"dqxnxq\");\n        if (dqRows.length > 0) defaultDM = dqRows[0].DM;\n    } catch (e) {}\n\n    var top = semesterList.slice(0, 10);\n    var names = top.map(function(s) { return s.MC || s.DM; });\n    var defaultIdx = -1;\n    if (defaultDM) {\n        for (var i = 0; i < top.length; i++) {\n            if (top[i].DM === defaultDM) { defaultIdx = i; break; }\n        }\n    }\n\n    var idx = await window.shiguangBridgePromise.showSingleSelection(\n        \"请选择学期\", JSON.stringify(names), defaultIdx\n    );\n    if (idx === null || idx === -1) return null;\n    return top[idx];\n}\n\nasync function importTimeSlots() {\n    var slots = null;\n    try {\n        var data = await postApi(HEU_API.timeSlots);\n        var rows = getRows(data, \"jc\");\n        if (rows.length > 0) {\n            slots = rows.map(function(r) {\n                return { number: parseInt(r.DM), startTime: r.KSSJ, endTime: r.JSSJ };\n            });\n        }\n    } catch (e) {}\n\n    if (!slots || slots.length === 0) {\n        slots = DEFAULT_TIME_SLOTS;\n    }\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(slots));\n}\n\nasync function fetchSemesterConfig(xn, xq) {\n    try {\n        var data = await postApi(HEU_API.config, \"XN=\" + xn + \"&XQ=\" + xq);\n        var row = getRows(data, \"cxjcs\")[0];\n        if (row) {\n            var rawDate = row.XQKSRQ;\n            return {\n                semesterStartDate: rawDate ? rawDate.split(\" \")[0] : null,\n                semesterTotalWeeks: parseInt(row.ZZC) || 20\n            };\n        }\n    } catch (e) {}\n    return { semesterStartDate: null, semesterTotalWeeks: 20 };\n}\n\nasync function runImportFlow() {\n    var confirmed = await window.shiguangBridgePromise.showAlert(\n        \"哈尔滨工程大学课表导入\",\n        \"导入前请确保已登录教务系统。\",\n        \"好的，开始导入\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"已取消导入\");\n        return;\n    }\n\n    var semester = await selectSemester();\n    if (!semester) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n    var XNXQDM = semester.DM;\n\n    window.shiguangBridge.showToast(\"正在获取作息时间...\");\n    await importTimeSlots();\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    var courseData = await postApi(HEU_API.course, \"XNXQDM=\" + XNXQDM);\n    var rawCourses = getRows(courseData, \"cxxszhxqkb\");\n\n    // 获取实验课\n    var rawExpCourses = [];\n    try {\n        var expData = await postApi(HEU_API.experiment, \"XNXQDM=\" + XNXQDM);\n        rawExpCourses = getRows(expData, \"cxsyjxxskb\");\n    } catch (e) {\n        console.warn(\"HEU: 获取实验课失败:\", e);\n    }\n\n    var allRaw = rawCourses.concat(rawExpCourses);\n    if (allRaw.length === 0) {\n        await window.shiguangBridgePromise.showAlert(\"导入提示\", \"该学期未查到课程数据。\", \"知道了\");\n        return;\n    }\n\n    if (rawExpCourses.length > 0) {\n        window.shiguangBridge.showToast(\"获取到 \" + rawCourses.length + \" 门理论课和 \" + rawExpCourses.length + \" 门实验课\");\n    }\n\n    var parsed = allRaw.map(parseSingleCourse).filter(function(c) { return c !== null; });\n\n    // 获取调课数据\n    try {\n        var chData = await postApi(HEU_API.change, \"XNXQDM=\" + XNXQDM + \"&*order=-SQSJ\");\n        var rawChanges = getRows(chData, \"xsdkkc\");\n        if (rawChanges.length > 0) {\n            parsed = applyCourseChanges(parsed, rawChanges);\n        }\n    } catch (e) {\n        console.warn(\"HEU: 获取调课数据失败:\", e);\n    }\n\n    var courses = cleanAndMerge(parsed);\n\n    if (courses.length === 0) {\n        window.shiguangBridge.showToast(\"课表解析结果为空\");\n        return;\n    }\n\n    var config = await fetchSemesterConfig(semester.XNDM, semester.XQDM);\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n    window.shiguangBridge.showToast(XNXQDM + \" 课表导入成功，共 \" + courses.length + \" 门课程\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n(async function() {\n    try {\n        await runImportFlow();\n    } catch (error) {\n        console.error(\"HEU课表导入失败:\", error);\n        if (window.shiguangBridgePromise) {\n            await window.shiguangBridgePromise.showAlert(\n                \"导入失败\",\n                \"错误: \" + error.message + \"\\n\\n请确认：\\n1. 已登录教务系统\\n2. 处于校园网或VPN环境\",\n                \"确定\"\n            );\n        }\n    }\n})();\n","HRBEU_YJS":"// 哈尔滨工程大学(yjs.hrbeu.edu.cn) 研究生课表适配脚本\n// 研究生教育管理信息系统\n\nvar HEU_YJS_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"09:55\", endTime: \"10:40\" },\n    { number: 4, startTime: \"10:50\", endTime: \"11:35\" },\n    { number: 5, startTime: \"11:35\", endTime: \"12:20\" },\n    { number: 6, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 7, startTime: \"14:20\", endTime: \"15:05\" },\n    { number: 8, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 9, startTime: \"16:20\", endTime: \"17:05\" },\n    { number: 10, startTime: \"17:05\", endTime: \"17:50\" },\n    { number: 11, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 12, startTime: \"19:25\", endTime: \"20:10\" },\n    { number: 13, startTime: \"20:10\", endTime: \"20:55\" }\n];\n\nvar DAY_FIELDS = [\n    { field: \"Monday\", day: 1 },\n    { field: \"Tuesday\", day: 2 },\n    { field: \"Wednesday\", day: 3 },\n    { field: \"Thursday\", day: 4 },\n    { field: \"Friday\", day: 5 },\n    { field: \"Saturday\", day: 6 },\n    { field: \"Sunday\", day: 7 }\n];\n\nfunction findTimetableRequest() {\n    var resources = performance.getEntriesByType(\"resource\");\n    var matches = resources.map(function(r) { return r.name; })\n        .filter(function(url) { return url.indexOf(\"GetTimeTableByStudent\") !== -1; });\n    return matches.length ? matches[matches.length - 1] : null;\n}\n\nfunction parseWeeks(text) {\n    if (!text) return [];\n    var weeks = {};\n    var parts = text.split(/[;；]/);\n    for (var i = 0; i < parts.length; i++) {\n        var part = parts[i].replace(/\\([^)]*\\)/g, \"\").trim();\n        if (!part) continue;\n        var segs = part.split(/[,，]/);\n        for (var j = 0; j < segs.length; j++) {\n            var seg = segs[j].trim();\n            var rangeMatch = seg.match(/(\\d+)\\s*[-~]\\s*(\\d+)/);\n            if (rangeMatch) {\n                for (var w = parseInt(rangeMatch[1]); w <= parseInt(rangeMatch[2]); w++) {\n                    weeks[w] = true;\n                }\n            } else {\n                var num = parseInt(seg);\n                if (!isNaN(num) && num > 0) weeks[num] = true;\n            }\n        }\n    }\n    return Object.keys(weeks).map(Number).sort(function(a, b) { return a - b; });\n}\n\nfunction parseMultiTeacherWeeks(weekText) {\n    // 格式: \"1-5(张翼飞);7-9(张翼飞);10-17(郝龙)\"\n    var result = [];\n    var re = /([\\d,\\-~]+)\\(([^)]+)\\)/g;\n    var match;\n    while ((match = re.exec(weekText)) !== null) {\n        result.push({ weeks: parseWeeks(match[1]), teacher: match[2].trim() });\n    }\n    return result;\n}\n\nfunction parseSections(text) {\n    if (!text) return null;\n    var match = text.match(/(\\d+)/g);\n    if (!match || !match.length) return null;\n    var nums = match.map(Number);\n    return { start: Math.min.apply(null, nums), end: Math.max.apply(null, nums) };\n}\n\nfunction parseCourseCell(cellStr, day, sections) {\n    if (!cellStr || typeof cellStr !== \"string\") return [];\n    var courses = [];\n    var text = cellStr.replace(/\\\\r\\\\n/g, \"\\r\\n\");\n    var blocks = text.split(/\\r?\\n\\r?\\n/).filter(function(b) { return b.trim(); });\n\n    for (var i = 0; i < blocks.length; i++) {\n        var lines = blocks[i].split(/\\r?\\n/).map(function(l) { return l.trim(); }).filter(function(l) { return l; });\n        if (lines.length < 2) continue;\n\n        var name = lines[0];\n        var teacherLine = lines[1] || \"\";\n        var defaultTeacher = teacherLine.split(/\\s+/)[0] || \"未知\";\n\n        var weekText = \"\", position = \"\";\n        for (var j = 0; j < lines.length; j++) {\n            var wm = lines[j].match(/^周次[:：]\\s*(.+)/);\n            if (wm) weekText = wm[1].trim();\n            var pm = lines[j].match(/^地点[:：]\\s*(.+)/);\n            if (pm) position = pm[1].trim();\n        }\n\n        if (!weekText) continue;\n\n        var secInfo = null;\n        for (var k = 0; k < lines.length; k++) {\n            var sm = lines[k].match(/^节次[:：]\\s*(.+)/);\n            if (sm) { secInfo = parseSections(sm[1]); break; }\n        }\n        var startSection = secInfo ? secInfo.start : sections.start;\n        var endSection = secInfo ? secInfo.end : sections.end;\n\n        // 一班多师: \"1-5(张翼飞);7-9(张翼飞);10-17(郝龙)\"\n        var multiTeacher = parseMultiTeacherWeeks(weekText);\n        if (multiTeacher.length > 0) {\n            for (var m = 0; m < multiTeacher.length; m++) {\n                courses.push({\n                    name: name,\n                    teacher: multiTeacher[m].teacher,\n                    position: position || \"待定\",\n                    day: day,\n                    startSection: startSection,\n                    endSection: endSection,\n                    weeks: multiTeacher[m].weeks\n                });\n            }\n        } else {\n            var weeks = parseWeeks(weekText);\n            if (!weeks.length) continue;\n            courses.push({\n                name: name,\n                teacher: defaultTeacher,\n                position: position || \"待定\",\n                day: day,\n                startSection: startSection,\n                endSection: endSection,\n                weeks: weeks\n            });\n        }\n    }\n    return courses;\n}\n\nfunction parseScheduleData(data) {\n    var allCourses = [];\n    if (!Array.isArray(data)) return allCourses;\n\n    for (var i = 0; i < data.length; i++) {\n        var row = data[i];\n        var sections = parseSections(row.JieCi);\n        if (!sections) continue;\n\n        for (var j = 0; j < DAY_FIELDS.length; j++) {\n            var cellStr = row[DAY_FIELDS[j].field];\n            if (!cellStr) continue;\n            var courses = parseCourseCell(cellStr, DAY_FIELDS[j].day, sections);\n            allCourses.push.apply(allCourses, courses);\n        }\n    }\n    return allCourses;\n}\n\nfunction dedup(courses) {\n    var index = {};\n    var result = [];\n    for (var i = 0; i < courses.length; i++) {\n        var c = courses[i];\n        var key = c.day + \"|\" + c.startSection + \"|\" + c.endSection + \"|\" + c.name + \"|\" + c.teacher + \"|\" + c.position;\n        if (index[key] === undefined) {\n            index[key] = result.length;\n            result.push(c);\n        } else {\n            var ex = result[index[key]];\n            c.weeks.forEach(function(w) { if (ex.weeks.indexOf(w) === -1) ex.weeks.push(w); });\n        }\n    }\n    result.forEach(function(c) { c.weeks.sort(function(a, b) { return a - b; }); });\n    return result;\n}\n\nasync function fetchSchedule() {\n    // 方案1: 拦截已有请求\n    var url = findTimetableRequest();\n    if (url) {\n        console.log(\"HEU研: 拦截到课表请求 \" + url);\n        var resp = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\",\n            headers: { \"Accept\": \"application/json, text/javascript, */*; q=0.01\", \"X-Requested-With\": \"XMLHttpRequest\" }\n        });\n        if (resp.ok) return await resp.json();\n    }\n    throw new Error(\"未找到课表请求，请先在页面上查询课表后再点击导入\");\n}\n\nasync function runImportFlow() {\n    var confirmed = await window.shiguangBridgePromise.showAlert(\n        \"哈工程研究生课表导入\",\n        \"请确保已登录研究生系统，并已打开课表查询页面，等待课表加载完成后点击确定。\",\n        \"确定，开始导入\"\n    );\n    if (!confirmed) {\n        window.shiguangBridge.showToast(\"已取消导入\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    var data = await fetchSchedule();\n\n    console.log(\"HEU研: 获取到 \" + data.length + \" 行数据\");\n    var courses = dedup(parseScheduleData(data));\n    console.log(\"HEU研: 解析出 \" + courses.length + \" 门课程\");\n\n    if (courses.length === 0) {\n        await window.shiguangBridgePromise.showAlert(\"导入提示\", \"未解析到课程数据，请确认课表页面已加载完成。\", \"知道了\");\n        return;\n    }\n\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(HEU_YJS_TIME_SLOTS));\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n        semesterStartDate: null,\n        semesterTotalWeeks: 20,\n        defaultClassDuration: 45,\n        defaultBreakDuration: 5,\n        firstDayOfWeek: 1\n    }));\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n    window.shiguangBridge.showToast(\"研究生课表导入成功，共 \" + courses.length + \" 门课程\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n(async function() {\n    try {\n        await runImportFlow();\n    } catch (error) {\n        console.error(\"HEU研究生课表导入失败:\", error);\n        if (window.shiguangBridgePromise) {\n            await window.shiguangBridgePromise.showAlert(\n                \"导入失败\",\n                \"错误: \" + error.message + \"\\n\\n请确认：\\n1. 已登录研究生系统\\n2. 已打开课表查询页面并加载完成\\n3. 处于校园网或VPN环境\",\n                \"确定\"\n            );\n        }\n    }\n})();\n","HHTC_01":"// 怀化学院(hhtc.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n/**\n * 年份输入验证函数\n * @param {string} input 用户输入的年份\n * @returns {boolean|string} 验证通过返回false，失败返回错误提示\n */\nwindow.validateYearInput = function(input) {\n    return /^[0-9]{4}$/.test(input) ? false : \"请输入四位数字的学年！\";\n};\n\n// 数据解析函数\n\n/**\n * 将周次字符串解析为数字数组\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    \n    // 适配 \"1-9,11-17(周)[01-02节]\" 或 \"12-15(周)\"\n    const pureWeekData = weekStr.split('(')[0]; \n    \n    pureWeekData.split(',').forEach(seg => {\n        if (seg.includes('-')) {\n            const [s, e] = seg.split('-').map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 转换课程 HTML 格式为应用模型\n */\nfunction parseTimetableToModel(doc) {\n    const timetable = doc.getElementById('timetable');\n    if (!timetable) return [];\n\n    const results = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).slice(1);\n\n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        if (cells.length < 7) return;\n\n        cells.forEach((cell, dayIndex) => {\n            let day = dayIndex + 1;\n            const detailDivs = cell.querySelectorAll('.kbcontent, .kbcontent1');\n            \n            detailDivs.forEach(detailDiv => {\n                const rawHtml = detailDiv.innerHTML.trim();\n                if (rawHtml === \"\" || rawHtml === \"&nbsp;\") return;\n\n                const courseBlocks = rawHtml.split(/---------------------|----------------------/);\n                \n                courseBlocks.forEach(block => {\n                    if (block.replace(/&nbsp;|<br\\/?>/g, '').trim() === \"\") return;\n\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    let name = \"\";\n                    const nameFont = tempDiv.querySelector('font:not([title])');\n                    if (nameFont) {\n                        name = nameFont.innerText.trim();\n                    }\n\n                    // 提取教师、周次、地点\n                    const teacher = tempDiv.querySelector('font[title=\"教师\"]')?.innerText.trim() || \"未知教师\";\n                    const weekInfo = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText.trim() || \"\";\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText.trim() || \"未知地点\";\n\n                    let start = 0, end = 0;\n                    if (weekInfo) {\n                        const secMatch = weekInfo.match(/\\[(\\d+)(?:-(\\d+))?节\\]/);\n                        if (secMatch) {\n                            start = parseInt(secMatch[1]);\n                            end = secMatch[2] ? parseInt(secMatch[2]) : start;\n                        }\n                    }\n\n                    if (name && start > 0) {\n                        results.push({\n                            \"name\": name,\n                            \"teacher\": teacher,\n                            \"weeks\": parseWeeks(weekInfo),\n                            \"position\": position,\n                            \"day\": day,\n                            \"startSection\": start,\n                            \"endSection\": end\n                        });\n                    }\n                });\n            });\n        });\n    });\n\n    return results;\n}\n\n/**\n * 全局课程合并逻辑\n */\nfunction mergeContinuousLessons(lessons) {\n    if (!lessons || lessons.length === 0) return [];\n\n    // 1. 建立基于 (课程名|教师|地点|星期几) 的分组\n    const groups = {};\n    lessons.forEach(l => {\n        const key = `${l.name}|${l.teacher}|${l.position}|${l.day}`;\n        if (!groups[key]) {\n            groups[key] = {\n                name: l.name,\n                teacher: l.teacher,\n                position: l.position,\n                day: l.day,\n                // 假设大学最多 50 周，构建一个：第 N 周对应哪些节次的矩阵\n                weeksMatrix: Array.from({ length: 50 }, () => new Set())\n            };\n        }\n        // 将系统传来的凌乱数据彻底打散，按“周”填入对应的“节”中，Set自动去重\n        if (l.weeks && Array.isArray(l.weeks)) {\n            l.weeks.forEach(w => {\n                if (w >= 0 && w < 50) {\n                    for (let s = l.startSection; s <= l.endSection; s++) {\n                        groups[key].weeksMatrix[w].add(s);\n                    }\n                }\n            });\n        }\n    });\n\n    const merged = [];\n\n    // 2. 根据矩阵重新组装绝对精确的课程块\n    for (const key in groups) {\n        const group = groups[key];\n        const matrix = group.weeksMatrix;\n        \n        // 用于记录相同的“连续节次块”分布在哪些周次\n        // 例如 blockMap[\"1-2\"] = [1, 2, 3, 4, 5, 6, 7, 8, 9]\n        // 例如 blockMap[\"2-2\"] = [10]\n        const blockMap = {};\n\n        for (let w = 0; w < matrix.length; w++) {\n            const sections = Array.from(matrix[w]).sort((a, b) => a - b);\n            if (sections.length === 0) continue;\n\n            // 寻找当前周的连续节次块\n            let start = sections[0];\n            let prev = sections[0];\n\n            for (let i = 1; i < sections.length; i++) {\n                const curr = sections[i];\n                if (curr === prev + 1) {\n                    prev = curr; // 节次连续，继续延伸\n                } else {\n                    // 节次断开，结算上一个块\n                    const blockKey = `${start}-${prev}`;\n                    if (!blockMap[blockKey]) blockMap[blockKey] = [];\n                    blockMap[blockKey].push(w);\n                    \n                    // 开启新块\n                    start = curr;\n                    prev = curr;\n                }\n            }\n            // 结算每周最后一个块\n            const blockKey = `${start}-${prev}`;\n            if (!blockMap[blockKey]) blockMap[blockKey] = [];\n            blockMap[blockKey].push(w);\n        }\n\n        // 3. 将聚合好的 blockMap 转换为最终的 JSON 对象\n        for (const blockKey in blockMap) {\n            const [startSec, endSec] = blockKey.split('-').map(Number);\n            merged.push({\n                name: group.name,\n                teacher: group.teacher,\n                position: group.position,\n                day: group.day,\n                startSection: startSec,\n                endSection: endSec,\n                weeks: blockMap[blockKey]\n            });\n        }\n    }\n\n    // 4. 排序以便输出整洁美观\n    merged.sort((a, b) => {\n        if (a.day !== b.day) return a.day - b.day;\n        if (a.startSection !== b.startSection) return a.startSection - b.startSection;\n        return a.name.localeCompare(b.name);\n    });\n\n    return merged;\n}\n\n/**\n * 保存课表全局配置\n */\nasync function saveAppConfig() {\n    const config = {\n        \"firstDayOfWeek\": 1\n    };\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n/**\n * 保存时间段配置\n */\nasync function saveAppTimeSlots() {\n    const timeSlots = [\n        { \"number\": 1, \"startTime\": \"08:20\", \"endTime\": \"09:05\" },\n        { \"number\": 2, \"startTime\": \"09:15\", \"endTime\": \"10:00\" },\n        { \"number\": 3, \"startTime\": \"10:20\", \"endTime\": \"11:05\" },\n        { \"number\": 4, \"startTime\": \"11:15\", \"endTime\": \"12:00\" },\n        { \"number\": 5, \"startTime\": \"14:20\", \"endTime\": \"15:05\" },\n        { \"number\": 6, \"startTime\": \"15:15\", \"endTime\": \"16:00\" },\n        { \"number\": 7, \"startTime\": \"16:20\", \"endTime\": \"17:05\" },\n        { \"number\": 8, \"startTime\": \"17:15\", \"endTime\": \"18:00\" },\n        { \"number\": 9, \"startTime\": \"19:30\", \"endTime\": \"20:15\" },\n        { \"number\": 10, \"startTime\": \"20:25\", \"endTime\": \"21:10\" }\n    ];\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n}\n\n/**\n * 获取并让用户选择学期 ID\n */\nasync function getSelectedSemesterId() {\n    const currentYear = new Date().getFullYear();\n    const year = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\", \"请输入起始学年（如 2025-2026 应输入 2025）:\", String(currentYear), \"validateYearInput\"\n    );\n    if (!year) return null;\n    \n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify([\"第一学期\", \"第二学期\"]), -1\n    );\n    if (semesterIndex === null) return null;\n    \n    return `${year}-${parseInt(year) + 1}-${semesterIndex + 1}`;\n}\n\n// 流程控制\n\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"导入提示\",\n            \"脚本将获取当前教务系统的课表数据。请确保您已登录。是否继续？\",\n            \"确认并开始\"\n        );\n        if (!confirmed) return;\n\n        const semesterId = await getSelectedSemesterId();\n        if (!semesterId) {\n            window.shiguangBridge.showToast(\"用户取消了学期选择\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(\"正在请求教务数据...\");\n        const response = await fetch(\"https://jwmis.hhtc.edu.cn/jsxsd/xskb/xskb_list.do\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: `cj0701id=&zc=&demo=&xnxq01id=${semesterId}`,\n            credentials: \"include\"\n        });\n        \n        if (!response.ok) throw new Error(\"网络请求失败，请检查登录状态\");\n\n        const html = await response.text();\n        let finalCourses = parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"));\n\n        finalCourses = mergeContinuousLessons(finalCourses);\n\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现课程数据，请检查该学期是否有课或登录是否过期\");\n            return;\n        }\n        await saveAppConfig();\n        await saveAppTimeSlots();\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n        \n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程！`);\n\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        console.error(error);\n        window.shiguangBridge.showToast(\"异常: \" + error.message);\n    }\n}\n\n// 启动导入流程\nrunImportFlow();","HHVTC":"// 怀化职业技术学院教务系统（jwgl.hhvtc.com.cn）拾光课表导入适配脚本\n// 青果教务：课表表格单元格 .have-content 只有空内容，课程详情在隐藏 div [id^=\"weekly0\"] 内\n//   每个详情 div 含 ul>li：课程名称 / 任课教师 / 上课时间（[周次]星期[节次]）/ 上课地点 / 合班信息\n// 作息分夏秋（5.1起）与冬春（10.1起）两套，导入时通过选择器让用户选择\n\n// 夏秋作息（5.1 起）\nconst HHVT_TIME_SLOTS_SUMMER = [\n    { number: 1, startTime: \"08:10\", endTime: \"08:55\" },\n    { number: 2, startTime: \"09:05\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 7, startTime: \"16:20\", endTime: \"17:05\" },\n    { number: 8, startTime: \"17:15\", endTime: \"18:00\" }\n];\n\n// 冬春作息（10.1 起）\nconst HHVT_TIME_SLOTS_WINTER = [\n    { number: 1, startTime: \"08:20\", endTime: \"09:05\" },\n    { number: 2, startTime: \"09:15\", endTime: \"10:00\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:05\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"15:50\", endTime: \"16:35\" },\n    { number: 8, startTime: \"16:45\", endTime: \"17:30\" }\n];\n\nfunction getErrorMessage(error) {\n    if (error && typeof error.message === \"string\" && error.message.trim()) return error.message;\n    if (typeof error === \"string\" && error.trim()) return error;\n    try {\n        const serialized = JSON.stringify(error);\n        if (serialized && serialized !== \"{}\") return serialized;\n    } catch (_) {\n        // Ignore serialization failures.\n    }\n    return \"未知错误\";\n}\n\n// 收集可访问的 document（frameset 用 <frame>，普通页面用 <iframe>）\nfunction collectDocs() {\n    const docs = [document];\n    const frames = document.querySelectorAll(\"iframe, frame\");\n    for (const f of frames) {\n        try {\n            if (f.contentDocument) docs.push(f.contentDocument);\n        } catch (_) {\n            // 跨域 frame 无法访问，忽略。\n        }\n    }\n    return docs;\n}\n\n// 从各 frame 中查找课表详情 div（[id^=\"weekly0\"]）\n// 注入时机早于页面加载完成，故轮询等待（最长 6 秒）\nasync function findDetailDivs() {\n    const deadline = Date.now() + 6000;\n    while (Date.now() < deadline) {\n        for (const doc of collectDocs()) {\n            const divs = doc.querySelectorAll('[id^=\"weekly0\"]');\n            if (divs.length > 0) {\n                return { doc, divs };\n            }\n        }\n        await new Promise(resolve => setTimeout(resolve, 300));\n    }\n    return null;\n}\n\n// 解析周次文本：\"3周\"→[3]；\"1-18周\"→[1..18]；\"1-8,10-18周\"→[1..8,10..18]\nfunction parseWeeksText(weekStr) {\n    const text = String(weekStr || \"\").replace(/\\s+/g, \"\");\n    const m = text.match(/\\[(.*?)\\]/);\n    if (!m) return [];\n    const body = m[1].replace(/周/g, \"\");\n    const weeks = [];\n    const parts = body.split(\",\");\n    for (const part of parts) {\n        const range = part.split(\"-\");\n        const start = Number(range[0]);\n        const end = range.length > 1 ? Number(range[1]) : start;\n        if (!start) continue;\n        for (let w = start; w <= end; w++) weeks.push(w);\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 星期汉字 → 拾光 day（一=1 … 日=7）\nconst DAY_MAP = { 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 日: 7 };\n\n// 解析单个详情 div（ul>li 结构）\nfunction parseDetailDiv(div) {\n    const lis = div.querySelectorAll(\"li\");\n    if (lis.length === 0) return null;\n\n    let name = \"\";\n    let teacher = \"\";\n    let position = \"\";\n    let timeText = \"\";\n\n    for (const li of lis) {\n        const text = (li.textContent || \"\").trim();\n        if (text.indexOf(\"课程名称\") !== -1) {\n            name = text.replace(/^.*?[:：]/, \"\").trim();\n        } else if (text.indexOf(\"任课教师\") !== -1) {\n            teacher = text.replace(/^.*?[:：]/, \"\").trim();\n        } else if (text.indexOf(\"上课时间\") !== -1) {\n            timeText = text.replace(/^.*?[:：]/, \"\").trim();\n        } else if (text.indexOf(\"上课地点\") !== -1) {\n            position = text.replace(/^.*?[:：]/, \"\").trim();\n        }\n    }\n\n    if (!name || !timeText) return null;\n\n    // 上课时间：[3周]一[1-2节]\n    const dayMatch = timeText.match(/[一二三四五六日]/);\n    if (!dayMatch) return null;\n    const day = DAY_MAP[dayMatch[0]];\n    const sectionMatch = timeText.match(/\\[(\\d+)-(\\d+)节\\]/);\n    if (!sectionMatch) return null;\n    const weeks = parseWeeksText(timeText);\n    if (weeks.length === 0) return null;\n\n    return {\n        name,\n        teacher: teacher || \"未知\",\n        position: position || \"待定\",\n        day,\n        startSection: Number(sectionMatch[1]),\n        endSection: Number(sectionMatch[2]),\n        weeks\n    };\n}\n\n// 解析所有详情 div\nfunction parseCourses(divs) {\n    const courses = [];\n    for (const div of divs) {\n        const course = parseDetailDiv(div);\n        if (course) courses.push(course);\n    }\n    return courses;\n}\n\n// 合并同课程同时间同教室的条目\nfunction mergeCourses(courses) {\n    const merged = new Map();\n    for (const c of courses) {\n        const key = `${c.name}|${c.teacher}|${c.position}|${c.day}|${c.startSection}|${c.endSection}`;\n        const holder = merged.get(key);\n        if (holder) {\n            holder.weeks = Array.from(new Set([...holder.weeks, ...c.weeks])).sort((a, b) => a - b);\n        } else {\n            merged.set(key, { ...c, weeks: [...c.weeks].sort((a, b) => a - b) });\n        }\n    }\n    return Array.from(merged.values()).sort(\n        (a, b) => a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name)\n    );\n}\n\n// 保存作息时间\nasync function saveTimeSlots(timeSlots) {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    } catch (error) {\n        console.error(\"JS: 作息时间保存失败\", error);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n        \"课表导入\",\n        \"导入前请确保已登录并打开课表查询页面。\",\n        \"好的，开始导入\"\n    );\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    // 作息选择：按当前日期给默认（5.1-9.30 夏秋，10.1-4.30 冬春）\n    const now = new Date();\n    const defaultIdx = (now.getMonth() + 1 >= 5 && now.getMonth() + 1 <= 9) ? 0 : 1;\n    const picked = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择作息时间\",\n        JSON.stringify([\"夏秋作息（5月1日起）\", \"冬春作息（10月1日起）\"]),\n        defaultIdx\n    );\n    if (picked === null || picked < 0) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n    const timeSlots = picked === 0 ? HHVT_TIME_SLOTS_SUMMER : HHVT_TIME_SLOTS_WINTER;\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    try {\n        const found = await findDetailDivs();\n        if (!found) throw new Error(\"未找到课表详情，请确认已登录并打开课表查询页面。\");\n\n        const courses = parseCourses(found.divs);\n        if (courses.length === 0) throw new Error(\"课表中未解析到有效课程，请确认当前学期有课。\");\n\n        const merged = mergeCourses(courses);\n\n        window.shiguangBridge.showToast(`正在保存 ${merged.length} 门课程...`);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(merged, null, 2));\n        await saveTimeSlots(timeSlots);\n\n        window.shiguangBridge.showToast(`课程导入成功，共导入 ${merged.length} 门课程！`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(`导入失败：${getErrorMessage(error)}`);\n        console.error(\"JS: Import Error\", error);\n    }\n}\n\nrunImportFlow();\n","HEBAU":"// 河北农业大学 (urp.hebau.edu.cn) 拾光课程表适配脚本\n// 金智教务 jwapp/sys/wdkb 模块，各接口均为 POST：\n//   学期列表 /jwapp/sys/wdkb/modules/jshkcb/xnxqcx.do      body: *order=-DM\n//   校历     /jwapp/sys/wdkb/modules/xskcb/cxxljc.do        body: XN=&XQ=\n//   课表     /jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do    body: XNXQDM=\n//   作息     /jwapp/sys/wdkb/modules/jshkcb/jc.do           body: 空\n// 周次用 SKZC 位图：第 i 位为 '1' 表示第 i+1 周有课\n\nasync function postForm(path, params) {\n    const response = await fetch(path, {\n        method: \"POST\",\n        credentials: \"include\",\n        headers: {\n            \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: new URLSearchParams(params).toString()\n    });\n    if (!response.ok) throw new Error(\"接口请求失败（HTTP \" + response.status + \"）\");\n    return response.json();\n}\n\n// 金智响应统一取 datas.<key>.rows\nfunction rowsOf(payload, key) {\n    const data = payload && payload.datas && payload.datas[key];\n    return data && Array.isArray(data.rows) ? data.rows : [];\n}\n\n// SKZC 位图 → 周次数组\nfunction parseWeeks(bitmap) {\n    const weeks = [];\n    const text = String(bitmap || \"\");\n    for (let i = 0; i < text.length; i++) {\n        if (text.charAt(i) === \"1\") weeks.push(i + 1);\n    }\n    return weeks;\n}\n\n// 学期列表没有「当前学期」标记，按日期推断作为默认选项：9月~次年1月为第一学期\nfunction inferYearTerm() {\n    const now = new Date();\n    const year = now.getFullYear();\n    const month = now.getMonth() + 1;\n    if (month >= 9) return year + \"-\" + (year + 1) + \"-1\";\n    if (month <= 1) return (year - 1) + \"-\" + year + \"-1\";\n    return (year - 1) + \"-\" + year + \"-2\";\n}\n\n// 每条课表行 = 一天的一段课，按「课程名+教师+星期+节次+教室」合并同键周次\nfunction parseCourses(tableRows) {\n    const map = new Map();\n    for (const row of tableRows) {\n        const name = String(row.KCM || \"\").trim();\n        const day = Number(row.SKXQ);\n        const startSection = Number(row.KSJC);\n        const endSection = Number(row.JSJC);\n        const weeks = parseWeeks(row.SKZC);\n        if (!name || day < 1 || day > 7 || !startSection || !endSection ||\n            startSection > endSection || weeks.length === 0) continue;\n\n        const teacher = String(row.SKJS || \"\").trim();\n        const position = String(row.JASMC || \"\").trim();\n        const key = [name, teacher, day, startSection, endSection, position].join(\"|\");\n        const holder = map.get(key);\n        if (holder) {\n            holder.weeks = Array.from(new Set([...holder.weeks, ...weeks])).sort((a, b) => a - b);\n        } else {\n            map.set(key, { name, teacher, position, day, startSection, endSection, weeks });\n        }\n    }\n    return Array.from(map.values()).sort((a, b) =>\n        a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name));\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\", \"导入前请确保您已在浏览器中成功登录河北农业大学教务系统\", \"好的，开始导入\");\n}\n\nasync function selectSemester(semesterRows, defaultTerm) {\n    const defaultIndex = semesterRows.findIndex(row => row.DM === defaultTerm);\n    const names = semesterRows.map(row => row.MC || row.DM);\n    const index = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify(names), defaultIndex === -1 ? 0 : defaultIndex);\n    if (index === null || index === -1) return null;\n    return semesterRows[index];\n}\n\n// 校历：开学日期与总周数（ZZC 为总周数，取不到退回 ZJXZC）\nasync function fetchSemesterConfig(term) {\n    try {\n        const payload = await postForm(\"/jwapp/sys/wdkb/modules/xskcb/cxxljc.do\",\n            { XN: term.XNDM, XQ: term.XQDM });\n        const row = rowsOf(payload, \"cxxljc\")[0];\n        if (!row) return null;\n        const beginDate = String(row.XQKSRQ || \"\").split(\" \")[0];\n        const totalWeeks = Number(row.ZZC) || Number(row.ZJXZC) || 0;\n        if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(beginDate) || !totalWeeks) return null;\n        return { semesterStartDate: beginDate, semesterTotalWeeks: totalWeeks };\n    } catch (e) { return null; }\n}\n\nasync function fetchTimeSlots() {\n    try {\n        const payload = await postForm(\"/jwapp/sys/wdkb/modules/jshkcb/jc.do\", {});\n        return rowsOf(payload, \"jc\").map(row => ({\n            number: row.DM,\n            startTime: row.KSSJ,\n            endTime: row.JSSJ\n        }));\n    } catch (e) { return []; }\n}\n\nasync function saveCourses(courses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        return true;\n    } catch (e) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + e.message);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    if (!await promptUserToStart()) { window.shiguangBridge.showToast(\"用户取消了导入。\"); return; }\n\n    try {\n        const semesterRows = rowsOf(\n            await postForm(\"/jwapp/sys/wdkb/modules/jshkcb/xnxqcx.do\", { \"*order\": \"-DM\" }),\n            \"xnxqcx\"\n        ).filter(row => row && row.DM);\n        if (semesterRows.length === 0) throw new Error(\"未获取到学期列表。\");\n\n        const term = await selectSemester(semesterRows, inferYearTerm());\n        if (!term) { window.shiguangBridge.showToast(\"未选择学期，导入终止。\"); return; }\n\n        window.shiguangBridge.showToast(\"正在请求课表数据...\");\n        const [tablePayload, config, timeSlots] = await Promise.all([\n            postForm(\"/jwapp/sys/wdkb/modules/xskcb/cxxszhxqkb.do\", { XNXQDM: term.DM }),\n            fetchSemesterConfig(term),\n            fetchTimeSlots()\n        ]);\n\n        const courses = parseCourses(rowsOf(tablePayload, \"cxxszhxqkb\"));\n        if (courses.length === 0) throw new Error(\"未找到课程数据，请确认所选学期是否正确。\");\n        if (!await saveCourses(courses)) return;\n\n        if (config) {\n            try { await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config)); } catch (e) {}\n        }\n        if (timeSlots.length > 0) {\n            try { await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots)); } catch (e) {}\n        }\n\n        window.shiguangBridge.showToast(\"课程导入成功，共导入 \" + courses.length + \" 门课程！\");\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (e) {\n        window.shiguangBridge.showToast(\"导入失败：\" + e.message);\n        console.error(\"JS: Import Error\", e);\n    }\n}\n\nrunImportFlow();","HBGUHX":"// 河北地质大学华信学院强智教务 (61.182.88.214:8090) 拾光课程表适配脚本\n// 本校 25 届开发者适配，无法覆盖所有边界情况\n// 出现问题请联系 4831884790@qq.com 或提交 pr，pr 更加快速\n\nconst BASE_URL = \"http://61.182.88.214:8090\";\n\n/**\n * 带错误检查的 fetch，返回响应文本\n */\nasync function fetchText(url, options = {}) {\n    const response = await fetch(url, { credentials: \"include\", ...options });\n    if (!response.ok) {\n        throw new Error(`HTTP error! status: ${response.status}`);\n    }\n    return response.text();\n}\n\n/**\n * 解析周次字符串为数组\n * 支持 \"1-17\"、\"1-17(周)\"、\"(单周)\"/\"(双周)\" 标记（按段生效）、中英文逗号与顿号分隔\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n\n    // 移除节次信息（防御性），保留周次段\n    const pureWeekData = weekStr.replace(/\\[.*?节\\]/g, '').trim();\n    if (!pureWeekData) return weeks;\n\n    // 分割并处理每个段\n    const segments = pureWeekData.split(/[,，、]/);\n    segments.forEach(seg => {\n        seg = seg.trim();\n        if (!seg) return;\n\n        // 检测本段的单双周标记（如 \"1-17(单周)\"、\"6(双)\"），需在剥离标记前记录\n        const onlyOdd = /单/.test(seg);\n        const onlyEven = /双/.test(seg);\n        seg = seg.replace(/单|双|周|\\(.*?\\)/g, '').trim();\n        if (!seg) return;\n\n        if (seg.includes('-')) {\n            const [start, end] = seg.split('-').map(Number);\n            if (!isNaN(start) && !isNaN(end)) {\n                for (let i = start; i <= end; i++) {\n                    if (onlyOdd && i % 2 === 0) continue;\n                    if (onlyEven && i % 2 === 1) continue;\n                    weeks.push(i);\n                }\n            }\n        } else {\n            const w = parseInt(seg, 10);\n            if (!isNaN(w)) {\n                if (onlyOdd && w % 2 === 0) return;\n                if (onlyEven && w % 2 === 1) return;\n                weeks.push(w);\n            }\n        }\n    });\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 合并连续节次的相同课程\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (courses.length <= 1) return courses;\n\n    // 排序以便合并\n    courses.sort((a, b) => {\n        if (a.name !== b.name) return a.name.localeCompare(b.name);\n        if (a.day !== b.day) return a.day - b.day;\n        if (a.startSection !== b.startSection) return a.startSection - b.startSection;\n        if (a.teacher !== b.teacher) return a.teacher.localeCompare(b.teacher);\n        if (a.position !== b.position) return a.position.localeCompare(b.position);\n        return a.weeks.join(',').localeCompare(b.weeks.join(','));\n    });\n\n    const merged = [];\n    let current = courses[0];\n\n    for (let i = 1; i < courses.length; i++) {\n        const next = courses[i];\n\n        // 判断是否为同一门课程\n        const isSameCourse =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        // 判断节次是否连续\n        const isContinuous = (current.endSection + 1 === next.startSection);\n\n        if (isSameCourse && isContinuous) {\n            // 合并连续节次\n            current.endSection = next.endSection;\n        } else if (!(isSameCourse && current.startSection === next.startSection && current.endSection === next.endSection)) {\n            // 完全重复的条目直接丢弃，其余推入结果\n            merged.push(current);\n            current = next;\n        }\n    }\n    merged.push(current);\n    return merged;\n}\n\n/**\n * 从课程块中提取周次和节次\n * 匹配 \"1-17(周)[01-02节]\" / \"1-17(周)[01-02 节]\" 格式，空格均可选\n */\nfunction extractWeekAndSection(weekFull) {\n    const match = weekFull.match(/(.+?)\\(周\\)\\s*\\[\\s*(\\d+)-(\\d+)\\s*节\\s*\\]/);\n    if (match) {\n        return {\n            weekStr: match[1],\n            startSection: parseInt(match[2], 10),\n            endSection: parseInt(match[3], 10)\n        };\n    }\n    // 兜底：只匹配周次范围，节次按 1-2 节假设\n    const altMatch = weekFull.match(/(\\d+)-(\\d+)/);\n    if (altMatch) {\n        return {\n            weekStr: altMatch[0],\n            startSection: 1,\n            endSection: 2\n        };\n    }\n    return null;\n}\n\n/**\n * 将 HTML 源码解析为课程模型\n */\nfunction parseTimetableToModel(htmlString) {\n    const doc = new DOMParser().parseFromString(htmlString, \"text/html\");\n    const timetable = doc.getElementById('kbtable');\n    if (!timetable) {\n        return [];\n    }\n\n    const rawCourses = [];\n    // 行 = 大节，列 = 星期；只处理含 td 的行（跳过表头），备注/中午行会因缺少周次标记被自然过滤\n    const rows = Array.from(timetable.querySelectorAll('tr')).filter(r => r.querySelector('td'));\n\n    rows.forEach((row) => {\n        const cells = row.querySelectorAll('td');\n\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1; // 星期几（1-7）\n\n            // 获取所有课程详情 div，包括所有状态的\n            const detailDivs = Array.from(cell.querySelectorAll('div.kbcontent'));\n\n            detailDivs.forEach((detailDiv) => {\n                const rawHtml = detailDiv.innerHTML.trim();\n                const innerText = detailDiv.innerText.trim();\n\n                if (!rawHtml || rawHtml === \"&nbsp;\" || innerText.length < 2) return;\n\n                // 分割同一个格子内的多门课程（10 个以上连字符即为分隔线）\n                const blocks = rawHtml.split(/-{10,}/);\n\n                blocks.forEach((block) => {\n                    if (!block.trim()) return;\n\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    // 1. 提取课程名（跳过开头的空行，处理 <br> 开头的分隔块）\n                    // 注意：innerHTML 中的 &nbsp; 等实体不会自动解码，需手动处理\n                    let name = \"\";\n                    const htmlLines = tempDiv.innerHTML.split('<br>');\n                    for (const line of htmlLines) {\n                        const text = line\n                            .replace(/<[^>]*>/g, '')\n                            .replace(/&nbsp;/gi, ' ')\n                            .replace(/\\s+/g, ' ')\n                            .trim();\n                        if (text) {\n                            name = text;\n                            break;\n                        }\n                    }\n\n                    if (!name) return;\n\n                    // 2. 提取周次和节次信息\n                    const weekFont = tempDiv.querySelector('font[title=\"周次(节次)\"]');\n                    const weekFull = weekFont?.innerText || \"\";\n                    const weekSection = extractWeekAndSection(weekFull);\n                    if (!weekSection) return;\n\n                    // 3. 提取教师信息\n                    const teacher = tempDiv.querySelector('font[title=\"老师\"]')?.innerText.trim() || \"未知教师\";\n\n                    // 4. 提取教室地点\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText.trim() || \"未知地点\";\n\n                    rawCourses.push({\n                        \"name\": name,\n                        \"teacher\": teacher,\n                        \"weeks\": parseWeeks(weekSection.weekStr),\n                        \"position\": position,\n                        \"day\": day,\n                        \"startSection\": weekSection.startSection,\n                        \"endSection\": weekSection.endSection\n                    });\n                });\n            });\n        });\n    });\n\n    return mergeAndDistinctCourses(rawCourses);\n}\n\n/**\n * 从网页中提取学期选项列表\n */\nfunction extractSemesterOptions(htmlString) {\n    const doc = new DOMParser().parseFromString(htmlString, \"text/html\");\n    const semesterSelect = doc.getElementById('xnxq01id');\n    if (!semesterSelect) {\n        return [];\n    }\n\n    return Array.from(semesterSelect.querySelectorAll('option'))\n        .filter(opt => opt.value)\n        .map(opt => ({\n            value: opt.value,\n            text: opt.text\n        }));\n}\n\n/**\n * 时间字符串加分钟数，\"08:30\" + 45 → \"09:15\"\n */\nfunction addMinutes(hhmm, minutes) {\n    const parts = hhmm.split(':').map(Number);\n    const total = parts[0] * 60 + parts[1] + minutes;\n    const h = Math.floor(total / 60) % 24;\n    const m = total % 60;\n    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;\n}\n\n/**\n * 从网页中提取作息时间\n * 课表页 #kbtable 中每个大节行头 th 形如 \"第一大节\\n08:30-10:05\"\n * 拆分规则：第 1 小节 = 开始 ~ 开始+45 分钟；第 2 小节 = 开始+55 分钟 ~ 大节结束\n */\nfunction extractTimeSlots(htmlString) {\n    const doc = new DOMParser().parseFromString(htmlString, \"text/html\");\n    const timetable = doc.getElementById('kbtable');\n    if (!timetable) return null;\n\n    const timeSlots = [];\n    const rows = Array.from(timetable.querySelectorAll('tr'));\n\n    rows.forEach((row) => {\n        const th = row.querySelector('th');\n        if (!th) return;\n\n        // 提取时间范围，如 \"08:30-10:05\"\n        const timeText = th.innerText.trim();\n        const timeMatch = timeText.match(/(\\d{2}:\\d{2})-(\\d{2}:\\d{2})/);\n        if (!timeMatch) return;\n\n        const startTime = timeMatch[1];\n        const endTime = timeMatch[2];\n\n        // 判断是否是有效的时间段（排除\"中午\"等）\n        const sectionName = timeText.split('\\n')[0].trim();\n        if (sectionName === '中午') return;\n\n        // 为每个大节创建两个小节（时间加法，勿用分钟硬替换）\n        timeSlots.push(\n            {\n                number: timeSlots.length + 1,\n                startTime: startTime,\n                endTime: addMinutes(startTime, 45)\n            },\n            {\n                number: timeSlots.length + 2,\n                startTime: addMinutes(startTime, 55),\n                endTime: endTime\n            }\n        );\n    });\n\n    return timeSlots.length > 0 ? timeSlots : null;\n}\n\n/**\n * 根据学期字符串估算学期第一周周一日期\n * 学期格式如 \"2025-2026-2\"\n * 春季学期：3月第二个周一，秋季学期：9月1日所在周的周一\n * 仅作兜底，优先使用教学周历解析出的真实日期\n */\nfunction getSemesterStartMonday(semesterId) {\n    if (!semesterId) return null;\n    const parts = semesterId.split('-');\n    if (parts.length < 3) return null;\n    const year1 = parseInt(parts[0], 10);\n    const year2 = parseInt(parts[1], 10);\n    const semester = parseInt(parts[2], 10);\n    if (isNaN(year1) || isNaN(year2) || isNaN(semester)) return null;\n\n    // 估算学期开始日期\n    let startDate;\n    if (semester === 1) {\n        startDate = new Date(year1, 8, 1); // 秋季学期：约9月1日\n    } else {\n        // 春季学期：3月第二个周一\n        const march1Day = new Date(year2, 2, 1).getDay();\n        const firstMondayDate = march1Day === 1 ? 1 : march1Day === 0 ? 2 : 9 - march1Day;\n        startDate = new Date(year2, 2, firstMondayDate + 7); // 第二个周一\n    }\n\n    // 找到学期开始日期所在周的周一\n    const startDay = startDate.getDay(); // 0=周日\n    const monday = new Date(startDate);\n    monday.setDate(startDate.getDate() + (startDay === 0 ? -6 : 1 - startDay));\n    return monday;\n}\n\n/**\n * 从教学周历页面 HTML 中解析第一周周一的日期\n * 表格结构：<tr height='28'><td>1</td><td title='2026年08月31'>31</td>...\n * 第 1 个 td 为周次，第 2 个 td 为星期一，title 为完整日期\n */\nfunction extractWeekCalendarStartDate(htmlString) {\n    const doc = new DOMParser().parseFromString(htmlString, \"text/html\");\n    const timetable = doc.getElementById('kbtable');\n    if (!timetable) return null;\n\n    const rows = Array.from(timetable.querySelectorAll('tr'));\n    for (const row of rows) {\n        const tds = row.querySelectorAll('td');\n        if (tds.length < 2) continue;\n        if (tds[0].innerText.trim() !== '1') continue; // 只看第 1 周\n\n        const title = tds[1].getAttribute('title') || '';\n        const match = title.match(/(\\d{4})年(\\d{1,2})月(\\d{1,2})/);\n        if (match) {\n            const date = new Date(\n                parseInt(match[1], 10),\n                parseInt(match[2], 10) - 1,\n                parseInt(match[3], 10)\n            );\n            if (!isNaN(date.getTime())) return date;\n        }\n        return null; // 找到第 1 周行但解析失败，不再继续扫\n    }\n    return null;\n}\n\n/**\n * 请求教学周历页面，获取准确的学期第一周周一日期\n * 失败时返回 null，由调用方回退到估算\n */\nasync function fetchSemesterStartMonday(semesterId) {\n    try {\n        // 注意：必须使用完整 URL 或前导 \"/\"，否则相对路径会被教务框架错误拼接\n        const html = await fetchText(`${BASE_URL}/jsxsd/jxzl/jxzl_query`, {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: `xnxq01id=${encodeURIComponent(semesterId)}`\n        });\n        return extractWeekCalendarStartDate(html);\n    } catch (error) {\n        console.error('获取教学周历失败，将回退到估算学期起点：', error);\n        return null;\n    }\n}\n\n/**\n * 格式化日期为 YYYY-MM-DD\n */\nfunction formatDate(date) {\n    const y = date.getFullYear();\n    const m = String(date.getMonth() + 1).padStart(2, '0');\n    const d = String(date.getDate()).padStart(2, '0');\n    return `${y}-${m}-${d}`;\n}\n\n/**\n * 根据学期字符串计算当前周数\n * 优先使用从教学周历解析到的真实起始日期，否则回退到估算\n */\nfunction calculateCurrentWeek(semesterId, startMondayOverride) {\n    const monday = startMondayOverride || getSemesterStartMonday(semesterId);\n    if (!monday) return 1;\n\n    const now = new Date();\n    const diffMs = now.getTime() - monday.getTime();\n    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));\n    return Math.max(1, Math.floor(diffDays / 7) + 1);\n}\n\n/**\n * 显示欢迎提示\n */\nasync function showWelcomeAlert() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"导入提示\",\n        \"请先进入学期理论课表页面，首页周课表无法导入\",\n        \"开始导入\"\n    );\n}\n\n/**\n * 获取用户选择的学期参数\n */\nasync function getSemesterParamsFromUser(semesterOptions) {\n    if (!semesterOptions || semesterOptions.length === 0) {\n        window.shiguangBridge.showToast(\"未获取到学期列表\");\n        return null;\n    }\n\n    // 直接显示所有学期选项，让用户一次性选择\n    const semesterLabels = semesterOptions.map(opt => opt.text);\n\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterLabels),\n        0 // 默认选择第一个（最新学期）\n    );\n\n    if (semesterIndex == null) return null; // 兼容 null / undefined（用户取消）\n\n    return semesterOptions[semesterIndex].value;\n}\n\n/**\n * 请求课表页面 HTML\n */\nasync function fetchCourseHtml() {\n    // 浏览器禁止通过 fetch 设置 User-Agent，无需伪装请求头，Cookie 跟随即可\n    return fetchText(`${BASE_URL}/jsxsd/xskb/xskb_list.do`);\n}\n\n/**\n * 根据选择的学期请求课表页面 HTML\n */\nasync function fetchCourseHtmlBySemester(semesterId) {\n    return fetchText(`${BASE_URL}/jsxsd/xskb/xskb_list.do`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n        body: `cj0701id=&zc=&demo=&xnxq01id=${encodeURIComponent(semesterId)}`\n    });\n}\n\n/**\n * 保存课程数据到 App\n */\nasync function saveCourseDataToApp(courses, timeSlots, semesterId, startMondayOverride) {\n    // 计算学期开始日期和当前周数（优先使用教学周历解析出的真实日期）\n    const startMonday = startMondayOverride || getSemesterStartMonday(semesterId);\n    const currentWeek = calculateCurrentWeek(semesterId, startMondayOverride);\n\n    // 学期总周数：从课程数据中的最大周次推导，最小 20 周\n    const maxCourseWeek = courses.reduce((max, c) => Math.max(max, ...(c.weeks || [])), 0);\n\n    // 保存学期配置\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n        \"semesterStartDate\": startMonday ? formatDate(startMonday) : null,\n        \"currentWeek\": currentWeek,\n        \"semesterTotalWeeks\": Math.max(20, maxCourseWeek),\n        \"firstDayOfWeek\": 1\n    }));\n\n    // 保存作息时间（从网页提取）\n    if (timeSlots && timeSlots.length > 0) {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    }\n\n    // 保存课程数据\n    return await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n}\n\n/**\n * 主流程控制\n */\nasync function runImportFlow() {\n    try {\n        // 1. 显示欢迎提示\n        const start = await showWelcomeAlert();\n        if (!start) return;\n\n        // 2. 获取课表 HTML（包含学期选项和作息时间）\n        const html = await fetchCourseHtml();\n\n        // 3. 从网页中提取学期选项\n        const semesterOptions = extractSemesterOptions(html);\n\n        // 4. 从网页中提取作息时间，失败则回退到内置默认值（按本校实际作息）\n        const timeSlots = extractTimeSlots(html) || [\n            { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n            { number: 2, startTime: \"09:25\", endTime: \"10:05\" },\n            { number: 3, startTime: \"10:15\", endTime: \"11:00\" },\n            { number: 4, startTime: \"11:10\", endTime: \"11:50\" },\n            { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n            { number: 6, startTime: \"15:25\", endTime: \"16:05\" },\n            { number: 7, startTime: \"16:15\", endTime: \"17:00\" },\n            { number: 8, startTime: \"17:10\", endTime: \"17:50\" },\n            { number: 9, startTime: \"19:00\", endTime: \"19:45\" },\n            { number: 10, startTime: \"19:55\", endTime: \"20:40\" }\n        ];\n\n        // 5. 让用户选择学期\n        const semesterId = await getSemesterParamsFromUser(semesterOptions);\n        if (!semesterId) return;\n\n        // 6. 根据选择的学期重新请求课表数据\n        const courseHtml = await fetchCourseHtmlBySemester(semesterId);\n\n        // 7. 从教学周历获取准确的学期第一周周一日期（失败则自动回退到估算）\n        const realStartMonday = await fetchSemesterStartMonday(semesterId);\n\n        // 8. 解析课程数据\n        const finalCourses = parseTimetableToModel(courseHtml);\n\n        if (finalCourses.length === 0) {\n            // 兜底：直接从初始页面解析，成功不额外提示，仅在失败时提示\n            const initialCourses = parseTimetableToModel(html);\n            if (initialCourses.length > 0) {\n                await saveCourseDataToApp(initialCourses, timeSlots, semesterId, realStartMonday);\n                window.shiguangBridge.notifyTaskCompletion();\n            } else {\n                window.shiguangBridge.showToast(\"未获取到课程，请确认已登录且所选学期有课\");\n            }\n            return;\n        }\n\n        // 9. 保存课程数据\n        await saveCourseDataToApp(finalCourses, timeSlots, semesterId, realStartMonday);\n\n        const currentWeek = calculateCurrentWeek(semesterId, realStartMonday);\n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程（当前第 ${currentWeek} 周）`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        console.error('导入异常：', error);\n        window.shiguangBridge.showToast(\"导入异常：\" + error.message);\n    }\n}\n\n// 启动执行\nrunImportFlow();\n","HUEB":"// 湖北工程学院(vpn.hueb.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 出现问题请提issues或者提交pr更改\n\n/**\n * 节次与周次合并去重函数\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\n/**\n * 解析周次字符串，处理单双周和周次范围\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/);\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) {\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) {\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n\n        if (processed) {\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue;\n                if (isDouble && w % 2 !== 0) continue;\n                weeks.push(w);\n            }\n        }\n    }\n\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据\n */\nfunction parseJsonData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        return [];\n    }\n\n    const rawCourseList = jsonData.kbList;\n    const initialCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc ||\n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        if (weeksArray.length === 0) {\n            continue;\n        }\n\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]);\n        const day = Number(rawCourse.xqj);\n\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) ||\n            day < 1 || day > 7 || startSection > endSection) {\n            continue;\n        }\n\n        initialCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeksArray\n        });\n    }\n\n    return mergeAndDistinctCourses(initialCourseList);\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\n/**\n * 从教务系统获取学年学期选项\n */\nasync function fetchAcademicOptions() {\n    const url = \"https://202-206-194-100.vpn.hueb.edu.cn:8118/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151\";\n\n    try {\n        const response = await fetch(url, {\n            method: \"GET\",\n            credentials: \"include\"\n        });\n\n        if (!response.ok) return null;\n\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlText, \"text/html\");\n\n        const allYearOptions = Array.from(doc.querySelectorAll(\"#xnm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        const semesterOptions = Array.from(doc.querySelectorAll(\"#xqm option\"))\n            .filter(opt => opt.value !== \"\")\n            .map(opt => ({\n                value: opt.value,\n                text: opt.textContent.trim(),\n                selected: opt.selected\n            }));\n\n        if (allYearOptions.length === 0 || semesterOptions.length === 0) {\n            return null;\n        }\n\n        const selectedIndex = allYearOptions.findIndex(opt => opt.selected);\n\n        if (selectedIndex === -1) {\n            return {\n                yearOptions: allYearOptions.slice(0, 5),\n                semesterOptions,\n                defaultYearIndex: 0,\n                defaultSemesterIndex: semesterOptions.findIndex(opt => opt.selected) !== -1\n                    ? semesterOptions.findIndex(opt => opt.selected)\n                    : 0\n            };\n        }\n\n        const start = Math.max(0, selectedIndex - 2);\n        const end = Math.min(allYearOptions.length, selectedIndex + 3);\n        const yearOptions = allYearOptions.slice(start, end);\n        const newDefaultIndex = selectedIndex - start;\n        const defaultSemesterIndex = semesterOptions.findIndex(opt => opt.selected);\n\n        return {\n            yearOptions,\n            semesterOptions,\n            defaultYearIndex: newDefaultIndex,\n            defaultSemesterIndex: defaultSemesterIndex !== -1 ? defaultSemesterIndex : 0\n        };\n    } catch (e) {\n        return null;\n    }\n}\n\n/**\n * 提示用户选择学年和学期\n */\nasync function selectAcademicYearAndSemester() {\n    const optionsData = await fetchAcademicOptions();\n\n    if (!optionsData) {\n        window.shiguangBridge.showToast(\"从教务系统读取学年学期失败，请确保登录状态。\");\n        return null;\n    }\n\n    const { yearOptions, semesterOptions, defaultYearIndex, defaultSemesterIndex } = optionsData;\n\n    const yearTexts = yearOptions.map(item => item.text);\n    const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年\",\n        JSON.stringify(yearTexts),\n        defaultYearIndex\n    );\n\n    if (yearIndex === null || yearIndex === -1) return null;\n    const selectedYearCode = yearOptions[yearIndex].value;\n\n    const semesterTexts = semesterOptions.map(item => item.text);\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesterTexts),\n        defaultSemesterIndex\n    );\n\n    if (semesterIndex === null || semesterIndex === -1) return null;\n    const selectedSemesterCode = semesterOptions[semesterIndex].value;\n\n    return {\n        academicYear: selectedYearCode,\n        semesterCode: selectedSemesterCode\n    };\n}\n\n/**\n * 获取学期开学日期\n */\nasync function fetchSemesterStartDate(academicYear, semesterCode) {\n    const url = \"https://202-206-194-100.vpn.hueb.edu.cn:8118/jwglxt/kbcx/xskbcxZccx_cxZcByXnxq.html?gnmkdm=N2154\";\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}`;\n\n    try {\n        const response = await fetch(url, {\n            method: \"POST\",\n            headers: {\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        });\n\n        if (response.ok) {\n            const json = await response.json();\n            if (Array.isArray(json) && json.length > 0) {\n                const firstWeekObj = json.find(item => String(item.zs) === \"1\" || String(item.zsmc) === \"1\") || json[0];\n\n                if (firstWeekObj.rq) {\n                    const startDateStr = firstWeekObj.rq.split('/')[0];\n                    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(startDateStr)) {\n                        return startDateStr;\n                    }\n                }\n\n                if (firstWeekObj.zcrq) {\n                    const match = firstWeekObj.zcrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n\n                if (firstWeekObj.ksrq) {\n                    const match = firstWeekObj.ksrq.match(/(\\d{4}-\\d{2}-\\d{2})/);\n                    if (match) return match[1];\n                }\n            }\n        }\n    } catch (e) {\n        // 获取失败不影响主流程\n    }\n    return null;\n}\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterCode) {\n    const requestBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`;\n    const targetUrl = \"https://202-206-194-100.vpn.hueb.edu.cn:8118/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n\n    const [courseResponse, semesterStartDate] = await Promise.all([\n        fetch(targetUrl, {\n            method: \"POST\",\n            headers: {\n                \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\"\n            },\n            body: requestBody,\n            credentials: \"include\"\n        }),\n        fetchSemesterStartDate(academicYear, semesterCode)\n    ]);\n\n    try {\n        if (courseResponse.ok) {\n            const jsonText = await courseResponse.text();\n            const jsonData = JSON.parse(jsonText);\n            if (jsonData && jsonData.kbList) {\n                const parsedCourses = parseJsonData(jsonData);\n                if (parsedCourses.length > 0) {\n                    return {\n                        courses: parsedCourses,\n                        config: {\n                            semesterStartDate: semesterStartDate,\n                            semesterTotalWeeks: 20\n                        }\n                    };\n                }\n            }\n        }\n    } catch (e) {\n        // 请求失败\n    }\n\n    window.shiguangBridge.showToast(\"未能获取课表数据，请检查网络环境或登录状态。\");\n    return null;\n}\n\nasync function saveCourses(parsedCourses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        return false;\n    }\n}\n\nconst TimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:45\", endTime: \"09:30\" },\n    { number: 3, startTime: \"09:45\", endTime: \"10:30\" },\n    { number: 4, startTime: \"10:30\", endTime: \"11:15\" },\n    { number: 5, startTime: \"11:25\", endTime: \"12:10\" },\n    { number: 6, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 7, startTime: \"14:45\", endTime: \"15:30\" },\n    { number: 8, startTime: \"15:45\", endTime: \"16:30\" },\n    { number: 9, startTime: \"16:30\", endTime: \"17:15\" },\n    { number: 10, startTime: \"17:25\", endTime: \"18:10\" },\n    { number: 11, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 12, startTime: \"19:45\", endTime: \"20:30\" },\n    { number: 13, startTime: \"20:40\", endTime: \"21:25\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    if (timeSlots.length === 0) return;\n    try { await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots)); } catch (e) {}\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    const selection = await selectAcademicYearAndSemester();\n    if (!selection) {\n        window.shiguangBridge.showToast(\"未选择学年学期，导入流程终止。\");\n        return;\n    }\n\n    const { academicYear, semesterCode } = selection;\n\n    const result = await fetchAndParseCourses(academicYear, semesterCode);\n    if (result === null) {\n        return;\n    }\n\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        let configMsg = \"课表配置更新成功！\";\n        if (config.semesterStartDate) {\n            configMsg += ` 开学日期：${config.semesterStartDate}`;\n        }\n        window.shiguangBridge.showToast(configMsg);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n    }\n\n    await importPresetTimeSlots(TimeSlots);\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","HIIT_01":"(function () {\n    function showToast(message) {\n        if (typeof window.shiguangBridge !== \"undefined\" && window.shiguangBridge.showToast) {\n            window.shiguangBridge.showToast(String(message || \"\"));\n        } else {\n            console.log(message);\n        }\n    }\n\n    function getBaseOrigin() {\n        return window.location.origin;\n    }\n\n    async function requestText(url, options) {\n        const response = await fetch(url, {\n            credentials: \"include\",\n            ...(options || {})\n        });\n\n        if (!response.ok) {\n            throw new Error(`请求失败（${response.status}）：${url}`);\n        }\n\n        return response.text();\n    }\n\n    function parseEntryParams(entryHtml) {\n        const html = String(entryHtml || \"\");\n        const idsMatch = html.match(/bg\\.form\\.addInput\\(form,\"ids\",\"(\\d+)\"\\)/);\n        const tagIdMatch = html.match(/id=\"(semesterBar\\d+Semester)\"/);\n\n        return {\n            studentId: idsMatch ? idsMatch[1] : \"\",\n            tagId: tagIdMatch ? tagIdMatch[1] : \"\"\n        };\n    }\n\n    function formatSemesterName(schoolYear, termName) {\n        const suffixMap = {\n            \"1\": \"第一学期\",\n            \"2\": \"第二学期\"\n        };\n        const suffix = suffixMap[String(termName || \"\").trim()] || `第${String(termName || \"\").trim()}学期`;\n        return `${String(schoolYear || \"\").trim()}学年${suffix}`;\n    }\n\n    function parseSemesterResponse(rawText) {\n        let data;\n        try {\n            data = Function(`return (${String(rawText || \"\").trim()});`)();\n        } catch (_) {\n            throw new Error(\"学期数据解析失败。\");\n        }\n\n        const semesters = [];\n        if (!data || !data.semesters || typeof data.semesters !== \"object\") {\n            return semesters;\n        }\n\n        Object.keys(data.semesters).forEach((key) => {\n            const list = data.semesters[key];\n            if (!Array.isArray(list)) return;\n\n            list.forEach((semester) => {\n                if (!semester || !semester.id) return;\n                const schoolYear = String(semester.schoolYear || \"\").trim();\n                const termName = String(semester.name || \"\").trim();\n                semesters.push({\n                    id: String(semester.id),\n                    schoolYear,\n                    termName,\n                    name: formatSemesterName(schoolYear, termName)\n                });\n            });\n        });\n\n        return semesters;\n    }\n\n    function parseStudentProfile(htmlText) {\n        const html = String(htmlText || \"\");\n        const allDates = html.match(/\\d{4}-\\d{2}-\\d{2}/g) || [];\n        const enrollmentDate = allDates[0] || \"\";\n\n        return {\n            enrollmentDate,\n            enrollmentYear: enrollmentDate ? Number(enrollmentDate.slice(0, 4)) : 0\n        };\n    }\n\n    function filterSemestersByEnrollmentYear(semesters, enrollmentYear) {\n        if (!enrollmentYear) return semesters;\n\n        const filtered = semesters.filter((semester) => {\n            const startYear = Number(String(semester.schoolYear || \"\").split(\"-\")[0]);\n            return startYear >= enrollmentYear;\n        });\n\n        return filtered.length ? filtered : semesters;\n    }\n\n    function normalizeEnglishDate(dateText) {\n        const parsed = new Date(String(dateText || \"\"));\n        if (Number.isNaN(parsed.getTime())) return \"\";\n        const year = parsed.getFullYear();\n        const month = String(parsed.getMonth() + 1).padStart(2, \"0\");\n        const day = String(parsed.getDate()).padStart(2, \"0\");\n        return `${year}-${month}-${day}`;\n    }\n\n    function parseCalendarInfo(htmlText) {\n        const html = String(htmlText || \"\");\n        const match = html.match(/([A-Za-z]{3}\\s+\\d{1,2},\\s+\\d{4})~([A-Za-z]{3}\\s+\\d{1,2},\\s+\\d{4})\\s*\\((\\d+)\\)/);\n        if (!match) {\n            return {\n                semesterStartDate: \"\",\n                semesterTotalWeeks: 0\n            };\n        }\n\n        return {\n            semesterStartDate: normalizeEnglishDate(match[1]),\n            semesterTotalWeeks: Number(match[3] || 0)\n        };\n    }\n\n    function chineseSectionToNumber(text) {\n        const mapping = {\n            \"一\": 1,\n            \"二\": 2,\n            \"三\": 3,\n            \"四\": 4,\n            \"五\": 5,\n            \"六\": 6,\n            \"七\": 7,\n            \"八\": 8,\n            \"九\": 9,\n            \"十\": 10,\n            \"十一\": 11\n        };\n        return mapping[String(text || \"\").trim()] || 0;\n    }\n\n    function parseTimeSlotsFromHtml(htmlText) {\n        const doc = new DOMParser().parseFromString(String(htmlText || \"\"), \"text/html\");\n        const slots = [];\n\n        doc.querySelectorAll(\"#manualArrangeCourseTable tbody tr\").forEach((row) => {\n            const cells = Array.from(row.querySelectorAll(\"td\"));\n            const sectionCell = cells.find((cell) => /第.+节/.test(cell.textContent || \"\"));\n            if (!sectionCell) return;\n\n            const text = sectionCell.textContent.replace(/\\s+/g, \" \").trim();\n            const match = text.match(/第([一二三四五六七八九十十一]+)节\\s*(\\d{2}:\\d{2})\\s*-\\s*(\\d{2}:\\d{2})/);\n            if (!match) return;\n\n            const sectionNumber = chineseSectionToNumber(match[1]);\n            if (!sectionNumber) return;\n\n            slots.push({\n                number: sectionNumber,\n                startTime: match[2],\n                endTime: match[3]\n            });\n        });\n\n        return slots.sort((a, b) => a.number - b.number);\n    }\n\n    function splitJsArgs(argsText) {\n        const args = [];\n        let current = \"\";\n        let quote = \"\";\n        let escaped = false;\n\n        for (let i = 0; i < argsText.length; i++) {\n            const ch = argsText[i];\n\n            if (escaped) {\n                current += ch;\n                escaped = false;\n                continue;\n            }\n\n            if (ch === \"\\\\\") {\n                current += ch;\n                escaped = true;\n                continue;\n            }\n\n            if (quote) {\n                current += ch;\n                if (ch === quote) quote = \"\";\n                continue;\n            }\n\n            if (ch === \"'\" || ch === \"\\\"\") {\n                current += ch;\n                quote = ch;\n                continue;\n            }\n\n            if (ch === \",\") {\n                args.push(current.trim());\n                current = \"\";\n                continue;\n            }\n\n            current += ch;\n        }\n\n        if (current.trim()) {\n            args.push(current.trim());\n        }\n\n        return args;\n    }\n\n    function unquoteJsLiteral(token) {\n        const text = String(token || \"\").trim();\n        if (!text || text === \"null\" || text === \"undefined\") return \"\";\n\n        if ((text.startsWith(\"\\\"\") && text.endsWith(\"\\\"\")) || (text.startsWith(\"'\") && text.endsWith(\"'\"))) {\n            const quote = text[0];\n            return text.slice(1, -1)\n                .replace(/\\\\\\\\/g, \"\\\\\")\n                .replace(new RegExp(`\\\\\\\\${quote}`, \"g\"), quote)\n                .replace(/\\\\n/g, \"\\n\")\n                .replace(/\\\\r/g, \"\\r\")\n                .replace(/\\\\t/g, \"\\t\");\n        }\n\n        return text;\n    }\n\n    function parseValidWeeksBitmap(bitmap) {\n        const weeks = [];\n        const text = String(bitmap || \"\");\n        for (let i = 0; i < text.length; i++) {\n            if (text[i] === \"1\" && i >= 1) {\n                weeks.push(i);\n            }\n        }\n        return weeks;\n    }\n\n    function normalizeWeeks(weeks) {\n        return Array.from(new Set((weeks || []).filter((week) => Number.isInteger(week) && week > 0))).sort((a, b) => a - b);\n    }\n\n    function cleanCourseName(name) {\n        return String(name || \"\")\n            .replace(/\\s*\\([^()]*\\)\\s*$/, \"\")\n            .trim();\n    }\n\n    function cleanPosition(position) {\n        return String(position || \"\")\n            .replace(/鹤壁工程技术学院/g, \"\")\n            .replace(/\\s+/g, \" \")\n            .trim();\n    }\n\n    function resolveTeachersForTaskActivityBlock(fullText, blockStartIndex) {\n        const start = Math.max(0, blockStartIndex - 2500);\n        const segment = fullText.slice(start, blockStartIndex);\n        const teachersRegex = /var\\s+teachers\\s*=\\s*\\[([^]*?)\\];/g;\n        let lastTeachersBlock = \"\";\n        let match;\n\n        while ((match = teachersRegex.exec(segment)) !== null) {\n            lastTeachersBlock = match[1] || \"\";\n        }\n\n        if (!lastTeachersBlock) return \"\";\n\n        const names = [];\n        const nameRegex = /name\\s*:\\s*(?:\"([^\"]*)\"|'([^']*)')/g;\n        let nameMatch;\n        while ((nameMatch = nameRegex.exec(lastTeachersBlock)) !== null) {\n            const name = (nameMatch[1] || nameMatch[2] || \"\").trim();\n            if (name) names.push(name);\n        }\n\n        return Array.from(new Set(names)).join(\",\");\n    }\n\n    function mergeContiguousSections(courses) {\n        const normalized = (courses || []).map((course) => ({\n            ...course,\n            weeks: normalizeWeeks(course.weeks)\n        }));\n\n        normalized.sort((a, b) => {\n            const keyA = `${a.name}|${a.teacher}|${a.position}|${a.day}|${a.weeks.join(\",\")}`;\n            const keyB = `${b.name}|${b.teacher}|${b.position}|${b.day}|${b.weeks.join(\",\")}`;\n            if (keyA < keyB) return -1;\n            if (keyA > keyB) return 1;\n            return a.startSection - b.startSection;\n        });\n\n        const merged = [];\n        normalized.forEach((course) => {\n            const previous = merged[merged.length - 1];\n            const canMerge = previous\n                && previous.name === course.name\n                && previous.teacher === course.teacher\n                && previous.position === course.position\n                && previous.day === course.day\n                && previous.weeks.join(\",\") === course.weeks.join(\",\")\n                && previous.endSection + 1 >= course.startSection;\n\n            if (canMerge) {\n                previous.endSection = Math.max(previous.endSection, course.endSection);\n            } else {\n                merged.push({ ...course });\n            }\n        });\n\n        return merged;\n    }\n\n    function parseCoursesFromTaskActivityScript(htmlText) {\n        const text = String(htmlText || \"\");\n        const unitCountMatch = text.match(/\\bvar\\s+unitCount\\s*=\\s*(\\d+)\\s*;/);\n        const unitCount = unitCountMatch ? Number(unitCountMatch[1]) : 0;\n        if (!unitCount) return [];\n\n        const courses = [];\n        const blockRegex = /activity\\s*=\\s*new\\s+TaskActivity\\(([^]*?)\\)\\s*;([\\s\\S]*?)(?=activity\\s*=\\s*new\\s+TaskActivity\\(|table\\d+\\.marshalTable|$)/g;\n        let match;\n\n        while ((match = blockRegex.exec(text)) !== null) {\n            const args = splitJsArgs(match[1] || \"\");\n            if (args.length < 7) continue;\n\n            let teacher = unquoteJsLiteral(args[1]);\n            if (/join\\s*\\(/.test(String(args[1] || \"\"))) {\n                teacher = resolveTeachersForTaskActivityBlock(text, match.index) || teacher;\n            }\n\n            const name = cleanCourseName(unquoteJsLiteral(args[3]));\n            const position = cleanPosition(unquoteJsLiteral(args[5]));\n            const weeks = normalizeWeeks(parseValidWeeksBitmap(unquoteJsLiteral(args[6])));\n            if (!name) continue;\n            const indexBlock = match[2] || \"\";\n            const indexRegex = /index\\s*=\\s*(?:(\\d+)\\s*\\*\\s*unitCount\\s*\\+\\s*(\\d+)|(\\d+))\\s*;\\s*table\\d+\\.activities\\[index\\]/g;\n            let indexMatch;\n\n            while ((indexMatch = indexRegex.exec(indexBlock)) !== null) {\n                let linearIndex = -1;\n                if (indexMatch[1] != null && indexMatch[2] != null) {\n                    linearIndex = Number(indexMatch[1]) * unitCount + Number(indexMatch[2]);\n                } else if (indexMatch[3] != null) {\n                    linearIndex = Number(indexMatch[3]);\n                }\n                if (linearIndex < 0) continue;\n\n                const day = Math.floor(linearIndex / unitCount) + 1;\n                const section = (linearIndex % unitCount) + 1;\n                if (day < 1 || day > 7) continue;\n\n                courses.push({\n                    name,\n                    teacher: teacher || \"未知教师\",\n                    position: position || \"待定\",\n                    day,\n                    startSection: section,\n                    endSection: section,\n                    weeks\n                });\n            }\n        }\n\n        return mergeContiguousSections(courses);\n    }\n\n    async function fetchEntryParams() {\n        const entryHtml = await requestText(`${getBaseOrigin()}/eams/courseTableForStd.action?&sf_request_type=ajax`, {\n            method: \"GET\",\n            headers: {\n                \"x-requested-with\": \"XMLHttpRequest\"\n            }\n        });\n\n        return parseEntryParams(entryHtml);\n    }\n\n    async function fetchStudentProfile() {\n        const profileHtml = await requestText(`${getBaseOrigin()}/eams/stdInfoApply!stdInfoCheck.action?_=${Date.now()}`, {\n            method: \"GET\",\n            headers: {\n                accept: \"text/html, */*; q=0.01\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            }\n        });\n\n        return parseStudentProfile(profileHtml);\n    }\n\n    async function fetchSemesters(tagId) {\n        const semesterRaw = await requestText(`${getBaseOrigin()}/eams/dataQuery.action?sf_request_type=ajax`, {\n            method: \"POST\",\n            headers: {\n                \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\"\n            },\n            body: `tagId=${encodeURIComponent(tagId)}&dataType=semesterCalendar&empty=false`\n        });\n\n        return parseSemesterResponse(semesterRaw);\n    }\n\n    async function fetchCourseHtml(studentId, semesterId) {\n        return requestText(`${getBaseOrigin()}/eams/courseTableForStd!courseTable.action?sf_request_type=ajax`, {\n            method: \"POST\",\n            headers: {\n                accept: \"*/*\",\n                \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: [\n                \"ignoreHead=1\",\n                \"setting.kind=std\",\n                \"startWeek=\",\n                `semester.id=${encodeURIComponent(semesterId)}`,\n                `ids=${encodeURIComponent(studentId)}`\n            ].join(\"&\")\n        });\n    }\n\n    async function fetchCalendarInfo(semesterId) {\n        const calendarHtml = await requestText(`${getBaseOrigin()}/eams/base/calendar-info.action`, {\n            method: \"POST\",\n            headers: {\n                accept: \"text/html, */*; q=0.01\",\n                \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: `version=1&semesterId=${encodeURIComponent(semesterId)}`\n        });\n\n        return parseCalendarInfo(calendarHtml);\n    }\n\n    async function selectSemester(semesters) {\n        const recent = semesters.slice(-8);\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择要导入的学期\",\n            JSON.stringify(recent.map((semester) => semester.name || semester.id)),\n            recent.length - 1\n        );\n\n        if (selectedIndex === null || selectedIndex === -1) {\n            throw new Error(\"已取消导入。\");\n        }\n\n        return recent[selectedIndex];\n    }\n\n    async function runImportFlow() {\n        showToast(\"正在识别课表参数...\");\n        const params = await fetchEntryParams();\n        if (!params.studentId || !params.tagId) {\n            throw new Error(\"未能自动识别学生ID或学期参数\");\n        }\n\n        showToast(\"正在获取学籍信息...\");\n        const studentProfile = await fetchStudentProfile();\n\n        showToast(\"正在获取学期列表...\");\n        const semesters = filterSemestersByEnrollmentYear(\n            await fetchSemesters(params.tagId),\n            studentProfile.enrollmentYear\n        );\n        if (!semesters.length) {\n            throw new Error(\"未获取到学期列表。\");\n        }\n\n        const selectedSemester = await selectSemester(semesters);\n\n        showToast(`正在获取 ${selectedSemester.name} 课表...`);\n        const courseHtml = await fetchCourseHtml(params.studentId, selectedSemester.id);\n        const timeSlots = parseTimeSlotsFromHtml(courseHtml);\n        const courses = parseCoursesFromTaskActivityScript(courseHtml);\n        const calendarInfo = await fetchCalendarInfo(selectedSemester.id);\n\n        if (!courses.length) {\n            console.log(courseHtml);\n            throw new Error(\"未解析到课程数据，请确认当前学期有课表。\");\n        }\n\n        const config = {\n            firstDayOfWeek: 1\n        };\n        if (calendarInfo.semesterStartDate) {\n            config.semesterStartDate = calendarInfo.semesterStartDate;\n        }\n        if (calendarInfo.semesterTotalWeeks) {\n            config.semesterTotalWeeks = calendarInfo.semesterTotalWeeks;\n        }\n\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (timeSlots.length) {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        }\n\n        showToast(`导入完成，共 ${courses.length} 门课程`);\n        if (typeof window.shiguangBridge !== \"undefined\" && window.shiguangBridge.notifyTaskCompletion) {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    }\n\n    (async function bootstrap() {\n        try {\n            await runImportFlow();\n        } catch (error) {\n            console.error(error);\n            showToast(`导入失败：${error.message || error}`);\n        }\n    })();\n})();\n","HUUC_01":"// 河南城建学院本科适配\n// 基于 resources/chaoxing_jiaowu/chaoxing.js，原维护者 b1n23。\n// 用户已反馈超星通用入口导入成功；本校独立入口及课表细节仍需核对。\n// 超星教务系统拾光课程表适配脚本\n// 理论上使用超星教务系统的学校通用\n// 课程数据处理部分来自sxgcxy_01.js，由GitHub Copilot生成\n\n/**\n * 从 HTML 字符串中提取纯文本内容。\n * 超星系统返回的部分字段包含 HTML 标签（如 <a> 标签）\n */\nfunction extractAnchorText(htmlStr) {\n    if (!htmlStr) return '';\n    // 移除 HTML 标签，返回剩余的文本内容\n    const match = htmlStr.match(/>([^<]+)</);\n    return match ? match[1].trim() : htmlStr.trim();\n}\n\n/**\n * 清理教师名称，去除括号及其内容。\n */\nfunction cleanTeacherName(name) {\n    if (!name) return '';\n    // 移除全角或半角的括号及其中的内容\n    return name.replace(/（[^）]*）/g, '').replace(/\\([^)]*\\)/g, '').trim();\n}\n\n/**\n * 解析周次字符串，超星系统直接提供逗号分隔的周次数字。\n * @param {string} weekStr - 周次字符串，如 \"1,2,3,4,5\"\n * @returns {number[]} - 排序后的周次数组\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    return weekStr.split(',')\n        .map(w => Number(w.trim()))\n        .filter(w => !isNaN(w) && w > 0)\n        .sort((a, b) => a - b);\n}\n\n/**\n * 从周次列表中获取开学日期（第1周的开始日期）。\n * @param {Array} zclist - 周次列表，来自 getZclistByXnxq 接口\n * @returns {string|null} - 开学日期，格式 YYYY-MM-DD\n */\nfunction getSemesterStartDate(zclist) {\n    if (!zclist || !Array.isArray(zclist) || zclist.length === 0) {\n        console.warn(\"JS: 周次列表为空或格式错误。\");\n        return null;\n    }\n\n    // 查找第1周的数据\n    const firstWeek = zclist.find(zc => Number(zc.zc) === 1);\n    if (!firstWeek || !firstWeek.minrq) {\n        console.warn(\"JS: 未找到第1周的开始日期。\");\n        return null;\n    }\n\n    // 将 \"2025-08-25 00:00:00\" 格式转换为 \"2025-08-25\"\n    const dateStr = firstWeek.minrq.split(' ')[0];\n    console.log(`JS: 获取到开学日期: ${dateStr}`);\n    return dateStr;\n}\n\n/**\n * 解析课程数据，并合并连续节次的同一课程。\n * @param {Object} jsonData - sdpkkbList 接口返回的 JSON 数据\n * @returns {Array<Object>} - 解析并合并后的课程列表\n */\nfunction parseCourseData(jsonData) {\n    console.log(\"JS: 开始解析超星课程数据...\");\n\n    if (!jsonData || !Array.isArray(jsonData.data)) {\n        console.warn(\"JS: 课程数据结构错误或缺少 data 字段。\");\n        return [];\n    }\n\n    const rawCourseList = jsonData.data;\n\n    // 1. 预处理课程数据，提取必要字段并标准化\n    const processedList = rawCourseList\n        .map(rawCourse => {\n            const name = extractAnchorText(rawCourse.kcmc);\n            const teacher = cleanTeacherName(extractAnchorText(rawCourse.tmc));\n            const position = extractAnchorText(rawCourse.croommc) || '待定';\n            const day = Number(rawCourse.xingqi);\n            const section = Number(rawCourse.djc);\n            \n            // 解析周次字符串并转换为标准 JSON 字符串（用于比较）\n            const weeksArray = parseWeeks(rawCourse.zcstr);\n            const standardizedWeeks = JSON.stringify(weeksArray);\n\n            // 验证必填字段\n            if (!name || isNaN(day) || isNaN(section) || day < 1 || day > 7 || section < 1 || weeksArray.length === 0) {\n                return null;\n            }\n\n            return { name, teacher, position, day, section, standardizedWeeks, weeksArray };\n        })\n        .filter(c => c !== null)\n        // 排序：按星期 > 周次 > 课程名 > 教师 > 教室 > 节次\n        .sort((a, b) =>\n            a.day - b.day ||\n            a.standardizedWeeks.localeCompare(b.standardizedWeeks) ||\n            a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            a.section - b.section \n        );\n\n    // 2. 合并连续节次的相同课程\n    const finalCourseList = [];\n    let i = 0;\n\n    while (i < processedList.length) {\n        let current = processedList[i];\n        let startSection = current.section;\n        let endSection = current.section;\n        let j = i + 1;\n\n        // 查找连续的节次\n        while (j < processedList.length) {\n            let next = processedList[j];\n\n            // 检查是否可以合并：周次、星期、课程名、教师、教室必须相同，且节次连续\n            if (\n                next.day === current.day &&\n                next.name === current.name &&\n                next.teacher === current.teacher &&\n                next.position === current.position &&\n                next.standardizedWeeks === current.standardizedWeeks && \n                next.section === endSection + 1\n            ) {\n                endSection = next.section;\n                j++;\n            } else {\n                break;\n            }\n        }\n\n        // 添加合并后的课程\n        finalCourseList.push({\n            name: current.name,\n            teacher: current.teacher,\n            position: current.position,\n            day: current.day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: current.weeksArray\n        });\n\n        i = j;\n    }\n\n    console.log(`JS: 课程数据解析完成，共 ${finalCourseList.length} 门课程（已合并连续节次）。`);\n    return finalCourseList;\n}\n\n/**\n * 生成学年学期选项列表。\n * @returns {Object} - 包含 labels（显示文本）、values（参数值）、defaultIndex（默认选项）\n */\nfunction getSemesterOptions() {\n    const currentYear = new Date().getFullYear();\n    const currentMonth = new Date().getMonth() + 1;\n    \n    // 根据当前月份判断默认学期（9月前为第二学期，9月后为第一学期）\n    const defaultSemester = currentMonth < 9 ? 2 : 1;\n    const defaultYear = currentMonth < 9 ? currentYear - 1 : currentYear;\n    \n    // 生成前后三年的学年学期选项\n    const years = [currentYear - 2, currentYear - 1, currentYear, currentYear + 1]; \n    const semesterCodes = [\"1\", \"2\"];\n\n    let labels = [];\n    let values = [];\n    let defaultIndex = -1;\n    \n    let index = 0;\n    for (let i = 0; i < years.length; i++) {\n        const startYear = years[i];\n        const endYear = startYear + 1;\n        const yearStr = `${startYear}-${endYear}`;\n\n        for (let j = 0; j < semesterCodes.length; j++) {\n            const code = semesterCodes[j];\n            const apiValue = `${yearStr}-${code}`;\n            const semesterName = code === \"1\" ? \"第一学期\" : \"第二学期\";\n            \n            labels.push(`${yearStr}学年 ${semesterName}`);\n            values.push(apiValue);\n            \n            // 设置默认选项\n            if (startYear === defaultYear && Number(code) === defaultSemester) {\n                defaultIndex = index;\n            }\n            \n            index++;\n        }\n    }\n    \n    return { labels, values, defaultIndex };\n}\n\n/**\n * 从学年学期下拉框 HTML 中解析选项。\n * @param {string} selectHtml - id=xnxq1 的 select 元素 HTML\n * @returns {Object|null} - 包含 labels、values、defaultIndex，失败返回 null\n */\nfunction parseSemesterOptionsFromHtml(selectHtml) {\n    if (!selectHtml || typeof selectHtml !== 'string') {\n        return null;\n    }\n\n    try {\n        const doc = new DOMParser().parseFromString(selectHtml, \"text/html\");\n        const selectElement = doc.querySelector('#xnxq1') || doc.querySelector('select[name=\"xnxq\"]');\n        if (!selectElement) {\n            return null;\n        }\n\n        const optionElements = Array.from(selectElement.querySelectorAll('option'));\n        const validOptions = optionElements.filter(option => (option.value || '').trim() !== '');\n        if (validOptions.length === 0) {\n            return null;\n        }\n\n        const labels = validOptions.map(option => (option.textContent || option.value || '').trim());\n        const values = validOptions.map(option => (option.value || '').trim());\n\n        let defaultIndex = validOptions.findIndex(option => option.selected);\n        if (defaultIndex < 0) {\n            defaultIndex = 0;\n        }\n\n        return { labels, values, defaultIndex };\n    } catch (error) {\n        console.warn(\"JS: 解析学年学期下拉 HTML 失败\", error);\n        return null;\n    }\n}\n\n/**\n * 提示用户选择学年学期。\n * @param {string|null|undefined} xnxqSelectHtml - 页面中 id=xnxq1 的 select 元素 HTML\n * @returns {Promise<string|null>} - 选中的学年学期参数（如 \"2025-2026-1\"），或 null（取消）\n */\nasync function selectAcademicYearAndSemester(xnxqSelectHtml) {\n    console.log(\"JS: 提示用户选择学年学期。\");\n    let options = parseSemesterOptionsFromHtml(xnxqSelectHtml);\n    if (!options) {\n        console.warn(\"JS: 页面学年学期选项解析失败，回退为前后三年选项。\");\n        options = getSemesterOptions();\n    }\n    const { labels, values, defaultIndex } = options;\n    \n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年学期\",\n        JSON.stringify(labels),\n        defaultIndex\n    );\n    \n    if (selectedIndex === null || selectedIndex === -1) {\n        return null;\n    }\n    \n    console.log(`JS: 用户选择了学年学期: ${values[selectedIndex]}`);\n    return values[selectedIndex];\n}\n\n/**\n * 获取校区列表。\n * @returns {Promise<Array<{xqdm: string, xqmc: string}>|null>} - 校区列表，或 null（失败）\n */\nasync function fetchCampusList() {\n    console.log(\"JS: 正在请求校区列表...\");\n\n    const url = \"/admin/api/jcsj/xqsj/getXqList\";\n    const requestOptions = {\n        \"headers\": {\n            \"Accept\": \"application/json, text/plain, */*\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        \"method\": \"GET\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n\n        const jsonData = await response.json();\n\n        if (jsonData.ret !== 0) {\n            throw new Error(`API 返回错误: ${jsonData.msg || '未知错误'}`);\n        }\n\n        if (!Array.isArray(jsonData.data)) {\n            throw new Error(\"校区列表数据格式错误。\");\n        }\n\n        const campusList = jsonData.data\n            .map(item => ({\n                xqdm: String(item.id || '').trim(),\n                xqmc: String(item.xqmc || item.id || '').trim()\n            }))\n            .filter(item => item.xqdm && item.xqmc);\n\n        if (campusList.length === 0) {\n            throw new Error(\"未获取到有效校区信息。\");\n        }\n\n        console.log(`JS: 校区列表获取成功，共 ${campusList.length} 个校区。`);\n        return campusList;\n    } catch (error) {\n        window.shiguangBridge.showToast(`获取校区列表失败: ${error.message}`);\n        console.error('JS: fetchCampusList Error:', error);\n        return null;\n    }\n}\n\n/**\n * 提示用户选择校区。\n * @param {string} defaultXqdm - 默认选中的校区代码\n * @returns {Promise<{xqdm: string, xqmc: string}|null>} - 选中的校区信息，或 null（取消/失败）\n */\nasync function selectCampus(defaultXqdm) {\n    const campusList = await fetchCampusList();\n    if (!campusList) {\n        console.warn(`JS: 获取校区列表失败，使用页面参数 xqdm=${defaultXqdm} 继续导入。`);\n        window.shiguangBridge.showToast(\"获取校区列表失败，使用默认校区继续导入。\");\n        return {\n            xqdm: defaultXqdm,\n            xqmc: \"\"\n        };\n    }\n\n    const labels = campusList.map(item => item.xqmc);\n    const defaultIndex = Math.max(\n        campusList.findIndex(item => item.xqdm === defaultXqdm),\n        0\n    );\n\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择校区\",\n        JSON.stringify(labels),\n        defaultIndex\n    );\n\n    if (selectedIndex === null || selectedIndex === -1) {\n        return null;\n    }\n\n    const selectedCampus = campusList[selectedIndex];\n    console.log(`JS: 用户选择了校区: ${selectedCampus.xqmc} (${selectedCampus.xqdm})`);\n    return selectedCampus;\n}\n\n/** \n * 时间格式化\n * @returns {string|null} - 格式化后的时间字符串 \"HH:MM\"，或 null（格式不合法）\n */\nfunction formatTime(timeStr) {\n    if (typeof timeStr !== 'string') return null;\n    const match = timeStr.match(/^(\\d{1,2}):(\\d{1,2})(?::\\d{1,2})?$/);\n    if (!match) return null;\n    const [, hour, minute, second] = match.map(Number);\n    if (hour > 23 || minute > 59 || (second !== undefined && second > 59)) return null;\n    return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;\n}\n\n// 用户提供的河南城建学院夏季作息。午间及傍晚加课未提供节次编号，不推测映射。\nconst HUUC_SUMMER_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"10:05\", endTime: \"10:50\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:20\", endTime: \"16:05\" },\n    { number: 7, startTime: \"16:35\", endTime: \"17:20\" },\n    { number: 8, startTime: \"17:25\", endTime: \"18:10\" },\n    { number: 9, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 10, startTime: \"19:50\", endTime: \"20:35\" },\n    { number: 11, startTime: \"20:40\", endTime: \"21:25\" }\n];\n\nfunction getSummerTimeSlots() {\n    return HUUC_SUMMER_TIME_SLOTS.map(slot => ({ ...slot }));\n}\n\n// 冬季仅第5至8节提前30分钟，上午及晚间保持不变。\nfunction getWinterTimeSlots() {\n    const advanceHalfHour = time => {\n        const [hour, minute] = time.split(\":\").map(Number);\n        const total = hour * 60 + minute - 30;\n        return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;\n    };\n    return getSummerTimeSlots().map(slot => slot.number >= 5 && slot.number <= 8\n        ? { ...slot, startTime: advanceHalfHour(slot.startTime), endTime: advanceHalfHour(slot.endTime) }\n        : slot);\n}\n\nasync function selectSchoolTimeSlots() {\n    const selected = await window.shiguangBridgePromise.showSingleSelection(\n        \"请选择本学期作息（第1至11节）\",\n        JSON.stringify([\"夏季：下午14:30开始\", \"冬季：下午14:00开始\"]),\n        -1\n    );\n    if (selected === 0) return getSummerTimeSlots();\n    if (selected === 1) return getWinterTimeSlots();\n    return null; // 用户取消，主流程在保存前退出。\n}\n\n/** 将接口作息转换为节次列表；数据无效时提供夏季备用作息。 */\nfunction generateTimeSlots(jcsjszList) {\n    const fallback = () => ({ timeSlots: getSummerTimeSlots(), usesFallback: true });\n    if (!Array.isArray(jcsjszList) || jcsjszList.length === 0) return fallback();\n    const timeSlots = [];\n    const numbers = new Set();\n    for (const item of jcsjszList) {\n        const startTime = formatTime(item?.kssj);\n        const endTime = formatTime(item?.jssj);\n        const number = Number(item?.jc);\n        if (!startTime || !endTime || startTime >= endTime ||\n            !Number.isInteger(number) || number < 1 || numbers.has(number)) {\n            return fallback();\n        }\n        numbers.add(number);\n        timeSlots.push({ number, startTime, endTime });\n    }\n    timeSlots.sort((a, b) => a.number - b.number);\n    return { timeSlots, usesFallback: false };\n}\n\n/**\n * 从页面中提取必要的参数。\n * @returns {Object|null} - 包含 xhid、xqdm 和 xnxqSelectHtml 的对象，或 null（提取失败）\n */\nasync function extractPageParams() {\n    console.log(\"JS: 尝试从页面中提取参数...\");\n    \n    // 方法1：从隐藏的 input 元素中获取\n    let xhid = document.querySelector('#xhid')?.value;\n    let xqdm = document.querySelector('#xqdm')?.value;\n    let xnxqSelectHtml = document.querySelector('#xnxq1')?.outerHTML;\n    \n    // 方法2：如果页面上找不到，尝试抓取课表页并解析\n    if (!xhid || !xqdm || !xnxqSelectHtml) {\n        console.log(\"JS: 尝试抓取课表页并解析...\");\n        const path = \"/admin/pkgl/xskb/queryKbForXsd\";\n\n        try {\n            // 获取课表页的 HTML 文档\n            const htmlText = await fetch(path).then(res => res.text());\n            const contentDom = new DOMParser().parseFromString(htmlText, \"text/html\");\n\n            // 从转换后的 HTML 文档中获取 xhid 和 xqdm 的值\n            xhid = contentDom.querySelector(\"#xhid\")?.value ||  xhid;\n            xqdm = contentDom.querySelector(\"#xqdm\")?.value || xqdm;\n            xnxqSelectHtml = contentDom.querySelector(\"#xnxq1\")?.outerHTML || xnxqSelectHtml;\n        } catch (error) {\n            console.warn(\"JS: 通过抓取课表页提取参数失败\", error);\n        }\n    }\n    \n    console.log(`JS: 提取到参数 - xhid: ${xhid}, xqdm: ${xqdm}, xnxqSelectHtml: ${xnxqSelectHtml ? 'yes' : 'no'}`);\n    \n    if (!xhid || !xqdm) {\n        console.warn(\"JS: 无法从页面中提取必要参数。\");\n        return null;\n    }\n    \n    return { xhid, xqdm, xnxqSelectHtml };\n}\n\n/**\n * 获取节次时间和开学日期信息。\n * @param {string} xnxq - 学年学期参数\n * @param {string} xqdm - 校区代码\n * @returns {Promise<Object>} - 包含 timeSlots 和 semesterStartDate，请求失败时提供夏季备用作息，待用户确认后使用\n */\nasync function fetchTimeAndWeekData(xnxq, xqdm) {\n    console.log(`JS: 正在请求节次时间和周次数据...`);\n    window.shiguangBridge.showToast(\"正在获取课表配置信息...\");\n    \n    const url = `/admin/api/getZclistByXnxq?xnxq=${xnxq}&xqid=${xqdm}`;\n    \n    const requestOptions = {\n        \"headers\": {\n            \"Accept\": \"application/json, text/plain, */*\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        \"method\": \"GET\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n        \n        const jsonData = await response.json();\n        \n        if (jsonData.ret !== 0) {\n            throw new Error(`API 返回错误: ${jsonData.msg || '未知错误'}`);\n        }\n\n        // 提取节次时间和开学日期\n        const { timeSlots, usesFallback } = generateTimeSlots(jsonData.data?.jcsjszList);\n        const semesterStartDate = getSemesterStartDate(jsonData.data?.zclist);\n\n        if (!timeSlots) {\n            console.warn(\"JS: 未获取到节次时间\");\n        }\n\n        if (!semesterStartDate) {\n            console.warn(\"JS: 未获取到开学日期\");\n        }\n\n        console.log(`JS: 成功获取节次时间（${Array.isArray(timeSlots) ? timeSlots.length : 0}个）和开学日期（${semesterStartDate}）。`);\n        return { timeSlots, semesterStartDate, usesFallback };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`获取配置信息失败，将继续导入课程: ${error.message}`);\n        console.error('JS: fetchTimeAndWeekData Error:', error);\n        return {\n            timeSlots: getSummerTimeSlots(),\n            usesFallback: true,\n            semesterStartDate: null\n        };\n    }\n}\n\n/**\n * 获取课程数据。\n * @param {string} xnxq - 学年学期参数\n * @param {string} xhid - 学号ID\n * @param {string} xqdm - 校区代码\n * @returns {Promise<Array|null>} - 课程列表，或 null（失败）\n */\nasync function fetchCourseData(xnxq, xhid, xqdm) {\n    console.log(`JS: 正在请求课程数据...`);\n    window.shiguangBridge.showToast(`正在获取 ${xnxq} 的课程数据...`);\n    \n    const url = `/admin/xsd/pkgl/xskb/sdpkkbList?xnxq=${xnxq}&xhid=${xhid}&xqdm=${xqdm}&xskbxslx=0`;\n    \n    const requestOptions = {\n        \"headers\": {\n            \"Accept\": \"application/json, text/plain, */*\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        \"method\": \"GET\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status}`);\n        }\n        \n        const jsonData = await response.json();\n        \n        if (jsonData.ret !== 0) {\n            throw new Error(`API 返回错误: ${jsonData.msg || '未知错误'}`);\n        }\n\n        const courses = parseCourseData(jsonData);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，本学期可能无课。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据获取成功，共 ${courses.length} 门课程。`);\n        return courses;\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`获取课程数据失败: ${error.message}`);\n        console.error('JS: fetchCourseData Error:', error);\n        return null;\n    }\n}\n\n/**\n * 保存课程数据到应用。\n * @param {Array} courses - 课程列表\n * @returns {Promise<boolean>} - 是否保存成功\n */\nasync function saveCourses(courses) {\n    console.log(`JS: 正在保存 ${courses.length} 门课程...`);\n    window.shiguangBridge.showToast(`正在保存 ${courses.length} 门课程...`);\n    \n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses, null, 2));\n        console.log(\"JS: 课程保存成功。\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: saveCourses Error:', error);\n        return false;\n    }\n}\n\n/**\n * 导入预设时间段到应用。\n * @param {Array} timeSlots - 时间段列表\n * @returns {Promise<boolean>} - 是否导入成功\n */\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 正在导入 ${timeSlots.length} 个预设时间段...`);\n    window.shiguangBridge.showToast(`正在导入作息时间...`);\n    \n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        console.log(\"JS: 预设时间段导入成功。\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n        console.error('JS: importPresetTimeSlots Error:', error);\n        return false;\n    }\n}\n\n/**\n * 保存课表配置（开学日期等）。\n * @param {string|null} semesterStartDate - 开学日期\n * @returns {Promise<boolean>} - 是否保存成功\n */\nasync function saveCourseConfig(semesterStartDate) {\n    if (!semesterStartDate) {\n        console.log(\"JS: 开学日期为空，跳过课表配置保存。\");\n        return true;\n    }\n    \n    console.log(`JS: 正在保存课表配置（开学日期: ${semesterStartDate}）...`);\n    \n    const config = {\n        semesterStartDate: semesterStartDate\n    };\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        console.log(\"JS: 课表配置保存成功。\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"保存课表配置失败: \" + error.message);\n        console.error('JS: saveCourseConfig Error:', error);\n        return false;\n    }\n}\n\n/**\n * 检查是否在登录页面。\n * @returns {boolean}\n */\nfunction isLoginPage() {\n    const url = window.location.href;\n    return url.includes('login') || url.includes('slogin');\n}\n\n/**\n * 提示用户开始导入。\n * @returns {Promise<boolean>} - 用户是否确认\n */\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        \"河南城建学院课表导入\",\n        \"导入前请确保您已在成功登录教务系统，并打开课表页面。\\n\\n本脚本将自动获取作息时间、开学日期和课程数据。\",\n        \"开始导入\"\n    );\n}\n\n/**\n * 主导入流程。\n */\nasync function runImportFlow() {\n    console.log(\"JS: 开始执行超星教务系统课表导入流程...\");\n    \n    // 1. 检查是否在登录页面\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        return;\n    }\n\n    // 2. 提示用户确认开始导入\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n    \n    // 3. 提取页面参数\n    const params = await extractPageParams();\n    if (!params) {\n        window.shiguangBridge.showToast(\"无法从页面获取必要参数，请确保在正确的页面执行脚本。\");\n        return;\n    }\n    \n    const { xhid, xqdm: pageXqdm, xnxqSelectHtml } = params;\n    \n    // 4. 让用户选择学年学期\n    const xnxq = await selectAcademicYearAndSemester(xnxqSelectHtml);\n    if (xnxq === null) {\n        window.shiguangBridge.showToast(\"导入已取消，未选择学年学期。\");\n        return;\n    }\n\n    // 5. 让用户选择校区（默认使用页面参数中的 xqdm，若校区接口失败则自动回退使用页面 xqdm）\n    const selectedCampus = await selectCampus(pageXqdm);\n    if (!selectedCampus) {\n        window.shiguangBridge.showToast(\"导入已取消，未选择校区。\");\n        return;\n    }\n    const { xqdm } = selectedCampus;\n\n    // 6. 获取节次时间和开学日期\n    const timeData = await fetchTimeAndWeekData(xnxq, xqdm);\n    const { semesterStartDate } = timeData;\n\n    // 7. 获取课程数据\n    const courses = await fetchCourseData(xnxq, xhid, xqdm);\n    if (!courses) {\n        return;\n    }\n\n    // 始终使用用户确认的本校作息，接口时间格式正确也可能不适用。\n    const timeSlots = await selectSchoolTimeSlots();\n    if (!timeSlots) return;\n\n    // 未确认编号的午间、傍晚加课不能自行映射。\n    const coversCourses = slots => courses.every(course => {\n        if (!Number.isInteger(course.startSection) || !Number.isInteger(course.endSection) ||\n            course.startSection < 1 || course.endSection < course.startSection) return false;\n        const numbers = new Set(slots.map(slot => slot.number));\n        for (let n = course.startSection; n <= course.endSection; n++) {\n            if (!numbers.has(n)) return false;\n        }\n        return true;\n    });\n    if (!coversCourses(timeSlots)) {\n        await window.shiguangBridgePromise.showAlert(\"无法确定节次时间\",\n            \"课程包含第1至11节以外的节次，请向维护者提供对应节次的作息。此次未保存课程。\", \"知道了\");\n        return;\n    }\n\n    // 8. 保存课程数据\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    // 9. 导入预设时间段\n    if (Array.isArray(timeSlots) && timeSlots.length > 0) {\n        if (!await importPresetTimeSlots(timeSlots)) {\n            window.shiguangBridge.showToast(\"课程已保存，但作息保存失败，请重试或手动设置作息。\");\n            return;\n        }\n    } else {\n        console.log(\"JS: 未生成有效时间段，跳过预设时间段导入。\");\n    }\n\n    // 10. 保存课表配置（开学日期）\n    if (semesterStartDate) {\n        await saveCourseConfig(semesterStartDate);\n    } else {\n        console.log(\"JS: 未获取到开学日期，跳过课表配置保存。\");\n    }\n\n    // 11. 完成\n    window.shiguangBridge.showToast(`导入成功！共导入 ${courses.length} 门课程。`);\n    window.shiguangBridge.notifyTaskCompletion();\n    console.log(\"JS: 超星教务系统课表导入流程完成。\");\n}\n\n// 执行主流程\nrunImportFlow();\n","HAUT_01":"// 河南工业大学(haut.edu.cn) 拾光课程表适配脚本\n// 基于正方教务系统接口适配\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提issues或者提交pr更改,这更加快速\n\n/**\n * 解析周次字符串，处理单双周和周次范围。\n */\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n\n    const weekSets = weekStr.split(',');\n    let weeks = [];\n\n    for (const set of weekSets) {\n        const trimmedSet = set.trim();\n\n        const rangeMatch = trimmedSet.match(/(\\d+)-(\\d+)周/);\n        const singleMatch = trimmedSet.match(/^(\\d+)周/); // 匹配以数字周结束的\n\n        let start = 0;\n        let end = 0;\n        let processed = false;\n\n        if (rangeMatch) { // 范围, 如 \"1-5周\"\n            start = Number(rangeMatch[1]);\n            end = Number(rangeMatch[2]);\n            processed = true;\n        } else if (singleMatch) { // 单个周, 如 \"6周\"\n            start = end = Number(singleMatch[1]);\n            processed = true;\n        }\n        \n        if (processed) {\n            // 确定单双周\n            const isSingle = trimmedSet.includes('(单)');\n            const isDouble = trimmedSet.includes('(双)');\n\n            for (let w = start; w <= end; w++) {\n                if (isSingle && w % 2 === 0) continue; // 单周跳过偶数\n                if (isDouble && w % 2 !== 0) continue; // 双周跳过奇数\n                weeks.push(w);\n            }\n        }\n    }\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 解析 API 返回的 JSON 数据。\n */\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    // 检查JSON结构：新的数据在 kbList 字段中\n    if (!jsonData || !Array.isArray(jsonData.kbList)) {\n        console.warn(\"JS: JSON 数据结构错误或缺少 kbList 字段。\");\n        return []; \n    }\n\n    const rawCourseList = jsonData.kbList;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查： kcmc(课名), xm(教师), cdmc(教室), xqj(星期), jcs(节次范围), zcd(周次描述)\n        if (!rawCourse.kcmc || !rawCourse.xm || !rawCourse.cdmc || \n            !rawCourse.xqj || !rawCourse.jcs || !rawCourse.zcd) {\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zcd);\n        \n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n            continue;\n        }\n        \n        // 解析节次范围，例如 \"1-2\"\n        const sectionParts = rawCourse.jcs.split('-');\n        const startSection = Number(sectionParts[0]);\n        const endSection = Number(sectionParts[sectionParts.length - 1]); \n\n        const day = Number(rawCourse.xqj); // xqj: 星期几 (周一为1, 周日为7)\n        \n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n            // console.warn(`JS: 课程 ${rawCourse.kcmc} 星期或节次数据无效，跳过。`);\n            continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.xm.trim(),\n            position: rawCourse.cdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\n/**\n * 检查是否在登录页面。\n * 只有当 URL 精确匹配时，才返回 true。\n */\nfunction isLoginPage() {\n    const url = window.location.href;\n    const loginUrl = \"https://jwglxt.haut.edu.cn/jwglxt/xtgl/login_slogin.html\";\n    \n    // 如果当前 URL 与指定的登录 URL 完全一致，则返回 true (是登录页)\n    return url === loginUrl; \n}\n\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\n\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期\", \"第二学期\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\n/**\n * 将选择索引转换为 API 所需的学期码。\n */\nfunction getSemesterCode(semesterIndex) {\n    // semesterIndex 3 (第一学期), 12 (第二学期)\n    return semesterIndex === 0 ? \"3\" : \"12\";\n}\n\n\n/**\n * 请求和解析课程数据\n */\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    const semesterCode = getSemesterCode(semesterIndex);\n    \n    // API URL 和请求体\n    const xnmXqmBody = `xnm=${academicYear}&xqm=${semesterCode}&kzlx=ck&xsdm=&kclbdm=`; \n    const url = \"https://jwglxt.haut.edu.cn/jwglxt/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151\";\n\n    console.log(`JS: 发送请求到 ${url}, body: ${xnmXqmBody}`);\n\n    const requestOptions = {\n        \"headers\": {\n            \"content-type\": \"application/x-www-form-urlencoded;charset=UTF-8\", \n        },\n        \"body\": xnmXqmBody,\n        \"method\": \"POST\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status} (${response.statusText})`);\n        }\n        \n        const jsonText = await response.text();\n        let jsonData;\n        try {\n            jsonData = JSON.parse(jsonText);\n        } catch (e) {\n            console.error('JS: JSON 解析失败，可能是会话过期:', e);\n            window.shiguangBridge.showToast(\"数据返回格式错误，可能是您未成功登录或会话已过期。\");\n            return null;\n        }\n\n        const courses = parseJsonData(jsonData); \n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确或本学期无课，或教务系统需要二次登录。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程。`);\n        \n        // 默认总周数为 20，周一为一周第一天。\n        const config = {\n            semesterTotalWeeks: 20,\n            firstDayOfWeek: 1 \n        };\n\n        // 返回课程列表和配置信息\n        return { courses: courses, config: config }; \n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\n// 统一作息时间\nconst TimeSlots = [\n    { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:20\", endTime: \"10:05\" },\n    { number: 3, startTime: \"10:25\", endTime: \"11:10\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:20\", endTime: \"16:05\" },\n    { number: 7, startTime: \"16:25\", endTime: \"17:10\" },\n    { number: 8, startTime: \"17:15\", endTime: \"18:00\" },\n    { number: 9, startTime: \"19:30\", \"endTime\": \"20:15\" },\n    { number: 10, startTime: \"20:25\", \"endTime\": \"21:10\" },\n    { number: 11, startTime: \"21:20\", \"endTime\": \"22:30\" }\n];\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        console.log(\"JS: 检测到当前在登录页面，终止导入。\");\n        return;\n    }\n\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses, config } = result;\n\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n    \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`课表配置更新成功！总周数：${config.semesterTotalWeeks}周。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n        console.error('JS: Save Config Error:', error);\n    }\n\n\n    await importPresetTimeSlots(TimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","HAUE_01":"// 河南工程学院正方 V9：依据本校实际课表、作息响应适配。\r\n// 参考 resources/JSEI/jsei_01.js（星河欲转）的网络请求方案。\r\n// 登录教务后即可导入；通过请求获取学年学期及默认值，随后在桥接弹窗中选择。\r\n\r\n\r\nfunction normalizeText(value) {\r\n    return String(value == null ? '' : value).replace(/[！-～]/g, c => String.fromCharCode(c.charCodeAt(0) - 65248)).replace(/　/g, ' ').replace(/[～~—–]/g, '-');\r\n}\r\n\r\nfunction normalizeTime(value) {\r\n    const m = normalizeText(value).trim().match(/^(\\d{1,2}):(\\d{2})(?::(\\d{2}))?$/);\r\n    if (!m || +m[1] > 23 || +m[2] > 59 || (m[3] && +m[3] > 59)) throw new Error('无法识别时间：' + value);\r\n    return m[1].padStart(2, '0') + ':' + m[2];\r\n}\r\n\r\n// 保留当前教务页面的代理路径前缀，避免从 WebVPN 跳回校内地址。\r\nfunction getBaseUrl() {\r\n    const current = new URL(window.location.href);\r\n    const index = current.pathname.indexOf('/jwglxt/');\r\n    if (index < 0) throw new Error('请先登录并进入教务系统（WebVPN 需先打开教务系统应用）');\r\n    return current.origin + current.pathname.slice(0, index) + '/jwglxt/';\r\n}\r\n\r\nfunction parseSemesterConfig(rows) {\r\n    if (!Array.isArray(rows) || !rows.length) throw new Error('校历接口未返回周次列表');\r\n    let first = null, max = 0;\r\n    const weeks = new Set();\r\n    for (const row of rows) {\r\n        const m = normalizeText(row.zs == null ? row.zsmc : row.zs).trim().match(/^(?:第)?(\\d+)(?:周)?$/);\r\n        if (!m || +m[1] < 1) continue;\r\n        const week = +m[1]; weeks.add(week); max = Math.max(max, week);\r\n        if (week === 1) first = row;\r\n    }\r\n    const config = {};\r\n    // 校历允许从非第 1 周开始；仅接受连续且最大周次为 10～60 的列表。\r\n    const sortedWeeks = Array.from(weeks).sort((a, b) => a - b);\r\n    let continuous = sortedWeeks.length > 0;\r\n    for (let i = 1; i < sortedWeeks.length; i++) {\r\n        if (sortedWeeks[i] - sortedWeeks[i - 1] !== 1) { continuous = false; break; }\r\n    }\r\n    if (continuous && max >= 10 && max <= 60) config.semesterTotalWeeks = max;\r\n    if (first) {\r\n        for (const key of ['rq', 'zcrq', 'ksrq']) {\r\n            const m = normalizeText(first[key]).match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})(?=$|[\\s/至~\\-])/);\r\n            if (!m) continue;\r\n            const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));\r\n            if (d.getUTCFullYear() !== +m[1] || d.getUTCMonth() !== +m[2] - 1 || d.getUTCDate() !== +m[3]) continue;\r\n            config.semesterStartDate = m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');\r\n            break;\r\n        }\r\n    }\r\n    return config;\r\n}\r\n\r\nasync function fetchSemesterConfig(xnm, xqm, warnings) {\r\n    let config = {};\r\n    try { config = parseSemesterConfig(await requestHaue('kbcx/xskbcxZccx_cxZcByXnxq.html', { xnm, xqm }, 'N2154')); }\r\n    catch (error) { warnings.push('校历获取失败：' + error.message); }\r\n    if (!config.semesterStartDate) warnings.push('开学日期未获取，请在软件内手动设置');\r\n    if (!config.semesterTotalWeeks) warnings.push('学期总周数未确认，请在软件内手动设置');\r\n    return config;\r\n}\r\n\r\n// 全局变量、URL 参数都必须匹配接口提供的有效选项；不匹配则继续回退。\r\nfunction getDefaultOptionIndex(options, key) {\r\n    const match = value => {\r\n        if (typeof value !== 'string' && typeof value !== 'number') return -1;\r\n        const text = String(value).trim();\r\n        if (!text) return -1;\r\n        return options.findIndex(option => option.value === text);\r\n    };\r\n    let index = match(window[key]);\r\n    if (index >= 0) return index;\r\n    index = match(new URL(window.location.href).searchParams.get(key));\r\n    if (index >= 0) return index;\r\n    index = options.findIndex(option => option.selected);\r\n    return index >= 0 ? index : 0;\r\n}\r\n\r\nfunction assertNotLoginPage(text) {\r\n    if (/login_slogin|用户登录|统一身份认证/i.test(text)) {\r\n        throw new Error('登录已过期，请重新登录教务系统后再导入');\r\n    }\r\n}\r\n\r\n// 只解析新请求返回的文档，不依赖当前页面是否已经打开课表。\r\nfunction parseAcademicOptions(doc) {\r\n    const read = selector => Array.from(doc.querySelectorAll(selector))\r\n        .filter(option => !option.disabled && String(option.value).trim() !== '')\r\n        .map(option => ({ value: String(option.value).trim(), text: option.textContent.trim(), selected: option.selected }));\r\n    const allYears = read('#xnm option');\r\n    const semesterOptions = read('#xqm option');\r\n    if (!allYears.length || !semesterOptions.length) {\r\n        // 正常教务页也可能包含登录跳转脚本，仅缺少有效选项时判定登录页。\r\n        const html = doc.documentElement ? doc.documentElement.outerHTML : '';\r\n        assertNotLoginPage(html || (doc.body ? doc.body.textContent : '') || '');\r\n        throw new Error('未获取到学年学期选项，请确认已登录教务系统后重试');\r\n    }\r\n    const selectedYear = getDefaultOptionIndex(allYears, 'xnm');\r\n    const start = Math.max(0, selectedYear - 2);\r\n    const yearOptions = allYears.slice(start, selectedYear + 3);\r\n    const selectedSemester = getDefaultOptionIndex(semesterOptions, 'xqm');\r\n    return { yearOptions, semesterOptions, defaultYearIndex: selectedYear - start, defaultSemesterIndex: selectedSemester };\r\n}\r\n\r\nasync function fetchAcademicOptions() {\r\n    const response = await fetch(getBaseUrl() + 'kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default', {\r\n        method: 'GET', credentials: 'same-origin'\r\n    });\r\n    if (!response.ok) throw new Error('获取学年学期失败（HTTP ' + response.status + '）');\r\n    const doc = new DOMParser().parseFromString(await response.text(), 'text/html');\r\n    return parseAcademicOptions(doc);\r\n}\r\n\r\nasync function selectAcademicYearAndSemester(bridge) {\r\n    const options = await fetchAcademicOptions();\r\n    const select = async (title, entries, defaultIndex) => {\r\n        const result = await bridge.showSingleSelection(title, JSON.stringify(entries.map(item => item.text)), defaultIndex);\r\n        if (result == null || !/^\\d+$/.test(String(result).trim()) || String(result) === '-1') return null;\r\n        const index = String(result).trim();\r\n        return entries[+index] || null;\r\n    };\r\n    const makeSelection = (year, semester) => ({ xnm: year.value, xqm: semester.value, label: year.text + ' / ' + semester.text });\r\n    const defaultSelection = makeSelection(options.yearOptions[options.defaultYearIndex], options.semesterOptions[options.defaultSemesterIndex]);\r\n    const action = await select('确认导入学期', [\r\n        { value: 'default', text: '导入：' + defaultSelection.label },\r\n        { value: 'change', text: '更换学年、学期' }\r\n    ], 0);\r\n    if (!action) return null;\r\n    if (action.value === 'default') return defaultSelection;\r\n    const year = await select('选择学年', options.yearOptions, options.defaultYearIndex);\r\n    if (!year) return null;\r\n    const semester = await select('选择学期', options.semesterOptions, options.defaultSemesterIndex);\r\n    if (!semester) return null;\r\n    return makeSelection(year, semester);\r\n}\r\n\r\n// 参考 JSEI 的移动端作息接口，以当前登录会话请求，不从课程推断校区。\r\n// 两校省略 xqh_id 时的返回结果仍需账号实测，失败时明确提示，不猜测校区。\r\nasync function fetchTimeSlots(xnm, xqm) {\r\n    let data;\r\n    try {\r\n        data = await requestHaue('jzgl/skxxMobile_cxRsdjc.html', { xnm, xqm }, 'N2154');\r\n    } catch (error) {\r\n        const serverError = String(error.message || error).match(/HTTP 5\\d\\d\\b/);\r\n        if (serverError) throw new Error('教务作息接口异常（' + serverError[0] + '），请稍后重试或联系维护者');\r\n        throw new Error('获取教务作息失败：' + error.message + '。请检查登录状态，或将该作息请求的响应提供给维护者核对');\r\n    }\r\n    try { return parseTimeSlots(data); }\r\n    catch (error) { throw new Error('作息数据无法解析：' + error.message + '。本次尚未保存，请将此提示或作息接口响应提供给维护者核对'); }\r\n}\r\n\r\n// 参考 JSEI 的合并规则；按课程、星期、周次先合并重叠/连续区间，避免重复排课。\r\nfunction mergeAndDistinctCourses(courses) {\r\n    if (!Array.isArray(courses)) return courses;\r\n    if (courses.length <= 1) return courses.map(c => ({ ...c, weeks: [...(c.weeks || [])] }));\r\n    const groups = new Map();\r\n    for (const course of courses) {\r\n        const key = JSON.stringify([course.name, course.teacher, course.position, course.day]);\r\n        if (!groups.has(key)) groups.set(key, { course, byWeek: new Map() });\r\n        const group = groups.get(key);\r\n        for (const week of new Set(course.weeks)) {\r\n            if (!group.byWeek.has(week)) group.byWeek.set(week, []);\r\n            group.byWeek.get(week).push({ start: course.startSection, end: course.endSection });\r\n        }\r\n    }\r\n    const result = [];\r\n    for (const group of groups.values()) {\r\n        const bySection = new Map();\r\n        for (const [week, intervals] of group.byWeek) {\r\n            intervals.sort((a, b) => a.start - b.start || a.end - b.end);\r\n            const merged = [];\r\n            for (const interval of intervals) {\r\n                const previous = merged[merged.length - 1];\r\n                if (previous && interval.start <= previous.end + 1) previous.end = Math.max(previous.end, interval.end);\r\n                else merged.push({ ...interval });\r\n            }\r\n            for (const interval of merged) {\r\n                const key = interval.start + '-' + interval.end;\r\n                if (!bySection.has(key)) bySection.set(key, { ...group.course, startSection: interval.start, endSection: interval.end, weeks: [] });\r\n                bySection.get(key).weeks.push(week);\r\n            }\r\n        }\r\n        for (const course of bySection.values()) {\r\n            course.weeks.sort((a, b) => a - b);\r\n            result.push(course);\r\n        }\r\n    }\r\n    return result;\r\n}\r\n\r\nfunction parseWeeks(value) {\r\n    const weeks = new Set();\r\n    const text = normalizeText(value).replace(/（/g, '(').replace(/）/g, ')').replace(/周/g, '').replace(/[，、]/g, ',');\r\n    for (const part of text.split(',')) {\r\n        const match = part.trim().match(/^(\\d+)\\s*(?:-\\s*(\\d+))?\\s*(?:\\(([单双])\\))?$/);\r\n        if (!match) throw new Error('无法识别周次：' + value);\r\n        const start = +match[1], end = +(match[2] || match[1]);\r\n        if (start < 1 || end < start || end > 60) throw new Error('周次范围异常：' + value);\r\n        for (let week = start; week <= end; week++) {\r\n            if (match[3] === '单' && week % 2 === 0) continue;\r\n            if (match[3] === '双' && week % 2 === 1) continue;\r\n            weeks.add(week);\r\n        }\r\n    }\r\n    if (!weeks.size) throw new Error('课程周次为空');\r\n    return Array.from(weeks).sort((a, b) => a - b);\r\n}\r\n\r\nfunction joinField(value) {\r\n    return Array.isArray(value) ? value.join('、') : String(value || '').trim();\r\n}\r\n\r\nfunction parseCourses(data, warnings = []) {\r\n    if (!data || !Array.isArray(data.kbList)) throw new Error('未收到课表数据，请确认登录状态及所在页面');\r\n    const courses = [];\r\n    for (const row of data.kbList) {\r\n      try {\r\n        const name = String(row.kcmc || '').trim();\r\n        const section = normalizeText(row.jcs || row.jc).trim().match(/^(\\d+)\\s*(?:-\\s*(\\d+))?\\s*节?$/);\r\n        const day = +normalizeText(row.xqj);\r\n        if (!name || !section || !/^[1-7]$/.test(normalizeText(row.xqj))) throw new Error('课程排课信息异常：' + (name || '未命名课程'));\r\n        const startSection = +section[1], endSection = +(section[2] || section[1]);\r\n        if (startSection < 1 || endSection < startSection || endSection > 30) throw new Error('节次异常：' + name);\r\n        courses.push({ name, day, weeks: parseWeeks(row.zcd), teacher: joinField(row.xm), position: joinField(row.cdmc), startSection, endSection });\r\n      } catch (error) { warnings.push('跳过课程 ' + String(row && row.kcmc || '未命名') + '：' + error.message); }\r\n    }\r\n    return mergeAndDistinctCourses(courses);\r\n}\r\n\r\nfunction parseTimeSlots(data) {\r\n    if (!Array.isArray(data) || !data.length) throw new Error('未收到有效的作息列表');\r\n    const byNumber = new Map();\r\n    const describe = value => String(value == null ? '缺失' : value).slice(0, 60);\r\n    for (let i = 0; i < data.length; i++) {\r\n        const row = data[i];\r\n        if (!row || typeof row !== 'object') throw new Error('第 ' + (i + 1) + ' 条作息不是有效记录');\r\n        const section = normalizeText(row.jcmc).trim();\r\n        const number = +section;\r\n        if (!/^\\d+$/.test(section) || number < 1 || number > 30) {\r\n            throw new Error('第 ' + (i + 1) + ' 条作息的节次无法识别（jcmc=' + describe(row.jcmc) + '）');\r\n        }\r\n        let startTime, endTime;\r\n        try { startTime = normalizeTime(row.qssj); endTime = normalizeTime(row.jssj); }\r\n        catch (_) { throw new Error('第 ' + number + ' 节时间无法识别（qssj=' + describe(row.qssj) + '，jssj=' + describe(row.jssj) + '）'); }\r\n        if (startTime >= endTime) throw new Error('第 ' + number + ' 节起止时间异常：' + startTime + '–' + endTime);\r\n        const existing = byNumber.get(number);\r\n        if (existing) {\r\n            // 接口可能重复返回同一节次；完全相同的作息只保留一条，不选择相互冲突的时间。\r\n            if (existing.startTime === startTime && existing.endTime === endTime) continue;\r\n            throw new Error('第 ' + number + ' 节返回不同时间：' + existing.startTime + '–' + existing.endTime + ' 与 ' + startTime + '–' + endTime);\r\n        }\r\n        byNumber.set(number, { number, startTime, endTime });\r\n    }\r\n    const slots = Array.from(byNumber.values()).sort((a, b) => a.number - b.number);\r\n    for (let i = 1; i < slots.length; i++) {\r\n        if (slots[i].startTime < slots[i - 1].endTime) throw new Error('第 ' + slots[i - 1].number + ' 节与第 ' + slots[i].number + ' 节作息时间重叠');\r\n    }\r\n    return slots;\r\n}\r\n\r\nasync function requestHaue(path, params, moduleId = 'N2151') {\r\n    const response = await fetch(getBaseUrl() + path + '?gnmkdm=' + encodeURIComponent(moduleId), {\r\n        method: 'POST', credentials: 'same-origin',\r\n        headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8', 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },\r\n        body: new URLSearchParams(params).toString()\r\n    });\r\n    if (!response.ok) throw new Error('教务请求失败（HTTP ' + response.status + '）');\r\n    const text = await response.text();\r\n    try { return JSON.parse(text); }\r\n    catch (_) {\r\n        // 有效 JSON 中的课程名可能含登录关键词，不能按内容关键词拦截。\r\n        assertNotLoginPage(text);\r\n        throw new Error('教务未返回 JSON 数据，请重新登录后重试');\r\n    }\r\n}\r\n\r\nasync function saveWithConfirmation(bridge, method, data, label) {\r\n    const result = await bridge[method](JSON.stringify(data));\r\n    if (result !== true && result !== 'true') throw new Error(label + '保存未成功，请重试并核对');\r\n}\r\n\r\nasync function runImportFlow() {\r\n    const bridge = window.shiguangBridgePromise;\r\n    let coursesSaved = false;\r\n    let saveStage = '课程';\r\n    try {\r\n        const selection = await selectAcademicYearAndSemester(bridge);\r\n        if (!selection) return;\r\n        const { xnm, xqm } = selection;\r\n        window.shiguangBridge.showToast('正在获取课程、校历和作息…');\r\n        const warnings = [];\r\n        const [data, config, slots] = await Promise.all([\r\n            requestHaue('kbcx/xskbcx_cxXsgrkb.html', { xnm, xqm, kzlx: 'ck', xsdm: '', kclbdm: '', kclxdm: '' }),\r\n            fetchSemesterConfig(xnm, xqm, warnings),\r\n            fetchTimeSlots(xnm, xqm)\r\n        ]);\r\n        let courses = parseCourses(data, warnings);\r\n        if (!courses.length) throw new Error('没有可导入的有效课程，请核对学期。\\n' + warnings.join('\\n'));\r\n        const numbers = new Set(slots.map(slot => slot.number));\r\n        courses = courses.filter(course => {\r\n            for (let n = course.startSection; n <= course.endSection; n++) {\r\n                if (!numbers.has(n)) { warnings.push('跳过课程 ' + course.name + '：第 ' + n + ' 节缺少作息'); return false; }\r\n            }\r\n            return true;\r\n        });\r\n        if (!courses.length) throw new Error('没有可导入的有效课程。\\n' + warnings.join('\\n'));\r\n        if (config.semesterTotalWeeks) {\r\n            for (const course of courses) {\r\n                if (course.weeks[course.weeks.length - 1] > config.semesterTotalWeeks) {\r\n                    delete config.semesterTotalWeeks;\r\n                    warnings.push('校历总周数小于课程周次，未保存总周数，请手动核对');\r\n                    break;\r\n                }\r\n            }\r\n        }\r\n        const practices = Array.isArray(data.sjkList) ? data.sjkList : [];\r\n        const practiceNote = practices.length ? '\\n\\n以下实践课没有具体星期和节次，本次不导入，请另行核对安排：\\n' + practices.map(row => String(row.kcmc || '未命名实践课') + '（' + String(row.qsjsz || '周次未定') + '）').join('\\n') : '';\r\n        const message = selection.label + '\\n共 ' + courses.length + ' 条排课记录。教务返回的作息如下，请核对：\\n' + slots.map(slot => '第' + slot.number + '节 ' + slot.startTime + '–' + slot.endTime).join('\\n') + practiceNote + '\\n\\n开学日期：' + (config.semesterStartDate || '需手动设置') + '\\n学期总周数：' + (config.semesterTotalWeeks || '需手动设置') + (warnings.length ? '\\n\\n注意：\\n' + warnings.join('\\n') : '');\r\n        const confirmed = await bridge.showAlert('核对课程与作息', message, '确认并保存');\r\n        if (confirmed !== true && confirmed !== 'true') return;\r\n        await saveWithConfirmation(bridge, 'saveImportedCourses', courses, '课程');\r\n        coursesSaved = true;\r\n        saveStage = '作息';\r\n        await saveWithConfirmation(bridge, 'savePresetTimeSlots', slots, '作息');\r\n        saveStage = '学期配置';\r\n        await saveWithConfirmation(bridge, 'saveCourseConfig', config, '学期配置');\r\n        window.shiguangBridge.showToast('已导入 ' + courses.length + ' 条排课记录及作息，请核对学期配置');\r\n        window.shiguangBridge.notifyTaskCompletion();\r\n    } catch (error) {\r\n        await bridge.showAlert('导入未完成', (coursesSaved ? '课程已保存，但' + saveStage + '未保存成功，请重试并核对。\\n' : '') + error.message, '确定');\r\n    }\r\n}\r\n\r\nrunImportFlow();\r\n","HNSF_01":"// 河南师范大学(htu.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    \n    // 假设新接口的 'zc' 字段已经是逗号分隔的周次数字字符串\n    const weeks = weekStr.split(',')\n        .map(w => Number(w.trim())) // 转换为数字\n        .filter(w => !isNaN(w) && w > 0); // 过滤掉无效数字\n\n    // 去重并排序\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseJsonData(jsonData) {\n    console.log(\"JS: parseJsonData 正在解析 JSON 数据...\");\n    \n    // 检查JSON结构\n    if (!jsonData || jsonData.code !== 0 || !Array.isArray(jsonData.data)) {\n        console.warn(\"JS: JSON 数据结构错误或code不为0。\");\n        return [];\n    }\n\n    const rawCourseList = jsonData.data;\n    const finalCourseList = [];\n\n    for (const rawCourse of rawCourseList) {\n        // 关键字段检查\n        if (!rawCourse.kcmc || !rawCourse.teaxms || !rawCourse.jxcdmc || \n            !rawCourse.xq || !rawCourse.ps || !rawCourse.pe || !rawCourse.zc) {\n            // console.warn(\"JS: 发现缺少关键字段的课程记录，跳过。\", rawCourse);\n            continue;\n        }\n\n        const weeksArray = parseWeeks(rawCourse.zc);\n        \n        // 周次有效性检查\n        if (weeksArray.length === 0) {\n             // console.warn(`JS: 课程 ${rawCourse.kcmc} 周次解析失败或为空，跳过。`);\n             continue;\n        }\n\n        const day = Number(rawCourse.xq); // xq: 星期几 (周一为1)\n        const startSection = Number(rawCourse.ps);\n        const endSection = Number(rawCourse.pe);\n        \n        // 数字有效性检查\n        if (isNaN(day) || isNaN(startSection) || isNaN(endSection) || day < 1 || day > 7 || startSection > endSection) {\n             // console.warn(`JS: 课程 ${rawCourse.kcmc} 星期或节次数据无效，跳过。`);\n             continue;\n        }\n\n        finalCourseList.push({\n            name: rawCourse.kcmc.trim(),\n            teacher: rawCourse.teaxms.trim(),\n            position: rawCourse.jxcdmc.trim(),\n            day: day, \n            startSection: startSection,\n            endSection: endSection, \n            weeks: weeksArray\n        });\n    }\n\n    finalCourseList.sort((a, b) =>\n        a.day - b.day ||\n        a.startSection - b.startSection ||\n        a.name.localeCompare(b.name)\n    );\n    \n    console.log(`JS: JSON 数据解析完成，共找到 ${finalCourseList.length} 门课程。`);\n    return finalCourseList;\n}\n\n\nfunction isLoginPage() {\n    const url = window.location.href;\n    \n    const expectedBaseUrl = 'https://jwc.htu.edu.cn';\n    \n    const cleanUrl = url.endsWith('/') ? url.slice(0, -1) : url;\n    const isRootLogin = cleanUrl === expectedBaseUrl; \n\n    const isKeywordLogin = url.includes('login') || url.includes('cas');\n    \n    return url.includes('htu.edu.cn') && (isRootLogin || isKeywordLogin);\n}\n\nfunction validateYearInput(input) {\n    console.log(\"JS: validateYearInput 被调用，输入: \" + input);\n    if (/^[0-9]{4}$/.test(input)) {\n        console.log(\"JS: validateYearInput 验证通过。\");\n        return false;\n    } else {\n        console.log(\"JS: validateYearInput 验证失败。\");\n        return \"请输入四位数字的学年！\";\n    }\n}\nasync function promptUserToStart() {\n    console.log(\"JS: 流程开始：显示公告。\");\n    return await window.shiguangBridgePromise.showAlert(\n        \"教务系统课表导入\",\n        \"导入前请确保您已在浏览器中成功登录教务系统\",\n        \"好的，开始导入\"\n    );\n}\n\nasync function getAcademicYear() {\n    const currentYear = new Date().getFullYear().toString();\n    console.log(\"JS: 提示用户输入学年。\");\n    return await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\",\n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        currentYear,\n        \"validateYearInput\"\n    );\n}\n\nasync function selectSemester() {\n    const semesters = [\"第一学期 (01)\", \"第二学期 (02)\"];\n    console.log(\"JS: 提示用户选择学期。\");\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\",\n        JSON.stringify(semesters),\n        0\n    );\n    return semesterIndex;\n}\n\nasync function fetchAndParseCourses(academicYear, semesterIndex) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n\n    // 学年学期代码组合：202501 (第一学期), 202502 (第二学期)\n    // semesterIndex 0 对应 01, 1 对应 02\n    const semesterCode = semesterIndex === 0 ? \"01\" : \"02\"; \n    const xnxqdmBody = `xnxqdm=${academicYear}${semesterCode}`;\n    const url = \"https://jwc.htu.edu.cn/new/student/xsgrkb/getCalendarWeekDatas\";\n\n    console.log(`JS: 发送请求到 ${url}, body: ${xnxqdmBody}`);\n\n    const requestOptions = {\n        \"headers\": {\n            \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n        },\n        \"body\": xnxqdmBody,\n        \"method\": \"POST\",\n        \"credentials\": \"include\"\n    };\n\n    try {\n        const response = await fetch(url, requestOptions);\n\n        if (!response.ok) {\n            throw new Error(`网络请求失败。状态码: ${response.status} (${response.statusText})`);\n        }\n        \n        const jsonText = await response.text();\n        let jsonData;\n        try {\n            jsonData = JSON.parse(jsonText);\n        } catch (e) {\n            console.error('JS: JSON 解析失败:', e);\n            window.shiguangBridge.showToast(\"数据返回格式错误，可能是您未成功登录或会话已过期。\");\n            return null;\n        }\n\n        const courses = parseJsonData(jsonData);\n\n        if (courses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据，请检查所选学年学期是否正确或本学期无课。\");\n            return null;\n        }\n\n        console.log(`JS: 课程数据解析成功，共找到 ${courses.length} 门课程。`);\n\n        return { courses: courses };\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求或解析失败: ${error.message}`);\n        console.error('JS: Fetch/Parse Error:', error);\n        return null;\n    }\n}\n\n\nasync function saveCourses(parsedCourses) {\n    window.shiguangBridge.showToast(`正在保存 ${parsedCourses.length} 门课程...`);\n    console.log(`JS: 尝试保存 ${parsedCourses.length} 门课程...`);\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(parsedCourses, null, 2));\n        console.log(\"JS: 课程保存成功！\");\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程保存失败: ${error.message}`);\n        console.error('JS: Save Courses Error:', error);\n        return false;\n    }\n}\n\nconst Non_summerTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 6, startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 7, startTime: \"16:40\", endTime: \"17:25\" },\n    { number: 8, startTime: \"17:35\", \"endTime\": \"18:20\" },\n    { number: 9, startTime: \"19:30\", \"endTime\": \"20:15\" },\n    { number: 10, startTime: \"20:25\", \"endTime\": \"21:10\" }\n];\nconst SummerTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:10\", endTime: \"10:55\" },\n    { number: 4, startTime: \"11:05\", endTime: \"11:50\" },\n    { number: 5, startTime: \"15:00\", endTime: \"15:45\" },\n    { number: 6, startTime: \"15:55\", endTime: \"16:40\" },\n    { number: 7, startTime: \"17:10\", endTime: \"17:55\" },\n    { number: 8, startTime: \"18:05\", \"endTime\": \"18:50\" },\n    { number: 9, startTime: \"20:00\", \"endTime\": \"20:45\" },\n    { number: 10, startTime: \"20:55\", \"endTime\": \"21:40\" }\n];\nconst NewCampusTimeSlots = [\n     { number: 1, startTime: \"08:30\", endTime: \"09:15\" },\n    { number: 2, startTime: \"09:25\", endTime: \"10:10\" },\n    { number: 3, startTime: \"10:30\", endTime: \"11:15\" },\n    { number: 4, startTime: \"11:25\", endTime: \"12:10\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"16:00\", endTime: \"16:45\" },\n    { number: 8, startTime: \"16:55\", \"endTime\": \"17:40\" },\n    { number: 9, startTime: \"18:40\", \"endTime\": \"19:25\" },\n    { number: 10, startTime: \"19:35\", \"endTime\": \"20:20\" }\n]\n\nasync function selectCampus() {\n    const campusOptions = [\"建设东路校区/平原湖校区\", \"创新港校区\"]\n    console.log(\"JS: 提示用户选择校区。\");\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择校区\",\n        JSON.stringify(campusOptions),\n        0\n    );\n    return selectedIndex;\n}\n\nasync function selectTimeSlotsType() {\n    const timeSlotsOptions = [\"非夏季作息\", \"夏季作息\"];\n    console.log(\"JS: 提示用户选择作息时间类型。\");\n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择作息时间\",\n        JSON.stringify(timeSlotsOptions),\n        0\n    );\n    return selectedIndex;\n}\n\nasync function importPresetTimeSlots(timeSlots) {\n    console.log(`JS: 准备导入 ${timeSlots.length} 个预设时间段。`);\n\n    if (timeSlots.length > 0) {\n        window.shiguangBridge.showToast(`正在导入 ${timeSlots.length} 个预设时间段...`);\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n            window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n            console.log(\"JS: 预设时间段导入成功。\");\n        } catch (error) {\n            window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n            console.error('JS: Save Time Slots Error:', error);\n        }\n    } else {\n        window.shiguangBridge.showToast(\"警告：时间段为空，未导入时间段信息。\");\n        console.warn(\"JS: 警告：传入时间段为空，未导入时间段信息。\");\n    }\n}\n\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast(\"导入失败：请先登录教务系统！\");\n        console.log(\"JS: 检测到当前在登录页面，终止导入。\");\n        return;\n    }\n\n    // 1. 公告和前置检查。\n    const alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        console.log(\"JS: 用户取消了导入流程。\");\n        return;\n    }\n\n    const academicYear = await getAcademicYear();\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 获取学年失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学年: ${academicYear}`);\n\n\n    const semesterIndex = await selectSemester();\n    if (semesterIndex === null || semesterIndex === -1) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        console.log(\"JS: 选择学期失败/取消，流程终止。\");\n        return;\n    }\n    console.log(`JS: 已选择学期索引: ${semesterIndex}`);\n\n    // 2. 获取并解析课程\n    const result = await fetchAndParseCourses(academicYear, semesterIndex);\n    if (result === null) {\n        console.log(\"JS: 课程获取或解析失败，流程终止。\");\n        return;\n    }\n    const { courses } = result;\n\n    // 3. 课程数据保存。\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        console.log(\"JS: 课程保存失败，流程终止。\");\n        return;\n    }\n\n    // 4. 作息时间选择与导入\n    const campusIndex = await selectCampus();\n    let selectedTimeSlots = [];\n    if (campusIndex === 0) {\n        // 0: 建设东路校区/平原湖校区\n        const timeSlotsIndex = await selectTimeSlotsType();\n        if (timeSlotsIndex === 0) {\n            // 0: 非夏季作息\n            selectedTimeSlots = Non_summerTimeSlots;\n            console.log(\"JS: 已选择非夏季作息。\");\n        } else if (timeSlotsIndex === 1) {\n            // 1: 夏季作息\n            selectedTimeSlots = SummerTimeSlots;\n            console.log(\"JS: 已选择夏季作息。\");\n        } else {\n            selectedTimeSlots = Non_summerTimeSlots;\n            console.warn(\"JS: 作息时间选择失败/取消，使用非夏季作息作为默认值。\");\n        }\n    } else if (campusIndex === 1) {\n        // 1: 创新港校区\n        selectedTimeSlots = NewCampusTimeSlots;\n        console.log(\"JS: 已选择创新港校区作息。\");\n    }\n    await importPresetTimeSlots(selectedTimeSlots);\n\n\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS: 整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();","HNSF_02":"// ====================== 工具函数 ======================\n\n/**\n * 检查用户是否已登录。\n * 如果当前URL包含登录关键字，说明用户未登录，返回false。\n * 如果不包含登录关键字，说明用户已登录，返回true。\n */\nfunction isUserLoggedIn() {\n    const url = window.location.href;\n    const loginKeywords = [\n        \"https://jwc.htu.edu.cn/xtgl/login_slogin.html\"\n    ];\n    \n    // 检查URL是否包含登录关键字\n    for (const keyword of loginKeywords) {\n        if (url.includes(keyword)) {\n            return false; // 包含登录关键字，说明用户未登录\n        }\n    }\n    \n    // 不包含登录关键字，说明用户已登录\n    return true;\n}\n\n// 展开 weeks 字符串 -> 数字数组\nfunction parseWeeks(weeksStr) {\n    const weeks = new Set();\n    if (!weeksStr) return [];\n    const parts = weeksStr.split(\",\");\n    for (const part of parts) {\n        if (part.includes(\"-\")) {\n            const [start, end] = part.split(\"-\").map(n => parseInt(n));\n            for (let i = start; i <= end && i <= 20; i++) {\n                weeks.add(i);\n            }\n        } else {\n            const n = parseInt(part);\n            if (n >= 1 && n <= 20) weeks.add(n);\n        }\n    }\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\n// 合并重复课程\nfunction mergeDuplicateCourses(courses) {\n    const merged = [];\n    const keyMap = {}; // key = name+day+startSection+endSection+position\n\n    for (const c of courses) {\n        const key = `${c.name}|${c.day}|${c.startSection}|${c.endSection}|${c.position}`;\n        if (!keyMap[key]) {\n            keyMap[key] = { ...c, weeks: [...c.weeks] };\n        } else {\n            keyMap[key].weeks = Array.from(new Set([...keyMap[key].weeks, ...c.weeks]));\n        }\n    }\n\n    for (const k in keyMap) merged.push(keyMap[k]);\n    return merged;\n}\n\n\n\n// ====================== 选择月份 ======================\nasync function selectMonth() {\n    try {\n        // 生成月份选项\n        const months = [];\n        const currentYear = new Date().getFullYear();\n        \n        // 生成当前学年（9月到次年6月）的月份选项\n        for (let month = 9; month <= 12; month++) {\n            months.push(`${currentYear}年${month}月`);\n        }\n        for (let month = 1; month <= 6; month++) {\n            months.push(`${currentYear + 1}年${month}月`);\n        }\n        \n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"请选择要获取课程的月份\",\n            JSON.stringify(months),\n            0\n        );\n        \n        if (selectedIndex === null) return null;\n        \n        const selectedMonth = months[selectedIndex];\n        const year = parseInt(selectedMonth.split('年')[0]);\n        const month = parseInt(selectedMonth.split('年')[1].split('月')[0]);\n        \n        // 计算该月的开始和结束日期\n        const startDate = new Date(year, month - 1, 1);\n        const endDate = new Date(year, month, 0); // 该月最后一天\n        \n        return {\n            startDate: startDate,\n            endDate: endDate,\n            year: year,\n            month: month\n        };\n    } catch (err) {\n        console.error(\"选择月份失败:\", err);\n        return null;\n    }\n}\n\n// ====================== 异步获取课程数据 ======================\nasync function fetchCoursesData() {\n    try {\n        // 让用户选择月份\n        const monthSelection = await selectMonth();\n        if (!monthSelection) {\n            window.shiguangBridge.showToast(\"用户取消选择月份！\");\n            return null;\n        }\n        \n        // 格式化日期为API需要的格式\n        const formatDate = (date) => {\n            const year = date.getFullYear();\n            const month = String(date.getMonth() + 1).padStart(2, '0');\n            const day = String(date.getDate()).padStart(2, '0');\n            return `${year}-${month}-${day}+00%3A00%3A00`;\n        };\n        \n        const d1 = formatDate(monthSelection.startDate);\n        const d2 = formatDate(monthSelection.endDate);\n        \n        \n        const res = await fetch(\"https://jwc.htu.edu.cn/new/desktop/getCalendar\", {\n            method: 'POST',\n            headers: {\n                'Content-Type': 'application/x-www-form-urlencoded',\n            },\n            body: `d1=${d1}&d2=${d2}`\n        });\n        const json = await res.json();\n        \n        \n        return json; // 直接返回课程数据数组\n    } catch (err) {\n        console.error(\"获取课程数据失败:\", err);\n        window.shiguangBridge.showToast(\"获取课程数据失败：\" + err.message);\n        return null;\n    }\n}\n\n// ====================== 处理新格式的课程数据 ======================\nasync function processCoursesData(coursesData) {\n    if (!coursesData || !Array.isArray(coursesData)) {\n        return null;\n    }\n\n    const allCourses = [];\n\n    coursesData.forEach((course) => {\n        // 解析节次代码 (如 \"0910\" -> 第9节到第10节)\n        const jcdm = course.jcdm || \"\";\n        if (!jcdm || jcdm.length < 4) {\n            return;\n        }\n\n        const startSection = parseInt(jcdm.substring(0, 2));\n        const endSection = parseInt(jcdm.substring(2, 4));\n        \n        // 解析周次 (如 \"10\" -> [10])\n        const weeks = parseWeeks(course.zc || \"\");\n        if (!weeks.length) {\n            return;\n        }\n\n        // 解析星期 (如 \"3\" -> 星期三)\n        const day = parseInt(course.xq || \"1\");\n        if (day < 1 || day > 7) {\n            return;\n        }\n\n        // 处理地点格式，按照 [校本部]西校区新联楼0303 的格式\n        let position = course.jxcdmc || \"\";\n        const xqmc = course.xqmc || \"校本部\";\n        if (position && !position.startsWith(\"[\")) {\n            position = `[${xqmc}]${position}`;\n        }\n\n        const processedCourse = {\n            name: course.kcmc || \"\",\n            teacher: course.teaxms || \"\",\n            position: position,\n            day: day,\n            startSection: startSection,\n            endSection: endSection,\n            weeks: weeks\n        };\n        \n        allCourses.push(processedCourse);\n    });\n\n    const mergedCourses = mergeDuplicateCourses(allCourses);\n    \n    return mergedCourses.length ? mergedCourses : null;\n}\n\n// ====================== 保存课程 ======================\nasync function saveCourses(courses) {\n    try {\n        const result = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (result === true) {\n            window.shiguangBridge.showToast(\"课程导入成功！\");\n            return true;\n        } else {\n            window.shiguangBridge.showToast(\"课程导入失败，请查看日志！\");\n            return false;\n        }\n    } catch (err) {\n        console.error(\"保存课程失败:\", err);\n        window.shiguangBridge.showToast(\"保存课程失败：\" + err.message);\n        return false;\n    }\n}\n\n// ====================== 导入预设时间段（一天5节大课，10节小课） ======================\nasync function importPresetTimeSlots() {\n    // 一天5节大课，10节小课的时间安排\n    const presetTimeSlots = [\n        { number: 1, startTime: \"08:00\", endTime: \"08:45\" }, // 第1节\n        { number: 2, startTime: \"08:45\", endTime: \"09:30\" }, // 第2节\n        { number: 3, startTime: \"09:50\", endTime: \"10:35\" }, // 第3节\n        { number: 4, startTime: \"10:35\", endTime: \"11:20\" }, // 第4节\n        { number: 5, startTime: \"14:00\", endTime: \"14:45\" }, // 第5节\n        { number: 6, startTime: \"14:45\", endTime: \"15:30\" }, // 第6节\n        { number: 7, startTime: \"15:50\", endTime: \"16:35\" }, // 第7节\n        { number: 8, startTime: \"16:35\", endTime: \"17:20\" }, // 第8节\n        { number: 9, startTime: \"19:00\", endTime: \"19:45\" }, // 第9节\n        { number: 10, startTime: \"19:45\", endTime: \"20:30\" } // 第10节\n    ];\n    \n    try {\n        const result = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n        if (result === true) {\n            window.shiguangBridge.showToast(\"时间段导入成功！\");\n        } else {\n            window.shiguangBridge.showToast(\"时间段导入失败，请查看日志！\");\n        }\n    } catch (err) {\n        console.error(\"时间段导入失败:\", err);\n        window.shiguangBridge.showToast(\"时间段导入失败：\" + err.message);\n    }\n}\n\n\n// ====================== 显示公告 ======================\nasync function showAnnouncement() {\n    try {\n        const announcement = `\n课程导入工具使用说明：\n\n1. 本工具用于从教务系统获取课程数据\n2. 请确保已登录教务系统\n3. 选择要获取课程的月份\n4. 工具会自动下载原始数据和处理后的数据\n5. 支持一天10节课的时间安排\n6. 自动合并重复课程\n\n使用前请确认网络连接正常！\n        `.trim();\n        \n        await window.shiguangBridgePromise.showAlert(\n            \"课程导入工具公告\",\n            announcement\n        );\n    } catch (err) {\n        console.error(\"显示公告失败:\", err);\n        // 如果弹窗失败，使用Toast提示\n        window.shiguangBridge.showToast(\"课程导入工具启动中...\");\n    }\n}\n\n// ====================== 主流程 ======================\nasync function runImportFlow() {\n    // 检查用户是否已登录\n    if (!isUserLoggedIn()) {\n        window.shiguangBridge.showToast(\"检测到未登录状态，请先登录后再使用课程导入功能！\");\n        return;\n    }\n    \n    // 显示公告\n    await showAnnouncement();\n    \n    window.shiguangBridge.showToast(\"课程导入流程即将开始...\");\n\n    // 1️⃣ 获取课程数据\n    const coursesData = await fetchCoursesData();\n    if (!coursesData) {\n        return;\n    }\n\n    // 2️⃣ 处理课程数据\n    const courses = await processCoursesData(coursesData);\n    if (!courses) {\n        window.shiguangBridge.showToast(\"没有找到有效的课程数据！\");\n        return;\n    }\n\n    // 3️⃣ 保存课程\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    // 4️⃣ 导入预设时间段\n    await importPresetTimeSlots();\n\n    // ✅ 只有所有步骤都成功完成，才通知任务完成\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS：整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动流程\nrunImportFlow();\n","HPU_01":"// 文件: hpu.js\n// 河南理工大学 树维教务系统课程表导入脚本\n// 适配目标: zhjw.hpu.edu.cn (树维教务系统, Struts2 .action, /eams/ 路径) + uia.hpu.edu.cn 统一身份认证(CAS)\n// 数据链路(已对 HPU 线上服务器实测):\n//   1. GET  courseTableForStd.action?sf_request_type=ajax        → 解析 ids(学生) + tagId(学期栏)\n//   2. POST dataQuery.action (dataType=semesterCalendar)          → 学期列表\n//   3. POST courseTableForStd!courseTable.action (semester.id)    → 课表 HTML\n//      课表 HTML 内课程以 TaskActivity JS 块内嵌(unitCount=11, bitmap周次), 表格骨架含节次/时间\n//   4. 解析 TaskActivity → 课程; 解析 #manualArrangeCourseTable 节次格 → 时间段\n// 兜底: 若当前页面已是渲染后的课表页(#manualArrangeCourseTable + .infoTitle), 直接解析 DOM\n// 解析参考: HIIT/hiit_01.js (同款 eams 架构系统)\n(function () {\n    function showToast(message) {\n        if (typeof window.shiguangBridge !== \"undefined\" && window.shiguangBridge.showToast) {\n            window.shiguangBridge.showToast(String(message || \"\"));\n        } else {\n            console.log(\"[HPU适配]\", message);\n        }\n    }\n\n    async function request(url, options) {\n        const res = await fetch(url, { credentials: \"include\", ...(options || {}) });\n        if (!res.ok) throw new Error(\"网络请求失败(\" + res.status + \"): \" + url);\n        return await res.text();\n    }\n\n    // ================= 通用小工具 =================\n    const CN_DIGIT = { \"一\": 1, \"二\": 2, \"三\": 3, \"四\": 4, \"五\": 5, \"六\": 6, \"七\": 7, \"八\": 8, \"九\": 9 };\n    function cnDigit(c) { return CN_DIGIT[c] || 0; }\n    function cnToInt(s) {\n        if (!s) return 0;\n        if (s === \"十\") return 10;\n        const i = s.indexOf(\"十\");\n        if (i >= 0) {\n            const tens = i > 0 ? cnDigit(s.charAt(0)) : 1;\n            const ones = s.length > i + 1 ? cnDigit(s.charAt(i + 1)) : 0;\n            return tens * 10 + ones;\n        }\n        return cnDigit(s);\n    }\n\n    function splitJsArgs(argsText) {\n        const args = [];\n        let current = \"\";\n        let quote = \"\";\n        let escaped = false;\n        for (let i = 0; i < argsText.length; i++) {\n            const ch = argsText[i];\n            if (escaped) { current += ch; escaped = false; continue; }\n            if (ch === \"\\\\\") { current += ch; escaped = true; continue; }\n            if (quote) { current += ch; if (ch === quote) quote = \"\"; continue; }\n            if (ch === \"'\" || ch === \"\\\"\") { current += ch; quote = ch; continue; }\n            if (ch === \",\") { args.push(current.trim()); current = \"\"; continue; }\n            current += ch;\n        }\n        if (current.trim()) args.push(current.trim());\n        return args;\n    }\n\n    function unquoteJsLiteral(token) {\n        const text = String(token || \"\").trim();\n        if (!text || text === \"null\" || text === \"undefined\") return \"\";\n        if ((text.startsWith(\"\\\"\") && text.endsWith(\"\\\"\")) || (text.startsWith(\"'\") && text.endsWith(\"'\"))) {\n            const quote = text[0];\n            return text.slice(1, -1)\n                .replace(/\\\\\\\\/g, \"\\\\\")\n                .replace(new RegExp(\"\\\\\\\\\" + quote, \"g\"), quote)\n                .replace(/\\\\n/g, \"\\n\").replace(/\\\\r/g, \"\\r\").replace(/\\\\t/g, \"\\t\");\n        }\n        return text;\n    }\n\n    function parseValidWeeksBitmap(bitmap) {\n        const weeks = [];\n        const text = String(bitmap || \"\");\n        for (let i = 0; i < text.length; i++) {\n            if (text[i] === \"1\" && i >= 1) weeks.push(i);\n        }\n        return weeks;\n    }\n\n    function normalizeWeeks(weeks) {\n        return Array.from(new Set((weeks || []).filter(function (w) { return Number.isInteger(w) && w > 0; }))).sort(function (a, b) { return a - b; });\n    }\n\n    function cleanCourseName(name) {\n        return String(name || \"\").replace(/\\s*\\([^()]*\\)\\s*$/, \"\").trim();\n    }\n\n    function resolveTeachersForTaskActivityBlock(fullText, blockStartIndex) {\n        const start = Math.max(0, blockStartIndex - 2500);\n        const segment = fullText.slice(start, blockStartIndex);\n        const teachersRegex = /var\\s+teachers\\s*=\\s*\\[([^]*?)\\];/g;\n        let lastTeachersBlock = \"\";\n        let match;\n        while ((match = teachersRegex.exec(segment)) !== null) lastTeachersBlock = match[1] || \"\";\n        if (!lastTeachersBlock) return \"\";\n        const names = [];\n        const nameRegex = /name\\s*:\\s*(?:\"([^\"]*)\"|'([^']*)')/g;\n        let nameMatch;\n        while ((nameMatch = nameRegex.exec(lastTeachersBlock)) !== null) {\n            const name = (nameMatch[1] || nameMatch[2] || \"\").trim();\n            if (name) names.push(name);\n        }\n        return Array.from(new Set(names)).join(\",\");\n    }\n\n    // ================= 课程解析 (TaskActivity, 从 AJAX HTML) =================\n    function parseCoursesFromTaskActivityScript(htmlText) {\n        const text = String(htmlText || \"\");\n        const unitCountMatch = text.match(/\\bvar\\s+unitCount\\s*=\\s*(\\d+)\\s*;/);\n        const unitCount = unitCountMatch ? Number(unitCountMatch[1]) : 0;\n        if (!unitCount) return [];\n\n        const courses = [];\n        const blockRegex = /activity\\s*=\\s*new\\s+TaskActivity\\(([^]*?)\\)\\s*;([\\s\\S]*?)(?=activity\\s*=\\s*new\\s+TaskActivity\\(|table\\d+\\.marshalTable|$)/g;\n        let match;\n        while ((match = blockRegex.exec(text)) !== null) {\n            const args = splitJsArgs(match[1] || \"\");\n            if (args.length < 7) continue;\n\n            let teacher = unquoteJsLiteral(args[1]);\n            if (/join\\s*\\(/.test(String(args[1] || \"\"))) {\n                teacher = resolveTeachersForTaskActivityBlock(text, match.index) || teacher;\n            }\n            const name = cleanCourseName(unquoteJsLiteral(args[3]));\n            const position = String(unquoteJsLiteral(args[5]) || \"\").replace(/\\s+/g, \" \").trim();\n            const weeks = normalizeWeeks(parseValidWeeksBitmap(unquoteJsLiteral(args[6])));\n            if (!name) continue;\n\n            const indexBlock = match[2] || \"\";\n            const indexRegex = /index\\s*=\\s*(?:(\\d+)\\s*\\*\\s*unitCount\\s*\\+\\s*(\\d+)|(\\d+))\\s*;/g;\n            let indexMatch;\n            while ((indexMatch = indexRegex.exec(indexBlock)) !== null) {\n                let linearIndex = -1;\n                if (indexMatch[1] != null && indexMatch[2] != null) {\n                    linearIndex = Number(indexMatch[1]) * unitCount + Number(indexMatch[2]);\n                } else if (indexMatch[3] != null) {\n                    linearIndex = Number(indexMatch[3]);\n                }\n                if (linearIndex < 0) continue;\n                const day = Math.floor(linearIndex / unitCount) + 1;\n                const section = (linearIndex % unitCount) + 1;\n                if (day < 1 || day > 7) continue;\n                courses.push({\n                    name: name,\n                    teacher: teacher || \"未知教师\",\n                    position: position || \"待定\",\n                    day: day,\n                    startSection: section,\n                    endSection: section,\n                    weeks: weeks\n                });\n            }\n        }\n        return mergeContiguousSections(courses);\n    }\n\n    function mergeContiguousSections(courses) {\n        const normalized = (courses || []).map(function (c) {\n            return { ...c, weeks: normalizeWeeks(c.weeks) };\n        });\n        normalized.sort(function (a, b) {\n            const keyA = a.name + \"|\" + a.teacher + \"|\" + a.position + \"|\" + a.day + \"|\" + a.weeks.join(\",\");\n            const keyB = b.name + \"|\" + b.teacher + \"|\" + b.position + \"|\" + b.day + \"|\" + b.weeks.join(\",\");\n            if (keyA < keyB) return -1;\n            if (keyA > keyB) return 1;\n            return a.startSection - b.startSection;\n        });\n        const merged = [];\n        normalized.forEach(function (course) {\n            const previous = merged[merged.length - 1];\n            const canMerge = previous\n                && previous.name === course.name\n                && previous.teacher === course.teacher\n                && previous.position === course.position\n                && previous.day === course.day\n                && previous.weeks.join(\",\") === course.weeks.join(\",\")\n                && previous.endSection + 1 >= course.startSection;\n            if (canMerge) {\n                previous.endSection = Math.max(previous.endSection, course.endSection);\n            } else {\n                merged.push({ ...course });\n            }\n        });\n        return merged;\n    }\n\n    // ================= 时间段解析 (从 HTML 表格骨架) =================\n    function parseTimeSlotsFromHtml(htmlText) {\n        const doc = new DOMParser().parseFromString(String(htmlText || \"\"), \"text/html\");\n        const slots = [];\n        const slotMap = {};\n        const table = doc.querySelector(\"#manualArrangeCourseTable\");\n        if (!table) return slots;\n        table.querySelectorAll(\"tbody tr\").forEach(function (row) {\n            const cells = Array.from(row.querySelectorAll(\"td\"));\n            cells.forEach(function (cell) {\n                const txt = (cell.textContent || \"\").replace(/\\s+/g, \"\");\n                const m = txt.match(/第([一二三四五六七八九十]+)节/);\n                if (!m) return;\n                const tm = txt.match(/(\\d{1,2}:\\d{2})-(\\d{1,2}:\\d{2})/);\n                if (!tm) return;\n                const num = cnToInt(m[1]);\n                if (num && !slotMap[num]) {\n                    slotMap[num] = { number: num, startTime: tm[1], endTime: tm[2] };\n                }\n            });\n        });\n        Object.keys(slotMap).map(Number).sort(function (a, b) { return a - b; })\n            .forEach(function (k) { slots.push(slotMap[k]); });\n        return slots;\n    }\n\n    // ================= 兜底: DOM 解析(已渲染的课表页) =================\n    function parseCourseCellFromInfoTitle(raw) {\n        const clean = String(raw || \"\").replace(/;;;/g, \" \")\n            .replace(/[\\t\\r\\n]+/g, \" \").replace(/\\s+/g, \" \").trim();\n        const m = clean.match(/^(.+?)\\(\\d[\\d.]*\\)\\s*\\(([^)]*)\\)\\s*\\(([^)]+)\\)\\s*$/);\n        if (!m) return null;\n        const info = m[3];\n        const comma = info.indexOf(\",\");\n        if (comma < 0) return null;\n        // 周次字符串(可能含\"单3-17\"式样)直接转为 bitmap 语义\n        const weekStr = info.substring(0, comma).trim();\n        const weeks = [];\n        const segs = weekStr.replace(/周/g, \"\").split(/[,，;；]/);\n        segs.forEach(function (seg) {\n            const isEven = seg.indexOf(\"双\") >= 0;\n            const isOdd = seg.indexOf(\"单\") >= 0;\n            const cleanSeg = seg.replace(/[单双]/g, \"\").trim();\n            if (cleanSeg.indexOf(\"-\") >= 0) {\n                const p = cleanSeg.split(\"-\");\n                const s = parseInt(p[0], 10), e = parseInt(p[1], 10);\n                if (!isNaN(s) && !isNaN(e)) {\n                    for (let w = s; w <= e; w++) {\n                        if (isEven && w % 2 !== 0) continue;\n                        if (isOdd && w % 2 === 0) continue;\n                        weeks.push(w);\n                    }\n                }\n            } else {\n                const n = parseInt(cleanSeg, 10);\n                if (!isNaN(n) && n > 0) weeks.push(n);\n            }\n        });\n        const finalWeeks = Array.from(new Set(weeks)).sort(function (a, b) { return a - b; });\n        if (!finalWeeks.length) return null;\n        return {\n            name: m[1].trim(),\n            teacher: m[2].trim() || \"未知教师\",\n            position: info.substring(comma + 1).replace(/\\s+/g, \" \").trim() || \"待定\",\n            weeks: finalWeeks\n        };\n    }\n\n    function parseCoursesFromCurrentDom() {\n        const table = document.querySelector(\"#manualArrangeCourseTable\");\n        if (!table) return [];\n        const courses = [];\n        const seen = {};\n        table.querySelectorAll(\"tbody tr\").forEach(function (tr) {\n            const tds = Array.from(tr.querySelectorAll(\"td\"));\n            let labelIdx = -1, section = 0;\n            tds.forEach(function (td, i) {\n                const txt = (td.textContent || \"\").replace(/\\s+/g, \"\");\n                const m = txt.match(/第([一二三四五六七八九十]+)节/);\n                if (m) { labelIdx = i; section = cnToInt(m[1]); }\n            });\n            if (labelIdx < 0) return;\n            tds.forEach(function (td, i) {\n                if (i <= labelIdx) return;\n                if ((td.className || \"\").indexOf(\"infoTitle\") < 0) return;\n                const raw = td.getAttribute(\"title\") || td.textContent || \"\";\n                if (!raw.trim()) return;\n                const day = i - labelIdx - 1;\n                if (day < 0 || day > 6) return;\n                const parsed = parseCourseCellFromInfoTitle(raw);\n                if (!parsed) return;\n                const rowspan = td.rowSpan > 1 ? td.rowSpan : 1;\n                const key = [day, section, rowspan, parsed.name, parsed.teacher, parsed.position, parsed.weeks.join(\",\")].join(\"|\");\n                if (seen[key]) return;\n                seen[key] = 1;\n                courses.push({\n                    name: parsed.name, teacher: parsed.teacher, position: parsed.position,\n                    day: day + 1, startSection: section, endSection: section + rowspan - 1,\n                    weeks: parsed.weeks\n                });\n            });\n        });\n        return courses;\n    }\n\n    // ================= AJAX 链路 =================\n    async function detectParams() {\n        if (/cas\\/login|loginExt/i.test(window.location.href)) throw new Error(\"请先登录教务系统后再执行导入\");\n        const html = await request(window.location.origin + \"/eams/courseTableForStd.action?sf_request_type=ajax\", {\n            headers: { \"x-requested-with\": \"XMLHttpRequest\" }\n        });\n        const idsM = html.match(/bg\\.form\\.addInput\\(form,\"ids\",\"(\\d+)\"\\)/);\n        const tagM = html.match(/id=\"(semesterBar\\d+Semester)\"/);\n        return (idsM && tagM) ? { ids: idsM[1], tagId: tagM[1] } : null;\n    }\n\n    async function fetchSemesters(tagId) {\n        const raw = await request(window.location.origin + \"/eams/dataQuery.action?sf_request_type=ajax\", {\n            method: \"POST\",\n            headers: { \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\" },\n            body: \"tagId=\" + encodeURIComponent(tagId) + \"&dataType=semesterCalendar\"\n        });\n        const data = Function(\"return (\" + String(raw).trim() + \");\")();\n        const list = [];\n        if (data && data.semesters && typeof data.semesters === \"object\") {\n            Object.keys(data.semesters).forEach(function (k) {\n                (data.semesters[k] || []).forEach(function (s) {\n                    if (!s || !s.id) return;\n                    const term = String(s.name || \"\").trim();\n                    const termName = term === \"1\" ? \"第一学期\" : term === \"2\" ? \"第二学期\" : \"第\" + term + \"学期\";\n                    list.push({\n                        id: String(s.id),\n                        schoolYear: String(s.schoolYear || \"\").trim(),\n                        term: term,\n                        name: (String(s.schoolYear || \"\") + \"学年\" + termName).trim()\n                    });\n                });\n            });\n        }\n        return list;\n    }\n\n    // 按当前日期猜测所在学期(用于默认选中): 8-12月→该学年第一学期; 2-7月→上学年第二学期; 1月→上学年第一学期\n    function guessCurrentSemesterIndex(semesters) {\n        const now = new Date();\n        const y = now.getFullYear();\n        const m = now.getMonth() + 1;\n        let targetYear, targetTerm;\n        if (m >= 8) { targetYear = y; targetTerm = \"1\"; }\n        else if (m >= 2) { targetYear = y - 1; targetTerm = \"2\"; }\n        else { targetYear = y - 1; targetTerm = \"1\"; }\n        for (let i = 0; i < semesters.length; i++) {\n            const s = semesters[i];\n            if (s.schoolYear === targetYear + \"-\" + (targetYear + 1) && s.term === targetTerm) return i;\n        }\n        return semesters.length - 1;\n    }\n\n    async function fetchCourseHtml(params, semesterId) {\n        return await request(window.location.origin + \"/eams/courseTableForStd!courseTable.action?sf_request_type=ajax\", {\n            method: \"POST\",\n            headers: {\n                \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n                \"x-requested-with\": \"XMLHttpRequest\"\n            },\n            body: \"ignoreHead=1&setting.kind=std&startWeek=&semester.id=\" + encodeURIComponent(semesterId) + \"&ids=\" + encodeURIComponent(params.ids)\n        });\n    }\n\n    // ================= 保存 =================\n    async function save(courses, timeSlots) {\n        const okCourses = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (okCourses !== true) throw new Error(\"课程保存失败: \" + String(okCourses));\n        if (timeSlots && timeSlots.length) {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        }\n    }\n\n    // ================= 主流程 =================\n    async function runImportFlow() {\n        // ① 已在渲染后的课表页 → DOM 直解\n        let courses = parseCoursesFromCurrentDom();\n        let timeSlots = [];\n        if (courses.length) {\n            showToast(\"已从当前课表页解析到 \" + courses.length + \" 门课\");\n        } else {\n            // ② AJAX(可自选学期)\n            showToast(\"正在识别课表参数...\");\n            const params = await detectParams();\n            if (!params) throw new Error(\"未能自动识别课表参数，请登录后在任意教务页面重试\");\n            showToast(\"正在获取学期列表...\");\n            const semesters = await fetchSemesters(params.tagId);\n            if (!semesters.length) throw new Error(\"未获取到学期列表\");\n            const showList = semesters.slice(-12); // 只展示最近6年, 避免列表过长\n            const defaultIdx = Math.min(guessCurrentSemesterIndex(semesters), semesters.length - 1);\n            const showDefault = Math.max(0, defaultIdx - (semesters.length - showList.length));\n            const picked = await window.shiguangBridgePromise.showSingleSelection(\n                \"选择要导入的学期\",\n                JSON.stringify(showList.map(function (s) { return s.name; })),\n                showDefault\n            );\n            if (picked === null || picked < 0 || picked >= showList.length) throw new Error(\"已取消导入\");\n            showToast(\"正在获取 \" + showList[picked].name + \" 课表...\");\n            const html = await fetchCourseHtml(params, showList[picked].id);\n            courses = parseCoursesFromTaskActivityScript(html);\n            timeSlots = parseTimeSlotsFromHtml(html);\n            if (!courses.length) throw new Error(\"该学期未解析到课程，请确认有课或尝试其他学期\");\n        }\n        await save(courses, timeSlots);\n        showToast(\"导入成功，共 \" + courses.length + \" 门课程\");\n        if (typeof window.shiguangBridge !== \"undefined\" && window.shiguangBridge.notifyTaskCompletion) {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    }\n\n    (async function bootstrap() {\n        try {\n            await runImportFlow();\n        } catch (e) {\n            console.error(\"[HPU适配]\", e);\n            showToast(\"导入失败：\" + (e && e.message ? e.message : String(e)));\n        }\n    })();\n})();\n","HAUST":"// resources/HAUST/haust.js\n// 河南科技大学 - 新版树维教务\n\nasync function promptUserToStart() {\n    try {\n        var confirmed = await window.shiguangBridgePromise.showAlert(\n            \"教务系统课表导入\",\n            \"请按以下步骤操作：\\n\\n1. 先在浏览器中登录VPN\\n2. 进入教务系统\\n3. 点击【我的课表】\\n4. 确保课表已完整显示\\n5. 然后点击下方按钮开始导入\",\n            \"我已进入课表页面，开始导入\"\n        );\n        return confirmed === true;\n    } catch (error) {\n        console.error(\"显示弹窗出错:\", error);\n        return false;\n    }\n}\n\nasync function getSemesterList() {\n    try {\n        var response = await fetch(\"/eams/dataQuery.action\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: \"dataType=semesterCalendar&tagId=semesterBar&empty=true\",\n            credentials: \"include\"\n        });\n\n        if (!response.ok) {\n            throw new Error(\"请求失败: \" + response.status);\n        }\n\n        var text = await response.text();\n        var data = eval(\"(\" + text + \")\");\n\n        if (!data || !data.semesters) {\n            throw new Error(\"未找到学期数据\");\n        }\n\n        var allSemesters = [];\n        for (var key in data.semesters) {\n            if (key.startsWith(\"y\") && Array.isArray(data.semesters[key])) {\n                for (var i = 0; i < data.semesters[key].length; i++) {\n                    allSemesters.push(data.semesters[key][i]);\n                }\n            }\n        }\n\n        if (allSemesters.length === 0) {\n            throw new Error(\"学期列表为空\");\n        }\n\n        allSemesters.sort(function(a, b) {\n            var yearA = a.schoolYear.split(\"-\")[0];\n            var yearB = b.schoolYear.split(\"-\")[0];\n            if (yearB !== yearA) return parseInt(yearB) - parseInt(yearA);\n            return parseInt(b.name) - parseInt(a.name);\n        });\n\n        var semesterTexts = allSemesters.map(function(sem) {\n            return sem.schoolYear + \"学年第\" + sem.name + \"学期\";\n        });\n\n        var selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择学期\",\n            JSON.stringify(semesterTexts),\n            0\n        );\n\n        if (selectedIndex !== null && selectedIndex >= 0) {\n            window.shiguangBridge.showToast(\"已选择: \" + semesterTexts[selectedIndex]);\n            return allSemesters[selectedIndex];\n        }\n\n        return null;\n    } catch (error) {\n        console.error(\"获取学期出错:\", error);\n        window.shiguangBridge.showToast(\"获取学期出错: \" + error.message);\n        return null;\n    }\n}\n\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    var cleaned = weekStr.replace(/周/g, \"\").trim();\n    if (!cleaned) return [];\n\n    var weeks = [];\n    var parts = cleaned.split(\",\");\n\n    for (var p = 0; p < parts.length; p++) {\n        var trimmed = parts[p].trim();\n        if (!trimmed) continue;\n\n        var isOdd = trimmed.charAt(0) === \"单\";\n        var isEven = trimmed.charAt(0) === \"双\";\n        var rangeStr = isOdd || isEven ? trimmed.substring(1) : trimmed;\n\n        var ranges = rangeStr.split(/\\s+/);\n        for (var r = 0; r < ranges.length; r++) {\n            var range = ranges[r];\n            var rangeMatch = range.match(/^(\\d+)\\s*[-~]\\s*(\\d+)$/);\n            if (rangeMatch) {\n                var start = parseInt(rangeMatch[1], 10);\n                var end = parseInt(rangeMatch[2], 10);\n                for (var w = start; w <= end; w++) {\n                    if (isOdd && w % 2 === 0) continue;\n                    if (isEven && w % 2 === 1) continue;\n                    weeks.push(w);\n                }\n            } else {\n                var num = parseInt(range, 10);\n                if (!isNaN(num)) {\n                    if (isOdd && num % 2 === 0) continue;\n                    if (isEven && num % 2 === 1) continue;\n                    weeks.push(num);\n                }\n            }\n        }\n    }\n\n    weeks.sort(function(a, b) { return a - b; });\n    var unique = [];\n    var seen = {};\n    for (var i = 0; i < weeks.length; i++) {\n        if (!seen[weeks[i]]) {\n            unique.push(weeks[i]);\n            seen[weeks[i]] = true;\n        }\n    }\n    return unique;\n}\n\nfunction parsePeriod(periodStr) {\n    if (!periodStr) return null;\n    var match = periodStr.match(/(\\d+)\\s*[-~]\\s*(\\d+)/);\n    if (match) {\n        return { start: parseInt(match[1], 10), end: parseInt(match[2], 10) };\n    }\n    return null;\n}\n\nfunction stripHtml(html) {\n    if (!html) return \"\";\n    return html.replace(/<[^>]+>/g, \"\").trim();\n}\n\nfunction parseTitle(title) {\n    if (!title) return [];\n    var courses = [];\n    var cleanTitle = stripHtml(title);\n\n    // 格式: \"课程名(课程号) (教师);;;(周次,节次,教室)\"\n    // 先提取课程名、课程号、教师\n    var nameMatch = cleanTitle.match(/^(.+?)\\(([^)]+)\\)\\s*\\(([^)]+)\\)/);\n    if (!nameMatch) return [];\n\n    var courseName = nameMatch[1].trim();\n    var teacher = nameMatch[3].trim();\n\n    // 提取周次、节次、教室 - 找到含\"周\"的括号内容，手动提取到最后一个\")\"\n    var detailStart = cleanTitle.search(/\\(\\d+[-~]\\d+周/);\n    if (detailStart === -1) return [];\n\n    var lastParen = cleanTitle.lastIndexOf(\")\");\n    if (lastParen <= detailStart) return [];\n\n    var details = cleanTitle.substring(detailStart + 1, lastParen);\n    var parts = details.split(\",\");\n\n    var weeksStr = parts.length >= 1 ? parts[0].trim() : \"\";\n    var periodStr = parts.length >= 2 ? parts[1].trim() : \"\";\n    var room = parts.length >= 3 ? parts.slice(2).join(\",\").trim() : \"\";\n\n    var weeks = parseWeeks(weeksStr);\n    var period = parsePeriod(periodStr);\n\n    if (weeks.length > 0 && period) {\n        courses.push({\n            courseName: courseName,\n            teacher: teacher,\n            weeks: weeks,\n            startSection: period.start,\n            endSection: period.end,\n            room: room\n        });\n    }\n\n    return courses;\n}\n\nfunction tryFindCourseTable() {\n    // 方法1: 当前页面直接查找\n    var cells = document.querySelectorAll(\"td[title]\");\n    if (cells.length === 0) cells = document.querySelectorAll(\"td[id^='TD']\");\n    if (cells.length > 0) {\n        return { doc: document, cells: cells, source: \"current\" };\n    }\n\n    // 方法2: iframe\n    var iframes = document.querySelectorAll(\"iframe\");\n    for (var i = 0; i < iframes.length; i++) {\n        try {\n            var iframeDoc = iframes[i].contentDocument || iframes[i].contentWindow.document;\n            if (!iframeDoc) continue;\n\n            cells = iframeDoc.querySelectorAll(\"td[title]\");\n            if (cells.length === 0) cells = iframeDoc.querySelectorAll(\"td[id^='TD']\");\n            if (cells.length > 0) {\n                return { doc: iframeDoc, cells: cells, source: \"iframe\" };\n            }\n\n            // 方法3: iframe的iframe\n            var innerIframes = iframeDoc.querySelectorAll(\"iframe\");\n            for (var j = 0; j < innerIframes.length; j++) {\n                try {\n                    var innerDoc = innerIframes[j].contentDocument || innerIframes[j].contentWindow.document;\n                    if (!innerDoc) continue;\n\n                    cells = innerDoc.querySelectorAll(\"td[title]\");\n                    if (cells.length === 0) cells = innerDoc.querySelectorAll(\"td[id^='TD']\");\n                    if (cells.length > 0) {\n                        return { doc: innerDoc, cells: cells, source: \"inner-iframe\" };\n                    }\n                } catch (e) {}\n            }\n        } catch (e) {}\n    }\n\n    return null;\n}\n\nfunction parseCoursesFromTable(tableData) {\n    var allCourses = [];\n    var seenKeys = {};\n    var cells = tableData.cells;\n\n    for (var i = 0; i < cells.length; i++) {\n        var cell = cells[i];\n        var title = cell.getAttribute(\"title\");\n        if (!title || !title.trim()) continue;\n\n        var row = cell.parentElement;\n        if (!row) continue;\n\n        var rowCells = Array.from(row.cells);\n        var colIndex = rowCells.indexOf(cell);\n\n        var day = colIndex;\n        if (day < 1 || day > 7) continue;\n\n        var parsed = parseTitle(title);\n\n        for (var j = 0; j < parsed.length; j++) {\n            var course = parsed[j];\n            if (course.weeks.length === 0 || course.startSection === 0) continue;\n\n            var key = course.courseName + \"_\" + day + \"_\" + course.startSection + \"_\" + course.weeks.join(\",\");\n            if (seenKeys[key]) continue;\n            seenKeys[key] = true;\n\n            allCourses.push({\n                name: course.courseName,\n                teacher: course.teacher,\n                position: course.room,\n                day: day,\n                startSection: course.startSection,\n                endSection: course.endSection,\n                weeks: course.weeks\n            });\n        }\n    }\n\n    return allCourses;\n}\n\nasync function saveCourses(courses) {\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        return true;\n    } catch (error) {\n        window.shiguangBridge.showToast(\"课程保存失败: \" + error.message);\n        return false;\n    }\n}\n\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"开始导入...\");\n\n    var alertConfirmed = await promptUserToStart();\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"已取消导入\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在查找课表...\");\n\n    var tableData = tryFindCourseTable();\n    if (!tableData) {\n        window.shiguangBridge.showToast(\"未找到课表，请确保已进入【我的课表】页面\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"找到课表 (\" + tableData.source + \")，共 \" + tableData.cells.length + \" 个单元格\");\n\n    // 调试：输出前几个单元格信息\n    var debugInfo = [];\n    for (var d = 0; d < Math.min(5, tableData.cells.length); d++) {\n        var dc = tableData.cells[d];\n        var dt = dc.getAttribute(\"title\") || \"\";\n        var dr = dc.parentElement;\n        var dci = -1;\n        if (dr) {\n            var drc = Array.from(dr.cells);\n            dci = drc.indexOf(dc);\n        }\n        debugInfo.push(dc.id + \"|col:\" + dci + \"|day:\" + dci + \"|title:\" + dt.substring(0, 80));\n    }\n    console.log(\"HAUST调试: \" + debugInfo.join(\" || \"));\n\n    var courses = parseCoursesFromTable(tableData);\n    if (courses.length === 0) {\n        // 输出解析失败的调试信息\n        var failDebug = [];\n        for (var f = 0; f < Math.min(3, tableData.cells.length); f++) {\n            var fc = tableData.cells[f];\n            var ft = fc.getAttribute(\"title\") || \"\";\n            var fr = fc.parentElement;\n            var fci = -1;\n            if (fr) {\n                var frc = Array.from(fr.cells);\n                fci = frc.indexOf(fc);\n            }\n            var parsed = parseTitle(ft);\n            failDebug.push(\"col:\" + fci + \"|parsed:\" + parsed.length + \"|raw:\" + ft.substring(0, 60));\n        }\n        window.shiguangBridge.showToast(\"解析失败: \" + failDebug[0]);\n    }\n    if (courses.length === 0) {\n        window.shiguangBridge.showToast(\"未解析到课程，请检查课表是否完整显示\");\n        return;\n    }\n\n    var saveResult = await saveCourses(courses);\n    if (!saveResult) return;\n\n    window.shiguangBridge.showToast(\"导入成功！共 \" + courses.length + \" 门课程\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","HIST_01":"// 河南科技学院（青果 / KINGOSOFT 教务系统） 拾光课程表适配脚本\n//\n// 教务系统入口：http://jwgl.hist.edu.cn/cas/login.action\n// 课程表数据接口：/wsxk/xkjg.ckdgxsxdkchj_data10319.jsp?params=<base64(xn=..&xq=..)>\n//   说明：params 为 Base64，内容是 \"xn=2025&xq=0\"；xh(学号/uid) 可省略，服务端用会话即可。\n//   xn = 学年（如 2025 表示 2025-2026 学年）；xq = 0 第一学期(秋季) / 1 第二学期(春季)。\n//\n// 适配者：@星河欲转 社区贡献（河南科技学院）\n// 说明：本脚本按青果课表接口进行解析，若学校变更菜单编号(10319)或表格结构，\n//       请参照文档在“更多→开发者功能”中打开源码调试。\n\nconst HOST = 'http://jwgl.hist.edu.cn';\nconst KB_DATA_URL = HOST + '/wsxk/xkjg.ckdgxsxdkchj_data10319.jsp';\n\nconst DAY_MAP = { '一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6, '日': 7, '天': 7 };\n\nfunction base64Encode(str) {\n    return btoa(str);\n}\n\nfunction isLoginPage() {\n    const url = window.location.href;\n    if (url.indexOf('/cas/') !== -1) return true;\n    if (url.indexOf('jwgl.hist.edu.cn') !== -1 && /login\\.action|login\\.jsp|\\/cas\\//i.test(url)) return true;\n    return false;\n}\n\n// ---------- token 解析 ----------\n\nfunction matchDay(text) {\n    // 兼容 \"星期四[1-2]\" / \"周四[1-2]\" / \"二[7-8]\"（青果导出常为单个汉字）\n    let m = text.match(/(?:星期|周)([一二三四五六日天])/);\n    if (m) return { day: DAY_MAP[m[1]] || 7, str: m[1] };\n    m = text.match(/([一二三四五六日天])\\s*\\[/);\n    if (m) return { day: DAY_MAP[m[1]] || 7, str: m[1] };\n    return null;\n}\n\nfunction matchSection(text) {\n    // 优先匹配方括号内的节次（青果：星期一[7-8] / 二[7-8]）；方括号里的数字必为节次。\n    let m = text.match(/\\[(\\d{1,2})\\s*[-—～]\\s*(\\d{1,2})\\]/);\n    if (m) {\n        const s = parseInt(m[1], 10), e = parseInt(m[2], 10);\n        if (s >= 1 && e >= s && e <= 30) return { start: s, end: e, str: m[0] };\n    }\n    m = text.match(/(\\d{1,2})\\s*[-—～]\\s*(\\d{1,2})\\s*节/);\n    if (m) {\n        const s = parseInt(m[1], 10), e = parseInt(m[2], 10);\n        if (s >= 1 && e >= s && e <= 30) return { start: s, end: e, str: m[0] };\n    }\n    m = text.match(/(?:第)?\\s*(\\d{1,2})\\s*节/);\n    if (m) {\n        const s = parseInt(m[1], 10);\n        if (s >= 1 && s <= 30) return { start: s, end: s, str: m[0] };\n    }\n    return null;\n}\n\nfunction matchWeeks(text) {\n    let flag = 0;\n    if (text.includes('单')) flag = 1;\n    else if (text.includes('双')) flag = 2;\n    let clean = text.replace(/单/g, '').replace(/双/g, '').replace(/[()（）]/g, '');\n    const m = clean.match(/([\\d,，\\-—～]+)\\s*周/);\n    if (!m) return [];\n    const weeks = [];\n    for (const part of m[1].split(/[,，]/)) {\n        const p = part.trim();\n        if (!p) continue;\n        const range = p.match(/^(\\d{1,3})[\\-—～](\\d{1,3})$/);\n        if (range) {\n            const s = parseInt(range[1], 10), e = parseInt(range[2], 10);\n            for (let i = s; i <= e; i++) {\n                if (flag === 1 && i % 2 !== 0) weeks.push(i);\n                else if (flag === 2 && i % 2 === 0) weeks.push(i);\n                else if (flag === 0) weeks.push(i);\n            }\n        } else if (/^\\d{1,3}$/.test(p)) {\n            const i = parseInt(p, 10);\n            if (flag === 1 && i % 2 !== 0) weeks.push(i);\n            else if (flag === 2 && i % 2 === 0) weeks.push(i);\n            else if (flag === 0) weeks.push(i);\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\nfunction parseTimePlaceCell(text) {\n    const items = [];\n    if (!text) return items;\n    const normalized = text\n        .replace(/／/g, '/').replace(/，/g, ',').replace(/；/g, ';')\n        .replace(/\\u3000/g, ' ').replace(/<[^>]+>/g, '');\n\n    // 每个时段形如：周次 星期[节次] 地点；多个时段用逗号分隔。\n    // 用“周次 + 星期[节次]”为锚点整体捕获，避免把周次列表里的逗号（如 6-8,10周）误当成时段分隔。\n    const re = /(\\S*周[^\\s\\[\\]]*)\\s*([一二三四五六日天])\\s*\\[(\\d{1,2})\\s*[-—～]\\s*(\\d{1,2})\\]\\s*([^,，;；\\n]*)/g;\n    let m;\n    while ((m = re.exec(normalized)) !== null) {\n        const day = DAY_MAP[m[2]] || 7;\n        const start = parseInt(m[3], 10), end = parseInt(m[4], 10);\n        if (!(start >= 1 && end >= start && end <= 30)) continue;\n        const weeks = matchWeeks(m[1]);\n        if (weeks.length === 0) continue;\n        let position = (m[5] || '')\n            .replace(/\\((\\d+)\\)\\s*$/, '') // 去掉结尾教室容量 \"(98)\"\n            .replace(/[\\[\\]()（）]/g, ' ')\n            .replace(/[,，;；\\/]/g, ' ')\n            .replace(/单|双/g, ' ')\n            .replace(/\\s+/g, ' ').trim();\n        if (position === '' || /^\\d+$/.test(position)) position = '';\n        items.push({ day, startSection: start, endSection: end, weeks, position });\n    }\n\n    // 兜底：若某时段缺地点，而同行后面的时段有地点，则继承该地点\n    const lastPos = items.map(i => i.position).filter(p => p).slice(-1)[0] || '';\n    if (lastPos) {\n        for (const it of items) if (!it.position) it.position = lastPos;\n    }\n    return items;\n}\n\n// ---------- HTML 解析 ----------\n\n// 清理教师串：格式 \"[工号]姓名 [工号]姓名 …\" → \"姓名 & 姓名\"\nfunction cleanTeacher(t) {\n    const name = t.split('[').map(part => {\n        const idx = part.indexOf(']');\n        return idx >= 0 ? part.slice(idx + 1).replace(/&ensp;|&nbsp;/g, ' ').trim() : '';\n    }).filter(Boolean).join(' & ');\n    return name || t.trim();\n}\n\nfunction findNameAndTeacher(cells, dataIdx) {\n    let name = '', teacher = '', nameIdx = -1;\n    // 课程名：形如 [xxx]课程名\n    for (let i = 0; i < cells.length; i++) {\n        if (i === dataIdx) continue;\n        const t = (cells[i]?.textContent || '').trim();\n        if (/^\\s*\\[[^\\]]*\\]\\s*\\S/.test(t)) {\n            name = t.replace(/^\\s*\\[[^\\]]*\\]\\s*/g, '').trim();\n            nameIdx = i;\n            break;\n        }\n    }\n    // 教师：形如 [工号]姓名 …（含 [工号] 且不是课程名）\n    for (let i = 0; i < cells.length; i++) {\n        if (i === dataIdx || i === nameIdx) continue;\n        const t = (cells[i]?.textContent || '').trim();\n        if (/\\d/.test(t) && /\\[[^\\]]*\\]\\s*/.test(t)) {\n            const ct = cleanTeacher(t);\n            if (ct) { teacher = ct; break; }\n        }\n    }\n    return { name, teacher };\n}\n\nfunction parseScheduleHtml(html) {\n    const doc = new DOMParser().parseFromString(html, 'text/html');\n    const rows = doc.querySelectorAll('tr');\n    const courses = [];\n\n    for (const tr of rows) {\n        const cells = Array.from(tr.querySelectorAll('td'));\n        if (cells.length < 3) continue;\n\n        let dataCell = null;\n        let dataIdx = -1;\n        for (let i = cells.length - 1; i >= 0; i--) {\n            const t = cells[i].textContent || '';\n            // 时间地点单元格特征：含“周”（周次）或方括号节次 [N-M]，或“星期X[”/“X[”\n            if (/周/.test(t) || /\\[(\\d{1,2})\\s*[-—～]\\s*(\\d{1,2})\\]/.test(t) || /[一二三四五六日天]\\s*\\[/.test(t)) {\n                dataCell = t;\n                dataIdx = i;\n                break;\n            }\n        }\n        if (dataCell === null) continue;\n\n        // 课程名与教师采用“按内容识别”，对导出/接口两种列布局都健壮：\n        //   课程名单元格形如 \"[2500T0002]大学生心理健康教育\"\n        //   教师单元格形如 \"[201201059]贾普君 [202201013]李金璐\"\n        const info = findNameAndTeacher(cells, dataIdx);\n        let name = info.name;\n        if (!name) name = (cells[2]?.textContent || '').trim() || (cells[1]?.textContent || '').trim() || (cells[0]?.textContent || '').trim();\n        name = name.replace(/^\\s*\\[[^\\]]*\\]\\s*/g, '').trim();\n        if (!name) continue;\n        const teacher = info.teacher;\n\n        const items = parseTimePlaceCell(String(dataCell));\n        for (const it of items) {\n            courses.push({\n                name: name, teacher: teacher, position: it.position,\n                day: it.day, startSection: it.startSection, endSection: it.endSection, weeks: it.weeks\n            });\n        }\n    }\n    return mergeCourses(courses);\n}\n\nfunction mergeCourses(courses) {\n    const map = new Map();\n    for (const c of courses) {\n        const key = [c.name, c.teacher, c.position, c.day, c.startSection, c.endSection].join('|');\n        if (!map.has(key)) map.set(key, { ...c, weeks: [] });\n        const entry = map.get(key);\n        entry.weeks = [...new Set([...entry.weeks, ...c.weeks])].sort((a, b) => a - b);\n    }\n    return Array.from(map.values());\n}\n\n// ---------- 流程 ----------\n\nfunction validateYearInput(input) {\n    if (/^[0-9]{4}$/.test(input)) return false;\n    return '请输入四位数字的学年！';\n}\n\nasync function promptUserToStart() {\n    return await window.shiguangBridgePromise.showAlert(\n        '教务系统课表导入',\n        '导入前请确认已在本页面登录教务系统（登录成功后无需再点登录）。',\n        '好的，开始导入'\n    );\n}\n\nasync function selectYear() {\n    const now = new Date();\n    const month = now.getMonth() + 1;\n    let year = now.getFullYear();\n    if (month < 7) year -= 1;\n    const input = await window.shiguangBridgePromise.showPrompt(\n        '选择学年',\n        '请输入要导入课程的起始学年（例如 2025-2026 学年输入 2025）：',\n        String(year), 'validateYearInput'\n    );\n    if (input === null) return null;\n    return parseInt(input, 10);\n}\n\nasync function selectSemester() {\n    const semesters = ['第一学期（秋季）', '第二学期（春季）'];\n    return await window.shiguangBridgePromise.showSingleSelection('选择学期', JSON.stringify(semesters), 0);\n}\n\n// 自动判断响应编码：UTF-8 与 GBK 二选一（谁替换字符少、中文多就用谁）\nfunction decodeBest(buf) {\n    const utf8 = (() => { try { return new TextDecoder('utf-8').decode(buf); } catch (e) { return ''; } })();\n    const gbk = (() => { try { return new TextDecoder('gbk').decode(buf); } catch (e) { return null; } })();\n    const repl = s => (s.match(/\\uFFFD/g) || []).length;\n    const cjk = s => (s.match(/[\\u4e00-\\u9fa5]/g) || []).length;\n    if (gbk == null) return utf8;\n    if (repl(utf8) === 0 && repl(gbk) > 0) return utf8;\n    if (repl(gbk) === 0 && repl(utf8) > 0) return gbk;\n    if (cjk(gbk) > cjk(utf8)) return gbk;\n    return repl(gbk) < repl(utf8) ? gbk : utf8;\n}\n\nasync function fetchScheduleHtml(academicYear, semesterIndex) {\n    const xq = semesterIndex === 0 ? 0 : 1;\n    const params = base64Encode(`xn=${academicYear}&xq=${xq}`);\n    const url = `${KB_DATA_URL}?params=${encodeURIComponent(params)}`;\n    window.shiguangBridge.showToast('正在请求课表数据…');\n    console.log('HIST: fetch ->', url);\n\n    const resp = await fetch(url, { method: 'GET', credentials: 'include' });\n    const buf = await resp.arrayBuffer();\n    const text = decodeBest(buf);\n    if (text.includes('凭证已失效') || text.includes('请重新登录')) {\n        window.shiguangBridge.showToast('请先登录教务系统！');\n        return null;\n    }\n    return text;\n}\n\n// 内置备用作息：key 0=第一学期(2026-2027实测), 1=第二学期(旧版兜底，仅抓取失败时用)\nconst FALLBACK_TIMES = {\n    0: [\n        { number: 1, startTime: '08:00', endTime: '08:45' }, { number: 2, startTime: '08:55', endTime: '09:40' },\n        { number: 3, startTime: '10:10', endTime: '10:55' }, { number: 4, startTime: '11:05', endTime: '11:50' },\n        { number: 5, startTime: '15:00', endTime: '15:45' }, { number: 6, startTime: '15:55', endTime: '16:40' },\n        { number: 7, startTime: '17:10', endTime: '17:55' }, { number: 8, startTime: '18:05', endTime: '18:50' },\n        { number: 9, startTime: '20:00', endTime: '20:45' }, { number: 10, startTime: '20:55', endTime: '21:40' }\n    ],\n    1: [\n        { number: 1, startTime: '08:00', endTime: '08:45' }, { number: 2, startTime: '08:55', endTime: '09:40' },\n        { number: 3, startTime: '10:10', endTime: '10:55' }, { number: 4, startTime: '11:05', endTime: '11:50' },\n        { number: 5, startTime: '14:30', endTime: '15:15' }, { number: 6, startTime: '15:25', endTime: '16:10' },\n        { number: 7, startTime: '16:40', endTime: '17:25' }, { number: 8, startTime: '17:35', endTime: '18:20' },\n        { number: 9, startTime: '19:30', endTime: '20:15' }, { number: 10, startTime: '20:25', endTime: '21:10' }\n    ]\n};\n\n// 解析教务作息页表格：节次行形如 [\"1\",\"08:00\",\"08:45\"] 或 [\"上午\",\"1\",\"08:00\",\"08:45\"]\nfunction parseTimetableHtml(html) {\n    const doc = new DOMParser().parseFromString(html, 'text/html');\n    const out = [];\n    for (const tr of doc.querySelectorAll('tr')) {\n        const cells = Array.from(tr.querySelectorAll('td,th'))\n            .map(c => (c.textContent || '').trim()).filter(c => c !== '');\n        let num = parseInt(cells[0] || '', 10);\n        if (isNaN(num)) num = parseInt(cells[1] || '', 10);\n        let start = '', end = '';\n        for (let i = 1; i < cells.length; i++) {\n            if (/^\\d{2}:\\d{2}$/.test(cells[i])) {\n                if (!start) start = cells[i];\n                else if (!end) { end = cells[i]; break; }\n            }\n        }\n        if (num >= 1 && num <= 30 && start && end) out.push({ number: num, startTime: start, endTime: end });\n    }\n    const map = new Map();\n    out.forEach(s => { if (!map.has(s.number)) map.set(s.number, s); });\n    return Array.from(map.values()).sort((a, b) => a.number - b.number);\n}\n\n// 动态抓取教务公布的当学期作息（公开同源接口，免登录）\nasync function fetchTermTimeSlots(year, xq) {\n    const url = HOST + '/public/SchoolTimetable.show.jsp';\n    const body = 'xn=' + year + '&xq_m=' + xq + '&menucode=&is_ssxq=0&axq=&ssxq=';\n    const resp = await fetch(url, {\n        method: 'POST',\n        headers: { 'content-type': 'application/x-www-form-urlencoded; charset=UTF-8' },\n        body: body,\n        credentials: 'include'\n    });\n    const buf = await resp.arrayBuffer();\n    const text = decodeBest(buf);\n    if (text.includes('未设置') || text.includes('未设定') || text.includes('未发布')) return null;\n    const slots = parseTimetableHtml(text);\n    return slots.length ? slots : null;\n}\n\nasync function runImportFlow() {\n    if (isLoginPage()) {\n        window.shiguangBridge.showToast('请先登录教务系统，再点击导入！');\n        return;\n    }\n    const confirmed = await promptUserToStart();\n    if (!confirmed) return;\n    const year = await selectYear();\n    if (year === null) return;\n    const semIdx = await selectSemester();\n    if (semIdx === null || semIdx === -1) return;\n\n    const html = await fetchScheduleHtml(year, semIdx);\n    if (!html) return;\n    if (html.includes('凭证已失效') || html.includes('请重新登录')) {\n        window.shiguangBridge.showToast('登录已失效，请重新登录后重试。');\n        return;\n    }\n\n    const courses = parseScheduleHtml(html);\n    if (!courses || courses.length === 0) {\n        window.shiguangBridge.showToast('未解析到课程，可能是本学期无课或页面结构已变化。');\n        console.log('HIST: raw html head ->', (html || '').slice(0, 1200));\n        return;\n    }\n\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses, null, 2));\n    window.shiguangBridge.showToast(`课程解析成功：${courses.length} 条`);\n\n    // 作息与学年学期强相关：合并为一步，按所选学期自动抓取教务公布作息；失败用内置备用并提示\n    const xq = semIdx === 0 ? 0 : 1;\n    const termName = xq === 0 ? '第一学期' : '第二学期';\n    let slots = null;\n    try { slots = await fetchTermTimeSlots(year, xq); } catch (e) { slots = null; }\n    if (slots && slots.length) {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(slots));\n        window.shiguangBridge.showToast(`已按 ${year}-${year + 1} 学年${termName}作息导入`);\n    } else {\n        const fallback = FALLBACK_TIMES[xq] || FALLBACK_TIMES[0];\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(fallback));\n        window.shiguangBridge.showToast(`未能获取学校${termName}作息（可能未发布），已用备用作息，请核对`);\n    }\n    window.shiguangBridge.showToast(`导入完成，共 ${courses.length} 门课程！`);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","HNZY_01":"// ====================== 工具函数 ======================\n\n/**\n * 检查用户是否已登录。\n * 如果当前URL包含登录关键字，说明用户未登录，返回false。\n * 如果不包含登录关键字，说明用户已登录，返回true。\n */\nfunction isUserLoggedIn() {\n    const url = window.location.href;\n    const loginKeywords = [\n        \"https://we.hnzj.edu.cn/sso/login\"\n    ];\n    \n    // 检查URL是否包含登录关键字\n    for (const keyword of loginKeywords) {\n        if (url.includes(keyword)) {\n            return false; // 包含登录关键字，说明用户未登录\n        }\n    }\n    \n    // 不包含登录关键字，说明用户已登录\n    return true;\n}\n\n// 展开 weeks 字符串 -> 数字数组\nfunction parseWeeks(weeksStr) {\n    const weeks = new Set();\n    if (!weeksStr) return [];\n    const parts = weeksStr.split(\",\");\n    for (const part of parts) {\n        if (part.includes(\"-\")) {\n            const [start, end] = part.split(\"-\").map(n => parseInt(n));\n            for (let i = start; i <= end && i <= 20; i++) {\n                weeks.add(i);\n            }\n        } else {\n            const n = parseInt(part);\n            if (n >= 1 && n <= 20) weeks.add(n);\n        }\n    }\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\n// 合并重复课程\nfunction mergeDuplicateCourses(courses) {\n    const merged = [];\n    const keyMap = {}; // key = name+day+startSection+endSection+position\n\n    for (const c of courses) {\n        const key = `${c.name}|${c.day}|${c.startSection}|${c.endSection}|${c.position}`;\n        if (!keyMap[key]) {\n            keyMap[key] = { ...c, weeks: [...c.weeks] };\n        } else {\n            keyMap[key].weeks = Array.from(new Set([...keyMap[key].weeks, ...c.weeks]));\n        }\n    }\n\n    for (const k in keyMap) merged.push(keyMap[k]);\n    return merged;\n}\n\n// ====================== 弹窗选择学年学期 ======================\nasync function selectYearAndTerm(schoolYears, schoolTerms) {\n    try {\n        // 构造所有学年 x 学期组合\n        const options = [];\n        const mapping = []; // 用于根据选项索引找到学年和学期\n        schoolYears.forEach(y => {\n            schoolTerms.forEach(t => {\n                options.push(`${y.label} ${t.label}`);\n                mapping.push({ year: y.value, term: t.value });\n            });\n        });\n\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"请选择学年和学期\",\n            JSON.stringify(options),\n            0\n        );\n\n        if (selectedIndex === null) return null;\n\n        return mapping[selectedIndex];\n    } catch (err) {\n        console.error(\"选择学年学期失败:\", err);\n        return null;\n    }\n}\n\n\n// ====================== 异步获取学年学期 ======================\nasync function fetchSchoolYearTerms() {\n    try {\n        const res = await fetch(\"https://one.hnzj.edu.cn/kcb/api/schoolyearTerms\");\n        const json = await res.json();\n        return {\n            schoolYears: json.response.schoolYears,\n            schoolTerms: json.response.schoolTerms\n        };\n    } catch (err) {\n        console.error(\"获取学年学期失败:\", err);\n        window.shiguangBridge.showToast(\"获取学年学期失败：\" + err.message);\n        return null;\n    }\n}\n\n// ====================== 异步获取课程并处理 ======================\nasync function fetchCoursesForAllWeeks(year, term) {\n    let allCourses = [];\n\n    for (let week = 1; week <= 20; week++) {\n        try {\n            const url = `https://one.hnzj.edu.cn/kcb/api/course?schoolYear=${year}&schoolTerm=${term}&week=${week}`;\n            const res = await fetch(url);\n            const json = await res.json();\n\n\n            json.response.forEach(dayInfo => {\n                dayInfo.data.forEach(c => {\n                    const weeks = parseWeeks(c.weeks);\n                    if (!weeks.length) return;\n                    allCourses.push({\n                        name: c.courseName,\n                        teacher: c.teacherName,\n                        position: c.classRoom,\n                        day: dayInfo.week,\n                        startSection: parseInt(c.startSection),\n                        endSection: parseInt(c.endSection),\n                        weeks\n                    });\n                });\n            });\n        } catch (err) {\n            console.error(`第 ${week} 周课程获取失败:`, err);\n        }\n    }\n\n    const mergedCourses = mergeDuplicateCourses(allCourses);\n\n\n    return mergedCourses.length ? mergedCourses : null;\n}\n\n// ====================== 保存课程 ======================\nasync function saveCourses(courses) {\n    try {\n        const result = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (result === true) {\n            window.shiguangBridge.showToast(\"课程导入成功！\");\n            return true;\n        } else {\n            window.shiguangBridge.showToast(\"课程导入失败，请查看日志！\");\n            return false;\n        }\n    } catch (err) {\n        console.error(\"保存课程失败:\", err);\n        window.shiguangBridge.showToast(\"保存课程失败：\" + err.message);\n        return false;\n    }\n}\n\n// ====================== 导入预设时间段（实际大节时间） ======================\nasync function importPresetTimeSlots() {\n    // 调整后的课程大节时间，端点衔接，总时长不变\n    const presetTimeSlots = [\n        { number: 1, startTime: \"08:30\", endTime: \"09:15\" }, // 第一大节第一部分\n        { number: 2, startTime: \"09:15\", endTime: \"10:00\" }, // 第一大节第二部分\n        { number: 3, startTime: \"10:20\", endTime: \"11:05\" }, // 第二大节第一部分\n        { number: 4, startTime: \"11:05\", endTime: \"11:50\" }, // 第二大节第二部分\n        { number: 5, startTime: \"14:20\", endTime: \"15:05\" }, // 第三大节第一部分\n        { number: 6, startTime: \"15:05\", endTime: \"15:50\" }, // 第三大节第二部分\n        { number: 7, startTime: \"16:10\", endTime: \"16:55\" }, // 第四大节第一部分\n        { number: 8, startTime: \"16:55\", endTime: \"17:40\" }, // 第四大节第二部分\n\t\t{ number: 9, startTime: \"18:00\", endTime: \"18:45\" }, // 第五大节第一部分\n\t\t{ number: 10, startTime: \"18:45\", endTime: \"19:00\" }, // 第五大节第二部分\n        { number: 11, startTime: \"19:00\", endTime: \"19:45\" }, // 第六大节第一部分\n        { number: 12, startTime: \"19:45\", endTime: \"20:30\" }  // 第六大节第二部分\n    ];\n    \n    try {\n        const result = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n        if (result === true) {\n            window.shiguangBridge.showToast(\"时间段导入成功！\");\n        } else {\n            window.shiguangBridge.showToast(\"时间段导入失败，请查看日志！\");\n        }\n    } catch (err) {\n        console.error(\"时间段导入失败:\", err);\n        window.shiguangBridge.showToast(\"时间段导入失败：\" + err.message);\n    }\n}\n\n\n// ====================== 主流程 ======================\nasync function runImportFlow() {\n    // 检查用户是否已登录\n    if (!isUserLoggedIn()) {\n        window.shiguangBridge.showToast(\"检测到未登录状态，请先登录后再使用课程导入功能！\");\n        return;\n    }\n    \n    window.shiguangBridge.showToast(\"课程导入流程即将开始...\");\n\n    // 1️⃣ 获取学年学期\n    const yearTermData = await fetchSchoolYearTerms();\n    if (!yearTermData) {\n        return;\n    }\n\n    // 2️⃣ 用户选择\n    const selection = await selectYearAndTerm(yearTermData.schoolYears, yearTermData.schoolTerms);\n    if (!selection) {\n        window.shiguangBridge.showToast(\"用户取消选择！\");\n        return;\n    }\n\n    // 3️⃣ 异步获取课程并处理\n    const courses = await fetchCoursesForAllWeeks(selection.year, selection.term);\n    if (!courses) {\n        return;\n    }\n\n    // 4️⃣ 保存课程\n    const saveResult = await saveCourses(courses);\n    if (!saveResult) {\n        return;\n    }\n\n    // 5️⃣ 导入预设时间段\n    await importPresetTimeSlots();\n\n    // ✅ 只有所有步骤都成功完成，才通知任务完成\n    window.shiguangBridge.showToast(`课程导入成功，共导入 ${courses.length} 门课程！`);\n    console.log(\"JS：整个导入流程执行完毕并成功。\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动流程\nrunImportFlow();\n","HUEL_01":"const BASE = 'https://xk.huel.edu.cn/jwglxt';\n\nconst TIME_SLOTS = [\n  { number: 1, startTime: '08:00', endTime: '08:45' },\n  { number: 2, startTime: '08:55', endTime: '09:40' },\n  { number: 3, startTime: '09:55', endTime: '10:40' },\n  { number: 4, startTime: '10:50', endTime: '11:35' },\n  { number: 5, startTime: '11:45', endTime: '12:30' },\n  { number: 6, startTime: '13:30', endTime: '14:15' },\n  { number: 7, startTime: '14:25', endTime: '15:10' },\n  { number: 8, startTime: '15:25', endTime: '16:10' },\n  { number: 9, startTime: '16:20', endTime: '17:05' },\n  { number: 10, startTime: '17:15', endTime: '18:00' },\n  { number: 11, startTime: '19:00', endTime: '19:45' },\n  { number: 12, startTime: '19:50', endTime: '20:35' },\n  { number: 13, startTime: '20:40', endTime: '21:25' }\n];\n\nasync function req(url, method, body) {\n  const res = await fetch(url, {\n    method,\n    credentials: 'include',\n    headers: {\n      'content-type': 'application/x-www-form-urlencoded;charset=UTF-8',\n      'x-requested-with': 'XMLHttpRequest'\n    },\n    body\n  });\n  if (!res.ok) throw new Error(`请求失败: ${res.status}`);\n  return await res.text();\n}\n\nfunction isOnTimetablePage() {\n  const path = '/jwglxt/kbcx/xskbcx_cxXskbcxIndex.html';\n  return window.location.origin === 'https://xk.huel.edu.cn' && window.location.pathname === path;\n}\n\nfunction readCurrentPageTerm() {\n  const xnmEl = document.querySelector('#xnm');\n  const xqmEl = document.querySelector('#xqm');\n  const xnm = xnmEl ? String(xnmEl.value || '').trim() : '';\n  const xqm = xqmEl ? String(xqmEl.value || '').trim() : '';\n  if (!xnm || !xqm) throw new Error('当前课表页未读到学年学期，请先选择后再导入');\n  return { xnm, xqm };\n}\n\nfunction parseSelectOptions(selectEl) {\n  if (!selectEl) return { options: [], defaultIndex: 0 };\n  const options = [];\n  let defaultIndex = 0;\n  Array.from(selectEl.querySelectorAll('option')).forEach((opt) => {\n    const value = String(opt.value || '').trim();\n    if (!value) return;\n    const text = String(opt.textContent || '').trim() || value;\n    if (opt.selected) defaultIndex = options.length;\n    options.push({ value, text });\n  });\n  return { options, defaultIndex };\n}\n\nfunction parseTermOptionsFromDoc(doc) {\n  const yearData = parseSelectOptions(doc.querySelector('#xnm'));\n  const semesterData = parseSelectOptions(doc.querySelector('#xqm'));\n  if (!yearData.options.length || !semesterData.options.length) {\n    throw new Error('课表页学年学期选项解析失败');\n  }\n  return { yearData, semesterData };\n}\n\nasync function fetchIndexDoc() {\n  const html = await req(`${BASE}/kbcx/xskbcx_cxXskbcxIndex.html?gnmkdm=N2151&layout=default`, 'GET');\n  return new DOMParser().parseFromString(html, 'text/html');\n}\n\nasync function selectTermByUserFromDoc(doc) {\n  const { yearData, semesterData } = parseTermOptionsFromDoc(doc);\n\n  const yearIndex = await window.shiguangBridgePromise.showSingleSelection(\n    '选择学年',\n    JSON.stringify(yearData.options.map(i => i.text)),\n    yearData.defaultIndex\n  );\n  if (yearIndex === null || yearIndex === -1) throw new Error('已取消学年选择');\n\n  const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n    '选择学期',\n    JSON.stringify(semesterData.options.map(i => i.text)),\n    semesterData.defaultIndex\n  );\n  if (semesterIndex === null || semesterIndex === -1) throw new Error('已取消学期选择');\n\n  return {\n    xnm: yearData.options[yearIndex].value,\n    xqm: semesterData.options[semesterIndex].value\n  };\n}\n\nasync function resolveTerm() {\n  if (isOnTimetablePage()) {\n    return readCurrentPageTerm();\n  }\n  const doc = await fetchIndexDoc();\n  return await selectTermByUserFromDoc(doc);\n}\n\nfunction parseWeeks(zcd) {\n  if (!zcd) return [];\n  const result = new Set();\n  String(zcd).replace(/\\s+/g, '').split(/[,，]/).forEach(seg => {\n    const odd = seg.includes('单');\n    const even = seg.includes('双');\n    const m = seg.replace(/周|\\(|\\)|单|双/g, '').match(/(\\d+)(?:-(\\d+))?/);\n    if (!m) return;\n    const start = Number(m[1]);\n    const end = Number(m[2] || m[1]);\n    for (let w = start; w <= end; w++) {\n      if (odd && w % 2 === 0) continue;\n      if (even && w % 2 !== 0) continue;\n      result.add(w);\n    }\n  });\n  return [...result].sort((a, b) => a - b);\n}\n\nfunction parseCourses(data) {\n  if (!data || !Array.isArray(data.kbList)) return [];\n  const courses = [];\n\n  data.kbList.forEach(c => {\n    const day = Number(c.xqj);\n    const secRaw = String(c.jcs || '').replace(/节/g, '').trim();\n    const sectionNums = (secRaw.match(/\\d+/g) || []).map(Number).filter(n => !Number.isNaN(n));\n    const weeks = parseWeeks(c.zcd);\n    if (!c.kcmc || !sectionNums.length || !weeks.length || !(day >= 1 && day <= 7)) return;\n    const startSection = sectionNums[0];\n    const endSection = sectionNums[sectionNums.length - 1];\n\n    courses.push({\n      name: String(c.kcmc).trim(),\n      teacher: String(c.xm || '未知').trim(),\n      position: String(c.cdmc || c.cdbh || '未排地点').trim(),\n      day,\n      startSection,\n      endSection,\n      weeks\n    });\n  });\n\n  const map = new Map();\n  courses.forEach(c => {\n    const k = `${c.name}|${c.teacher}|${c.day}|${c.startSection}|${c.endSection}|${c.weeks.join(',')}|${c.position}`;\n    if (!map.has(k)) map.set(k, c);\n  });\n  return [...map.values()];\n}\n\nfunction validateSemesterStartDateInput(input) {\n  const v = String(input || '').trim();\n  if (!v) return false;\n  return /^\\d{4}-\\d{2}-\\d{2}$/.test(v) ? false : '请输入 YYYY-MM-DD，例如 2026-02-24';\n}\n\nasync function selectSemesterStartDate(xnm, xqm) {\n  const defaultDate = xqm === '3' ? `${xnm}-09-01` : `${Number(xnm) + 1}-03-01`;\n  const picked = await window.shiguangBridgePromise.showPrompt(\n    '选择开学日期',\n    '请输入开学日期（YYYY-MM-DD）',\n    defaultDate,\n    'validateSemesterStartDateInput'\n  );\n  if (picked === null) return null;\n  const value = String(picked).trim();\n  return value || null;\n}\n\nasync function run() {\n  try {\n    const { xnm, xqm } = await resolveTerm();\n\n    const body = `xnm=${xnm}&xqm=${xqm}&kzlx=ck&xsdm=&kclbdm=&kclxdm=`;\n    const text = await req(`${BASE}/kbcx/xskbcx_cxXsgrkb.html?gnmkdm=N2151`, 'POST', body);\n    const data = JSON.parse(text);\n\n    const courses = parseCourses(data);\n    if (!courses.length) {\n      window.shiguangBridge.showToast('导入失败: 未获取到课表数据');\n      return;\n    }\n\n    const semesterStartDate = await selectSemesterStartDate(xnm, xqm);\n    const allWeeks = courses.flatMap(c => c.weeks);\n    const maxWeek = allWeeks.length ? Math.max(...allWeeks) : 20;\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n      semesterTotalWeeks: maxWeek,\n      semesterStartDate: semesterStartDate,\n      firstDayOfWeek: 1\n    }));\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TIME_SLOTS));\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n    window.shiguangBridge.showToast(`导入成功：${courses.length} 门`);\n    window.shiguangBridge.notifyTaskCompletion();\n  } catch (e) {\n    console.error(e);\n    window.shiguangBridge.showToast(`导入失败: ${e.message}`);\n  }\n}\n\nrun();","HBLGXY_01":"// 淮北理工学院(hblgxy.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 验证逻辑\n\n/**\n * 年份输入验证函数\n * @param {string} input 用户输入的年份\n * @returns {boolean|string} 验证通过返回false，失败返回错误提示\n */\nwindow.validateYearInput = function(input) {\n    return /^[0-9]{4}$/.test(input) ? false : \"请输入四位数字的学年！\";\n};\n\n// 数据解析函数\n\n/**\n * 将周次字符串解析为数字数组\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    \n    // 适配 \"1-9,11-17(周)[01-02节]\" 或 \"12-15(周)\"\n    const pureWeekData = weekStr.split('(')[0]; \n    \n    pureWeekData.split(',').forEach(seg => {\n        if (seg.includes('-')) {\n            const [s, e] = seg.split('-').map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 转换课程 HTML 格式为应用模型\n */\nfunction parseTimetableToModel(doc) {\n    const timetable = doc.getElementById('timetable');\n    if (!timetable) return [];\n\n    const results = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).slice(1);\n\n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        if (cells.length < 7) return;\n\n        // 遍历周一到周日\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1;\n            const detailDiv = cell.querySelector('div.kbcontent[style*=\"none\"]');\n            \n            if (detailDiv) {\n                const rawHtml = detailDiv.innerHTML.trim();\n                if (rawHtml === \"\" || rawHtml === \"&nbsp;\") return;\n\n                // 拆分可能存在的多个课程块\n                const courseBlocks = rawHtml.split(/---------------------|----------------------/);\n                \n                courseBlocks.forEach(block => {\n                    if (block.replace(/&nbsp;|<br\\/?>/g, '').trim() === \"\") return;\n\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    // 提取课程名\n                    let name = \"\";\n                    for (let node of tempDiv.childNodes) {\n                        if (node.nodeType === 3 && node.textContent.trim() !== \"\") {\n                            name = node.textContent.trim();\n                            break;\n                        } else if (node.tagName === \"BR\" && name !== \"\") {\n                            break;\n                        } else if (node.nodeType === 3) {\n                            name += node.textContent.trim();\n                        }\n                    }\n\n                    // 提取教师、周次(节次)、地点\n                    const teacher = tempDiv.querySelector('font[title=\"教师\"]')?.innerText || \"未知教师\";\n                    const weekStr = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText || \"\";\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText || \"未知地点\";\n\n                    let start = 0, end = 0;\n                    if (weekStr) {\n                        const secMatch = weekStr.match(/\\[(\\d+)(?:-(\\d+))?节\\]/);\n                        if (secMatch) {\n                            start = parseInt(secMatch[1]);\n                            end = secMatch[2] ? parseInt(secMatch[2]) : start;\n                        }\n                    }\n\n                    if (name && weekStr && start > 0) {\n                        results.push({\n                            \"name\": name,\n                            \"teacher\": teacher,\n                            \"weeks\": parseWeeks(weekStr),\n                            \"position\": position,\n                            \"day\": day,\n                            \"startSection\": start,\n                            \"endSection\": end\n                        });\n                    }\n                });\n            }\n        });\n    });\n\n    return results;\n}\n\n/**\n * 保存课表全局配置\n */\nasync function saveAppConfig() {\n    const config = {\n        \"semesterTotalWeeks\": 20,\n        \"firstDayOfWeek\": 1\n    };\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n/**\n * 保存时间段配置\n */\nasync function saveAppTimeSlots() {\n    const timeSlots = [\n        { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n        { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n        { \"number\": 3, \"startTime\": \"10:00\", \"endTime\": \"10:45\" },\n        { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\" },\n        { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        { \"number\": 6, \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        { \"number\": 7, \"startTime\": \"16:00\", \"endTime\": \"16:45\" },\n        { \"number\": 8, \"startTime\": \"16:55\", \"endTime\": \"17:40\" },\n        { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n        { \"number\": 10, \"startTime\": \"19:55\", \"endTime\": \"20:40\" },\n        { \"number\": 11, \"startTime\": \"20:50\", \"endTime\": \"21:35\" },\n        { \"number\": 12, \"startTime\": \"21:45\", \"endTime\": \"22:30\" },\n        { \"number\": 13, \"startTime\": \"22:40\", \"endTime\": \"23:25\" },\n        { \"number\": 14, \"startTime\": \"23:25\", \"endTime\": \"23:59\" }\n    ];\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n}\n\n/**\n * 获取并让用户选择学期 ID\n */\nasync function getSelectedSemesterId() {\n    const currentYear = new Date().getFullYear();\n    // 绑定验证函数 validateYearInput\n    const year = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\", \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\", String(currentYear), \"validateYearInput\"\n    );\n    if (!year) return null;\n    \n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify([\"第一学期\", \"第二学期\"]), 0\n    );\n    if (semesterIndex === null) return null;\n    \n    return `${year}-${parseInt(year) + 1}-${semesterIndex + 1}`;\n}\n\n// 流程控制\n\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"公告\",\n            \"请确保您已在当前页面成功登录教务系统，否则无法获取数据。是否继续？\",\n            \"确认已登录\"\n        );\n        if (!confirmed) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        const semesterId = await getSelectedSemesterId();\n        if (!semesterId) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(\"正在获取教务数据...\");\n        \n        const response = await fetch(\"https://a.hblgxy.edu.cn:5111/jsxsd/xskb/xskb_list.do\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: `cj0701id=&zc=&demo=&xnxq01id=${semesterId}`,\n            credentials: \"include\"\n        });\n        \n        const html = await response.text();\n        const finalCourses = parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"));\n\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现任何课程数据,检查是否登录或者学期选择是否正确\");\n            return;\n        }\n\n        // 保存数据\n        window.shiguangBridge.showToast(\"正在保存配置...\");\n        await saveAppConfig();\n        await saveAppTimeSlots();\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n        \n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        window.shiguangBridge.showToast(\"异常: \" + error.message);\n    }\n}\n\n// 启动导入流程\nrunImportFlow();","HNNU_01":"// 淮南师范学院 (xxmh.hnnu.edu.cn) 库表图融合门户 拾光课程表适配脚本\n\n// ==================== 工具函数 ====================\n\n// 解析周次字符串 -> 数字数组\nfunction parseWeeks(weekStr) {\n    const weeks = new Set();\n    if (!weekStr) return [];\n    const parts = weekStr.split(\",\");\n    for (const part of parts) {\n        const trimmed = part.trim();\n        if (trimmed === \"\") continue;\n        if (trimmed.includes(\"-\")) {\n            const [start, end] = trimmed.split(\"-\").map(n => parseInt(n));\n            if (!isNaN(start) && !isNaN(end)) {\n                for (let i = start; i <= end; i++) {\n                    weeks.add(i);\n                }\n            }\n        } else {\n            const n = parseInt(trimmed);\n            if (!isNaN(n) && n >= 1 && n <= 30) {\n                weeks.add(n);\n            }\n        }\n    }\n    return Array.from(weeks).sort((a, b) => a - b);\n}\n\n// 检查是否已登录\nfunction isUserLoggedIn() {\n    const token = localStorage.getItem(\"token\");\n    return token !== null && token !== \"\";\n}\n\n// 合并课程（相同课程合并周次）\nfunction mergeCourses(allCourses) {\n    const merged = {};\n    for (const course of allCourses) {\n        const key = `${course.day}-${course.startSection}-${course.name}`;\n        if (merged[key]) {\n            merged[key].weeks = Array.from(new Set([...merged[key].weeks, ...course.weeks])).sort((a, b) => a - b);\n        } else {\n            merged[key] = { ...course, weeks: [...course.weeks] };\n        }\n    }\n    return Object.values(merged);\n}\n\n// ==================== 预设时间段 ====================\n\nconst presetTimeSlots = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"16:00\", endTime: \"16:45\" },\n    { number: 8, startTime: \"16:55\", endTime: \"17:40\" },\n    { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 10, startTime: \"19:25\", endTime: \"20:10\" },\n    { number: 11, startTime: \"20:20\", endTime: \"21:05\" }\n];\n\nasync function importPresetTimeSlots() {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n        window.shiguangBridge.showToast(\"预设时间段导入成功！\");\n    } catch (error) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + error.message);\n    }\n}\n\n// ==================== 主流程 ====================\n\nasync function runImportFlow() {\n    try {\n        // 1. 检查是否已登录\n        if (!isUserLoggedIn()) {\n            window.shiguangBridge.showToast(\"请先登录教务系统后再导入课程！\");\n            return;\n        }\n\n        // 2. 获取当前学期信息\n        window.shiguangBridge.showToast(\"正在获取学期信息...\");\n        const nowTermRes = await fetch(\"/zhxyApi/term/rhptTerm/get/nowTerm\", {\n            method: \"GET\",\n            headers: {\n                \"X-Access-Token\": localStorage.getItem(\"token\")\n            }\n        });\n        const nowTermData = await nowTermRes.json();\n\n        if (!nowTermData.success || !nowTermData.result) {\n            window.shiguangBridge.showToast(\"获取学期信息失败，请重试！\");\n            return;\n        }\n\n        const { schoolYearKey, nowDate } = nowTermData.result;\n\n        // 3. 让用户选择学期（因为API不返回termCode）\n        const semesterOptions = [\"第一学期 (autumn)\", \"第二学期 (spring)\"];\n        const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择学期\",\n            JSON.stringify(semesterOptions),\n            0\n        );\n\n        if (semesterIndex === null || semesterIndex === undefined) {\n            window.shiguangBridge.showToast(\"导入已取消。\");\n            return;\n        }\n\n        const termCode = semesterIndex === 0 ? \"autumn\" : \"spring\";\n\n        // 4. 遍历所有周次（1-20周）获取课表\n        window.shiguangBridge.showToast(\"正在遍历获取所有周次课表...\");\n        const allCourses = [];\n        const totalWeeks = 20;\n\n        for (let week = 1; week <= totalWeeks; week++) {\n            try {\n                const scheduleUrl = `/zhxyApi/workhall/api/weeklySchedule?_t=${Date.now()}&schoolYear=${schoolYearKey}&termCode=${termCode}&count=${week}`;\n                const scheduleRes = await fetch(scheduleUrl, {\n                    method: \"GET\",\n                    headers: {\n                        \"X-Access-Token\": localStorage.getItem(\"token\")\n                    }\n                });\n                const scheduleData = await scheduleRes.json();\n\n                if (scheduleData.success && Array.isArray(scheduleData.result)) {\n                    for (const item of scheduleData.result) {\n                        const day = parseInt(item.WEEK);\n                        if (isNaN(day) || day < 1 || day > 7) continue;\n\n                        const startSection = parseInt(item.SESSION);\n                        if (isNaN(startSection) || startSection < 1) continue;\n\n                        const continuedSession = parseInt(item.continuedSession) || 1;\n                        const endSection = startSection + continuedSession - 1;\n\n                        const weeks = parseWeeks(item.count);\n                        if (weeks.length === 0) continue;\n\n                        allCourses.push({\n                            name: item.courseName || \"\",\n                            teacher: item.teacherName || \"\",\n                            position: item.address || \"\",\n                            day: day,\n                            startSection: startSection,\n                            endSection: endSection,\n                            weeks: weeks\n                        });\n                    }\n                }\n            } catch (e) {\n                console.warn(`第${week}周获取失败:`, e);\n            }\n        }\n\n        // 5. 合并课程\n        const mergedCourses = mergeCourses(allCourses);\n\n        if (mergedCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未找到任何课程数据！\");\n            return;\n        }\n\n        // 6. 按星期和节次排序\n        mergedCourses.sort((a, b) => a.day - b.day || a.startSection - b.startSection);\n\n        // 7. 保存课程\n        window.shiguangBridge.showToast(`共解析到${mergedCourses.length}门课程，正在导入...`);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(mergedCourses));\n\n        await importPresetTimeSlots();\n\n        window.shiguangBridge.showToast(`课程导入成功！共${mergedCourses.length}门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        console.error(\"导入失败:\", error);\n        window.shiguangBridge.showToast(\"导入失败：\" + error.message);\n    }\n}\n\n// 启动\nrunImportFlow();","HBMU_01":"// 功能：从湖医药教务系统获取课程表，通过桥接 API 导入到拾光课程表\r\n\r\n// ---------- 全局验证函数 ----------\r\nfunction validateYearInput(input) {\r\n    if (/^\\d{4}$/.test(input)) {\r\n        return false; // 验证通过\r\n    } else {\r\n        return \"请输入四位数字的年份（例如 2024）\";\r\n    }\r\n}\r\n\r\n// ---------- 工具函数 ----------\r\nfunction parseWeeks(weeksStr) {\r\n    weeksStr = weeksStr.replace('周', '');\r\n    const parts = weeksStr.split(',');\r\n    const weeks = [];\r\n    for (const part of parts) {\r\n        if (part.includes('-')) {\r\n            const [start, end] = part.split('-').map(Number);\r\n            for (let i = start; i <= end; i++) weeks.push(i);\r\n        } else {\r\n            weeks.push(Number(part));\r\n        }\r\n    }\r\n    return weeks;\r\n}\r\n\r\nfunction parseSections(jcdm) {\r\n    const str = String(jcdm);\r\n    const sections = [];\r\n    if (str.includes('-')) {\r\n        const [start, end] = str.split('-').map(Number);\r\n        for (let i = start; i <= end; i++) sections.push(i);\r\n    } else if (/^\\d+$/.test(str)) {\r\n        for (let i = 0; i < str.length; i += 2) {\r\n            const sec = parseInt(str.substring(i, i + 2), 10);\r\n            if (!isNaN(sec)) sections.push(sec);\r\n        }\r\n    } else {\r\n        sections.push(parseInt(str));\r\n    }\r\n    return sections;\r\n}\r\n\r\nfunction parseRawCourses(rawData) {\r\n    const courseInfos = [];\r\n    for (const course of rawData) {\r\n        const name = course.kcmc;\r\n        const teacher = course.teaxms;\r\n        const position = course.jxcdmc;\r\n        const weeks = parseWeeks(course.zc);\r\n        const day = parseInt(course.xq);\r\n        const sections = parseSections(course.jcdm);\r\n        courseInfos.push({ name, teacher, position, weeks, day, sections });\r\n    }\r\n    return courseInfos;\r\n}\r\n\r\nfunction convertToTargetCourses(middleCourses) {\r\n    return middleCourses.map(c => ({\r\n        name: c.name,\r\n        teacher: c.teacher,\r\n        position: c.position,\r\n        day: c.day,\r\n        startSection: c.sections[0],\r\n        endSection: c.sections[c.sections.length - 1],\r\n        weeks: c.weeks,\r\n        isCustomTime: false\r\n    }));\r\n}\r\n\r\nfunction getTimeSlots() {\r\n    return [\r\n        { number: 1, startTime: \"08:00\", endTime: \"08:40\" },\r\n        { number: 2, startTime: \"08:50\", endTime: \"09:30\" },\r\n        { number: 3, startTime: \"09:40\", endTime: \"10:20\" },\r\n        { number: 4, startTime: \"10:30\", endTime: \"11:10\" },\r\n        { number: 5, startTime: \"11:20\", endTime: \"12:00\" },\r\n        { number: 6, startTime: \"14:30\", endTime: \"15:10\" },\r\n        { number: 7, startTime: \"15:20\", endTime: \"16:00\" },\r\n        { number: 8, startTime: \"16:10\", endTime: \"16:50\" },\r\n        { number: 9, startTime: \"17:00\", endTime: \"17:40\" },\r\n        { number: 10, startTime: \"19:00\", endTime: \"19:40\" },\r\n        { number: 11, startTime: \"19:50\", endTime: \"20:30\" },\r\n        { number: 12, startTime: \"20:40\", endTime: \"21:20\" }\r\n    ];\r\n}\r\n\r\n// ---------- 网络请求 ----------\r\nasync function fetchCourseData(xnxqdm) {\r\n    let page = 1;\r\n    const rowsPerPage = 100;\r\n    let allRows = [];\r\n    let total = 0;\r\n\r\n    while (true) {\r\n        const res = await fetch(\"https://jw.hbmu.edu.cn/xsgrkbcx!getDataList.action\", {\r\n            headers: {\r\n                \"accept\": \"application/json, text/javascript, */*; q=0.01\",\r\n                \"content-type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\r\n                \"x-requested-with\": \"XMLHttpRequest\"\r\n            },\r\n            body: `xnxqdm=${xnxqdm}&page=${page}&rows=${rowsPerPage}`,\r\n            method: \"POST\",\r\n            credentials: \"include\"\r\n        });\r\n        if (!res.ok) {\r\n            throw new Error(`HTTP ${res.status}: ${res.statusText}`);\r\n        }\r\n        const ret = await res.json();\r\n        if (!ret.rows || !Array.isArray(ret.rows)) {\r\n            throw new Error(\"返回数据格式不正确\");\r\n        }\r\n        total = ret.total;\r\n        allRows = allRows.concat(ret.rows);\r\n        if (allRows.length >= total) break;\r\n        page++;\r\n        if (page > 10) break;\r\n    }\r\n    return allRows;\r\n}\r\n\r\n// ---------- 用户交互 ----------\r\nasync function promptUserToStart() {\r\n    return await window.shiguangBridgePromise.showAlert(\r\n        \"重要提醒\",\r\n        \"请确保您已登录湖医药教务系统，且当前页面为教务系统内任意页面。\\n\\n点击确定继续。\",\r\n        \"确定\"\r\n    );\r\n}\r\n\r\nasync function getAcademicYear() {\r\n    return await window.shiguangBridgePromise.showPrompt(\r\n        \"学年设置\",\r\n        \"请输入本学年开始的年份\\n（例如 2024，代表 2024-2025 学年）\",\r\n        \"2024\",\r\n        \"validateYearInput\"  // 传入验证函数名\r\n    );\r\n}\r\n\r\nasync function selectSemester() {\r\n    const semesterOptions = [\"上学期\", \"下学期\", \"短学期\"];\r\n    const index = await window.shiguangBridgePromise.showSingleSelection(\r\n        \"选择学期\",\r\n        JSON.stringify(semesterOptions),\r\n        0\r\n    );\r\n    if (index === null || index < 0) return null;\r\n    return index;\r\n}\r\n\r\n// ---------- 主流程 ----------\r\nasync function run() {\r\n    try {\r\n        // 1. 公告\r\n        const confirmed = await promptUserToStart();\r\n        if (!confirmed) {\r\n            window.shiguangBridge.showToast(\"用户取消了导入流程。\");\r\n            return;\r\n        }\r\n\r\n        // 2. 获取学年\r\n        const yearInput = await getAcademicYear();\r\n        if (yearInput === null) {\r\n            window.shiguangBridge.showToast(\"导入已取消。\");\r\n            return;\r\n        }\r\n        const yearNum = parseInt(yearInput);\r\n        if (isNaN(yearNum) || yearNum < 2000 || yearNum > 2100) {\r\n            await window.shiguangBridgePromise.showAlert(\"错误\", \"学年输入无效，请输入2000-2100之间的数字。\", \"确定\");\r\n            return;\r\n        }\r\n\r\n        // 3. 获取学期\r\n        const semesterIndex = await selectSemester();\r\n        if (semesterIndex === null) {\r\n            window.shiguangBridge.showToast(\"导入已取消。\");\r\n            return;\r\n        }\r\n        const termCode = semesterIndex === 0 ? \"01\" : (semesterIndex === 1 ? \"02\" : \"03\");\r\n        const xnxqdm = `${yearNum}${termCode}`;\r\n\r\n        // 4. 请求课表\r\n        window.shiguangBridge.showToast(\"正在获取课表，请稍候...\");\r\n        let rawData;\r\n        try {\r\n            rawData = await fetchCourseData(xnxqdm);\r\n        } catch (fetchErr) {\r\n            await window.shiguangBridgePromise.showAlert(\r\n                \"网络请求失败\",\r\n                `请求教务系统失败：${fetchErr.message}\\n\\n请检查网络连接和登录状态。`,\r\n                \"确定\"\r\n            );\r\n            return;\r\n        }\r\n\r\n        if (!rawData.length) {\r\n            await window.shiguangBridgePromise.showAlert(\"提示\", \"未获取到任何课程数据。请确认已登录教务系统并选择正确的学年学期。\", \"确定\");\r\n            return;\r\n        }\r\n\r\n        // 5. 解析并转换\r\n        const middleCourses = parseRawCourses(rawData);\r\n        const targetCourses = convertToTargetCourses(middleCourses);\r\n\r\n        // 6. 保存课程\r\n        try {\r\n            await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(targetCourses));\r\n            window.shiguangBridge.showToast(`课程数据已导入（共 ${targetCourses.length} 条）`);\r\n        } catch (saveErr) {\r\n            await window.shiguangBridgePromise.showAlert(\"保存课程失败\", saveErr.message, \"确定\");\r\n            return;\r\n        }\r\n\r\n        // 7. 保存时间段\r\n        const timeSlots = getTimeSlots();\r\n        try {\r\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\r\n            window.shiguangBridge.showToast(\"时间段数据已导入\");\r\n        } catch (slotErr) {\r\n            // 时间段保存失败不终止流程，只提示\r\n            window.shiguangBridge.showToast(`时间段保存失败：${slotErr.message}`);\r\n        }\r\n\r\n        // 8. 完成通知\r\n        window.shiguangBridge.showToast(\"导入完成！\");\r\n        window.shiguangBridge.notifyTaskCompletion();\r\n\r\n    } catch (err) {\r\n        // 捕获所有未预料的错误\r\n        console.error(\"run error:\", err);\r\n        await window.shiguangBridgePromise.showAlert(\r\n            \"导入失败\",\r\n            `未知错误：${err.message || err}\\n\\n请联系开发者。`,\r\n            \"确定\"\r\n        );\r\n        // 仍然通知完成，但可能不会生成有效文件\r\n        window.shiguangBridge.notifyTaskCompletion();\r\n    }\r\n}\r\n\r\n// 启动\r\nrun();","HBUAS_01":"// 湖北文理学院(hbuas.edu.cn) 拾光课程表适配脚本\n// 教务系统：超星教务（hbuas.jw.chaoxing.com，dbname = hbuas）\n// 使用流程：登录教务系统（账密登录或学习通扫码均可）→ 停留在任意教务页面 → 点击“执行导入”\n//\n// 接口说明（2026-2027-1 学期实测，返回 ret 均为 0）：\n//   GET /admin/pkgl/xskb/queryKbForXsd                                  课表页 HTML（内含 #xhid / #xqdm / #xnxq1）\n//   GET /admin/api/jcsj/xqsj/getXqList                                  校区列表（item.id = 校区代码，item.xqmc = 名称）\n//   GET /admin/api/getZclistByXnxq?xnxq=<学年-学期>&xqid=<校区代码>      周次表 data.zclist + 节次时间 data.jcsjszList\n//   GET /admin/xsd/pkgl/xskb/sdpkkbList?xnxq=&xhid=&xqdm=&xskbxslx=0     课程数据 JSON（data[]）\n//\n// 细节说明：\n//   1. 课程数据按“单节”返回（djc = 第几节），脚本先逐节转成课程块，\n//      再交给 wiki 教程《课程合并与去重函数》中的合并去重函数处理：\n//      连续节次合并（1-2 + 3-4 → 1-4）、单双周合并（1,3,5 + 2,4,6 → 1-6）、完全重复去重。\n//      实测 60 条原始记录 → 26 条，节次×周次单元 472 → 472，无数据丢失。\n//   2. kcmc / tmc / croommc 都是 <a> 包裹的 HTML 片段，需要抽文本。\n//   3. 教务系统的 #xnxq1 会把“当前学期”标为 selected，脚本把它作为学期单选列表的默认项：\n//      常用场景一键确认；学期未开始时也可改选下学期提前导入。校区则默认沿用页面校区、不弹窗。\n//   4. 作息时间与开学日期都从教务接口读取，不写死；仅在接口异常时回退到内置的北校区作息表。\n//\n// 维护者：salt-fishes\n\n// 学期选择：默认【弹出单选列表】，并把教务系统标记的“当前学期”作为默认选中项。\n//   常用场景直接确认即可；学期尚未开始时，也可在这里改选下学期，提前导入课表。\n//   若希望完全不弹窗、始终使用当前学期，改为 false。\nconst ASK_SEMESTER = true;\n\n// 校区选择：默认沿用当前页面校区、不弹窗（同一学生通常只在一个校区上课）。\n//   若希望每次手动选择校区，改为 true。\nconst ASK_CAMPUS = false;\n\n// 接口异常时的兜底作息（2026-2027-1 北校区实测值），正常情况不会用到\nconst FALLBACK_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4, startTime: \"10:50\", endTime: \"11:40\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"16:00\", endTime: \"16:45\" },\n    { number: 8, startTime: \"16:45\", endTime: \"17:30\" },\n    { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 10, startTime: \"19:15\", endTime: \"20:00\" }\n];\n\n// 兜底总周数（接口返回 zclist 长度时以接口为准）\nconst FALLBACK_TOTAL_WEEKS = 20;\n\n// 出错时附在弹窗里的诊断信息（便于用户反馈时定位）\nlet diagnoseInfo = '';\n\n// =========================================================================\n// 桥接封装\n// =========================================================================\n\nfunction toast(message) {\n    if (window.shiguangBridge && typeof window.shiguangBridge.showToast === 'function') {\n        window.shiguangBridge.showToast(message);\n    } else {\n        console.log('[HBUAS] ' + message);\n    }\n}\n\nasync function alertUser(title, content) {\n    if (window.shiguangBridgePromise && typeof window.shiguangBridgePromise.showAlert === 'function') {\n        return await window.shiguangBridgePromise.showAlert(title, content, \"确定\");\n    }\n    console.warn('[HBUAS] ' + title + ' - ' + content);\n    return true;\n}\n\n// =========================================================================\n// 文本与周次解析\n// =========================================================================\n\n// 超星返回的字段带有 <a> 标签，取出其中的纯文本\nfunction extractAnchorText(htmlStr) {\n    if (!htmlStr) return '';\n    const match = String(htmlStr).match(/>([^<]+)</);\n    return match ? match[1].trim() : String(htmlStr).trim();\n}\n\n// 去掉教师名里的括号备注\nfunction cleanTeacherName(name) {\n    if (!name) return '';\n    return name.replace(/（[^）]*）/g, '').replace(/\\([^)]*\\)/g, '').trim();\n}\n\n// 超星的 zcstr 直接是逗号分隔的周次数字，例如 \"1,2,3,10,11\"\nfunction parseWeeks(weekStr) {\n    if (!weekStr) return [];\n    return String(weekStr).split(',')\n        .map(w => Number(String(w).trim()))\n        .filter(w => !isNaN(w) && w > 0)\n        .sort((a, b) => a - b);\n}\n\nfunction formatTime(timeStr) {\n    if (typeof timeStr !== 'string') return null;\n    const match = timeStr.match(/^(\\d{1,2}):(\\d{1,2})(?::\\d{1,2})?$/);\n    if (!match) return null;\n    const hour = Number(match[1]);\n    const minute = Number(match[2]);\n    return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;\n}\n\n// =========================================================================\n// 网络请求封装\n// =========================================================================\n\nasync function getJson(url) {\n    const response = await fetch(url, {\n        method: 'GET',\n        credentials: 'include',\n        headers: {\n            'Accept': 'application/json, text/plain, */*',\n            'X-Requested-With': 'XMLHttpRequest'\n        }\n    });\n    if (!response.ok) throw new Error(`网络请求失败，状态码 ${response.status}（${url.split('?')[0]}）`);\n    const json = await response.json();\n    if (json.ret !== 0) {\n        // 带上接口名与 ret，便于用户反馈时快速定位（例如 xhid 无效时 sdpkkbList 会返回 ret=-1）\n        throw new Error(`${url.split('?')[0]} 返回 ret=${json.ret}：${json.msg || '未知错误'}`);\n    }\n    return json;\n}\n\n// =========================================================================\n// 页面参数提取\n// =========================================================================\n\n// 课表页地址。其服务端渲染的 #xhid（86 字符加密串）/ #xqdm / #xnxq1 才是正确参数。\n// 注意：教务首页 /admin 里也存在一个 id=\"xhid\" 的元素，但值是用户 ID（32 字符）。\n// 若误用它调 sdpkkbList，服务端会返回 ret=-1「功能暂时停用，请联系管理员」。\n// 因此这里【始终优先采用课表页里的值】，只有当课表页抓取失败时才退回当前页面 DOM。\nconst KB_PAGE_URL = '/admin/pkgl/xskb/queryKbForXsd';\n\nfunction pickKbParams(doc) {\n    return {\n        xhid: doc.querySelector('#xhid')?.value || '',\n        xqdm: doc.querySelector('#xqdm')?.value || '',\n        xnxqSelectHtml: doc.querySelector('#xnxq1')?.outerHTML || null\n    };\n}\n\n// 提取 #xhid（学号加密串）/ #xqdm（校区代码）/ #xnxq1（学期下拉）\nasync function extractPageParams() {\n    let pageHtml = null;\n    try {\n        const response = await fetch(KB_PAGE_URL, {\n            method: 'GET',\n            credentials: 'include',\n            headers: { 'Accept': 'text/html,application/xhtml+xml,*/*;q=0.8' }\n        });\n        if (response.ok) {\n            pageHtml = await response.text();\n        } else {\n            console.warn(`JS: 抓取课表页失败，状态码 ${response.status}`);\n        }\n    } catch (error) {\n        console.warn('JS: 抓取课表页异常:', error.message);\n    }\n\n    let params = { xhid: '', xqdm: '', xnxqSelectHtml: null };\n    let source = '';\n\n    if (pageHtml) {\n        const fromPage = pickKbParams(new DOMParser().parseFromString(pageHtml, 'text/html'));\n        if (fromPage.xhid && fromPage.xqdm) {\n            params = fromPage;\n            source = '课表页';\n        }\n    }\n    if (!params.xhid || !params.xqdm) {\n        const fromDom = pickKbParams(document);\n        if (fromDom.xhid && fromDom.xqdm) {\n            params = fromDom;\n            source = '当前页面';\n        }\n    }\n\n    if (!params.xhid || !params.xqdm) {\n        throw new Error('无法获取课表页参数（#xhid / #xqdm），请确认已登录教务系统');\n    }\n    console.log(`JS: 参数来源=${source}，xhid=${params.xhid.length} 字符，xqdm=${params.xqdm.length} 字符`);\n    return params;\n}\n\n// 解析 #xnxq1 下拉：labels / values / 当前选中索引\nfunction parseSemesterOptions(selectHtml) {\n    if (!selectHtml) return null;\n    const doc = new DOMParser().parseFromString(selectHtml, 'text/html');\n    const select = doc.querySelector('#xnxq1') || doc.querySelector('select[name=\"xnxq\"]');\n    if (!select) return null;\n\n    const options = Array.from(select.querySelectorAll('option')).filter(o => (o.value || '').trim() !== '');\n    if (options.length === 0) return null;\n\n    const labels = options.map(o => (o.textContent || o.value || '').trim());\n    const values = options.map(o => (o.value || '').trim());\n\n    // 当前选中项（教务系统会把当前学期标为 selected）\n    let selectedIndex = options.findIndex(o => o.selected);\n    if (selectedIndex < 0) selectedIndex = -1;\n\n    return { labels, values, selectedIndex: selectedIndex, defaultIndex: selectedIndex >= 0 ? selectedIndex : 0 };\n}\n\n// =========================================================================\n// 学期 / 校区选择\n// =========================================================================\n\nasync function chooseSemester(selectHtml) {\n    const options = parseSemesterOptions(selectHtml);\n    if (!options) {\n        throw new Error('未能读取学年学期下拉，请确认已登录教务系统');\n    }\n\n    // 默认静默采用教务系统标记的当前学期（可改为始终询问，见 ASK_SEMESTER）\n    if (!ASK_SEMESTER && options.selectedIndex >= 0) {\n        const picked = options.values[options.selectedIndex];\n        console.log(`JS: 自动使用当前学期 ${picked}`);\n        return picked;\n    }\n\n    // 弹出单选列表，并把“当前学期”作为默认选中项：\n    // 常用场景直接确认即可；学期未开始时，也可在此改选下学期提前导入课表\n    const index = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学年学期\", JSON.stringify(options.labels), options.defaultIndex\n    );\n    if (index === null || index === -1) return null;\n    return options.values[index];\n}\n\nasync function chooseCampus(pageXqdm) {\n    let campusList = null;\n    try {\n        const json = await getJson('/admin/api/jcsj/xqsj/getXqList');\n        campusList = (json.data || [])\n            .map(item => ({ xqdm: String(item.id || '').trim(), xqmc: String(item.xqmc || item.id || '').trim() }))\n            .filter(item => item.xqdm && item.xqmc);\n    } catch (error) {\n        console.warn('JS: 获取校区列表失败:', error.message);\n    }\n\n    if (!campusList || campusList.length === 0) {\n        toast(\"未获取到校区列表，使用当前页面校区继续导入。\");\n        return { xqdm: pageXqdm, xqmc: \"\" };\n    }\n\n    const matched = campusList.findIndex(item => item.xqdm === pageXqdm);\n    if (!ASK_CAMPUS && matched >= 0) {\n        console.log(`JS: 自动使用页面校区 ${campusList[matched].xqmc}`);\n        return campusList[matched];\n    }\n\n    const index = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择校区\", JSON.stringify(campusList.map(item => item.xqmc)), matched >= 0 ? matched : 0\n    );\n    if (index === null || index === -1) return null;\n    return campusList[index];\n}\n\n// =========================================================================\n// 作息时间与开学日期\n// =========================================================================\n\n// 返回 { timeSlots, semesterStartDate, semesterTotalWeeks }\nasync function fetchTimeAndWeekData(xnxq, xqdm) {\n    const json = await getJson(`/admin/api/getZclistByXnxq?xnxq=${encodeURIComponent(xnxq)}&xqid=${encodeURIComponent(xqdm)}`);\n    const data = json.data || {};\n\n    // 节次时间\n    let timeSlots = null;\n    if (Array.isArray(data.jcsjszList) && data.jcsjszList.length > 0) {\n        timeSlots = data.jcsjszList\n            .map(item => ({ number: Number(item.jc), startTime: formatTime(item.kssj), endTime: formatTime(item.jssj) }))\n            .filter(item => item.number > 0 && item.startTime && item.endTime)\n            .sort((a, b) => a.number - b.number);\n        if (timeSlots.length === 0) timeSlots = null;\n    }\n\n    // 开学日期 = 第 1 周的周一\n    let semesterStartDate = null;\n    if (Array.isArray(data.zclist)) {\n        const firstWeek = data.zclist.find(z => Number(z.zc) === 1);\n        if (firstWeek && firstWeek.minrq) {\n            semesterStartDate = String(firstWeek.minrq).split(' ')[0];\n        }\n    }\n\n    const semesterTotalWeeks = Array.isArray(data.zclist) && data.zclist.length > 0\n        ? data.zclist.length\n        : FALLBACK_TOTAL_WEEKS;\n\n    return { timeSlots, semesterStartDate, semesterTotalWeeks };\n}\n\n// =========================================================================\n// 课程数据\n// =========================================================================\n\n/**\n * 节次与周次合并去重函数\n * 采用 wiki 教程《课程合并与去重函数》的参考实现，未做修改\n * @param {Array<Object>} courses 原始解析课程数组\n * @returns {Array<Object>} 合并去重后的课程数组\n */\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    // 1. 深拷贝并规范周次数据，过滤无效项\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    // 阶段 1：合并连续节次与完全重复记录（前提：名称、教师、地点、星期、周次一致）\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n               (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            // 节次连续：延长结束节次 (如 1-2 节 + 3-4 节 -> 1-4 节)\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            // 完全重复：跳过\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    // 阶段 2：合并同节次的周次（前提：名称、教师、地点、星期、开始/结束节次一致）\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n               a.teacher.localeCompare(b.teacher) ||\n               a.position.localeCompare(b.position) ||\n               (a.day || 0) - (b.day || 0) ||\n               (a.startSection || 0) - (b.startSection || 0) ||\n               (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let cur = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const nxt = step1Merged[i];\n\n        const isSameCourseAndSection =\n            cur.name === nxt.name &&\n            cur.teacher === nxt.teacher &&\n            cur.position === nxt.position &&\n            cur.day === nxt.day &&\n            cur.startSection === nxt.startSection &&\n            cur.endSection === nxt.endSection;\n\n        if (isSameCourseAndSection) {\n            // 周次合并去重 (如 1-8 周 + 9-16 周 -> 1-16 周)\n            cur.weeks = Array.from(new Set([...cur.weeks, ...nxt.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(cur);\n            cur = nxt;\n        }\n    }\n    step2Merged.push(cur);\n\n    return step2Merged;\n}\n\nfunction parseCourseData(jsonData) {\n    if (!jsonData || !Array.isArray(jsonData.data)) return [];\n\n    // 超星按“单节”返回（djc = 第几节）：先逐节转成课程块（startSection = endSection = 节次），\n    // 再交给 mergeAndDistinctCourses 处理连续节次、单双周与重复记录\n    const rawCourses = [];\n\n    for (const raw of jsonData.data) {\n        const name = extractAnchorText(raw.kcmc);\n        const teacher = cleanTeacherName(extractAnchorText(raw.tmc));\n        const position = extractAnchorText(raw.croommc) || '待定';\n        const day = Number(raw.xingqi);\n        const section = Number(raw.djc);\n        const weeks = parseWeeks(raw.zcstr);\n\n        if (!name || isNaN(day) || isNaN(section) || day < 1 || day > 7 || section < 1 || weeks.length === 0) {\n            continue;\n        }\n\n        rawCourses.push({\n            name: name,\n            teacher: teacher,\n            position: position,\n            day: day,\n            startSection: section,\n            endSection: section,\n            weeks: weeks\n        });\n    }\n\n    return mergeAndDistinctCourses(rawCourses);\n}\n\nasync function fetchCourses(xnxq, xhid, xqdm) {\n    const url = `/admin/xsd/pkgl/xskb/sdpkkbList?xnxq=${encodeURIComponent(xnxq)}&xhid=${encodeURIComponent(xhid)}&xqdm=${encodeURIComponent(xqdm)}&xskbxslx=0`;\n    const json = await getJson(url);\n    return parseCourseData(json);\n}\n\n// =========================================================================\n// 保存\n// =========================================================================\n\nasync function saveCourses(courses) {\n    await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n}\n\nasync function saveTimeSlots(timeSlots) {\n    await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n}\n\nasync function saveConfig(semesterStartDate, semesterTotalWeeks) {\n    const config = { semesterTotalWeeks: semesterTotalWeeks };\n    if (semesterStartDate) config.semesterStartDate = semesterStartDate;\n    await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n// =========================================================================\n// 主流程\n// =========================================================================\n\nfunction isLoginPage() {\n    return window.location.href.includes('/admin/login') || window.location.href.includes('slogin');\n}\n\nasync function runImportFlow() {\n    try {\n        if (isLoginPage()) {\n            await alertUser(\"导入失败\", \"当前是登录页面，请先完成登录并进入教务系统内部页面后再执行导入。\");\n            return;\n        }\n\n        const confirmed = await alertUser(\n            \"湖北文理学院教务系统课表导入\",\n            \"将自动读取当前学期、校区、作息时间与开学日期。\\n导入前请确认已成功登录教务系统。\"\n        );\n        if (confirmed !== true && confirmed !== \"true\") {\n            toast(\"用户取消了导入。\");\n            return;\n        }\n\n        // 1. 参数（来自课表页而非当前页面，见 extractPageParams 注释）\n        const { xhid, xqdm: pageXqdm, xnxqSelectHtml } = await extractPageParams();\n        diagnoseInfo = `xhid ${xhid.length} 字符 / xqdm ${pageXqdm.length} 字符`;\n\n        // 2. 学期（默认取教务系统标记的当前学期）\n        const xnxq = await chooseSemester(xnxqSelectHtml);\n        if (xnxq === null) {\n            toast(\"导入已取消：未选择学年学期。\");\n            return;\n        }\n\n        // 3. 校区（默认取当前页面校区）\n        const campus = await chooseCampus(pageXqdm);\n        if (campus === null) {\n            toast(\"导入已取消：未选择校区。\");\n            return;\n        }\n\n        toast(`正在导入 ${xnxq}${campus.xqmc ? ' · ' + campus.xqmc : ''} ...`);\n\n        // 4. 课程\n        const courses = await fetchCourses(xnxq, xhid, campus.xqdm);\n        if (courses.length === 0) {\n            await alertUser(\"未找到课程\", `${xnxq} 学期未获取到任何课程数据，请确认学期选择是否正确，或该学期暂无排课。`);\n            return;\n        }\n        await saveCourses(courses);\n        console.log(`JS: 课程保存成功，共 ${courses.length} 条。`);\n\n        // 5. 作息时间与开学日期（失败不阻塞课程导入）\n        try {\n            const { timeSlots, semesterStartDate, semesterTotalWeeks } = await fetchTimeAndWeekData(xnxq, campus.xqdm);\n            await saveConfig(semesterStartDate, semesterTotalWeeks);\n\n            if (timeSlots && timeSlots.length > 0) {\n                await saveTimeSlots(timeSlots);\n            } else {\n                await saveTimeSlots(FALLBACK_TIME_SLOTS);\n                toast(\"未获取到教务作息，已使用内置作息表。\");\n            }\n            console.log(`JS: 配置导入完成，开学日期 ${semesterStartDate}，总周数 ${semesterTotalWeeks}。`);\n        } catch (error) {\n            console.warn('JS: 作息/开学日期获取失败:', error.message);\n            toast(\"作息时间与开学日期获取失败，课程已导入，可稍后重试。\");\n        }\n\n        toast(`导入成功：${courses.length} 条课程、${xnxq}${campus.xqmc ? ' · ' + campus.xqmc : ''}。`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        console.error('JS: 导入流程异常:', error);\n        const tail = diagnoseInfo ? `\\n\\n[诊断] ${diagnoseInfo}` : '';\n        await alertUser(\"导入失败\", `${error.message}\\n\\n请确认：\\n1. 已在教务系统中成功登录；\\n2. 网络可以正常访问 hbuas.jw.chaoxing.com。${tail}`);\n    }\n}\n\nrunImportFlow();\n","HBMZU":"// 湖北民族大学教务系统（jwgl.hbmzu.edu.cn/edu）拾光课表导入适配脚本\n// 课表查询页（/edu/report/mySchedule.mvc）直接渲染课表 DOM：\n//   #container 内每行 tr：首 td 为节次（\"上午1-2节\"…\"晚上11-12节\"），后续 7 个 td 对应周一~周日\n//   每格 .course-block 含 span：课程名、教室、周次、教师（无教室时仅 3 个）\n// 注意：无开学日期/总周数接口，config 仅保存作息时间\n\n// 预设作息时间（12 节，含午间/晚间）\nconst HBMZU_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"10:05\", endTime: \"10:50\" },\n    { number: 4, startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:50\", endTime: \"15:35\" },\n    { number: 7, startTime: \"16:05\", endTime: \"16:50\" },\n    { number: 8, startTime: \"16:55\", endTime: \"17:40\" },\n    { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 10, startTime: \"19:20\", endTime: \"20:05\" },\n    { number: 11, startTime: \"20:15\", endTime: \"21:00\" },\n    { number: 12, startTime: \"21:05\", endTime: \"21:50\" }\n];\n\nfunction getErrorMessage(error) {\n    if (error && typeof error.message === \"string\" && error.message.trim()) return error.message;\n    if (typeof error === \"string\" && error.trim()) return error;\n    try {\n        const serialized = JSON.stringify(error);\n        if (serialized && serialized !== \"{}\") return serialized;\n    } catch (_) {\n        // Ignore serialization failures.\n    }\n    return \"未知错误\";\n}\n\n// 收集可访问的 document（frameset 用 <frame>，普通页面用 <iframe>）\nfunction collectDocs() {\n    const docs = [document];\n    const frames = document.querySelectorAll(\"iframe, frame\");\n    for (const f of frames) {\n        try {\n            if (f.contentDocument) docs.push(f.contentDocument);\n        } catch (_) {\n            // 跨域 frame 无法访问，忽略。\n        }\n    }\n    return docs;\n}\n\n// 从各 frame 中查找课表表格（#container 内含 .course-block）\n// 注入时机早于 frame 加载完成，故轮询等待 frame 就绪（最长 6 秒）\nasync function findCourseTable() {\n    const deadline = Date.now() + 6000;\n    while (Date.now() < deadline) {\n        for (const doc of collectDocs()) {\n            const container = doc.getElementById(\"container\");\n            if (container && container.querySelector(\".course-block\")) {\n                return container;\n            }\n        }\n        await new Promise(resolve => setTimeout(resolve, 300));\n    }\n    return null;\n}\n\n// 解析周次文本：\"3-14周\"→3..14；\"3-13单周\"→3,5,7,9,11,13；\"4-14双周\"→4,6..14；\"14-15周\"→14,15\nfunction parseWeeksText(weekStr) {\n    const text = String(weekStr || \"\").replace(/\\s+/g, \"\");\n    const m = text.match(/^(\\d+)-(\\d+)(单|双)?周$/);\n    if (!m) return [];\n    const start = Number(m[1]);\n    const end = Number(m[2]);\n    const parity = m[3]; // \"单\" / \"双\" / undefined\n    const weeks = [];\n    for (let w = start; w <= end; w++) {\n        if (parity === \"单\" && w % 2 === 0) continue;\n        if (parity === \"双\" && w % 2 === 1) continue;\n        weeks.push(w);\n    }\n    return weeks;\n}\n\n// 是否为周次文本（\"3-14周\" / \"3-13单周\" / \"4-14双周\" / \"12-12周\"）\n// 用于在 3 个 span 时区分\"无教室（名-周次-教师）\"和\"无教师（名-教室-周次）\"两种结构\nfunction isWeeksText(text) {\n    return /^\\d+-\\d+(单|双)?周$/.test(String(text || \"\").replace(/\\s+/g, \"\"));\n}\n\n// 解析课表表格\n// 每行首 td 为节次文本（\"上午1-2节\"→1-2），其后 7 个 td 依次为周一~周日\nfunction parseCourseTable(container) {\n    const courses = [];\n    container.querySelectorAll(\"tr\").forEach(row => {\n        const tds = row.querySelectorAll(\"td\");\n        if (tds.length < 2) return;\n        const sectionText = (tds[0].textContent || \"\").replace(/\\s+/g, \"\");\n        const sectionMatch = sectionText.match(/(\\d+)-(\\d+)节/);\n        if (!sectionMatch) return;\n        const startSection = Number(sectionMatch[1]);\n        const endSection = Number(sectionMatch[2]);\n\n        for (let i = 0; i < 7; i++) {\n            const dayTd = tds[i + 1];\n            if (!dayTd) continue;\n            const blocks = dayTd.querySelectorAll(\".course-block\");\n            for (const block of blocks) {\n                const cells = [];\n                block.querySelectorAll(\"span\").forEach(function (s) {\n                    cells.push((s.textContent || \"\").trim());\n                });\n                if (cells.length < 3) continue;\n                const name = cells[0];\n                if (!name) continue;\n                // span 结构：[名称, 教室?, 周次, 教师]，教室或教师可能缺失：\n                //   3 个 span 可能是 [名称, 周次, 教师]（无教室），也可能是 [名称, 教室, 周次]（无教师）\n                // 先找出长得像周次的 span：它前面的第一个 span 是教室，后面的第一个 span 是教师\n                let weekIndex = -1;\n                let weekStr = \"\";\n                for (let j = 1; j < cells.length; j++) {\n                    if (isWeeksText(cells[j])) {\n                        weekIndex = j;\n                        weekStr = cells[j];\n                        break;\n                    }\n                }\n                if (weekIndex < 0) continue;\n                const position = weekIndex >= 2 ? cells[weekIndex - 1] : \"\";\n                const teacher = weekIndex + 1 < cells.length ? cells[weekIndex + 1] : \"\";\n                const weeks = parseWeeksText(weekStr);\n                if (weeks.length === 0) continue;\n                courses.push({\n                    name,\n                    teacher: teacher || \"未知\",\n                    position: position || \"待定\",\n                    day: i + 1,\n                    startSection,\n                    endSection,\n                    weeks\n                });\n            }\n        }\n    });\n    return courses;\n}\n\n// 合并同课程同时间同教室的条目（如单双周分教室的保持两条）\nfunction mergeCourses(courses) {\n    const merged = new Map();\n    for (const c of courses) {\n        const key = `${c.name}|${c.teacher}|${c.position}|${c.day}|${c.startSection}|${c.endSection}`;\n        const holder = merged.get(key);\n        if (holder) {\n            holder.weeks = Array.from(new Set([...holder.weeks, ...c.weeks])).sort((a, b) => a - b);\n        } else {\n            merged.set(key, { ...c, weeks: [...c.weeks].sort((a, b) => a - b) });\n        }\n    }\n    return Array.from(merged.values()).sort(\n        (a, b) => a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name)\n    );\n}\n\n// 保存作息时间\nasync function saveTimeSlots(timeSlots) {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    } catch (error) {\n        console.error(\"JS: 作息时间保存失败\", error);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n        \"课表导入\",\n        \"导入前请确保已登录并打开课表查询页面。\",\n        \"好的，开始导入\"\n    );\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    try {\n        const container = await findCourseTable();\n        if (!container) throw new Error(\"未找到课表，请确认已登录并打开课表查询页面。\");\n\n        const courses = parseCourseTable(container);\n        if (courses.length === 0) throw new Error(\"课表中未解析到有效课程，请确认当前学期有课。\");\n\n        const merged = mergeCourses(courses);\n\n        window.shiguangBridge.showToast(`正在保存 ${merged.length} 门课程...`);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(merged, null, 2));\n        await saveTimeSlots(HBMZU_TIME_SLOTS);\n\n        window.shiguangBridge.showToast(`课程导入成功，共导入 ${merged.length} 门课程！`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(`导入失败：${getErrorMessage(error)}`);\n        console.error(\"JS: Import Error\", error);\n    }\n}\n\nrunImportFlow();\n","HUAT":"// 文件: HUAT.js - 湖北汽车工业学院课表导入（基于教务系统 API） \n// 数据源:\n//   /api/semester/list  → 可选学期列表（用于学期选择 + 学期基本信息）\n//   /api/teachTask/list  → 教学任务列表（按 yearTermId 过滤）\n\n// ==================== 验证函数 ====================\nfunction validateDate(dateStr) {\n    if (!dateStr || dateStr.trim().length === 0) {\n        return \"日期不能为空！\";\n    }\n    const datePattern = /^\\d{4}-\\d{2}-\\d{2}$/;\n    if (!datePattern.test(dateStr)) {\n        return \"日期格式必须是 YYYY-MM-DD！\";\n    }\n    const parts = dateStr.split('-');\n    const year = parseInt(parts[0]);\n    const month = parseInt(parts[1]);\n    const day = parseInt(parts[2]);\n    const date = new Date(year, month - 1, day);\n    if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {\n        return \"请输入有效的日期！\";\n    }\n    return false;\n}\n\n// ==================== API 数据获取 ====================\n// 用当前页面协议构造 API 基址，避免 HTTP/HTTPS 跨域\n// （http:// 和 https:// 在 CORS 看来是不同 origin，会触发预检并失败）\nconst API_BASE = window.location.protocol + '//neweas.huat.edu.cn';\n\n/**\n * 获取认证 token（X-Token 头的值）\n * 优先级：localStorage / sessionStorage 常见 key → Admin-Token cookie → window 全局\n */\nfunction getAuthToken() {\n    const storageKeys = ['Admin-Token', 'adminToken', 'token', 'X-Token', 'x-token', 'admin_token'];\n    for (const key of storageKeys) {\n        const v = localStorage.getItem(key) || sessionStorage.getItem(key);\n        if (v) return v;\n    }\n    // 从 cookie 读 Admin-Token\n    const cookieMatch = document.cookie.match(/Admin-Token=([^;]+)/);\n    if (cookieMatch) return cookieMatch[1];\n    // window 全局\n    if (window.token) return window.token;\n    if (window.userToken) return window.userToken;\n    return null;\n}\n\n/**\n * 解析 JWT payload（仅解码，不验签）\n */\nfunction decodeJwtPayload(jwt) {\n    if (!jwt) return null;\n    const parts = jwt.split('.');\n    if (parts.length !== 3) return null;\n    try {\n        const b64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');\n        const json = decodeURIComponent(atob(b64).split('').map(c =>\n            '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)\n        ).join(''));\n        return JSON.parse(json);\n    } catch (e) {\n        return null;\n    }\n}\n\n/**\n * 从 JWT 的 sub 字段提取学生 ID\n */\nfunction getStudentId() {\n    const token = getAuthToken();\n    if (!token) return null;\n    const payload = decodeJwtPayload(token);\n    return (payload && payload.sub) || null;\n}\n\n/**\n * 诊断信息：token 来源 + 预览 + 当前页面 URL\n * 用于手机端排查认证失败问题（手机端通常没 DevTools 可看）\n */\nfunction getTokenDiagnostic() {\n    const storageKeys = ['Admin-Token', 'adminToken', 'token', 'X-Token', 'x-token', 'admin_token'];\n    let source = '未找到';\n    let token = null;\n\n    for (const key of storageKeys) {\n        const v = localStorage.getItem(key);\n        if (v) { token = v; source = 'localStorage[' + key + ']'; break; }\n    }\n    if (!token) {\n        for (const key of storageKeys) {\n            const v = sessionStorage.getItem(key);\n            if (v) { token = v; source = 'sessionStorage[' + key + ']'; break; }\n        }\n    }\n    if (!token) {\n        const m = document.cookie.match(/Admin-Token=([^;]+)/);\n        if (m) { token = m[1]; source = 'cookie[Admin-Token]'; }\n    }\n    if (!token && window.token) { token = window.token; source = 'window.token'; }\n    if (!token && window.userToken) { token = window.userToken; source = 'window.userToken'; }\n\n    const preview = token\n        ? (token.length > 24 ? token.slice(0, 12) + '...' + token.slice(-8) : token)\n        : 'null';\n    return 'token=' + preview + ' (长度=' + (token ? token.length : 0) + ', source=' + source + ')\\nURL=' + window.location.href;\n}\n\nasync function fetchSemesterList() {\n    console.log(\"拉取学期列表...\");\n    const token = getAuthToken();\n    if (!token) {\n        throw new Error('无法获取认证 token\\n\\n诊断:\\n' + getTokenDiagnostic());\n    }\n\n    // cURL 抓包：POST 无 body（Content-Length: 0），无 Content-Type\n    let res;\n    try {\n        res = await fetch(API_BASE + '/api/semester/list', {\n            method: 'POST',\n            credentials: 'include',\n            headers: {\n                'Accept': 'application/json, text/plain, */*',\n                'X-Token': token\n            }\n        });\n    } catch (fetchErr) {\n        // 网络层失败：CORS、URL 不可达、SSL 错误等\n        throw new Error('fetch 失败: ' + fetchErr.message + '\\n\\n诊断:\\n' + getTokenDiagnostic());\n    }\n    if (!res.ok) {\n        throw new Error('semester/list HTTP ' + res.status + '\\n\\n诊断:\\n' + getTokenDiagnostic());\n    }\n    const json = await res.json();\n    if (json.code !== 200) {\n        throw new Error('semester/list 返回错误 [code=' + json.code + ']: ' + json.msg + '\\n\\n诊断:\\n' + getTokenDiagnostic());\n    }\n    return json.data || [];\n}\n\nasync function fetchTeachTaskList(yearTermId) {\n    console.log(\"拉取教学任务... yearTermId=\" + (yearTermId || '(未指定)'));\n    const token = getAuthToken();\n    if (!token) {\n        throw new Error('无法获取认证 token，请确认已登录教务系统');\n    }\n    const studId = getStudentId() || '';\n\n    // body 格式来自 cURL 抓包：{\"weekNum\":\"\",\"yearTermId\":\"20252\",\"studId\":\"202402417\"}\n    let res;\n    try {\n        res = await fetch(API_BASE + '/api/teachTask/list', {\n            method: 'POST',\n            credentials: 'include',\n            headers: {\n                'Content-Type': 'application/json',\n                'X-Token': token,\n                'X-Requested-With': 'XMLHttpRequest'\n            },\n            body: JSON.stringify({\n                weekNum: \"\",\n                yearTermId: yearTermId || \"\",\n                studId: studId\n            })\n        });\n    } catch (fetchErr) {\n        throw new Error('fetch 失败: ' + fetchErr.message + '\\n\\n诊断:\\n' + getTokenDiagnostic());\n    }\n    if (!res.ok) {\n        throw new Error('teachTask/list HTTP ' + res.status);\n    }\n    const json = await res.json();\n    if (json.code !== 200) {\n        throw new Error('teachTask/list 返回错误 [code=' + json.code + ']: ' + json.msg);\n    }\n    return json.data || [];\n}\n\n// ==================== 数据转换 ====================\n/**\n * 把选中的学期对象转成内部用的 semesterInfo\n * semesterStartDate 来自学期 beginDate\n * semesterTotalWeeks 来自 beginWeek..endWeek\n */\nfunction buildSemesterInfoFromSemester(semester) {\n    if (!semester) {\n        return { semesterStartDate: '2026-09-07', semesterTotalWeeks: 25, yearTermId: null };\n    }\n    const beginWeek = semester.beginWeek || 1;\n    const endWeek = semester.endWeek || 25;\n    return {\n        semesterStartDate: semester.beginDate,\n        semesterTotalWeeks: endWeek - beginWeek + 1,\n        yearTermId: semester.yearTermID\n    };\n}\n\n/**\n * 根据 lessType 把 weekBegin..weekEnd 展开为周次数组\n *   \"全周\" → 所有周\n *   \"单周\" → 仅奇数周\n *   \"双周\" → 仅偶数周\n */\nfunction buildWeeksArray(weekBegin, weekEnd, lessType) {\n    const weeks = [];\n    const start = weekBegin || 1;\n    const end = weekEnd || start;\n    for (let w = start; w <= end; w++) {\n        if (lessType === '单周' && w % 2 === 0) continue;\n        if (lessType === '双周' && w % 2 === 1) continue;\n        weeks.push(w);\n    }\n    return weeks;\n}\n\n/**\n * 把 teachTask/list 返回的数组转换成 saveImportedCourses 所需格式\n * 注意：day 直接用 API 的 weekDay（1=周一 ... 7=周日）\n *       若发现课程排错星期，改成 task.weekDay - 1（0=周一）即可\n */\nfunction transformTeachTaskToCourses(taskList) {\n    const courses = [];\n    (taskList || []).forEach(task => {\n        // 教师名拼接（多个教师用「、」连接）\n        const teachers = (task.teacherList || [])\n            .map(t => t.teacherName)\n            .filter(name => name && String(name).trim().length > 0);\n        const teacher = teachers.length > 0 ? teachers.join('、') : '未知教师';\n\n        const course = {\n            name: task.courName || '未知课程',\n            teacher: teacher,\n            position: task.roomId ? String(task.roomId) : '未知教室',\n            day: task.weekDay,                              // API: 1=周一 ... 7=周日\n            startSection: task.startSection,\n            endSection: task.endSection,\n            weeks: buildWeeksArray(task.weekBegin, task.weekEnd, task.lessType),\n            isCustomTime: false\n        };\n        courses.push(course);\n    });\n    return courses;\n}\n\n// ========== 根据季节获取时间段（夏季/秋季） ==========\n/**\n * 根据季节返回对应的时间段数组\n * @param {string} season - \"summer\" 或 \"autumn\"\n * @returns {Array} 时间段对象数组\n */\nfunction getSeasonTimeSlots(season) {\n    // 上午固定时间（夏秋通用）\n    const morning_classes = [\n        {\"number\": 1, \"startTime\": \"08:10\", \"endTime\": \"08:55\"},\n        {\"number\": 2, \"startTime\": \"09:00\", \"endTime\": \"09:45\"},\n        {\"number\": 3, \"startTime\": \"10:05\", \"endTime\": \"10:50\"},\n        {\"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\"}\n    ];\n\n    // 夏季下午/晚上时间\n    const summer_afternoon_evening = [\n        {\"number\": 5, \"startTime\": \"14:30\", \"endTime\": \"15:15\"},\n        {\"number\": 6, \"startTime\": \"15:20\", \"endTime\": \"16:05\"},\n        {\"number\": 7, \"startTime\": \"16:25\", \"endTime\": \"17:10\"},\n        {\"number\": 8, \"startTime\": \"17:15\", \"endTime\": \"18:00\"},\n        {\"number\": 9, \"startTime\": \"18:45\", \"endTime\": \"19:30\"},\n        {\"number\": 10, \"startTime\": \"19:35\", \"endTime\": \"20:20\"},\n        {\"number\": 11, \"startTime\": \"20:25\", \"endTime\": \"21:10\"}\n    ];\n\n    // 秋季下午/晚上时间\n    const autumn_afternoon_evening = [\n        {\"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\"},\n        {\"number\": 6, \"startTime\": \"14:50\", \"endTime\": \"15:35\"},\n        {\"number\": 7, \"startTime\": \"15:55\", \"endTime\": \"16:40\"},\n        {\"number\": 8, \"startTime\": \"16:45\", \"endTime\": \"17:30\"},\n        {\"number\": 9, \"startTime\": \"18:15\", \"endTime\": \"19:00\"},\n        {\"number\": 10, \"startTime\": \"19:05\", \"endTime\": \"19:50\"},\n        {\"number\": 11, \"startTime\": \"19:55\", \"endTime\": \"20:40\"}\n    ];\n\n    if (season === 'autumn') {\n        return morning_classes.concat(autumn_afternoon_evening);\n    }\n    // 默认夏季（兼容旧调用）\n    return morning_classes.concat(summer_afternoon_evening);\n}\n\n// ==================== 弹窗和导入函数 ====================\nasync function demoAlert() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"📚 湖北汽车工业学院课表导入\",\n            \"将通过教务系统 API 拉取课表数据并导入到 App\\n\\n\" +\n            \"📌 请确认已登录教务系统\\n\" +\n            \"📌 流程：选择学期 → 选择季节 → 拉取课程\",\n            \"开始导入\",\n            \"取消\"\n        );\n        return confirmed;\n    } catch (error) {\n        console.error(\"显示弹窗错误:\", error);\n        return false;\n    }\n}\n\nasync function demoPrompt(semesterInfo) {\n    try {\n        const defaultDate = (semesterInfo && semesterInfo.semesterStartDate) || '2026-09-07';\n        const semesterStart = await window.shiguangBridgePromise.showPrompt(\n            \"📅 设置开学日期\",\n            \"已从教务系统获取开学日期，如需修改请直接编辑\",\n            defaultDate,\n            \"validateDate\"\n        );\n        return semesterStart || defaultDate;\n    } catch (error) {\n        console.error(\"日期输入错误:\", error);\n        return \"2026-09-07\";\n    }\n}\n\n/**\n * 学期选择 - 用单选列表让用户选学期\n * 默认选中 currYearTerm === 1 的当前学期\n */\nasync function pickSemester(semesterList) {\n    if (!semesterList || semesterList.length === 0) return null;\n\n    const names = semesterList.map(s => s.yearTermName || s.yearTermID);\n    // 默认选中当前学期（currYearTerm === 1）\n    let defaultIdx = semesterList.findIndex(s => s.currYearTerm === 1);\n    if (defaultIdx < 0) defaultIdx = 0;\n\n    try {\n        console.log(\"即将显示学期选择弹窗...\");\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择要导入的学期\",\n            JSON.stringify(names),\n            defaultIdx\n        );\n\n        if (selectedIndex !== null && selectedIndex >= 0 && selectedIndex < semesterList.length) {\n            const picked = semesterList[selectedIndex];\n            console.log(\"用户选择了: \" + picked.yearTermName + \" (yearTermID=\" + picked.yearTermID + \")\");\n            window.shiguangBridge.showToast(\"已选 \" + picked.yearTermName);\n            return picked;\n        }\n        console.log(\"用户取消了学期选择。\");\n        window.shiguangBridge.showToast(\"学期选择：用户取消\");\n        return null;\n    } catch (error) {\n        console.error(\"显示学期选择弹窗出错:\", error);\n        window.shiguangBridge.showToast(\"学期选择出错：\" + error.message);\n        return null;\n    }\n}\n\n/**\n * 导入时间段 - 使用单选列表弹窗让用户选择夏季或秋季\n * 参考 demoSingleSelection 的调用模式\n */\nasync function importPresetTimeSlots() {\n    const seasons = [\"夏季\", \"秋季\"];\n    try {\n        console.log(\"即将显示季节选择单选列表弹窗...\");\n        const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择作息时间\",\n            JSON.stringify(seasons),\n            0\n        );\n        if (selectedIndex !== null && selectedIndex >= 0 && selectedIndex < seasons.length) {\n            console.log(\"用户选择了: \" + seasons[selectedIndex] + \" (索引: \" + selectedIndex + \")\");\n            window.shiguangBridge.showToast(\"你选择了 \" + seasons[selectedIndex]);\n\n            // 索引 0 -> 夏季，索引 1 -> 秋季\n            const season = selectedIndex === 0 ? 'summer' : 'autumn';\n\n            // 获取对应季节的时间段\n            const presetTimeSlots = getSeasonTimeSlots(season);\n            console.log(`选择的季节: ${season}，时间段:`, presetTimeSlots);\n\n            // 导入时间段\n            const result = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(presetTimeSlots));\n            if (result === true) {\n                console.log(\"预设时间段导入成功！\");\n                window.shiguangBridge.showToast(`✅ ${seasons[selectedIndex]}时间段导入成功！`);\n                return true; // 成功时返回 true\n            } else {\n                console.log(\"预设时间段导入未成功，结果：\" + result);\n                window.shiguangBridge.showToast(\"❌ 时间段导入失败，请查看日志。\");\n                return false;\n            }\n        } else {\n            console.log(\"用户取消了选择。\");\n            window.shiguangBridge.showToast(\"季节选择：用户取消了选择！\");\n            return false; // 用户取消时返回 false\n        }\n    } catch (error) {\n        console.error(\"显示季节选择单选列表弹窗时发生错误:\", error);\n        window.shiguangBridge.showToast(\"季节选择：显示列表出错！\" + error.message);\n        return false; // 出现错误时也返回 false\n    }\n}\n\n/**\n * 从 API 拉取课程并导入（按选中的 yearTermId 过滤）\n */\nasync function importSchedule(semesterInfo) {\n    const result = { success: false, courseCount: 0, errorMsg: null };\n    try {\n        window.shiguangBridge.showToast(\"正在从教务系统拉取课表...\");\n\n        const yearTermId = semesterInfo && semesterInfo.yearTermId;\n        const tasks = await fetchTeachTaskList(yearTermId);\n        console.log(`拉取到 ${tasks.length} 条教学任务`);\n\n        const courses = transformTeachTaskToCourses(tasks);\n        result.courseCount = courses.length;\n\n        if (courses.length === 0) {\n            result.errorMsg = \"教务系统未返回任何课程数据\";\n            await window.shiguangBridgePromise.showAlert(\n                \"⚠️ 拉取失败\",\n                result.errorMsg + \"，请确认已登录且所选学期有课程\",\n                \"知道了\"\n            );\n            return result;\n        }\n\n        // 预览\n        const preview = await window.shiguangBridgePromise.showAlert(\n            \"📊 数据预览\",\n            `共拉取到 ${courses.length} 条课程记录\\n\\n` +\n            `示例:\\n${courses.slice(0, 5).map(c =>\n                `• 周${c.day} ${c.name} - 第${c.startSection}-${c.endSection}节`\n            ).join('\\n')}`,\n            \"确认导入\",\n            \"取消\"\n        );\n\n        if (!preview) {\n            result.errorMsg = \"用户在预览时取消\";\n            return result;\n        }\n\n        // 导入课程\n        window.shiguangBridge.showToast(\"正在导入课程...\");\n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n\n        if (saveResult !== true) {\n            result.errorMsg = \"saveImportedCourses 返回非 true\";\n            return result;\n        }\n\n        // 设置开学日期（默认值来自学期 API 的 beginDate）\n        const semesterDate = await demoPrompt(semesterInfo);\n        const totalWeeks = (semesterInfo && semesterInfo.semesterTotalWeeks) || 25;\n\n        // 保存课表配置\n        const configResult = await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({\n            semesterStartDate: semesterDate,\n            semesterTotalWeeks: totalWeeks,\n            defaultClassDuration: 45,\n            defaultBreakDuration: 10,\n            firstDayOfWeek: 1\n        }));\n\n        if (configResult === true) {\n            result.success = true;\n            return result;\n        }\n\n        result.errorMsg = \"saveCourseConfig 返回非 true\";\n        return result;\n    } catch (error) {\n        console.error(\"导入错误:\", error);\n        result.errorMsg = error.message;\n        return result;\n    }\n}\n\n/**\n * 显示最终结果汇总弹窗\n */\nasync function showFinalResult(results) {\n    const success = results.schedule && results.schedule.success;\n    const title = success ? '🎉 导入成功' : '❌ 导入失败';\n\n    let msg = '';\n    if (results.semesterName) msg += '📚 学期: ' + results.semesterName + '\\n';\n    if (results.schedule && results.schedule.courseCount > 0) {\n        msg += '📖 课程: ' + results.schedule.courseCount + ' 条\\n';\n    }\n    msg += '\\n📋 步骤状态:\\n';\n    msg += (results.semesterList ? '✅' : '❌') + ' 获取学期列表\\n';\n    msg += (results.season ? '✅' : '❌') + ' 导入时间段';\n    if (results.seasonName) msg += ' (' + results.seasonName + ')';\n    msg += '\\n';\n    msg += (results.schedule ? (results.schedule.success ? '✅' : '❌') : '⏭️') + ' 导入课表';\n    if (results.schedule && results.schedule.courseCount > 0) msg += ' (' + results.schedule.courseCount + '条)';\n    msg += '\\n';\n\n    if (results.errorMsg) {\n        msg += '\\n❗ 错误: ' + results.errorMsg;\n    }\n\n    try {\n        await window.shiguangBridgePromise.showAlert(title, msg, '知道了');\n    } catch (e) {\n        console.error('显示最终结果弹窗失败:', e);\n        window.shiguangBridge.showToast(title);\n    }\n}\n\nasync function runAllDemosSequentially() {\n    window.shiguangBridge.showToast(\"🚀 课表导入助手启动...\");\n\n    const results = {\n        semesterList: false,\n        semesterName: '',\n        season: false,\n        seasonName: '',\n        schedule: null,\n        errorMsg: null\n    };\n\n    try {\n        // 1. 确认开始\n        const start = await demoAlert();\n        if (!start) {\n            results.errorMsg = '用户取消（开始按钮）';\n            await showFinalResult(results);\n            return;\n        }\n\n        // 2. 拉学期列表\n        let semesterList = [];\n        try {\n            window.shiguangBridge.showToast(\"正在获取学期列表...\");\n            semesterList = await fetchSemesterList();\n            console.log(`拉取到 ${semesterList.length} 个学期`);\n            results.semesterList = true;\n        } catch (e) {\n            console.error(\"获取学期列表失败:\", e);\n            results.errorMsg = e.message;\n            await showFinalResult(results);\n            return;\n        }\n\n        // 3. 让用户选择学期\n        const pickedSemester = await pickSemester(semesterList);\n        if (!pickedSemester) {\n            results.errorMsg = '用户取消了学期选择';\n            await showFinalResult(results);\n            return;\n        }\n        results.semesterName = pickedSemester.yearTermName;\n        const semesterInfo = buildSemesterInfoFromSemester(pickedSemester);\n\n        // 4. 导入时间段（季节选择：夏季/秋季）\n        results.season = await importPresetTimeSlots();\n        // 季节名映射（与 importPresetTimeSlots 内部一致）\n        // 这里不直接拿名字，留空也行；如果想显示需要改 importPresetTimeSlots 返回值\n\n        // 5. 导入课表（用选中的 yearTermId 拉 teachTask）\n        results.schedule = await importSchedule(semesterInfo);\n    } catch (e) {\n        console.error(\"运行错误:\", e);\n        results.errorMsg = e.message;\n    }\n\n    await showFinalResult(results);\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 导出函数\nwindow.validateDate = validateDate;\nwindow.getAuthToken = getAuthToken;\nwindow.getStudentId = getStudentId;\nwindow.decodeJwtPayload = decodeJwtPayload;\nwindow.fetchSemesterList = fetchSemesterList;\nwindow.fetchTeachTaskList = fetchTeachTaskList;\nwindow.pickSemester = pickSemester;\nwindow.transformTeachTaskToCourses = transformTeachTaskToCourses;\nwindow.getSeasonTimeSlots = getSeasonTimeSlots;\nwindow.importPresetTimeSlots = importPresetTimeSlots;\nwindow.importSchedule = importSchedule;\n\n// 启动\nrunAllDemosSequentially();\n","SANYEDU":"// 湖南三一工业职业技术学院（ehall.sanyedu.com）拾光课表导入适配脚本\n// 金智教务（jwapp/sys/wdkb 模块）：\n//   xskcb.do 学生课表：POST XNXQDM=学年学期，返回 datas.xskcb.rows[]\n//   cxjcs.do 学期配置：返回当前学期开学日期(XQKSRQ)与总周数(ZZC)\n// 每日 10 节（无午休拆分的独立小节，晚饭 17:30-18:30 休息）\n\n// 预设作息时间（10 节）\nconst SANY_TIME_SLOTS = [\n    { number: 1, startTime: \"08:20\", endTime: \"09:05\" },\n    { number: 2, startTime: \"09:15\", endTime: \"10:00\" },\n    { number: 3, startTime: \"10:20\", endTime: \"11:05\" },\n    { number: 4, startTime: \"11:15\", endTime: \"12:00\" },\n    { number: 5, startTime: \"14:00\", endTime: \"14:45\" },\n    { number: 6, startTime: \"14:55\", endTime: \"15:40\" },\n    { number: 7, startTime: \"15:50\", endTime: \"16:35\" },\n    { number: 8, startTime: \"16:45\", endTime: \"17:30\" },\n    { number: 9, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 10, startTime: \"19:55\", endTime: \"20:40\" }\n];\n\nfunction getErrorMessage(error) {\n    if (error && typeof error.message === \"string\" && error.message.trim()) return error.message;\n    if (typeof error === \"string\" && error.trim()) return error;\n    try {\n        const serialized = JSON.stringify(error);\n        if (serialized && serialized !== \"{}\") return serialized;\n    } catch (_) {\n        // Ignore serialization failures.\n    }\n    return \"未知错误\";\n}\n\n// 从当前页面 URL 提取 /jwapp 前缀（含 ehall 域名与可选哈希路径）\nfunction getApiBase() {\n    const m = window.location.href.match(/^(https?:\\/\\/[^/]+(?:[^?#]*)?)\\/jwapp/);\n    return m ? m[1] : window.location.origin;\n}\n\nconst API_BASE = getApiBase();\nconst MODULES = {\n    table: `${API_BASE}/jwapp/sys/wdkb/modules/xskcb/xskcb.do?enlink-vpn`,\n    semester: `${API_BASE}/jwapp/sys/wdkb/modules/jshkcb/cxjcs.do?enlink-vpn`\n};\n\n// 从页面存储中提取 JWT 鉴权 token（金智常见 key + 全量扫描兜底）\nfunction getAuthToken() {\n    const keys = [\"Authorization\", \"access_token\", \"token\", \"X-Access-Token\", \"x-token\", \"auth_token\", \"jwt\", \"user_token\"];\n    for (const k of keys) {\n        try {\n            const v = window.localStorage.getItem(k) || window.sessionStorage.getItem(k);\n            if (v && v.includes(\"eyJ\")) return v;\n        } catch (_) {\n            // Ignore storage access errors.\n        }\n    }\n    const stores = [window.localStorage, window.sessionStorage];\n    for (const store of stores) {\n        try {\n            for (let i = 0; i < store.length; i++) {\n                const raw = store.getItem(store.key(i));\n                if (!raw) continue;\n                if (raw.startsWith(\"eyJ\")) return raw;\n                const m = raw.match(/\"([^\"]*eyJ[^\"]*)\"/);\n                if (m) return m[1];\n            }\n        } catch (_) {\n            // Ignore storage access errors.\n        }\n    }\n    return null;\n}\n\nasync function postForm(url, params) {\n    const token = getAuthToken();\n    const headers = { \"Content-Type\": \"application/x-www-form-urlencoded;charset=UTF-8\" };\n    if (token) headers[\"Authorization\"] = token.startsWith(\"Bearer \") ? token : `Bearer ${token}`;\n    const response = await fetch(url, {\n        method: \"POST\",\n        credentials: \"include\",\n        headers,\n        body: new URLSearchParams(params || {}).toString()\n    });\n    if (!response.ok) throw new Error(`接口请求失败（HTTP ${response.status}）`);\n    return response.json();\n}\n\n// 解析 SKZC 周次位图：\"00001111111111111111\" 从第5位起为1 → 5..20\nfunction parseWeekBitmap(bitmap) {\n    const weeks = [];\n    const s = String(bitmap || \"\");\n    for (let i = 0; i < s.length; i++) {\n        if (s.charAt(i) === \"1\") weeks.push(i + 1);\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 获取当前学期配置：cxjcs.do 返回全部学期（无 SFSY 等可区分字段），\n// 按开学日期(XQKSRQ)取\"最近开学且不晚于今天\"的学期，得 XN/XQ/XQKSRQ/ZZC\nasync function fetchSemesterConfig() {\n    const payload = await postForm(MODULES.semester);\n    const rows = payload && payload.datas && payload.datas.cxjcs && payload.datas.cxjcs.rows;\n    if (!Array.isArray(rows) || rows.length === 0) {\n        throw new Error(\"未获取到学期配置信息\");\n    }\n    const today = new Date();\n    let best = null;\n    let bestDate = -Infinity;\n    for (const s of rows) {\n        const start = new Date(String(s.XQKSRQ || \"\").slice(0, 10) + \"T00:00:00\");\n        if (isNaN(start.getTime()) || start > today) continue;\n        const t = start.getTime();\n        if (t > bestDate) {\n            bestDate = t;\n            best = s;\n        }\n    }\n    if (!best) {\n        // 兜底：全部开学日期都晚于今天（如学期刚开始数据未刷新），取可用的最近一条\n        best = rows[0];\n    }\n    const xn = String(best.XN || \"\").trim();\n    const xq = String(best.XQ || \"\").trim();\n    if (!xn || !xq) throw new Error(\"学期配置缺少学年学期\");\n    const semesterStart = String(best.XQKSRQ || \"\").slice(0, 10);\n    const totalWeeks = Number(best.ZZC) || Number(best.ZJXZC) || 0;\n    return { xnxqdm: `${xn}-${xq}`, semesterStartDate: semesterStart, totalWeeks };\n}\n\nasync function fetchCourses(xnxqdm) {\n    const payload = await postForm(MODULES.table, { XNXQDM: xnxqdm });\n    const rows = payload && payload.datas && payload.datas.xskcb && payload.datas.xskcb.rows;\n    if (!Array.isArray(rows)) return [];\n    return rows;\n}\n\nfunction parseSchedule(rows) {\n    const courses = [];\n    for (const row of rows) {\n        const name = String(row.KCM || \"\").trim();\n        if (!name) continue;\n        const day = Number(row.SKXQ);\n        const startSection = Number(row.KSJC);\n        const endSection = Number(row.JSJC);\n        if (!(day >= 1 && day <= 7) || !startSection || !endSection || endSection < startSection) continue;\n        const weeks = parseWeekBitmap(row.SKZC);\n        if (weeks.length === 0) continue;\n        courses.push({\n            name,\n            teacher: String(row.SKJS || \"\").trim() || \"未知\",\n            position: String(row.JASMC || \"\").trim() || \"待定\",\n            day,\n            startSection,\n            endSection,\n            weeks\n        });\n    }\n    return courses;\n}\n\n// 合并同课程同时间同教室的条目\nfunction mergeCourses(courses) {\n    const merged = new Map();\n    for (const c of courses) {\n        const key = `${c.name}|${c.teacher}|${c.position}|${c.day}|${c.startSection}|${c.endSection}`;\n        const holder = merged.get(key);\n        if (holder) {\n            holder.weeks = Array.from(new Set([...holder.weeks, ...c.weeks])).sort((a, b) => a - b);\n        } else {\n            merged.set(key, { ...c, weeks: [...c.weeks].sort((a, b) => a - b) });\n        }\n    }\n    return Array.from(merged.values()).sort(\n        (a, b) => a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name)\n    );\n}\n\n// 保存作息时间\nasync function saveTimeSlots(timeSlots) {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    } catch (error) {\n        console.error(\"JS: 作息时间保存失败\", error);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n        \"课表导入\",\n        \"导入前请确保已登录并打开课表页面。\",\n        \"好的，开始导入\"\n    );\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    try {\n        const config = await fetchSemesterConfig();\n        const rows = await fetchCourses(config.xnxqdm);\n        const courses = parseSchedule(rows);\n        if (courses.length === 0) throw new Error(\"课表中未解析到有效课程，请确认本学期有课。\");\n\n        const merged = mergeCourses(courses);\n\n        window.shiguangBridge.showToast(`正在保存 ${merged.length} 门课程...`);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(merged, null, 2));\n\n        // 保存学期配置（开学日期 + 总周数）\n        const courseConfig = { semesterTotalWeeks: config.totalWeeks };\n        if (config.semesterStartDate) courseConfig.semesterStartDate = config.semesterStartDate;\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(courseConfig));\n\n        await saveTimeSlots(SANY_TIME_SLOTS);\n\n        window.shiguangBridge.showToast(`课程导入成功，共导入 ${merged.length} 门课程！`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(`导入失败：${getErrorMessage(error)}`);\n        console.error(\"JS: Import Error\", error);\n    }\n}\n\nrunImportFlow();","HNIU_01":"// 湖南信息职业技术学院(hniu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 验证逻辑\n\n/**\n * 年份输入验证函数\n * @param {string} input 用户输入的年份\n * @returns {boolean|string} 验证通过返回false，失败返回错误提示\n */\nwindow.validateYearInput = function(input) {\n    return /^[0-9]{4}$/.test(input) ? false : \"请输入四位数字的学年！\";\n};\n\n// 数据解析函数\n\n/**\n * 将周次字符串解析为数字数组\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    \n    // 适配 \"1-9,11-17(周)[01-02节]\" 或 \"12-15(周)\"\n    const pureWeekData = weekStr.split('(')[0]; \n    \n    pureWeekData.split(',').forEach(seg => {\n        if (seg.includes('-')) {\n            const [s, e] = seg.split('-').map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 转换课程 HTML 格式为应用模型\n */\nfunction parseTimetableToModel(doc) {\n    const timetable = doc.getElementById('timetable');\n    if (!timetable) return [];\n\n    const rawResults = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).slice(1);\n\n    // 1. 原始解析阶段\n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        if (cells.length < 7) return;\n\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1;\n            const detailDiv = cell.querySelector('div.kbcontent[style*=\"none\"]');\n            \n            if (detailDiv) {\n                const rawHtml = detailDiv.innerHTML.trim();\n                if (rawHtml === \"\" || rawHtml === \"&nbsp;\") return;\n\n                const courseBlocks = rawHtml.split(/---------------------|----------------------/);\n                \n                courseBlocks.forEach(block => {\n                    if (block.replace(/&nbsp;|<br\\/?>/g, '').trim() === \"\") return;\n\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    let name = \"\";\n                    for (let node of tempDiv.childNodes) {\n                        if (node.nodeType === 3 && node.textContent.trim() !== \"\") {\n                            name = node.textContent.trim();\n                            break;\n                        } else if (node.tagName === \"BR\" && name !== \"\") {\n                            break;\n                        } else if (node.nodeType === 3) {\n                            name += node.textContent.trim();\n                        }\n                    }\n\n                    const teacher = tempDiv.querySelector('font[title=\"教师\"]')?.innerText || \"未知教师\";\n                    const weekStr = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText || \"\";\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText || \"未知地点\";\n\n                    let start = 0, end = 0;\n                    if (weekStr) {\n                        // 兼容 [01-02-03-04节] 格式\n                        const sectionPartMatch = weekStr.match(/\\[(.*?)节\\]/);\n                        if (sectionPartMatch && sectionPartMatch[1]) {\n                            const nums = sectionPartMatch[1].match(/\\d+/g);\n                            if (nums && nums.length > 0) {\n                                const sectionNums = nums.map(Number);\n                                start = Math.min(...sectionNums);\n                                end = Math.max(...sectionNums);\n                            }\n                        }\n                    }\n\n                    if (name && weekStr && start > 0) {\n                        rawResults.push({\n                            \"name\": name,\n                            \"teacher\": teacher,\n                            \"weeks\": parseWeeks(weekStr), // 解析出的数组\n                            \"position\": position,\n                            \"day\": day,\n                            \"startSection\": start,\n                            \"endSection\": end\n                        });\n                    }\n                });\n            }\n        });\n    });\n\n    // 2. 去重与合并阶段\n    // 排序顺序：星期 > 课程名 > 教师 > 教室 > 周次 > 起始节次\n    rawResults.sort((a, b) => \n        a.day - b.day || \n        a.name.localeCompare(b.name) || \n        a.teacher.localeCompare(b.teacher) || \n        a.position.localeCompare(b.position) || \n        JSON.stringify(a.weeks).localeCompare(JSON.stringify(b.weeks)) ||\n        a.startSection - b.startSection\n    );\n\n    const mergedResults = [];\n    rawResults.forEach(current => {\n        if (mergedResults.length === 0) {\n            mergedResults.push(current);\n            return;\n        }\n\n        const last = mergedResults[mergedResults.length - 1];\n\n        // 检查是否完全相同（完全相同的重复项直接跳过）\n        const isDuplicate = \n            last.day === current.day &&\n            last.name === current.name &&\n            last.teacher === current.teacher &&\n            last.position === current.position &&\n            last.startSection === current.startSection &&\n            last.endSection === current.endSection &&\n            JSON.stringify(last.weeks) === JSON.stringify(current.weeks);\n\n        if (isDuplicate) return;\n\n        // 检查是否可以合并（信息相同且节次连续，例如 1-2 节和 3-4 节合并为 1-4 节）\n        const canMerge = \n            last.day === current.day &&\n            last.name === current.name &&\n            last.teacher === current.teacher &&\n            last.position === current.position &&\n            JSON.stringify(last.weeks) === JSON.stringify(current.weeks) &&\n            current.startSection <= last.endSection + 1; // 节次连续或重叠\n\n        if (canMerge) {\n            last.endSection = Math.max(last.endSection, current.endSection);\n        } else {\n            mergedResults.push(current);\n        }\n    });\n\n    return mergedResults;\n}\n/**\n * 保存课表全局配置\n */\nasync function saveAppConfig() {\n    const config = {\n        \"semesterTotalWeeks\": 20,\n        \"firstDayOfWeek\": 1\n    };\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n/**\n * 保存时间段配置\n */\nasync function saveAppTimeSlots() {\n    const timeSlots = [\n        { \"number\": 1, \"startTime\": \"08:30\", \"endTime\": \"09:10\" },\n        { \"number\": 2, \"startTime\": \"09:20\", \"endTime\": \"10:00\" },\n        { \"number\": 3, \"startTime\": \"10:20\", \"endTime\": \"11:00\" },\n        { \"number\": 4, \"startTime\": \"11:10\", \"endTime\": \"11:50\" },\n        { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:40\" },\n        { \"number\": 6, \"startTime\": \"14:50\", \"endTime\": \"15:30\" },\n        { \"number\": 7, \"startTime\": \"15:50\", \"endTime\": \"16:30\" },\n        { \"number\": 8, \"startTime\": \"16:40\", \"endTime\": \"17:20\" },\n        { \"number\": 9, \"startTime\": \"18:40\", \"endTime\": \"19:20\" },\n        { \"number\": 10, \"startTime\": \"19:30\", \"endTime\": \"20:10\" },\n        { \"number\": 11, \"startTime\": \"20:20\", \"endTime\": \"21:00\" },\n        { \"number\": 12, \"startTime\": \"21:10\", \"endTime\": \"21:50\" }\n    ];\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n}\n\n/**\n * 获取并让用户选择学期 ID\n */\nasync function getSelectedSemesterId() {\n    const currentYear = new Date().getFullYear();\n    // 绑定验证函数 validateYearInput\n    const year = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\", \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\", String(currentYear), \"validateYearInput\"\n    );\n    if (!year) return null;\n    \n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify([\"第一学期\", \"第二学期\"]), 0\n    );\n    if (semesterIndex === null) return null;\n    \n    return `${year}-${parseInt(year) + 1}-${semesterIndex + 1}`;\n}\n\n// 流程控制\n\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"公告\",\n            \"请确保您已在当前页面成功登录教务系统，否则无法获取数据。是否继续？\",\n            \"确认已登录\"\n        );\n        if (!confirmed) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        const semesterId = await getSelectedSemesterId();\n        if (!semesterId) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(\"正在获取教务数据...\");\n        \n        const response = await fetch(\"https://jw.hniu.cn/jsxsd/xskb/xskb_list.do\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: `cj0701id=&zc=&demo=&xnxq01id=${semesterId}`,\n            credentials: \"include\"\n        });\n        \n        const html = await response.text();\n        const finalCourses = parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"));\n\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现任何课程数据,检查是否登录或者学期选择是否正确\");\n            return;\n        }\n\n        // 保存数据\n        window.shiguangBridge.showToast(\"正在保存配置...\");\n        await saveAppConfig();\n        await saveAppTimeSlots();\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n        \n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        window.shiguangBridge.showToast(\"异常: \" + error.message);\n    }\n}\n\n// 启动导入流程\nrunImportFlow();","HUNAU_01":"// 湖南农业大学（hunau.edu.cn）拾光课程表适配脚本\n// 教务系统：强智 jsxsd（湖南强智科技教务系统）\n// 校外经 WebVPN（webvpn.hunau.edu.cn）访问，校内可直连；脚本按当前页面自动推导 /jsxsd 前缀，两种形态通用\n// 使用流程：在软件内置浏览器登录学校统一身份认证/WebVPN，进入教务系统任意页面后执行导入\n// 数据来源：GET {前缀}/jsxsd/xskb/xskb_list.do?xnxq01id=学期  → 课表页（table#timetable）\n//           POST {前缀}/jsxsd/jxzl/jxzl_query  → 教学周历（首列为周次，第二列 title 为该周星期一日期）\n// 维护者：salt-fishes\n\nvar HUNAU_KB_PATH = '/jsxsd/xskb/xskb_list.do';\nvar HUNAU_CALENDAR_PATH = '/jsxsd/jxzl/jxzl_query';\nvar HUNAU_CLASS_DURATION = 45;\nvar HUNAU_BREAK_DURATION = 10;\nvar HUNAU_DEFAULT_TOTAL_WEEKS = 20;\nvar HUNAU_POST_OPTIONS = { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } };\n\n// 兜底作息：当课表页未提供节次时间时使用（按湖南农大 6 个大节、每节 45 分钟、课间 10 分钟推得）\nvar HUNAU_FALLBACK_TIME_SLOTS = [\n    { number: 1, startTime: '08:00', endTime: '08:45' },\n    { number: 2, startTime: '08:55', endTime: '09:40' },\n    { number: 3, startTime: '10:05', endTime: '10:50' },\n    { number: 4, startTime: '11:00', endTime: '11:45' },\n    { number: 5, startTime: '14:30', endTime: '15:15' },\n    { number: 6, startTime: '15:25', endTime: '16:10' },\n    { number: 7, startTime: '16:35', endTime: '17:20' },\n    { number: 8, startTime: '17:30', endTime: '18:15' },\n    { number: 9, startTime: '19:30', endTime: '20:15' },\n    { number: 10, startTime: '20:25', endTime: '21:10' },\n    { number: 11, startTime: '21:20', endTime: '22:05' },\n    { number: 12, startTime: '22:15', endTime: '23:00' }\n];\n\nvar HUNAU_CN_NUMBER = { '一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9, '十': 10 };\n\n// ==================== 桥接封装 ====================\n\nfunction toast(message) {\n    if (window.shiguangBridge && typeof window.shiguangBridge.showToast === 'function') {\n        window.shiguangBridge.showToast(message);\n    } else {\n        console.log('[HUNAU] ' + message);\n    }\n}\n\nasync function alertUser(title, message) {\n    if (window.shiguangBridgePromise && typeof window.shiguangBridgePromise.showAlert === 'function') {\n        const confirmed = await window.shiguangBridgePromise.showAlert(title, message, '知道了');\n        return confirmed === true || confirmed === 'true';\n    }\n    alert(title + '\\n' + message);\n    return true;\n}\n\n// 原生以字符串序号或 \"null\" 回传，统一为数字序号，-1 表示取消\nasync function selectFromList(title, items, defaultIndex) {\n    if (!(window.shiguangBridgePromise && typeof window.shiguangBridgePromise.showSingleSelection === 'function')) {\n        return defaultIndex;\n    }\n    const result = await window.shiguangBridgePromise.showSingleSelection(title, JSON.stringify(items), defaultIndex);\n    if (result === null || result === undefined || result === 'null') return -1;\n    const index = typeof result === 'number' ? result : parseInt(result, 10);\n    return isNaN(index) ? -1 : index;\n}\n\n// ==================== 请求 ====================\n\n// 兼容直连与 WebVPN 形态的地址，取当前路径中 /jsxsd/ 之前的部分作为前缀\nfunction jsxsdUrl(path) {\n    const currentPath = window.location.pathname || '';\n    const index = currentPath.indexOf('/jsxsd/');\n    return window.location.origin + (index < 0 ? '' : currentPath.slice(0, index)) + path;\n}\n\nasync function requestText(url, options) {\n    const response = await fetch(url, Object.assign({ credentials: 'include' }, options || {}));\n    return await response.text();\n}\n\n// 不同强智版本分别使用 #timetable 与 #kbtable\nfunction findTimetableTable(doc) {\n    return doc.getElementById('timetable') || doc.getElementById('kbtable');\n}\n\n// 优先 GET 带学期参数；失败再退回 POST 表单\nasync function fetchTimetableDoc(semesterValue) {\n    const url = jsxsdUrl(HUNAU_KB_PATH);\n    const got = new DOMParser().parseFromString(\n        await requestText(url + '?xnxq01id=' + encodeURIComponent(semesterValue)), 'text/html');\n    if (findTimetableTable(got)) return got;\n\n    const body = 'xnxq01id=' + encodeURIComponent(semesterValue) + '&sfFD=1';\n    const posted = new DOMParser().parseFromString(\n        await requestText(url, Object.assign({ method: 'POST', body: body }, HUNAU_POST_OPTIONS)), 'text/html');\n    return findTimetableTable(posted) ? posted : null;\n}\n\n// ==================== 学期 ====================\n\n// 学期列表：[{ value: \"2025-2026-2\", label: \"2025-2026 学年第 2 学期\", selected: true }]\nfunction parseSemesters(doc) {\n    const select = doc.querySelector('select[name=\"xnxq01id\"], select#xnxq01id');\n    if (!select) return [];\n    const list = [];\n    select.querySelectorAll('option').forEach(function (option) {\n        const value = String(option.getAttribute('value') || '').trim();\n        if (!value) return;\n        list.push({\n            value: value,\n            label: value.replace(/^(\\d{4})-(\\d{4})-(\\d)$/, '$1-$2 学年第 $3 学期'),\n            selected: option.hasAttribute('selected')\n        });\n    });\n    return list;\n}\n\n// ==================== 节次时间 ====================\n\nfunction timeToMinutes(text) {\n    const match = String(text || '').match(/(\\d{1,2}):(\\d{2})/);\n    return match ? parseInt(match[1], 10) * 60 + parseInt(match[2], 10) : null;\n}\n\nfunction minutesToTime(minutes) {\n    const value = Math.round(minutes);\n    return String(Math.floor(value / 60)).padStart(2, '0') + ':' + String(value % 60).padStart(2, '0');\n}\n\n// 从课表行标题（如“第一大节 08:00-09:40”）推导每一小节的上课时间。\n// 大节内的小节数由时长反推：n 个小节的时长 = n*45 + (n-1)*课间，\n// 大节内的剩余时间再均分为课间。这样即使某门课跨大节，也不会污染小节的节次编号。\nfunction parseTimeSlots(doc) {\n    const table = findTimetableTable(doc);\n    if (!table) return [];\n    const slots = [];\n    Array.from(table.querySelectorAll('tr')).forEach(function (row) {\n        const label = row.querySelector('th');\n        if (!label) return;\n        const labelText = String(label.textContent).replace(/\\s+/g, ' ').trim();\n        const match = labelText.match(/第([一二三四五六七八九十]+)大节\\s*(\\d{1,2}:\\d{2})\\s*[-~—]\\s*(\\d{1,2}:\\d{2})/);\n        if (!match) return;\n\n        const bigIndex = HUNAU_CN_NUMBER[match[1]];\n        const startMin = timeToMinutes(match[2]);\n        const endMin = timeToMinutes(match[3]);\n        if (!bigIndex || startMin === null || endMin === null || endMin <= startMin) return;\n\n        const span = endMin - startMin;\n        const unit = HUNAU_CLASS_DURATION + HUNAU_BREAK_DURATION;\n        const count = Math.max(1, Math.round((span + HUNAU_BREAK_DURATION) / unit));\n        const gap = count > 1 ? (span - count * HUNAU_CLASS_DURATION) / (count - 1) : 0;\n\n        for (let i = 0; i < count; i++) {\n            const start = startMin + i * (HUNAU_CLASS_DURATION + gap);\n            slots.push({\n                number: (bigIndex - 1) * count + i + 1,\n                startTime: minutesToTime(start),\n                endTime: minutesToTime(start + HUNAU_CLASS_DURATION)\n            });\n        }\n    });\n\n    // 去重并按节次排序；数据不足时回退到内置作息\n    const byNumber = {};\n    slots.forEach(function (slot) { if (!byNumber[slot.number]) byNumber[slot.number] = slot; });\n    const result = Object.keys(byNumber).map(function (key) { return byNumber[key]; })\n        .sort(function (a, b) { return a.number - b.number; });\n    return result.length >= 6 ? result : HUNAU_FALLBACK_TIME_SLOTS;\n}\n\n// ==================== 课表解析 ====================\n\n// 周次与节次：兼容 1-16(周)[01-02节]、1-8,10-16(周)、1-15周(单)、2-16(双) 等写法\nfunction parseWeeksAndSections(text) {\n    const result = { weeks: [], sections: [] };\n    const content = String(text || '').trim();\n    if (!content) return result;\n\n    const parity = /双/.test(content) ? 2 : (/单/.test(content) ? 1 : 0);\n    const bracketIndex = content.indexOf('[');\n    const cleaned = (bracketIndex >= 0 ? content.slice(0, bracketIndex) : content)\n        .replace(/第/g, '')\n        .replace(/至|到|~/g, '-')\n        .replace(/[（(][^（）()]*[）)]/g, '')\n        .replace(/周/g, '');\n\n    cleaned.split(/[,，、;；\\s]+/).forEach(function (segment) {\n        const item = segment.trim();\n        const range = item.match(/^(\\d+)\\s*[-–—]\\s*(\\d+)$/);\n        if (range) {\n            for (let week = parseInt(range[1], 10); week <= parseInt(range[2], 10); week++) result.weeks.push(week);\n        } else if (/^\\d+$/.test(item)) {\n            result.weeks.push(parseInt(item, 10));\n        }\n    });\n\n    if (parity) {\n        result.weeks = result.weeks.filter(function (week) { return week % 2 === (parity === 1 ? 1 : 0); });\n    }\n    result.weeks = Array.from(new Set(result.weeks)).sort(function (a, b) { return a - b; });\n\n    const sectionMatch = content.match(/\\[([^\\]]*)\\]/);\n    if (sectionMatch) {\n        (sectionMatch[1].match(/\\d+/g) || []).forEach(function (number) {\n            const section = parseInt(number, 10);\n            if (result.sections.indexOf(section) < 0) result.sections.push(section);\n        });\n        result.sections.sort(function (a, b) { return a - b; });\n    }\n    return result;\n}\n\n// 教师姓名在教师字体里与职称连写（如“何龙姣讲师”“周小红其他”），且多人以逗号分隔，逐个去掉常见职称后缀\nfunction cleanTeacher(text) {\n    const raw = String(text || '').trim();\n    if (!raw) return '';\n    const titles = ['其他正高级', '其他副高级', '其他中级', '其他初级', '副教授', '教授', '副研究员', '研究员',\n        '高级实验师', '实验师', '高级工程师', '工程师', '高级技师', '技师', '讲师', '助教', '其他'];\n    const strip = function (name) {\n        const value = name.trim();\n        for (let i = 0; i < titles.length; i++) {\n            if (value.length > titles[i].length && value.slice(-titles[i].length) === titles[i]) {\n                return value.slice(0, value.length - titles[i].length).trim();\n            }\n        }\n        return value;\n    };\n    return raw.split(/[,，、;；\\/]+/).map(strip).filter(function (name) { return name; }).join(',');\n}\n\n// 收集单个课表单元格内的全部课程候选。强智在格内同时输出简表与详表，\n// 简表缺少教师与节次方括号，此处一并解析，交由归并阶段择优。\nfunction collectCellCandidates(cellDiv, day, output, rowSections) {\n    const html = String(cellDiv.innerHTML || '').trim();\n    if (!html || html.replace(/&nbsp;/gi, '').trim() === '') return;\n\n    html.split(/[-—–]{6,}\\s*(?:<br\\s*\\/?>)?/i).forEach(function (blockHtml) {\n        if (!blockHtml.trim()) return;\n\n        const holder = document.createElement('div');\n        holder.innerHTML = blockHtml;\n\n        let name = '';\n        for (let i = 0; i < holder.childNodes.length; i++) {\n            const node = holder.childNodes[i];\n            if (node.nodeType === 3 && /[\\u4e00-\\u9fa5]/.test(node.textContent)) {\n                name = node.textContent.trim();\n                break;\n            }\n        }\n        if (!name) name = String(holder.textContent || '').split('\\n')[0].trim();\n        if (!name) return;\n\n        const pickText = function (titles) {\n            for (let i = 0; i < titles.length; i++) {\n                const element = holder.querySelector('font[title*=\"' + titles[i] + '\"]');\n                if (element && element.textContent.trim()) return element.textContent.trim();\n            }\n            return '';\n        };\n\n        let timeText = pickText(['周次', '节次']);\n        if (!/\\[[^\\]]*\\]/.test(timeText)) {\n            const bracket = String(holder.textContent || '').match(/\\[[^\\]]*\\]/);\n            if (bracket) timeText += bracket[0];\n        }\n\n        const parsed = parseWeeksAndSections(timeText || holder.textContent);\n        if (parsed.weeks.length === 0) return;\n        if (parsed.sections.length === 0 && rowSections) {\n            for (let section = rowSections[0]; section <= rowSections[1]; section++) parsed.sections.push(section);\n        }\n\n        const teacher = cleanTeacher(pickText(['教师', '老师']));\n        const position = pickText(['教室', '地点']).replace(/\\[\\s*\\d+\\s*-\\s*\\d+\\s*\\]\\s*节?$/, '').trim();\n\n        output.push({\n            name: name,\n            teacher: teacher,\n            position: position,\n            day: day,\n            weeks: parsed.weeks,\n            sections: parsed.sections,\n            score: (teacher ? 4 : 0) + (/\\[[^\\]]*\\]/.test(timeText) ? 3 : 0) +\n                (position ? 1 : 0) + (parsed.sections.length > 1 ? 1 : 0)\n        });\n    });\n}\n\n// 按课程名、周次、教室归并候选，保留信息更完整的一条\nfunction mergeCellCandidates(candidates) {\n    const groups = {};\n    const order = [];\n    candidates.forEach(function (item) {\n        const key = item.name + '|' + item.weeks.join(',') + '|' + item.position;\n        if (groups[key] === undefined) {\n            groups[key] = item;\n            order.push(key);\n        } else if (item.score > groups[key].score) {\n            groups[key] = item;\n        }\n    });\n\n    const courses = [];\n    order.forEach(function (key) {\n        const item = groups[key];\n        if (item.sections.length === 0) return;\n        courses.push({\n            name: item.name,\n            teacher: item.teacher || '未知教师',\n            position: item.position || '未知地点',\n            day: item.day,\n            weeks: item.weeks,\n            startSection: item.sections[0],\n            endSection: item.sections[item.sections.length - 1]\n        });\n    });\n    return courses;\n}\n\nfunction parseTimetable(doc) {\n    const table = findTimetableTable(doc);\n    if (!table) return [];\n\n    const courses = [];\n    let bigIndex = 0;\n    Array.from(table.querySelectorAll('tr')).forEach(function (row) {\n        const label = row.querySelector('th');\n        const labelText = label ? String(label.textContent).replace(/\\s+/g, ' ').trim() : '';\n        if (/^第[一二三四五六七八九十]+大节/.test(labelText)) bigIndex++;\n        const rowSections = bigIndex > 0 ? [2 * bigIndex - 1, 2 * bigIndex] : null;\n\n        Array.from(row.querySelectorAll('td')).forEach(function (cell, index) {\n            const blocks = cell.querySelectorAll('div.kbcontent, div.kbcontent1');\n            if (blocks.length === 0) return;\n\n            const candidates = [];\n            Array.from(blocks).forEach(function (block) {\n                collectCellCandidates(block, index + 1, candidates, rowSections);\n            });\n            mergeCellCandidates(candidates).forEach(function (course) {\n                courses.push(course);\n            });\n        });\n    });\n    return courses;\n}\n\n// ==================== 教学周历 ====================\n\n// 教学周历：首列为周次序号，第二列 title 为该周星期一日期（如 2026年08月31）\nfunction parseCalendar(doc) {\n    const result = { semesterStartDate: null, totalWeeks: null };\n    const table = doc.querySelector('table');\n    if (!table) return result;\n\n    const toDate = function (text) {\n        const match = String(text || '').match(/(\\d{4})\\s*[-年]\\s*(\\d{1,2})\\s*[-月]\\s*(\\d{1,2})/);\n        return match ? match[1] + '-' + match[2].padStart(2, '0') + '-' + match[3].padStart(2, '0') : null;\n    };\n\n    Array.from(table.querySelectorAll('tr')).forEach(function (row) {\n        const cells = Array.from(row.children);\n        const first = cells.length > 0 ? String(cells[0].textContent).trim() : '';\n        if (!/^\\d+$/.test(first)) return;\n\n        const week = parseInt(first, 10);\n        result.totalWeeks = result.totalWeeks === null ? week : Math.max(result.totalWeeks, week);\n        if (week === 1 && !result.semesterStartDate && cells.length > 1) {\n            result.semesterStartDate = toDate(cells[1].getAttribute('title')) || toDate(cells[1].textContent);\n        }\n    });\n    return result;\n}\n\nasync function fetchCalendar(semesterValue) {\n    try {\n        const text = await requestText(jsxsdUrl(HUNAU_CALENDAR_PATH), Object.assign(\n            { method: 'POST', body: 'xnxq01id=' + encodeURIComponent(semesterValue) }, HUNAU_POST_OPTIONS));\n        return parseCalendar(new DOMParser().parseFromString(text, 'text/html'));\n    } catch (error) {\n        console.warn('[HUNAU] 教学周历读取失败：', error);\n        return { semesterStartDate: null, totalWeeks: null };\n    }\n}\n\n// ==================== 合并去重 ====================\n\n// 节次与周次合并去重函数\n// 来源：官方 Wiki《课程合并与去重函数》\n// https://github.com/XingHeYuZhuan/shiguangschedule/wiki/课程合并与去重函数\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n            (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            (a.startSection || 0) - (b.startSection || 0) ||\n            (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let merged = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const next = step1Merged[i];\n\n        const isSameCourseAndSection =\n            merged.name === next.name &&\n            merged.teacher === next.teacher &&\n            merged.position === next.position &&\n            merged.day === next.day &&\n            merged.startSection === next.startSection &&\n            merged.endSection === next.endSection;\n\n        if (isSameCourseAndSection) {\n            merged.weeks = Array.from(new Set([...merged.weeks, ...next.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(merged);\n            merged = next;\n        }\n    }\n    step2Merged.push(merged);\n\n    return step2Merged;\n}\n\n// ==================== 流程编排 ====================\n\nasync function runImportFlow() {\n    try {\n        if ((window.location.pathname || '').indexOf('/jsxsd/') < 0) {\n            await alertUser('请先进入教务系统', '请登录教务系统并停留在任意教务功能页面后重新执行导入。');\n            return;\n        }\n\n        toast('正在获取学期信息…');\n        const listDoc = new DOMParser().parseFromString(await requestText(jsxsdUrl(HUNAU_KB_PATH)), 'text/html');\n        const semesters = parseSemesters(listDoc);\n        if (semesters.length === 0) {\n            await alertUser('未获取到学期列表', '课表页返回异常，请确认登录状态有效后重试。');\n            return;\n        }\n\n        let defaultIndex = 0;\n        semesters.forEach(function (item, index) { if (item.selected) defaultIndex = index; });\n        const picked = semesters.length > 1\n            ? await selectFromList('选择学期', semesters.map(function (item) { return item.label; }), defaultIndex)\n            : defaultIndex;\n        if (picked < 0 || picked >= semesters.length) {\n            toast('导入已取消');\n            return;\n        }\n        const semester = semesters[picked];\n\n        toast('正在获取 ' + semester.label + ' 课表…');\n        const tableDoc = await fetchTimetableDoc(semester.value);\n        if (!tableDoc) {\n            await alertUser('未获取到课表数据', '请确认已登录教务系统后重试。');\n            return;\n        }\n\n        const courses = mergeAndDistinctCourses(parseTimetable(tableDoc));\n        if (courses.length === 0) {\n            await alertUser('未解析到课程', semester.label + ' 页面中没有课程内容，该学期可能尚未发布课表。');\n            return;\n        }\n\n        const calendar = await fetchCalendar(semester.value);\n        const weeks = courses.reduce(function (all, course) { return all.concat(course.weeks); }, []);\n        const config = {\n            semesterTotalWeeks: Math.max(HUNAU_DEFAULT_TOTAL_WEEKS, Math.max.apply(null, weeks)),\n            defaultClassDuration: HUNAU_CLASS_DURATION,\n            defaultBreakDuration: HUNAU_BREAK_DURATION\n        };\n        if (calendar.semesterStartDate) {\n            config.semesterStartDate = calendar.semesterStartDate;\n        } else {\n            toast('未读取到教学周历，开学日期可在软件内手动校准');\n        }\n\n        // 课表配置与节次时间属于可选数据，失败不影响课程导入\n        try {\n            await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        } catch (error) {\n            console.warn('[HUNAU] 课表配置保存失败：', error);\n        }\n        try {\n            await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(parseTimeSlots(tableDoc)));\n        } catch (error) {\n            console.warn('[HUNAU] 节次时间保存失败：', error);\n        }\n\n        if (!await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses))) {\n            toast('课程保存失败，请重试');\n            return;\n        }\n\n        toast('导入成功：' + semester.label + ' 共 ' + courses.length + ' 条课程时段');\n        if (window.shiguangBridge && typeof window.shiguangBridge.notifyTaskCompletion === 'function') {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (error) {\n        console.error('[HUNAU] 导入流程异常：', error);\n        await alertUser('导入失败', error && error.message ? error.message : String(error));\n    }\n}\n\n// 启动导入流程\nrunImportFlow();\n","HNVCC_01":"/**\n * 湖南商务职业技术学院教务系统(hnvcc.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n/**\n * 定义一个全局的学年验证函数。\n */\nwindow.validateYearInput = function(input) {\n    // 检查输入是否为四位数字\n    if (/^[0-9]{4}$/.test(input)) {\n        return false;\n    } else {\n        return \"请输入四位数字的学年！\";\n    }\n}\n\n/**\n * 验证周次字符串并转换为数字数组\n * @param {string} weekStr 课表中的周次字符串\n * @returns {number[]} 周数数组\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    // 匹配 \"第...周\" 或 \"第...(...\"，提取中间的范围部分\n    const match = weekStr.match(/第(.*?)(周|\\()/); \n    if (!match) return weeks;\n\n    const ranges = match[1].split(','); \n\n    for (const range of ranges) {\n        // 兼容处理 1-10 或 10 这样的数字\n        const parts = range.split('-');\n        if (parts.length === 2) {\n            let start = parseInt(parts[0].trim());\n            let end = parseInt(parts[1].trim());\n            if (start > end) [start, end] = [end, start];\n            \n            for (let i = start; i <= end; i++) {\n                if (!weeks.includes(i)) {\n                    weeks.push(i);\n                }\n            }\n        } else if (parts.length === 1) {\n            const week = parseInt(parts[0].trim());\n            if (!isNaN(week) && !weeks.includes(week)) {\n                weeks.push(week);\n            }\n        }\n    }\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 解析节次字符串为开始和结束节次 \n * 允许字符串包含其他文本（如 \"第一大节\\n第1-2节\"），只要包含数字范围即可。\n * @param {string} sectionStr 课表的节次行标题（包含文字和数字）\n * @returns {{start: number, end: number} | null}\n */\nfunction parseSections(sectionStr) {\n    // 1. 尝试匹配范围格式：匹配 (\\d+)-(\\d+)\n    let match = sectionStr.match(/(\\d+)\\s*-\\s*(\\d+)/);\n    if (match) {\n        return {\n            start: parseInt(match[1]),\n            end: parseInt(match[2])\n        };\n    }\n    \n    // 2. 尝试匹配单个节次格式：匹配单个 (\\d+)\n    match = sectionStr.match(/(\\d+)/); \n    if (match) {\n        const section = parseInt(match[1]);\n        // 忽略小于 1 的数字，避免解析到其他无关的数字\n        if (section > 0) {\n            return {\n                start: section,\n                end: section\n            };\n        }\n    }\n    \n    // 3. 都没有匹配到，返回 null\n    return null;\n}\n\n\n/**\n * 异步获取教务系统课表 HTML 内容，并用 DOMParser 转换成 Document 对象。\n * @param {string} xnxqid 学年学期ID\n * @returns {Document | null} 解析后的 Document 对象或 null\n */\nasync function fetchTimetable(xnxqid) {\n    window.shiguangBridge.showToast(\"正在请求课表数据...\");\n    \n    // 完整的 URL 路径\n    const url = `http://jwxt.hnvcc.edu.cn/jsxsd/framework/mainV_index_loadkb.htmlx?rq=all&xnxqid=${xnxqid}&xswk=false`;\n\n    try {\n        const response = await fetch(url, {\n            \"body\": null,\n            \"mode\": \"cors\",\n            \"credentials\": \"include\" // 确保携带了教务系统的登录Session\n        });\n\n        if (!response.ok) {\n            window.shiguangBridge.showToast(`网络响应错误，状态码: ${response.status}。请检查登录状态。`);\n            return null;\n        }\n\n        const htmlData = await response.text();\n        window.shiguangBridge.showToast(\"数据获取成功，开始解析 HTML...\");\n        \n        const parser = new DOMParser();\n        const doc = parser.parseFromString(htmlData, \"text/html\");\n\n        return doc;\n\n    } catch (error) {\n        window.shiguangBridge.showToast(`请求过程中发生错误: ${error.message}`);\n        return null;\n    }\n}\n\n\n/**\n * 主要解析逻辑：从 Document 对象中提取课程数据\n * @param {Document} doc - 包含课表数据的 Document 对象\n * @returns {{courses: object[], config: object} | null}\n */\nfunction parseTimetable(doc) {\n    const courses = [];\n    let parsedRowCount = 0; \n    const timetable = doc.getElementById('timetable');\n    \n    if (!timetable) {\n        window.shiguangBridge.showToast(\"HTML 中未找到课表表格 #timetable。\");\n        return null;\n    }\n\n    // 尝试从 li_showWeek 元素中提取总周数，默认 20\n    const totalWeeksElement = doc.getElementById('li_showWeek');\n    const totalWeeksMatch = (totalWeeksElement ? totalWeeksElement.innerHTML : '').match(/\\/(\\d+)周/);\n    const semesterTotalWeeks = totalWeeksMatch ? parseInt(totalWeeksMatch[1]) : 20;\n\n    const rows = timetable.querySelectorAll('tbody > tr');\n\n    rows.forEach((row, rowIndex) => {\n        \n        const allCells = row.querySelectorAll('td');\n\n        // 1. 过滤掉不符合格式的行（如备注行或空行）\n        if (allCells.length < 2 || row.querySelector('td[colspan=\"7\"]')) {\n            return;\n        }\n\n        const sectionCell = allCells[0]; \n        // 提取节次单元格的纯文本\n        const sectionText = sectionCell.innerText.trim();\n        const sections = parseSections(sectionText); \n\n        if (!sections) {\n            return; \n        }\n        \n        parsedRowCount++;\n\n        // 遍历周一到周日\n        for (let day = 1; day <= 7; day++) {\n            const cellIndex = day; \n            const dayCell = allCells[cellIndex]; \n            \n            if (!dayCell) continue;\n\n            // 获取详细课程信息的容器\n            const itemBoxes = dayCell.querySelectorAll('.item-box');\n            \n            itemBoxes.forEach(box => {\n                \n                // 优化：只选择 .item-box 的直接子元素 <p>，避免任何可能的嵌套干扰\n                const courseNamePs = box.querySelectorAll(':scope > p'); \n\n                courseNamePs.forEach(nameP => {\n                    try {\n                        const name = nameP.innerText.trim();\n                        if (!name) return; // 课程名为空，跳过\n\n                        // 查找紧随 P 标签的 .tch-name 元素（包含教师和学分）\n                        let tchNameDiv = nameP.nextElementSibling;\n                        while (tchNameDiv && (tchNameDiv.nodeType !== 1 || !tchNameDiv.classList.contains('tch-name'))) {\n                            tchNameDiv = tchNameDiv.nextElementSibling;\n                        }\n\n                        if (!tchNameDiv || !tchNameDiv.classList.contains('tch-name')) {\n                            // 未找到教师信息，跳过\n                            return; \n                        }\n                        \n                        // 提取教师\n                        const teacherSpan = tchNameDiv.querySelector('span:nth-child(1)');\n                        const teacher = teacherSpan ? teacherSpan.innerText.replace('教师：', '').trim() : '';\n\n                        // 2. 查找地点/周次 Div\n                        let infoDiv = null;\n                        let currentElement = tchNameDiv.nextElementSibling;\n\n                        while (currentElement) {\n                            // 目标 Location/Week DIV: 必须是 DIV 且包含位置图标\n                            if (currentElement.tagName === 'DIV' && currentElement.querySelector('img[src*=\"item1.png\"]')) {\n                                infoDiv = currentElement;\n                                break; \n                            }\n                            \n                            // 遇到下一个课程名 P 标签，停止搜索\n                            if (currentElement.tagName === 'P') {\n                                break; \n                            }\n\n                            currentElement = currentElement.nextElementSibling;\n                        }\n\n                        if (!infoDiv) {\n                            // 未找到地点/周次信息，跳过\n                            return; \n                        }\n                        \n                        // 提取地点和周次\n                        let position = '';\n                        let weekText = '';\n\n                        const infoSpans = infoDiv.querySelectorAll('span');\n                        if (infoSpans.length >= 1) {\n                            position = infoSpans[0].innerText.trim(); \n                        }\n                        if (infoSpans.length >= 2) {\n                            weekText = infoSpans[1].innerText.trim();\n                        }\n                        \n                        // 3. 构造课程对象\n                        const weeksArray = parseWeeks(weekText);\n                        \n                        if (weeksArray.length > 0) {\n                            const newCourse = {\n                                name: name,\n                                teacher: teacher,\n                                position: position,\n                                day: day, // 1=周一, 7=周日\n                                startSection: sections.start,\n                                endSection: sections.end,\n                                weeks: weeksArray\n                            };\n                            courses.push(newCourse);\n                        } \n\n                    } catch (e) {\n                        // 保留 error 级别的日志以防关键错误被忽略\n                        console.error(`解析课程时发生未预期的错误: ${e.message}`, e);\n                    }\n                }); \n            }); \n        }\n    });\n    \n    // 构造配置对象\n    const config = {\n        semesterTotalWeeks: semesterTotalWeeks,\n        firstDayOfWeek: 1 // 一周的第一天是周一\n    };\n\n    return { courses, config };\n}\n\n/**\n * 合并连续的课程节次\n * 合并条件：同一天、同一周次、同一课程名、同一教师、同一地点，且节次连续。\n * @param {object[]} courses 待合并的课程列表\n * @returns {object[]} 合并后的课程列表\n */\nfunction mergeCourses(courses) {\n    if (!courses || courses.length === 0) {\n        return [];\n    }\n    \n    // 1. 排序：确保同一天、同一周次的课程按节次顺序排列\n    courses.sort((a, b) => {\n        if (a.day !== b.day) return a.day - b.day;\n        const weekA = JSON.stringify(a.weeks);\n        const weekB = JSON.stringify(b.weeks);\n        if (weekA !== weekB) return weekA.localeCompare(weekB);\n        return a.startSection - b.startSection;\n    });\n\n    const mergedCourses = [];\n    // 初始化第一个课程为当前的合并起点\n    let currentMergedCourse = { ...courses[0] }; \n\n    for (let i = 1; i < courses.length; i++) {\n        const nextCourse = courses[i];\n\n        const isSameDay = nextCourse.day === currentMergedCourse.day;\n        const isSameWeeks = JSON.stringify(nextCourse.weeks) === JSON.stringify(currentMergedCourse.weeks);\n        const isSameName = nextCourse.name === currentMergedCourse.name;\n        const isSameTeacher = nextCourse.teacher === currentMergedCourse.teacher;\n        const isSamePosition = nextCourse.position === currentMergedCourse.position;\n        const isConsecutive = nextCourse.startSection === currentMergedCourse.endSection + 1;\n\n        // 检查合并条件\n        const canMerge = isSameDay && isSameWeeks && isSameName && isSameTeacher && isSamePosition && isConsecutive;\n\n        if (canMerge) {\n            currentMergedCourse.endSection = nextCourse.endSection;\n        } else {\n            mergedCourses.push(currentMergedCourse);\n            currentMergedCourse = { ...nextCourse };\n        }\n    }\n    mergedCourses.push(currentMergedCourse);\n    \n    return mergedCourses;\n}\n\n\n\n// 生成夏季作息时间段\nfunction generateSummerTimeSlots() {\n    return [\n        { \"number\": 1, \"startTime\": \"08:20\", \"endTime\": \"09:05\" },\n        { \"number\": 2, \"startTime\": \"09:15\", \"endTime\": \"10:00\" }, \n        { \"number\": 3, \"startTime\": \"10:20\", \"endTime\": \"11:05\" }, \n        { \"number\": 4, \"startTime\": \"11:15\", \"endTime\": \"12:00\" },\n        { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n        { \"number\": 6, \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n        { \"number\": 7, \"startTime\": \"15:55\", \"endTime\": \"16:40\" },\n        { \"number\": 8, \"startTime\": \"16:50\", \"endTime\": \"17:35\" },\n        { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n        { \"number\": 10, \"startTime\": \"19:55\", \"endTime\": \"20:40\" },\n        { \"number\": 11, \"startTime\": \"20:45\", \"endTime\": \"21:30\" }, \n        { \"number\": 12, \"startTime\": \"21:35\", \"endTime\": \"22:20\" }\n    ];\n}\n\n// 生成冬季作息时间段\nfunction generateWinterTimeSlots() {\n    return [\n        { \"number\": 1, \"startTime\": \"08:20\", \"endTime\": \"09:05\" },\n        { \"number\": 2, \"startTime\": \"09:15\", \"endTime\": \"10:00\" }, \n        { \"number\": 3, \"startTime\": \"10:20\", \"endTime\": \"11:05\" }, \n        { \"number\": 4, \"startTime\": \"11:15\", \"endTime\": \"12:00\" },\n        { \"number\": 5, \"startTime\": \"14:30\", \"endTime\": \"15:15\" },\n        { \"number\": 6, \"startTime\": \"15:25\", \"endTime\": \"16:10\" },\n        { \"number\": 7, \"startTime\": \"16:25\", \"endTime\": \"17:10\" },\n        { \"number\": 8, \"startTime\": \"17:20\", \"endTime\": \"18:05\" },\n        { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n        { \"number\": 10, \"startTime\": \"19:55\", \"endTime\": \"20:40\" },\n        { \"number\": 11, \"startTime\": \"20:45\", \"endTime\": \"21:30\" }, \n        { \"number\": 12, \"startTime\": \"21:35\", \"endTime\": \"22:20\" }\n    ];\n}\n\n\nasync function runImportFlow() {\n    const currentTitle = document.title || '';\n    if (currentTitle.includes('登录') || currentTitle.includes('Login')) {\n        window.shiguangBridge.showToast(\"请先登录教务系统\");\n        return;\n    }\n\n    // 获取用户输入：学年\n    let currentYear = new Date().getFullYear();\n    const academicYear = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\", \n        \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\",\n        String(currentYear),\n        \"validateYearInput\"\n    );\n    if (academicYear === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n\n    // 获取用户输入：学期\n    const semesters = [\"1（第一学期）\", \"2（第二学期）\"];\n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", \n        JSON.stringify(semesters),\n        -1 \n    );\n    if (semesterIndex === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n    const semesterNumber = semesterIndex + 1;\n\n    // 构造学年学期 ID (xnxqid)\n    const nextYear = parseInt(academicYear) + 1;\n    const xnxqid = `${academicYear}-${nextYear}-${semesterNumber}`;\n    window.shiguangBridge.showToast(`准备获取 ${academicYear} 学年第 ${semesterNumber} 学期数据...`);\n    \n    // 获取用户输入：作息季节\n    const seasons = [\"夏季作息\", \"冬季作息\"];\n    const seasonIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择作息季节\", \n        JSON.stringify(seasons),\n        -1\n    );\n    if (seasonIndex === null) {\n        window.shiguangBridge.showToast(\"导入已取消。\");\n        return;\n    }\n    const selectedSeason = seasonIndex === 0 ? 'summer' : 'winter';\n    const seasonText = seasonIndex === 0 ? '夏季作息' : '冬季作息';\n    window.shiguangBridge.showToast(`已选择：${seasonText}。`);\n\n    // 异步获取和解析 HTML 数据\n    const doc = await fetchTimetable(xnxqid);\n    if (doc === null) {\n        return; \n    }\n    \n    const parsedData = parseTimetable(doc);\n    \n    if (!parsedData || parsedData.courses.length === 0) {\n        window.shiguangBridge.showToast(\"课表解析失败或未解析到课程。请检查登录状态、学期选择或课表数据是否为空。\");\n        return;\n    }\n\n    let { courses, config } = parsedData;\n    \n    // 执行课程合并逻辑\n    const originalCourseCount = courses.length;\n    courses = mergeCourses(courses);\n    \n    // 提交课程数据\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        const mergedCount = originalCourseCount - courses.length;\n        window.shiguangBridge.showToast(`课程导入成功！原始 ${originalCourseCount} 门，合并 ${mergedCount} 门，最终导入 ${courses.length} 门。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课程数据保存失败: ${error.message}`);\n        return;\n    }\n\n    // 提交课表配置数据 \n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        window.shiguangBridge.showToast(`课表配置更新成功！总周数：${config.semesterTotalWeeks}周。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`课表配置保存失败: ${error.message}`);\n    }\n\n    // 提交预设时间段数据\n    try {\n        let timeSlots;\n        if (selectedSeason === 'summer') {\n            timeSlots = generateSummerTimeSlots();\n        } else {\n            timeSlots = generateWinterTimeSlots();\n        }\n\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        window.shiguangBridge.showToast(`预设时间段导入成功！已使用${seasonText}。请在设置中校对具体时间。`);\n    } catch (error) {\n        window.shiguangBridge.showToast(`导入时间段失败: ${error.message}`);\n    }\n\n    window.shiguangBridge.showToast(\"所有任务已完成！\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\n// 启动导入流程\nrunImportFlow();","hnie_01":"// 湖南工程学院(hnie.edu.cn) 强智教务适配脚本\n// 双季作息：一个学期可能存在两种作息，用户手动选择\n\n// 年份输入验证\nwindow.validateYearInput = function(input) {\n    return /^[0-9]{4}$/.test(input) ? false : \"请输入四位数字的学年！\";\n};\n\n// 解析周次字符串为数组\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    const pureWeekData = weekStr.split('(')[0];\n    pureWeekData.split(',').forEach(seg => {\n        if (seg.includes('-')) {\n            const [s, e] = seg.split('-').map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 节次合并与去重\nfunction mergeAndDistinctCourses(courses) {\n    if (courses.length <= 1) return courses;\n    courses.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.day - b.day ||\n            a.startSection - b.startSection ||\n            a.weeks.join(',').localeCompare(b.weeks.join(','));\n    });\n    const merged = [];\n    let current = courses[0];\n    for (let i = 1; i < courses.length; i++) {\n        const next = courses[i];\n        const isSameCourse =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n        const isContinuous = current.endSection + 1 === next.startSection;\n        if (isSameCourse && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourse && current.startSection === next.startSection && current.endSection === next.endSection) {\n            continue;\n        } else {\n            merged.push(current);\n            current = next;\n        }\n    }\n    merged.push(current);\n    return merged;\n}\n\n// 解析课程数据\nfunction parseTimetableToModel(doc) {\n    const timetable = doc.getElementById('timetable');\n    if (!timetable) return [];\n    let rawCourses = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).filter(r => r.querySelector('td'));\n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1;\n            const detailDivs = cell.querySelectorAll('div.kbcontent, div.kbcontent1');\n            detailDivs.forEach(div => {\n                const rawHtml = div.innerHTML.trim();\n                if (!rawHtml || rawHtml === \"&nbsp;\" || div.innerText.trim().length < 2) return;\n                const blocks = rawHtml.split(/---------------------|----------------------/);\n                blocks.forEach(block => {\n                    if (!block.trim()) return;\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n                    let name = \"\";\n                    for (let node of tempDiv.childNodes) {\n                        if (node.nodeType === 3 && node.textContent.trim() !== \"\") {\n                            name = node.textContent.trim();\n                            break;\n                        }\n                    }\n                    if (!name) {\n                        const nameFont = tempDiv.querySelector('font:not([title])');\n                        if (nameFont) name = nameFont.innerText.trim();\n                    }\n                    const teacherRaw = tempDiv.querySelector('font[title=\"教师\"]')?.innerText || \"\";\n                    const teacher = teacherRaw.replace(\"任课教师:\", \"\").trim();\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText || \"未知地点\";\n                    const weekStr = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText || \"\";\n                    let startSection = 0;\n                    let endSection = 0;\n                    if (weekStr) {\n                        const sectionPart = weekStr.match(/\\[(.*?)节\\]/);\n                        if (sectionPart && sectionPart[1]) {\n                            const sections = sectionPart[1].split('-').map(Number).filter(n => !isNaN(n));\n                            if (sections.length > 0) {\n                                startSection = sections[0];\n                                endSection = sections[sections.length - 1];\n                            }\n                        }\n                    }\n                    if (name && startSection > 0) {\n                        rawCourses.push({\n                            \"name\": name,\n                            \"teacher\": teacher || \"未知教师\",\n                            \"weeks\": parseWeeks(weekStr),\n                            \"position\": position,\n                            \"day\": day,\n                            \"startSection\": startSection,\n                            \"endSection\": endSection\n                        });\n                    }\n                });\n            });\n        });\n    });\n    return mergeAndDistinctCourses(rawCourses);\n}\n\n// 从教学周历解析开学日期和结束日期\nfunction parseWeekCalendar(html) {\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(html, 'text/html');\n    const table = doc.getElementById('kbtable');\n    if (!table) return null;\n    \n    const rows = table.querySelectorAll('tr');\n    let firstWeekMonday = null;\n    let lastWeekSaturday = null;\n    \n    for (const row of rows) {\n        const cells = row.querySelectorAll('td');\n        if (cells.length < 2) continue;\n        \n        const firstCell = cells[0].innerText.trim();\n        if (!/^\\d+$/.test(firstCell)) continue;\n        \n        const weekNum = parseInt(firstCell);\n        if (weekNum === 1) {\n            // 第1周，找周一（索引2：周号0、周日1、周一2）\n            if (cells.length > 2) {\n                firstWeekMonday = cells[2].getAttribute('title');\n            }\n        }\n        // 记录最后一周\n        if (cells.length > 7) {\n            lastWeekSaturday = cells[7].getAttribute('title');\n        }\n    }\n    \n    return { firstWeekMonday, lastWeekSaturday };\n}\n\n// 保存课表配置\nasync function saveAppConfig(startDate) {\n    const config = { \n        \"semesterTotalWeeks\": 20, \n        \"firstDayOfWeek\": 1,\n        \"semesterStartDate\": startDate\n    };\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n// 双季作息时间表\nconst winterSlots = [\n    { \"number\": 1,  \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n    { \"number\": 2,  \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n    { \"number\": 3,  \"startTime\": \"10:10\", \"endTime\": \"10:55\" },\n    { \"number\": 4,  \"startTime\": \"11:05\", \"endTime\": \"11:50\" },\n    { \"number\": 5,  \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n    { \"number\": 6,  \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n    { \"number\": 7,  \"startTime\": \"16:10\", \"endTime\": \"16:55\" },\n    { \"number\": 8,  \"startTime\": \"17:05\", \"endTime\": \"17:50\" },\n    { \"number\": 9,  \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n    { \"number\": 10, \"startTime\": \"19:55\", \"endTime\": \"20:40\" },\n    { \"number\": 11, \"startTime\": \"20:50\", \"endTime\": \"21:35\" }\n];\n\nconst summerSlots = [\n    { \"number\": 1,  \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n    { \"number\": 2,  \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n    { \"number\": 3,  \"startTime\": \"10:10\", \"endTime\": \"10:55\" },\n    { \"number\": 4,  \"startTime\": \"11:05\", \"endTime\": \"11:50\" },\n    { \"number\": 5,  \"startTime\": \"14:30\", \"endTime\": \"15:15\" },\n    { \"number\": 6,  \"startTime\": \"15:25\", \"endTime\": \"16:10\" },\n    { \"number\": 7,  \"startTime\": \"16:40\", \"endTime\": \"17:25\" },\n    { \"number\": 8,  \"startTime\": \"17:35\", \"endTime\": \"18:20\" },\n    { \"number\": 9,  \"startTime\": \"19:30\", \"endTime\": \"20:15\" },\n    { \"number\": 10, \"startTime\": \"20:25\", \"endTime\": \"21:10\" },\n    { \"number\": 11, \"startTime\": \"21:20\", \"endTime\": \"22:05\" }\n];\n\n// 保存时间段（根据用户选择）\nasync function saveAppTimeSlots(timeSlots) {\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n}\n\n// 流程编排\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\"提示\", \"请确保已成功登录教务系统。是否开始导入？\", \"开始\");\n        if (!confirmed) return;\n\n        // 选择学年\n        const year = await window.shiguangBridgePromise.showPrompt(\"选择学年\", \"请输入要导入课程的起始学年（例如 2026-2027 应输入2026）:\", \"\", \"validateYearInput\");\n        if (!year) return;\n\n        // 选择学期\n        const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\"选择学期\", JSON.stringify([\"第一学期\", \"第二学期\"]), -1);\n        if (semesterIndex === null) return;\n\n        // 选择作息时间类型\n        const scheduleIndex = await window.shiguangBridgePromise.showSingleSelection(\n            \"选择作息时间\",\n            JSON.stringify([\"冬令时\", \"夏令时\"]),\n            -1\n        );\n        if (scheduleIndex === null) return;\n\n        const semesterId = `${year}-${parseInt(year) + 1}-${semesterIndex + 1}`;\n        window.shiguangBridge.showToast(\"正在获取学期日期...\");\n\n        // 请求教学周历获取开学日期\n        let semesterStartDate = null;\n        try {\n            let calendarBody = `xnxq01id=${semesterId}`;\n            for (let i = 1; i <= 20; i++) {\n                calendarBody += `&xqt=${i}&xqt=${i}`;\n            }\n            \n            const calendarResp = await fetch(\"/jsxsd/jxzl/jxzl_query\", {\n                method: \"POST\",\n                headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n                body: calendarBody,\n                credentials: \"include\"\n            });\n            const calendarHtml = await calendarResp.text();\n            const calendarInfo = parseWeekCalendar(calendarHtml);\n            if (calendarInfo && calendarInfo.firstWeekMonday) {\n                // 转换格式：2026年09月07日 -> 2026-09-07\n                const raw = calendarInfo.firstWeekMonday;\n                const m = raw.match(/(\\d{4})年(\\d{2})月(\\d{2})/);\n                if (m) semesterStartDate = `${m[1]}-${m[2]}-${m[3]}`;\n                window.shiguangBridge.showToast(`开学日期: ${semesterStartDate}`);\n            }\n        } catch (e) {\n            console.error(\"获取学期日期失败:\", e);\n        }\n\n        window.shiguangBridge.showToast(\"正在请求课程数据...\");\n\n        const response = await fetch(\"/jsxsd/xskb/xskb_list.do\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: `cj0701id=&zc=&demo=&xnxq01id=${semesterId}&sfFD=1&wkbkc=1`,\n            credentials: \"include\"\n        });\n\n        const html = await response.text();\n        const finalCourses = parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"));\n\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现课程，请检查学期选择或登录状态。\");\n            return;\n        }\n\n        await saveAppConfig(semesterStartDate);\n        const selectedSlots = scheduleIndex === 0 ? winterSlots : summerSlots;\n        await saveAppTimeSlots(selectedSlots);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(\"异常: \" + error.message);\n    }\n}\n\nrunImportFlow();\n","HUNNU":"/**\n * 湖南师范大学 (hunnu.edu.cn) 拾光课程表适配脚本\n *\n * 适配方式：从 courseTableForStd.action 返回的 HTML 中\n *           解析 TaskActivity JavaScript 数据，提取精确的课程信息。\n *           课程数据以 new TaskActivity(...) 调用 + index 赋值的形式嵌入页面。\n */\n\n\"use strict\";\n\n// ===== 常量 =====\nconst UNIT_COUNT = 13;\nconst TIME_SLOTS = [\n    { number: 1,  startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2,  startTime: \"08:55\", endTime: \"09:40\" },\n    { number: 3,  startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4,  startTime: \"10:55\", endTime: \"11:40\" },\n    { number: 5,  startTime: \"12:45\", endTime: \"13:30\" },\n    { number: 6,  startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 7,  startTime: \"14:30\", endTime: \"15:15\" },\n    { number: 8,  startTime: \"15:25\", endTime: \"16:10\" },\n    { number: 9,  startTime: \"16:30\", endTime: \"17:15\" },\n    { number: 10, startTime: \"17:25\", endTime: \"18:10\" },\n    { number: 11, startTime: \"19:00\", endTime: \"19:45\" },\n    { number: 12, startTime: \"19:55\", endTime: \"20:40\" },\n    { number: 13, startTime: \"20:50\", endTime: \"21:35\" }\n];\n\n// ===== 工具函数 =====\n\n/**\n * 将周次位图转为周次数组\n * 位图格式：50位0/1字符串，位置i（1-indexed）对应第i周\n * 位置0固定为0（占位符），位置1=第1周，位置2=第2周...\n */\nfunction parseWeeksFromBitmap(bitmap) {\n    const weeks = [];\n    if (!bitmap) return weeks;\n    for (let i = 1; i < bitmap.length; i++) {\n        if (bitmap[i] === \"1\") weeks.push(i);\n    }\n    return weeks;\n}\n\n/**\n * 智能分割 TaskActivity 参数（按逗号，保留引号内内容）\n */\nfunction splitArgs(str) {\n    const result = [];\n    let current = \"\";\n    let depth = 0;\n    let inQuote = false;\n    for (const ch of str) {\n        if (ch === '\"') { inQuote = !inQuote; current += ch; }\n        else if (ch === \"(\" && !inQuote) { depth++; current += ch; }\n        else if (ch === \")\" && !inQuote) { depth--; current += ch; }\n        else if (ch === \",\" && !inQuote && depth === 0) {\n            result.push(current.trim());\n            current = \"\";\n        } else { current += ch; }\n    }\n    if (current.trim()) result.push(current.trim());\n    return result;\n}\n\n/**\n * 从完整 HTML 中解析所有 TaskActivity 课程\n *\n * 匹配模式：actTeachers + 任意代码 + TaskActivity + index 赋值\n * 使用单个正则避免跨块获取错误的 actTeachers。\n */\nfunction parseTaskActivities(html) {\n    const courses = [];\n\n    const blockRe = /var\\s+actTeachers\\s*=\\s*\\[[^\\]]*?name\\s*:\\s*\"([^\"]+)\"[^\\]]*?\\]\\s*;[\\s\\S]*?activity\\s*=\\s*new\\s+TaskActivity\\s*\\(([\\s\\S]*?)\\)\\s*;([\\s\\S]*?)(?=var\\s+(?:actTeachers|teachers)|table0\\.marshalTable|$)/g;\n\n    let match;\n    while ((match = blockRe.exec(html)) !== null) {\n        const teacher = match[1];\n        const argsStr = match[2];\n        const tail = match[3];\n\n        const parts = splitArgs(argsStr);\n        if (parts.length < 7) continue;\n\n        const courseFull = (parts[3] || \"\").replace(/^\"|\"$/g, \"\");\n        const location = (parts[5] || \"\").replace(/^\"|\"$/g, \"\");\n        const weekBitmap = (parts[6] || \"\").replace(/^\"|\"$/g, \"\");\n\n        const nameMatch = courseFull.match(/^(.+?)\\(/);\n        const name = nameMatch ? nameMatch[1].trim() : courseFull;\n        if (!name) continue;\n\n        const weeks = parseWeeksFromBitmap(weekBitmap);\n        if (weeks.length === 0) continue;\n\n        const idxRe = /index\\s*=\\s*(\\d+)\\s*\\*\\s*(?:unitCount|\\d+)\\s*\\+\\s*(\\d+)\\s*;/g;\n        let idxMatch;\n        while ((idxMatch = idxRe.exec(tail)) !== null) {\n            const day = parseInt(idxMatch[1]);\n            const section = parseInt(idxMatch[2]);\n            courses.push({\n                name, teacher, position: location,\n                day: day + 1, startSection: section + 1, endSection: section + 1,\n                weeks: [...weeks]\n            });\n        }\n    }\n    return courses;\n}\n\n/**\n * 合并同一课程在相邻节次的条目\n */\nfunction mergeCourses(courses) {\n    // 第一步：按 name+teacher+position+day 分组\n    const groups = new Map();\n    for (const c of courses) {\n        const key = `${c.name}|${c.teacher}|${c.position}|${c.day}`;\n        if (!groups.has(key)) groups.set(key, []);\n        groups.get(key).push(c);\n    }\n\n    const merged = [];\n    for (const [, group] of groups) {\n        // 按 startSection 排序\n        group.sort((a, b) => a.startSection - b.startSection);\n\n        let current = null;\n        for (const c of group) {\n            if (!current) {\n                current = { ...c, weeks: [...c.weeks] };\n            } else if (c.startSection === current.endSection + 1) {\n                // 相邻节次，扩展 endSection 并合并周次\n                current.endSection = c.endSection;\n                current.weeks = [...new Set([...current.weeks, ...c.weeks])].sort((a, b) => a - b);\n            } else {\n                merged.push(current);\n                current = { ...c, weeks: [...c.weeks] };\n            }\n        }\n        if (current) merged.push(current);\n    }\n\n    return merged;\n}\n\n// ===== 主流程 =====\n\n/**\n * 等待指定毫秒\n */\nfunction sleep(ms) {\n    return new Promise(resolve => setTimeout(resolve, ms));\n}\n\n/**\n * 获取课表页面的完整 HTML\n *\n * 策略：\n * 1. 当前已经是课表页（URL 含 courseTableForStd）→ 直接取 document\n * 2. 在外层页面，课表 iframe 已存在 → 取 iframe 内容\n * 3. 在外层页面，课表 iframe 未创建 → 自动点击\"我的课表\"链接，等待 iframe 加载后取内容\n */\nasync function getCourseTableHtml() {\n    const url = window.location.href;\n\n    if (url.includes(\"courseTableForStd\")) {\n        return document.documentElement.outerHTML;\n    }\n\n    let iframe = Array.from(document.querySelectorAll(\"iframe.eams-iframe\")).find(\n        f => (f.src || f.getAttribute(\"src\") || \"\").includes(\"courseTableForStd\")\n    );\n\n    if (!iframe) {\n        const link = document.querySelector('a[href*=\"courseTableForStd\"][target*=\"eams-iframe\"]');\n        if (link) {\n            link.click();\n            for (let i = 0; i < 30; i++) {\n                iframe = Array.from(document.querySelectorAll(\"iframe.eams-iframe\")).find(\n                    f => (f.src || f.getAttribute(\"src\") || \"\").includes(\"courseTableForStd\")\n                );\n                if (iframe) break;\n                await sleep(200);\n            }\n        }\n    }\n\n    if (iframe) {\n        const srcdoc = iframe.getAttribute(\"srcdoc\");\n        if (srcdoc) return srcdoc;\n\n        if (!iframe.contentDocument) {\n            await new Promise(resolve => {\n                iframe.addEventListener(\"load\", resolve, { once: true });\n            });\n        }\n        return iframe.contentDocument.documentElement.outerHTML;\n    }\n\n    await window.shiguangBridgePromise.showAlert(\n        \"未找到课表\",\n        \"请先点击「我的课表」打开课表页面，然后重新运行导入。\",\n        \"确定\"\n    );\n    throw new Error(\"course table not found\");\n}\n\nasync function runImportFlow() {\n    window.shiguangBridge.showToast(\"湖南师范大学课程导入启动...\");\n\n    const confirmed = await window.shiguangBridgePromise.showAlert(\n        \"湖南师范大学课表导入\",\n        \"导入前请确保：\\n1. 您已登录教务系统\\n2. 课表页面已打开且课程数据正常显示\",\n        \"好的，开始导入\"\n    );\n    if (!confirmed) { window.shiguangBridge.showToast(\"导入已取消\"); return; }\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n\n    const html = await getCourseTableHtml();\n\n    // 解析课程\n    const rawCourses = parseTaskActivities(html);\n    if (rawCourses.length === 0) {\n        await window.shiguangBridgePromise.showAlert(\n            \"解析失败\",\n            \"未能从页面中识别到课程数据。\\n请确认课表页面已正确加载。\",\n            \"确定\"\n        );\n        return;\n    }\n\n    const courses = mergeCourses(rawCourses);\n\n    // 导入时间段\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(TIME_SLOTS));\n    } catch (e) {\n        window.shiguangBridge.showToast(\"导入时间段失败: \" + e.message);\n    }\n\n    // 保存配置\n    try {\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify({ semesterTotalWeeks: 20 }));\n    } catch (e) {\n        window.shiguangBridge.showToast(\"保存配置失败: \" + e.message);\n    }\n\n    // 保存课程\n    try {\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 门课程！`);\n    } catch (e) {\n        window.shiguangBridge.showToast(\"保存课程数据失败: \" + e.message);\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"课表导入完成！\");\n    window.shiguangBridge.notifyTaskCompletion();\n}\n\nrunImportFlow();\n","HNUST_01":"/**\n * 解析强智系统的周次字符串\n */\nfunction parseWeeks(weekStr) {\n    let weeks = [];\n    let parts = weekStr.split(',');\n    for (let part of parts) {\n        if (part.includes('-')) {\n            let [start, end] = part.split('-');\n            for (let i = parseInt(start); i <= parseInt(end); i++) {\n                if (!weeks.includes(i)) weeks.push(i);\n            }\n        } else {\n            let w = parseInt(part);\n            if (!isNaN(w) && !weeks.includes(w)) weeks.push(w);\n        }\n    }\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 提取课程数据\n */\n/**\n * 提取课程数据（已优化多节连堂课合并与去重逻辑）\n */\nfunction extractCoursesFromDoc(doc) {\n    let parsedCourses = [];\n    const table = doc.getElementById('timetable');\n    if (!table) throw new Error(\"请求成功但未找到课表表格，请确认教务系统状态。\");\n\n    const rows = table.getElementsByTagName('tr');\n    for (let i = 1; i < rows.length - 1; i++) {\n        const cells = rows[i].getElementsByTagName('td');\n        for (let j = 0; j < cells.length; j++) {\n            const dayOfWeek = j + 1; \n            const cell = cells[j];\n            \n            const detailDivs = cell.querySelectorAll('div.kbcontent');\n            if (detailDivs.length === 0) continue;\n\n            detailDivs.forEach(div => {\n                let htmlContent = div.innerHTML;\n                if (!htmlContent.trim() || htmlContent === '&nbsp;') return;\n\n                let courseBlocks = htmlContent.split(/-{10,}\\s*<br\\s*\\/?>/i);\n\n                courseBlocks.forEach(block => {\n                    if (!block.trim()) return;\n\n                    let tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    let courseObj = {\n                        day: dayOfWeek,\n                        isCustomTime: false\n                    };\n\n                    let firstNode = tempDiv.childNodes[0];\n                    if (firstNode && firstNode.nodeType === Node.TEXT_NODE) {\n                        courseObj.name = firstNode.nodeValue.trim();\n                    } else {\n                        courseObj.name = tempDiv.innerText.split('\\n')[0].trim();\n                    }\n\n                    let teacherFont = tempDiv.querySelector('font[title=\"教师\"]');\n                    courseObj.teacher = teacherFont ? teacherFont.innerText.trim() : \"未知\";\n\n                    let positionFont = tempDiv.querySelector('font[title=\"教室\"]');\n                    courseObj.position = positionFont ? positionFont.innerText.trim() : \"待定\";\n\n                    let timeFont = tempDiv.querySelector('font[title=\"周次(节次)\"]');\n                    if (timeFont) {\n                        let timeText = timeFont.innerText.trim();\n                        let timeMatch = timeText.match(/(.+?)\\(周\\)\\[([\\d-]+)节\\]/);\n                        if (timeMatch) {\n                            courseObj.weeks = parseWeeks(timeMatch[1]);\n                            let sections = timeMatch[2].split('-');\n                            courseObj.startSection = parseInt(sections[0]);\n                            courseObj.endSection = parseInt(sections[sections.length - 1]);\n                        } else {\n                            let weekOnlyMatch = timeText.match(/(.+?)\\(周\\)/);\n                            if (weekOnlyMatch) {\n                                courseObj.weeks = parseWeeks(weekOnlyMatch[1]);\n                                courseObj.startSection = i * 2 - 1;\n                                courseObj.endSection = i * 2;\n                            } else return; \n                        }\n                    } else return; \n\n                    if (courseObj.name && courseObj.weeks && courseObj.weeks.length > 0) {\n                        let isDuplicate = parsedCourses.some(c => \n                            c.day === courseObj.day &&\n                            c.name === courseObj.name &&\n                            c.startSection === courseObj.startSection &&\n                            c.endSection === courseObj.endSection &&\n                            c.teacher === courseObj.teacher &&\n                            c.position === courseObj.position &&\n                            JSON.stringify(c.weeks) === JSON.stringify(courseObj.weeks)\n                        );\n                        \n                        if (!isDuplicate) {\n                            parsedCourses.push(courseObj);\n                        }\n                    }\n                });\n            });\n        }\n    }\n    return parsedCourses;\n}\n\n// ======== 替换原有的 getPresetTimeSlots，引入双套作息时间 ========\n\n// 非夏季（秋冬春）作息（保持 HNUST 原有数据）\nconst Non_summerTimeSlots = [\n    { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n    { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n    { \"number\": 3, \"startTime\": \"10:00\", \"endTime\": \"10:45\" },\n    { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\" },\n    { \"number\": 5, \"startTime\": \"14:00\", \"endTime\": \"14:45\" },\n    { \"number\": 6, \"startTime\": \"14:55\", \"endTime\": \"15:40\" },\n    { \"number\": 7, \"startTime\": \"16:00\", \"endTime\": \"16:45\" },\n    { \"number\": 8, \"startTime\": \"16:55\", \"endTime\": \"17:40\" },\n    { \"number\": 9, \"startTime\": \"19:00\", \"endTime\": \"19:45\" },\n    { \"number\": 10,\"startTime\": \"19:55\", \"endTime\": \"20:40\" }\n];\n\n// 夏季作息（注：此处假设下午推迟半小时，请根据 HNUST 实际情况微调时间）\nconst SummerTimeSlots = [\n    { \"number\": 1, \"startTime\": \"08:00\", \"endTime\": \"08:45\" },\n    { \"number\": 2, \"startTime\": \"08:55\", \"endTime\": \"09:40\" },\n    { \"number\": 3, \"startTime\": \"10:00\", \"endTime\": \"10:45\" },\n    { \"number\": 4, \"startTime\": \"10:55\", \"endTime\": \"11:40\" },\n    { \"number\": 5, \"startTime\": \"14:30\", \"endTime\": \"15:15\" },\n    { \"number\": 6, \"startTime\": \"15:25\", \"endTime\": \"16:10\" },\n    { \"number\": 7, \"startTime\": \"16:30\", \"endTime\": \"17:15\" },\n    { \"number\": 8, \"startTime\": \"17:25\", \"endTime\": \"18:10\" },\n    { \"number\": 9, \"startTime\": \"19:30\", \"endTime\": \"20:15\" },\n    { \"number\": 10,\"startTime\": \"20:25\", \"endTime\": \"21:10\" }\n];\n\n/**\n * 弹出选择作息时间\n */\nasync function selectTimeSlotsType() {\n    const timeSlotsOptions = [\"非夏季作息 (14:00上课)\", \"夏季作息 (14:30上课)\"];\n    console.log(\"JS: 提示用户选择作息时间类型。\");\n    \n    // 如果不在APP内（网页测试环境），默认返回0\n    if (typeof window.shiguangBridgePromise === 'undefined') {\n        return 0; \n    }\n    \n    const selectedIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择作息时间\",\n        JSON.stringify(timeSlotsOptions),\n        0 // 默认选中第一个\n    );\n    return selectedIndex;\n}\n\n// =================================================================\n\n/**\n * 生成全局课表配置\n */\nfunction getCourseConfig() {\n    return {\n        \"defaultClassDuration\": 45,\n        \"defaultBreakDuration\": 10\n    };\n}\n\n/**\n * 异步编排流程\n */\nasync function runImportFlow() {\n    try {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"正在获取课表数据，请稍候...\");\n        } else {\n            console.log(\"正在发起请求获取课表...\");\n        }\n\n        const response = await fetch('/jsxsd/xskb/xskb_list.do', { method: 'GET' });\n        const htmlText = await response.text();\n        const parser = new DOMParser();\n        let doc = parser.parseFromString(htmlText, 'text/html');\n\n        const selectElem = doc.getElementById('xnxq01id');\n        let semesters = [];\n        let semesterValues = [];\n        let defaultIndex = 0;\n\n        if (selectElem) {\n            const options = selectElem.querySelectorAll('option');\n            options.forEach((opt, index) => {\n                semesters.push(opt.innerText.trim());\n                semesterValues.push(opt.value);\n                if (opt.hasAttribute('selected')) {\n                    defaultIndex = index;\n                }\n            });\n        }\n\n        if (semesters.length > 0 && typeof window.shiguangBridgePromise !== 'undefined') {\n            let selectedIdx = await window.shiguangBridgePromise.showSingleSelection(\n                \"请选择要导入的学期\", \n                JSON.stringify(semesters), \n                defaultIndex\n            );\n\n            if (selectedIdx === null) {\n                window.shiguangBridge.showToast(\"已取消导入\");\n                return;\n            }\n\n            if (selectedIdx !== defaultIndex) {\n                window.shiguangBridge.showToast(`正在获取 [${semesters[selectedIdx]}] 课表...`);\n                let formData = new URLSearchParams();\n                formData.append('xnxq01id', semesterValues[selectedIdx]);\n\n                const postResponse = await fetch('/jsxsd/xskb/xskb_list.do', {\n                    method: 'POST',\n                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n                    body: formData.toString()\n                });\n                const postHtml = await postResponse.text();\n                doc = parser.parseFromString(postHtml, 'text/html');\n            }\n        }\n\n        const courses = extractCoursesFromDoc(doc);\n        \n        if (courses.length === 0) {\n            const errMsg = \"未能解析到任何课程，请检查是否暂无排课。\";\n            if (typeof window.shiguangBridgePromise !== 'undefined') {\n                await window.shiguangBridgePromise.showAlert(\"提示\", errMsg, \"好的\");\n            } else {\n                alert(errMsg);\n            }\n            return;\n        }\n\n        const config = getCourseConfig();\n\n        // ------------------ 选择作息时间阶段 ------------------\n        const timeSlotsIndex = await selectTimeSlotsType();\n        if (timeSlotsIndex === null && typeof window.shiguangBridgePromise !== 'undefined') {\n             window.shiguangBridge.showToast(\"已取消选择作息时间，终止导入\");\n             return;\n        }\n        \n        let selectedTimeSlots = Non_summerTimeSlots;\n        if (timeSlotsIndex === 1) {\n             selectedTimeSlots = SummerTimeSlots;\n        }\n        // -----------------------------------------------------\n\n        // 浏览器测试环境，直接输出结果\n        if (typeof window.shiguangBridgePromise === 'undefined') {\n            console.log(\"【测试成功】课表配置：\", config);\n            console.log(\"【测试成功】作息时间：\", selectedTimeSlots);\n            console.log(\"【测试成功】课程数据：\", courses);\n            alert(`解析成功！获取到 ${courses.length} 门课程以及作息时间。请打开F12控制台查看。`);\n            return;\n        }\n\n        // APP 环境，执行保存配置和作息时间\n        const configSaved = await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        const timeSlotsSaved = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(selectedTimeSlots));\n        if (!configSaved || !timeSlotsSaved) {\n            window.shiguangBridge.showToast(\"保存课表时间配置失败！\");\n            // 注意：时间配置失败不一定阻断课程导入，这里选择继续导入课程\n        }\n\n        // APP 环境，执行保存课程\n        const saveResult = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (!saveResult) {\n            window.shiguangBridge.showToast(\"保存课程失败，请重试！\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 节课程及作息时间！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        if (typeof window.shiguangBridge !== 'undefined') {\n            window.shiguangBridge.showToast(\"导入发生异常: \" + error.message);\n        } else {\n            console.error(\"【导入发生异常】\", error);\n            alert(\"导入发生异常: \" + error.message);\n        }\n    }\n}\n\nrunImportFlow();","HUSE":"/**\n * 将周次字符串（如 \"1-4,6,8-10\"）解析为有序的周次数字数组。\n * 支持连续区间（如 \"1-4\"）和单个周次（如 \"6\"）的混合格式。\n * @param {string} weekStr - 原始周次字符串\n * @returns {number[]} 去重并升序排列的周次数组\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    const parts = weekStr.split(',');\n\n    for (const part of parts) {\n        if (part.includes('-')) {\n            const [start, end] = part.split('-');\n            for (let w = parseInt(start); w <= parseInt(end); w++) {\n                if (!weeks.includes(w)) weeks.push(w);\n            }\n        } else {\n            const w = parseInt(part);\n            if (!isNaN(w) && !weeks.includes(w)) weeks.push(w);\n        }\n    }\n\n    return weeks.sort((a, b) => a - b);\n}\n\n/**\n * 从教务系统返回的 HTML 文档中解析所有课程信息。\n * 遍历课表格 #timetable 中每个单元格，提取课程名、教师、教室及周次节次。\n * @param {Document} doc - 已解析的 HTML 文档对象\n * @returns {object[]} 课程对象数组，每项包含 day/name/teacher/position/weeks/startSection/endSection\n */\nfunction extractCoursesFromDoc(doc) {\n    const courses = [];\n    const table = doc.getElementById('timetable');\n    if (!table) throw new Error(\"未找到课表格元素（#timetable），请确认教务系统页面已正常加载。\");\n\n    const rows = table.getElementsByTagName('tr');\n    // 跳过首行（表头）和末行（通常为空白行）\n    for (let rowIdx = 1; rowIdx < rows.length - 1; rowIdx++) {\n        const cells = rows[rowIdx].getElementsByTagName('td');\n\n        for (let colIdx = 0; colIdx < cells.length; colIdx++) {\n            const dayOfWeek = colIdx + 1; // 列索引对应星期几（1=周一）\n            const cell = cells[colIdx];\n\n            const contentDivs = cell.querySelectorAll('div.kbcontent');\n            if (contentDivs.length === 0) continue;\n\n            contentDivs.forEach(div => {\n                const rawHtml = div.innerHTML;\n                // 跳过空单元格\n                if (!rawHtml.trim() || rawHtml === '&nbsp;') return;\n\n                // 同一格内多门课以 10 个以上连字符分隔\n                const blocks = rawHtml.split(/-{10,}\\s*<br\\s*\\/?>/i);\n\n                blocks.forEach(block => {\n                    if (!block.trim()) return;\n\n                    const tmp = document.createElement('div');\n                    tmp.innerHTML = block;\n\n                    const course = {\n                        day: dayOfWeek,\n                        isCustomTime: false\n                    };\n\n                    // 课程名称取第一个文本节点，fallback 到 innerText 首行\n                    const firstNode = tmp.childNodes[0];\n                    if (firstNode && firstNode.nodeType === Node.TEXT_NODE) {\n                        course.name = firstNode.nodeValue.trim();\n                    } else {\n                        course.name = tmp.innerText.split('\\n')[0].trim();\n                    }\n\n                    // 教师姓名\n                    const teacherEl = tmp.querySelector('font[title=\"教师\"]');\n                    course.teacher = teacherEl ? teacherEl.innerText.trim() : \"未知\";\n\n                    // 上课教室\n                    const roomEl = tmp.querySelector('font[title=\"教室\"]');\n                    course.position = roomEl ? roomEl.innerText.trim() : \"待定\";\n\n                    // 周次与节次：格式为 \"X-Y(周)[A-B节]\" 或仅 \"X-Y(周)\"\n                    const timeEl = tmp.querySelector('font[title=\"周次(节次)\"]');\n                    if (!timeEl) return;\n\n                    const timeText = timeEl.innerText.trim();\n                    const fullMatch = timeText.match(/(.+?)\\(周\\)\\[(\\d+)-(\\d+)节\\]/);\n                    if (fullMatch) {\n                        course.weeks = parseWeeks(fullMatch[1]);\n                        course.startSection = parseInt(fullMatch[2]);\n                        course.endSection = parseInt(fullMatch[3]);\n                    } else {\n                        const weekOnlyMatch = timeText.match(/(.+?)\\(周\\)/);\n                        if (weekOnlyMatch) {\n                            // 节次信息缺失时，根据行索引推算默认节次\n                            course.weeks = parseWeeks(weekOnlyMatch[1]);\n                            course.startSection = rowIdx * 2 - 1;\n                            course.endSection = rowIdx * 2;\n                        } else {\n                            return; // 无法识别的时间格式，跳过\n                        }\n                    }\n\n                    if (course.name && course.weeks && course.weeks.length > 0) {\n                        courses.push(course);\n                    }\n                });\n            });\n        }\n    }\n\n    return courses;\n}\n\n/**\n * 根据当前日期返回对应学期的作息时间表。\n * 通过配置参数动态推算各节课起止时间，支持早、午、晚三段以及\n * 普通课间 / 中课间 / 大课间三级课间时长。\n * 5月～9月使用夏季作息，其余月份使用春秋冬季作息。\n * @returns {object[]} 节次时间数组，每项包含 number/startTime/endTime\n */\nfunction getPresetTimeSlots() {\n    const month = new Date().getMonth() + 1;\n    const isSummer = month >= 5 && month <= 9;\n\n    // ── 作息参数配置 ──────────────────────────────────────────────\n    const params = isSummer ? {\n        // 夏季作息参数\n        morningStartTime:     \"08:10\",  // 早上第 1 节开始时间\n        afternoonStartTime:   \"14:45\",  // 中午第 1 节开始时间（第 5 节）\n        eveningStartTime:     \"19:30\",  // 晚上第 1 节开始时间（第 9 节）\n        classDuration:        45,       // 单节课时长（分钟）\n        normalBreakDuration:  10,       // 普通课间时长（分钟）\n        mediumBreakDuration:  15,       // 中课间时长（分钟）\n        longBreakDuration:    20,       // 大课间时长（分钟）\n        longBreakAfterSlot:   2,        // 大课间插入位置（第 N 节课后）\n        mediumBreakAfterSlot: 6,        // 中课间插入位置（第 N 节课后）\n    } : {\n        // 春秋冬季作息参数\n        morningStartTime:     \"08:20\",\n        afternoonStartTime:   \"14:30\",\n        eveningStartTime:     \"19:10\",\n        classDuration:        45,\n        normalBreakDuration:  10,\n        mediumBreakDuration:  15,\n        longBreakDuration:    20,\n        longBreakAfterSlot:   2,\n        mediumBreakAfterSlot: 6,\n    };\n\n    // 早上 4 节 / 下午 4 节 / 晚上 3 节\n    const SESSION_SLOTS   = [4, 4, 3];\n    const SESSION_STARTS  = [\n        params.morningStartTime,\n        params.afternoonStartTime,\n        params.eveningStartTime,\n    ];\n\n    const toMinutes = (t) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };\n    const toTimeStr = (min) => `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;\n\n    const { classDuration, normalBreakDuration, mediumBreakDuration, longBreakDuration,\n            longBreakAfterSlot, mediumBreakAfterSlot } = params;\n\n    const result = [];\n    let slotNumber = 1;\n\n    for (let s = 0; s < SESSION_SLOTS.length; s++) {\n        let cursor = toMinutes(SESSION_STARTS[s]);\n        const count = SESSION_SLOTS[s];\n\n        for (let i = 0; i < count; i++) {\n            result.push({\n                number:    slotNumber,\n                startTime: toTimeStr(cursor),\n                endTime:   toTimeStr(cursor + classDuration),\n            });\n            cursor += classDuration;\n            // 非本段末节时，按位置选择课间时长\n            if (i < count - 1) {\n                if      (slotNumber === longBreakAfterSlot)   cursor += longBreakDuration;\n                else if (slotNumber === mediumBreakAfterSlot) cursor += mediumBreakDuration;\n                else                                          cursor += normalBreakDuration;\n            }\n            slotNumber++;\n        }\n    }\n\n    return result;\n}\n/**\n * 从教学周历页面推断学期开学日期（YYYY-MM-DD）。\n * 解析策略：\n * 1) 优先读取第 1 周对应的周一日期；\n * 2) 若未命中，则在周历表中收集全部日期并取最小值兜底。\n * @returns {Promise<{ semesterStartDate: string|null, totalWeeks: number|null }>} 开学日期和总周数；无法解析时返回 null\n */\nasync function getStartDateandTotalWeeks() {\n    const response = await fetch('/jsxsd/jxzl/jxzl_query', { method: 'GET' });\n    if (!response.ok) {\n        throw new Error(`周历请求失败：${response.status}`);\n    }\n\n    const htmlText = await response.text();\n    const doc = new DOMParser().parseFromString(htmlText, 'text/html');\n    const table = doc.querySelector('#kbtable');\n\n    if (!table) {\n        console.log('未找到周历表格 #kbtable');\n        return { semesterStartDate: null, totalWeeks: null };\n    }\n\n    const parseCNDate = (text) => {\n        const m = String(text || '').match(/(\\d{4})年(\\d{1,2})月(\\d{1,2})/);\n        if (!m) return null;\n        const [, y, mo, d] = m;\n        return `${y}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}`;\n    };\n\n    let week1Monday = null;\n    let minDate = null;\n    let totalWeeks = null;\n\n    const rows = table.querySelectorAll('tr');\n    if(!rows || rows.length === 0) {\n        console.log('周历表格 #kbtable 中未找到任何行');\n        return { semesterStartDate: null, totalWeeks: null };\n    }\n\n    rows.forEach((row) => {\n        const firstCellText = row.cells?.[0]?.textContent?.trim() || '';\n        const week = /^\\d+$/.test(firstCellText) ? Number(firstCellText) : NaN;\n\n        if (!Number.isNaN(week)) {\n            totalWeeks = Math.max(totalWeeks, week);\n            if (week === 1 && !week1Monday) {\n                const candidate = parseCNDate(row.cells?.[1]?.getAttribute('title'));\n                if (candidate) week1Monday = candidate;\n            }\n        }\n\n        row.querySelectorAll('td[title]').forEach((td) => {\n            const candidate = parseCNDate(td.getAttribute('title'));\n            if (!candidate) return;\n            if (!minDate || candidate < minDate) {\n                minDate = candidate;\n            }\n        });\n    });\n\n    const semesterStartDate = week1Monday || minDate;\n    console.log('开学日期：', semesterStartDate || '未找到');\n    console.log('总周数：', totalWeeks);\n\n    return { semesterStartDate, totalWeeks };\n}\n\n/**\n * 返回全局课表基础配置（单节课时长与课间休息时长）。\n * @returns {Promise<{ semesterStartDate: string|null, semesterTotalWeeks: number, defaultClassDuration: number, defaultBreakDuration: number }>}\n */\nasync function getCourseConfig() {\n    const { semesterStartDate, totalWeeks } = await getStartDateandTotalWeeks();\n    return {\n        semesterStartDate: semesterStartDate,\n        semesterTotalWeeks: totalWeeks,\n        defaultClassDuration: 45,\n        defaultBreakDuration: 10\n    };\n}\n\n/**\n * 课表导入主流程。\n * 依次完成：发起请求 → 解析 HTML → 提取课程 → 保存配置/作息/课程 → 通知完成。\n * 在浏览器调试环境中仅打印结果，不调用 AndroidBridge。\n */\nasync function runImportFlow() {\n    const isApp = typeof window.shiguangBridgePromise !== 'undefined';\n    const hasToast = typeof window.shiguangBridge !== 'undefined';\n\n    try {\n        if (hasToast) {\n            window.shiguangBridge.showToast(\"正在拉取课表，请稍候...\");\n        } else {\n            console.log(\"[HUSE] 开始请求课表页面...\");\n        }\n\n        const response = await fetch('/jsxsd/xskb/xskb_list.do', { method: 'GET' });\n        const htmlText = await response.text();\n        const doc = new DOMParser().parseFromString(htmlText, 'text/html');\n\n        // 读取学期列表（当前仅用于记录，实际取最新学期）\n        const selectEl = doc.getElementById('xnxq01id');\n        const semesters = [];\n        const semesterValues = [];\n        let defaultIndex = 0;\n\n        if (selectEl) {\n            selectEl.querySelectorAll('option').forEach((opt, idx) => {\n                semesters.push(opt.innerText.trim());\n                semesterValues.push(opt.value);\n                if (opt.hasAttribute('selected')) defaultIndex = idx;\n            });\n        }\n        // 始终选取列表首的最新学期\n        defaultIndex = 0;\n        console.log(`[HUSE] 共找到 ${semesters.length} 个学期，当前使用：${semesters[defaultIndex] || '未知'}`);\n\n        const courses = extractCoursesFromDoc(doc);\n\n        if (courses.length === 0) {\n            const msg = \"未解析到任何课程，当前学期可能暂无排课。\";\n            console.warn(\"[HUSE] \" + msg);\n            if (isApp) {\n                await window.shiguangBridgePromise.showAlert(\"提示\", msg, \"好的\");\n            } else {\n                alert(msg);\n            }\n            return;\n        }\n\n        console.log(`[HUSE] 成功解析 ${courses.length} 门课程。`);\n\n        const config = await getCourseConfig();\n        const timeSlots = getPresetTimeSlots();\n\n        // 浏览器调试环境：输出结果后退出，不执行 APP 存储逻辑\n        if (!isApp) {\n            console.log(\"[HUSE] 课表基础配置：\", config);\n            console.log(\"[HUSE] 作息时间表：\", timeSlots);\n            console.log(\"[HUSE] 课程列表：\", courses);\n            alert(`解析完成！共获取 ${courses.length} 门课程及作息时间，详情见控制台（F12）。`);\n            return;\n        }\n\n        // APP 环境：保存课表配置与作息时间\n        const configSaved = await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        const slotsSaved = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n        if (!configSaved || !slotsSaved) {\n            // 时间配置保存失败不强制中断，继续尝试导入课程\n            console.warn(\"[HUSE] 课表时间配置保存失败，将继续尝试导入课程。\");\n            window.shiguangBridge.showToast(\"时间配置保存失败，继续导入课程...\");\n        }\n\n        // APP 环境：保存课程数据\n        const courseSaved = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (!courseSaved) {\n            console.error(\"[HUSE] 课程数据保存失败。\");\n            window.shiguangBridge.showToast(\"课程保存失败，请重试！\");\n            return;\n        }\n\n        console.log(`[HUSE] 导入完成，共写入 ${courses.length} 门课程。`);\n        window.shiguangBridge.showToast(`成功导入 ${courses.length} 门课程及作息时间！`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (err) {\n        console.error(\"[HUSE] 导入流程发生异常：\", err);\n        if (hasToast) {\n            window.shiguangBridge.showToast(\"导入失败：\" + err.message);\n        } else {\n            alert(\"导入失败：\" + err.message);\n        }\n    }\n}\n\nrunImportFlow();","HNPTC_01":"// 湖南邮电职业技术学院 · 湘邮教学管理平台（强智 jsxsd）\n// 适配作者：小漫君\n// 学生端入口：http://jx.hnxyjf.com:10081/jsxsd/\n// 使用流程：在软件内置浏览器登录学生端，点击导入并选择学期。\n// 说明：直接请求整学期课表与教学周历；作息参考学校 2025-2026 学年校历，后续调整请核对。\n\nconst HNPTC_KB_URL = '/jsxsd/xskb/xskb_list.do';\nconst HNPTC_CALENDAR_URL = '/jsxsd/jxzl/jxzl_query';\nconst HNPTC_POST_OPTIONS = { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } };\n// https://jwc.hnptc.edu.cn/2025_09/19_09/content-30331.html\nconst HNPTC_TIME_SLOTS = [\n    { number: 1, startTime: '08:30', endTime: '09:15' },\n    { number: 2, startTime: '09:25', endTime: '10:10' },\n    { number: 3, startTime: '10:25', endTime: '11:10' },\n    { number: 4, startTime: '11:20', endTime: '12:05' },\n    { number: 5, startTime: '14:00', endTime: '14:45' },\n    { number: 6, startTime: '14:55', endTime: '15:40' },\n    { number: 7, startTime: '15:50', endTime: '16:35' },\n    { number: 8, startTime: '16:45', endTime: '17:30' },\n    { number: 9, startTime: '19:30', endTime: '20:15' },\n    { number: 10, startTime: '20:25', endTime: '21:10' }\n];\n\n// ==================== 桥接封装 ====================\n\nfunction toast(message) {\n    if (window.shiguangBridge && typeof window.shiguangBridge.showToast === 'function') {\n        window.shiguangBridge.showToast(message);\n    } else {\n        console.log('[HNPTC] ' + message);\n    }\n}\n\nasync function alertUser(title, message) {\n    if (window.shiguangBridgePromise && typeof window.shiguangBridgePromise.showAlert === 'function') {\n        const confirmed = await window.shiguangBridgePromise.showAlert(title, message, '知道了');\n        return confirmed === true || confirmed === 'true';\n    }\n    alert(title + '\\n' + message);\n    return true;\n}\n\n// 原生以字符串序号或 \"null\" 回传，统一为数字序号，-1 表示取消\nasync function selectFromList(title, items, defaultIndex) {\n    if (!(window.shiguangBridgePromise && typeof window.shiguangBridgePromise.showSingleSelection === 'function')) {\n        return defaultIndex;\n    }\n    const result = await window.shiguangBridgePromise.showSingleSelection(title, JSON.stringify(items), defaultIndex);\n    if (result === null || result === undefined || result === 'null') return -1;\n    const index = typeof result === 'number' ? result : parseInt(result, 10);\n    return isNaN(index) ? -1 : index;\n}\n\n// ==================== 请求 ====================\n\n// 兼容直连与 WebVPN 形态的地址，取 /jsxsd/ 之前的部分作为前缀\nfunction jsxsdUrl(path) {\n    const currentPath = window.location.pathname || '';\n    const index = currentPath.indexOf('/jsxsd/');\n    return window.location.origin + (index < 0 ? '' : currentPath.slice(0, index)) + path;\n}\n\nasync function requestText(url, options) {\n    const response = await fetch(url, Object.assign({ credentials: 'include' }, options || {}));\n    if (!response.ok) throw new Error('教务请求失败（HTTP ' + response.status + '）');\n    return await response.text();\n}\n\n// 课表页表单字段与页面 Form1 一致，POST 失败时退回带查询参数的 GET\nasync function fetchTimetableDoc(semesterValue, kbjcmsid) {\n    const url = jsxsdUrl(HNPTC_KB_URL);\n    const body = 'jx0404id=&cj0701id=&zc=&demo=&xnxq01id=' + encodeURIComponent(semesterValue) +\n        '&sfFD=1&kbjcmsid=' + encodeURIComponent(kbjcmsid);\n\n    const posted = new DOMParser().parseFromString(\n        await requestText(url, Object.assign({ method: 'POST', body: body }, HNPTC_POST_OPTIONS)), 'text/html');\n    if (findTimetableTable(posted)) return posted;\n\n    const got = new DOMParser().parseFromString(\n        await requestText(url + '?xnxq01id=' + encodeURIComponent(semesterValue)), 'text/html');\n    return findTimetableTable(got) ? got : null;\n}\n\n// ==================== 学期与教学周历 ====================\n\n// 学期列表：[{ value: \"2026-2027-1\", label: \"2026-2027 学年第 1 学期\", selected: true }]\nfunction parseSemesters(doc) {\n    const select = doc.querySelector('select[name=\"xnxq01id\"], select#xnxq01id');\n    if (!select) return [];\n    const list = [];\n    select.querySelectorAll('option').forEach(function (option) {\n        const value = String(option.getAttribute('value') || '').trim();\n        if (!value) return;\n        list.push({\n            value: value,\n            label: value.replace(/^(\\d{4})-(\\d{4})-(\\d)$/, '$1-$2 学年第 $3 学期'),\n            selected: option.hasAttribute('selected')\n        });\n    });\n    return list;\n}\n\nfunction parseKbjcmsid(doc) {\n    const select = doc.querySelector('select[name=\"kbjcmsid\"]');\n    const option = select ? (select.querySelector('option[selected]') || select.querySelector('option')) : null;\n    return option ? String(option.getAttribute('value') || '').trim() : '';\n}\n\n// 教学周历：首列为周次序号，第二列含该周星期一日期\nfunction parseCalendar(doc) {\n    const result = { semesterStartDate: null, totalWeeks: null };\n    const table = doc.querySelector('table');\n    if (!table) return result;\n\n    const toDate = function (text) {\n        const match = String(text || '').match(/(\\d{4})\\s*[-年]\\s*(\\d{1,2})\\s*[-月]\\s*(\\d{1,2})/);\n        return match ? match[1] + '-' + match[2].padStart(2, '0') + '-' + match[3].padStart(2, '0') : null;\n    };\n\n    Array.from(table.querySelectorAll('tr')).forEach(function (row) {\n        const cells = Array.from(row.children);\n        const first = cells.length > 0 ? String(cells[0].textContent).trim() : '';\n        if (!/^\\d+$/.test(first)) return;\n\n        const week = parseInt(first, 10);\n        result.totalWeeks = result.totalWeeks === null ? week : Math.max(result.totalWeeks, week);\n        if (week === 1 && !result.semesterStartDate && cells.length > 1) {\n            result.semesterStartDate = toDate(cells[1].getAttribute('title')) || toDate(cells[1].textContent);\n        }\n    });\n    return result;\n}\n\nasync function fetchCalendar(semesterValue) {\n    try {\n        const text = await requestText(jsxsdUrl(HNPTC_CALENDAR_URL), Object.assign(\n            { method: 'POST', body: 'xnxq01id=' + encodeURIComponent(semesterValue) }, HNPTC_POST_OPTIONS));\n        return parseCalendar(new DOMParser().parseFromString(text, 'text/html'));\n    } catch (error) {\n        console.warn('[HNPTC] 教学周历读取失败：', error);\n        return { semesterStartDate: null, totalWeeks: null };\n    }\n}\n\n// ==================== 课表解析 ====================\n\n// 不同强智版本分别使用 #timetable 与 #kbtable\nfunction findTimetableTable(doc) {\n    return doc.getElementById('timetable') || doc.getElementById('kbtable');\n}\n\n// 周次与节次：兼容 1-16(周)[01-02节]、1-8,10-16(周)、1-15周(单)、2-16(双)、第3-4节 等写法\nfunction parseWeeksAndSections(text) {\n    const result = { weeks: [], sections: [] };\n    const content = String(text || '').trim();\n    if (!content) return result;\n\n    const parity = /双/.test(content) ? 2 : (/单/.test(content) ? 1 : 0);\n    const bracketIndex = content.indexOf('[');\n    const cleaned = (bracketIndex >= 0 ? content.slice(0, bracketIndex) : content)\n        .replace(/第/g, '')\n        .replace(/至|到|~/g, '-')\n        .replace(/[（(][^（）()]*[）)]/g, '')\n        .replace(/周/g, '');\n\n    cleaned.split(/[,，、;；\\s]+/).forEach(function (segment) {\n        const item = segment.trim();\n        const range = item.match(/^(\\d+)\\s*[-–—]\\s*(\\d+)$/);\n        if (range) {\n            for (let week = parseInt(range[1], 10); week <= parseInt(range[2], 10); week++) result.weeks.push(week);\n        } else if (/^\\d+$/.test(item)) {\n            result.weeks.push(parseInt(item, 10));\n        }\n    });\n\n    if (parity) {\n        result.weeks = result.weeks.filter(function (week) { return week % 2 === (parity === 1 ? 1 : 0); });\n    }\n    result.weeks = Array.from(new Set(result.weeks)).sort(function (a, b) { return a - b; });\n\n    const sectionMatch = content.match(/\\[([^\\]]*)\\]/);\n    if (sectionMatch) {\n        (sectionMatch[1].match(/\\d+/g) || []).forEach(function (number) {\n            const section = parseInt(number, 10);\n            if (result.sections.indexOf(section) < 0) result.sections.push(section);\n        });\n        result.sections.sort(function (a, b) { return a - b; });\n    }\n    return result;\n}\n\n// 收集单个课表单元格内的全部课程候选。强智在格内同时输出简表与详表，\n// 简表缺少教师与节次方括号，此处一并解析，交由归并阶段择优。\nfunction collectCellCandidates(cellDiv, day, output, rowSections) {\n    const html = String(cellDiv.innerHTML || '').trim();\n    if (!html || html.replace(/&nbsp;/gi, '').trim() === '') return;\n\n    html.split(/[-—–]{6,}\\s*(?:<br\\s*\\/?>)?/i).forEach(function (blockHtml) {\n        if (!blockHtml.trim()) return;\n\n        const holder = document.createElement('div');\n        holder.innerHTML = blockHtml;\n\n        let name = '';\n        for (let i = 0; i < holder.childNodes.length; i++) {\n            const node = holder.childNodes[i];\n            if (node.nodeType === 3 && /[\\u4e00-\\u9fa5]/.test(node.textContent)) {\n                name = node.textContent.trim();\n                break;\n            }\n        }\n        if (!name) name = String(holder.textContent || '').split('\\n')[0].trim();\n        if (!name) return;\n\n        const pickText = function (titles) {\n            for (let i = 0; i < titles.length; i++) {\n                const element = holder.querySelector('font[title*=\"' + titles[i] + '\"]');\n                if (element && element.textContent.trim()) return element.textContent.trim();\n            }\n            return '';\n        };\n\n        let timeText = pickText(['周次', '节次']);\n        if (!/\\[[^\\]]*\\]/.test(timeText)) {\n            const bracket = String(holder.textContent || '').match(/\\[[^\\]]*\\]/);\n            if (bracket) timeText += bracket[0];\n        }\n\n        const parsed = parseWeeksAndSections(timeText || holder.textContent);\n        if (parsed.weeks.length === 0) return;\n        if (parsed.sections.length === 0 && rowSections) {\n            for (let section = rowSections[0]; section <= rowSections[1]; section++) parsed.sections.push(section);\n        }\n\n        const teacher = pickText(['教师', '老师']);\n        const position = pickText(['教室', '地点']).replace(/\\[\\s*\\d+\\s*-\\s*\\d+\\s*\\]\\s*节?$/, '').trim();\n\n        output.push({\n            name: name,\n            teacher: teacher,\n            position: position,\n            day: day,\n            weeks: parsed.weeks,\n            sections: parsed.sections,\n            score: (teacher ? 4 : 0) + (/\\[[^\\]]*\\]/.test(timeText) ? 3 : 0) +\n                (position ? 1 : 0) + (parsed.sections.length > 1 ? 1 : 0)\n        });\n    });\n}\n\n// 按课程名、周次、教室归并候选，保留信息更完整的一条\nfunction mergeCellCandidates(candidates) {\n    const groups = {};\n    const order = [];\n    candidates.forEach(function (item) {\n        const key = item.name + '|' + item.weeks.join(',') + '|' + item.position;\n        if (groups[key] === undefined) {\n            groups[key] = item;\n            order.push(key);\n        } else if (item.score > groups[key].score) {\n            groups[key] = item;\n        }\n    });\n\n    const courses = [];\n    order.forEach(function (key) {\n        const item = groups[key];\n        if (item.sections.length === 0) return;\n        courses.push({\n            name: item.name,\n            teacher: item.teacher || '未知教师',\n            position: item.position || '未知地点',\n            day: item.day,\n            weeks: item.weeks,\n            startSection: item.sections[0],\n            endSection: item.sections[item.sections.length - 1]\n        });\n    });\n    return courses;\n}\n\nfunction parseTimetable(doc) {\n    const table = findTimetableTable(doc);\n    if (!table) return [];\n\n    const courses = [];\n    Array.from(table.querySelectorAll('tr')).forEach(function (row) {\n        const label = row.querySelector('th');\n        const labelMatch = label ? String(label.textContent).match(/(\\d+)\\s*[~～\\-—]\\s*(\\d+)\\s*节/) : null;\n        const rowSections = labelMatch ? [parseInt(labelMatch[1], 10), parseInt(labelMatch[2], 10)] : null;\n\n        Array.from(row.querySelectorAll('td')).forEach(function (cell, index) {\n            const blocks = cell.querySelectorAll('div.kbcontent, div.kbcontent1');\n            if (blocks.length === 0) return;\n\n            const candidates = [];\n            Array.from(blocks).forEach(function (block) {\n                collectCellCandidates(block, index + 1, candidates, rowSections);\n            });\n            mergeCellCandidates(candidates).forEach(function (course) {\n                courses.push(course);\n            });\n        });\n    });\n    return courses;\n}\n\n// 节次与周次合并去重函数\n// 来源：官方 Wiki《课程合并与去重函数》\n// https://github.com/XingHeYuZhuan/shiguangschedule/wiki/课程合并与去重函数\n// 阶段一按名称、教师、地点、星期、周次一致合并连续节次并去除完全重复，阶段二按相同节次合并周次\nfunction mergeAndDistinctCourses(courses) {\n    if (!Array.isArray(courses) || courses.length <= 1) return courses;\n\n    const list = courses.map(c => ({\n        ...c,\n        name: c.name || '',\n        teacher: c.teacher || '',\n        position: c.position || '',\n        weeks: Array.isArray(c.weeks) ? [...c.weeks].sort((a, b) => a - b) : []\n    }));\n\n    list.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            a.weeks.join(',').localeCompare(b.weeks.join(',')) ||\n            (a.startSection || 0) - (b.startSection || 0);\n    });\n\n    const step1Merged = [];\n    let current = list[0];\n\n    for (let i = 1; i < list.length; i++) {\n        const next = list[i];\n\n        const isSameCourseAndWeeks =\n            current.name === next.name &&\n            current.teacher === next.teacher &&\n            current.position === next.position &&\n            current.day === next.day &&\n            current.weeks.join(',') === next.weeks.join(',');\n\n        const isContinuous = current.endSection + 1 === next.startSection;\n        const isDuplicate = current.startSection === next.startSection && current.endSection === next.endSection;\n\n        if (isSameCourseAndWeeks && isContinuous) {\n            current.endSection = next.endSection;\n        } else if (isSameCourseAndWeeks && isDuplicate) {\n            continue;\n        } else {\n            step1Merged.push(current);\n            current = next;\n        }\n    }\n    step1Merged.push(current);\n\n    step1Merged.sort((a, b) => {\n        return a.name.localeCompare(b.name) ||\n            a.teacher.localeCompare(b.teacher) ||\n            a.position.localeCompare(b.position) ||\n            (a.day || 0) - (b.day || 0) ||\n            (a.startSection || 0) - (b.startSection || 0) ||\n            (a.endSection || 0) - (b.endSection || 0);\n    });\n\n    const step2Merged = [];\n    let merged = step1Merged[0];\n\n    for (let i = 1; i < step1Merged.length; i++) {\n        const next = step1Merged[i];\n\n        const isSameCourseAndSection =\n            merged.name === next.name &&\n            merged.teacher === next.teacher &&\n            merged.position === next.position &&\n            merged.day === next.day &&\n            merged.startSection === next.startSection &&\n            merged.endSection === next.endSection;\n\n        if (isSameCourseAndSection) {\n            merged.weeks = Array.from(new Set([...merged.weeks, ...next.weeks])).sort((a, b) => a - b);\n        } else {\n            step2Merged.push(merged);\n            merged = next;\n        }\n    }\n    step2Merged.push(merged);\n\n    return step2Merged;\n}\n\n// ==================== 流程编排 ====================\n\nasync function runImportFlow() {\n    try {\n        if ((window.location.pathname || '').indexOf('/jsxsd/') < 0) {\n            await alertUser('请先进入教务系统', '请登录教务系统并停留在任意教务功能页面后重新执行导入。');\n            return;\n        }\n\n        toast('正在获取学期信息…');\n        const listDoc = new DOMParser().parseFromString(await requestText(jsxsdUrl(HNPTC_KB_URL)), 'text/html');\n        const semesters = parseSemesters(listDoc);\n        if (semesters.length === 0) {\n            await alertUser('未获取到学期列表', '课表页返回异常，请确认登录状态有效后重试。');\n            return;\n        }\n\n        let defaultIndex = 0;\n        semesters.forEach(function (item, index) { if (item.selected) defaultIndex = index; });\n        // 即使只有一个学期，也交给宿主记忆/核对选项，避免后台刷新时默默切换学期。\n        const picked = await selectFromList('选择学期', semesters.map(function (item) { return item.label; }), defaultIndex);\n        if (picked < 0 || picked >= semesters.length) {\n            toast('导入已取消');\n            return;\n        }\n        const semester = semesters[picked];\n\n        toast('正在获取 ' + semester.label + ' 课表…');\n        const tableDoc = await fetchTimetableDoc(semester.value, parseKbjcmsid(listDoc));\n        if (!tableDoc) {\n            await alertUser('未获取到课表数据', '请确认已登录教务系统后重试。');\n            return;\n        }\n\n        const courses = mergeAndDistinctCourses(parseTimetable(tableDoc));\n        if (courses.length === 0) {\n            await alertUser('未找到课程', semester.label + ' 页面中没有课程内容，该学期可能尚未发布课表。');\n            return;\n        }\n\n        const calendar = await fetchCalendar(semester.value);\n        const weeks = courses.reduce(function (all, course) { return all.concat(course.weeks); }, []);\n        const config = {\n            semesterTotalWeeks: calendar.totalWeeks || Math.max.apply(null, weeks)\n        };\n        if (calendar.semesterStartDate) {\n            config.semesterStartDate = calendar.semesterStartDate;\n        } else {\n            toast('未读取到教学周历，开学日期可在软件内手动校准');\n        }\n\n        await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n        const saved = await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(courses));\n        if (saved !== true && saved !== 'true') {\n            toast('课程保存失败，请重试');\n            return;\n        }\n\n        // 校历只列出十节；若教务课表出现更多节次，保留课程导入并交由用户核对作息。\n        if (courses.every(function (course) { return course.endSection <= HNPTC_TIME_SLOTS.length; })) {\n            try {\n                const timeSaved = await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(HNPTC_TIME_SLOTS));\n                if (timeSaved === true || timeSaved === 'true') {\n                    toast('已按 2025-2026 学年校历预设作息，请核对学校最新安排');\n                } else {\n                    toast('作息时间未写入，请手动核对');\n                }\n            } catch (error) {\n                console.warn('[HNPTC] 作息时间未写入：', error);\n                toast('作息时间未写入，请手动核对');\n            }\n        } else {\n            toast('课表含校历之外的节次，请手动核对作息');\n        }\n\n        toast('导入成功：' + semester.label + ' 共 ' + courses.length + ' 条课程时段');\n        if (window.shiguangBridge && typeof window.shiguangBridge.notifyTaskCompletion === 'function') {\n            window.shiguangBridge.notifyTaskCompletion();\n        }\n    } catch (error) {\n        console.error('[HNPTC] 导入流程异常：', error);\n        await alertUser('导入失败', error && error.message ? error.message : String(error));\n    }\n}\n\n// 启动导入流程\nrunImportFlow();\n","HZU":"// 菏泽学院强智教务：新版学期理论课表（viweType=0）。\n// 参考仓库 CSUFT/MKU 的新版强智 DOM 结构，按本站实测重写。\n// 不保存登录凭据；所有请求沿用当前 WebView 的会话与协议。\n\nconst HZU_SUMMER_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:50\" },\n    { number: 2, startTime: \"09:00\", endTime: \"09:50\" },\n    { number: 3, startTime: \"10:10\", endTime: \"11:00\" },\n    { number: 4, startTime: \"11:10\", endTime: \"12:00\" },\n    { number: 5, startTime: \"14:30\", endTime: \"15:20\" },\n    { number: 6, startTime: \"15:30\", endTime: \"16:20\" },\n    { number: 7, startTime: \"16:40\", endTime: \"17:30\" },\n    { number: 8, startTime: \"17:40\", endTime: \"18:30\" },\n    { number: 9, startTime: \"19:30\", endTime: \"20:20\" },\n    { number: 10, startTime: \"20:30\", endTime: \"21:20\" }\n];\n\n// 冬季仅下午第5至8节提前半小时，上午和晚课保持不变。\nconst HZU_WINTER_TIME_SLOTS = HZU_SUMMER_TIME_SLOTS.map(slot => {\n    if (slot.number < 5 || slot.number > 8) return { ...slot };\n    const earlier = time => {\n        const [hour, minute] = time.split(\":\").map(Number);\n        const minutes = hour * 60 + minute - 30;\n        return String(Math.floor(minutes / 60)).padStart(2, \"0\") + \":\" +\n            String(minutes % 60).padStart(2, \"0\");\n    };\n    return { ...slot, startTime: earlier(slot.startTime), endTime: earlier(slot.endTime) };\n});\n\nfunction hzuComboSchedule(semesterId) {\n    const term = semesterId.match(/^(\\d{4})-(\\d{4})-([12])$/);\n    if (!term || Number(term[2]) !== Number(term[1]) + 1) {\n        throw new Error(\"无法识别作息所属学年。\");\n    }\n    const firstYear = Number(term[1]);\n    const lastYear = Number(term[2]);\n    const summerYear = term[3] === \"1\" ? firstYear : lastYear;\n    const publicSchedules = [\n        {\n            name: \"菏泽学院夏季作息\",\n            startDate: summerYear + \"-05-01\",\n            endDate: summerYear + \"-10-04\",\n            defaultClassDuration: 50,\n            defaultBreakDuration: 10,\n            timeSlots: HZU_SUMMER_TIME_SLOTS.filter(slot => slot.number >= 5 && slot.number <= 8)\n        }\n    ];\n    // App 在夏季规则之外回退到冬季基础作息，边界日期均为闭区间。\n    return { name: \"菏泽学院冬夏季作息\", publicSchedules };\n}\n\nfunction hzuUrl(path) {\n    const pathname = window.location.pathname;\n    const index = pathname.indexOf(\"/jsxsd/\");\n    if (index < 0 && !pathname.endsWith(\"/jsxsd\")) {\n        throw new Error(\"请先登录菏泽学院教务系统，再开始导入。\");\n    }\n    const prefix = index >= 0 ? pathname.slice(0, index) : pathname.slice(0, -6);\n    return window.location.origin + prefix + \"/jsxsd\" + path;\n}\n\nasync function hzuFetchDocument(path) {\n    const controller = new AbortController();\n    const timer = setTimeout(() => controller.abort(), 20000);\n    try {\n        const response = await fetch(hzuUrl(path), {\n            credentials: \"include\",\n            signal: controller.signal\n        });\n        if (!response.ok) throw new Error(\"教务请求失败：HTTP \" + response.status);\n        return new DOMParser().parseFromString(await response.text(), \"text/html\");\n    } finally {\n        clearTimeout(timer);\n    }\n}\n\nfunction hzuSemesters(doc) {\n    const select = doc.querySelector(\"#xnxq01id\");\n    if (!select) throw new Error(\"登录已失效或未获取到课表页面，请重新登录。\");\n    return Array.from(select.options).filter(option => option.value).map(option => ({\n        value: option.value,\n        text: option.textContent.trim(),\n        selected: option.selected\n    }));\n}\n\nfunction hzuCheckSemester(doc, semesterId) {\n    const value = doc.querySelector(\"#xnxq\")?.value || doc.querySelector(\"#xnxq01id\")?.value;\n    if (value !== semesterId) throw new Error(\"教务返回的学期与所选学期不一致，请重新查询。\");\n}\n\nfunction hzuNumbers(text, limit) {\n    const numbers = [];\n    const parts = text.replace(/\\s/g, \"\").split(/[,，、]/);\n    for (const part of parts) {\n        const match = part.match(/^(\\d+)(?:[-~～—至](\\d+))?$/);\n        if (!match) throw new Error(\"无法识别周次或节次：\" + text);\n        const start = Number(match[1]);\n        const end = Number(match[2] || match[1]);\n        if (start < 1 || end < start || end > limit) throw new Error(\"周次或节次超出范围：\" + text);\n        for (let number = start; number <= end; number++) numbers.push(number);\n    }\n    return Array.from(new Set(numbers)).sort((a, b) => a - b);\n}\n\nfunction hzuParseTime(text) {\n    const sectionMatch = text.match(/[\\[［]([^[\\]［］]+)节[\\]］]/);\n    if (!sectionMatch || !text.slice(0, sectionMatch.index).includes(\"周\")) {\n        throw new Error(\"课程缺少有效的周次或节次：\" + text);\n    }\n    const weekText = text.slice(0, sectionMatch.index).replace(/第|周|\\s/g, \"\");\n    const weeks = [];\n    for (const part of weekText.split(/[,，、]/)) {\n        const parity = part.match(/[（(]?(单|双)[）)]?$/);\n        const range = parity ? part.slice(0, parity.index) : part;\n        weeks.push(...hzuNumbers(range, 100).filter(week =>\n            !parity || week % 2 === (parity[1] === \"单\" ? 1 : 0)));\n    }\n    const sections = hzuNumbers(sectionMatch[1], 30);\n    // 不连续的节次拆开，不能把未上课的小节填进连续区间。\n    const ranges = [];\n    for (const section of sections) {\n        const last = ranges[ranges.length - 1];\n        if (last && last.endSection + 1 === section) last.endSection = section;\n        else ranges.push({ startSection: section, endSection: section });\n    }\n    const sortedWeeks = Array.from(new Set(weeks)).sort((a, b) => a - b);\n    if (!sortedWeeks.length) throw new Error(\"课程周次为空：\" + text);\n    return { weeks: sortedWeeks, ranges };\n}\n\nfunction hzuGrid(table) {\n    const grid = [];\n    Array.from(table.rows).forEach((row, r) => {\n        if (!grid[r]) grid[r] = [];\n        let column = 0;\n        Array.from(row.cells).forEach(cell => {\n            while (grid[r][column]) column++;\n            for (let dr = 0; dr < (cell.rowSpan || 1); dr++) {\n                if (!grid[r + dr]) grid[r + dr] = [];\n                for (let dc = 0; dc < (cell.colSpan || 1); dc++) {\n                    grid[r + dr][column + dc] = cell;\n                }\n            }\n            column += cell.colSpan || 1;\n        });\n    });\n    return grid;\n}\n\nfunction hzuField(text, label) {\n    return (text.match(new RegExp(label + \"[:：]\\\\s*([^;；]*)\")) || [])[1]?.trim() || \"\";\n}\n\nfunction hzuParseCourses(doc) {\n    const table = doc.querySelector('td[name=\"kbDataTd\"]')?.closest(\"table\");\n    if (!table) {\n        if (doc.querySelector(\"#xnxq01id\")) return [];\n        throw new Error(\"未获取到课表，请重新登录教务系统。\");\n    }\n    const grid = hzuGrid(table);\n    const days = new Map();\n    const dayNames = \"一二三四五六日\";\n    for (const row of grid) {\n        row.forEach((cell, column) => {\n            if (cell.tagName !== \"TH\") return;\n            const match = cell.textContent.trim().match(/^(?:星期|周)([一二三四五六日天])/);\n            if (match) days.set(column, match[1] === \"天\" ? 7 : dayNames.indexOf(match[1]) + 1);\n        });\n    }\n    if (days.size !== 7) throw new Error(\"无法识别课表的星期表头，已停止导入。\");\n\n    const seen = new Set();\n    const merged = new Map();\n    for (const row of grid) {\n        for (const [column, day] of days) {\n            const cell = row[column];\n            if (!cell || seen.has(cell) || cell.getAttribute(\"name\") !== \"kbDataTd\") continue;\n            seen.add(cell);\n            // 只读简表课程，跳过同一格内 tooltip 的重复详情。\n            for (const item of cell.querySelectorAll(\"ul.courselists > li.courselists-item\")) {\n                const name = item.querySelector(\".qz-hasCourse-title\")?.textContent.trim();\n                const info = item.querySelector(\".qz-hasCourse-abbrinfo\")?.textContent.trim() || \"\";\n                if (!name) throw new Error(\"课表中有无法识别的课程名称，已停止导入。\");\n                const time = hzuParseTime(hzuField(info, \"时间\"));\n                const teacher = hzuField(info, \"老师\");\n                const location = hzuField(info, \"地点\");\n                const position = /^[（(]\\s*[）)]$/.test(location) ? \"\" : location;\n                for (const range of time.ranges) {\n                    const key = JSON.stringify([name, teacher, position, day, range.startSection, range.endSection]);\n                    if (merged.has(key)) {\n                        const course = merged.get(key);\n                        course.weeks = Array.from(new Set(course.weeks.concat(time.weeks))).sort((a, b) => a - b);\n                    } else {\n                        merged.set(key, { name, teacher, position, day, ...range, weeks: time.weeks.slice() });\n                    }\n                }\n            }\n        }\n    }\n    return Array.from(merged.values());\n}\n\nfunction hzuCalendar(doc, semesterId) {\n    hzuCheckSemester(doc, semesterId);\n    const table = doc.querySelector(\"#dataTable\");\n    if (!table) throw new Error(\"未找到教学周历。\");\n    const anchors = [];\n    let totalWeeks = 0;\n    for (const row of table.rows) {\n        const match = row.cells[0]?.textContent.match(/第\\s*(\\d+)\\s*周/);\n        if (!match) continue;\n        const week = Number(match[1]);\n        if (week < 1 || week > 100) throw new Error(\"教学周历周次异常。\");\n        totalWeeks = Math.max(totalWeeks, week);\n        for (let day = 0; day < 7; day++) {\n            const cell = row.cells[day + 1];\n            const date = cell?.textContent.match(/(\\d{1,2})月(\\d{1,2})日/);\n            if (date) anchors.push({ offset: (week - 1) * 7 + day, month: Number(date[1]), day: Number(date[2]) });\n        }\n    }\n    if (!anchors.length || !totalWeeks) throw new Error(\"教学周历缺少日期。\");\n    anchors.sort((a, b) => a.offset - b.offset);\n    const term = semesterId.match(/^(\\d{4})-\\d{4}-([12])$/);\n    if (!term) throw new Error(\"无法识别校历学期。\");\n    const first = anchors[0];\n    const year = Number(term[1]) + (term[2] === \"2\" || first.month < 7 ? 1 : 0);\n    const dayMs = 86400000;\n    const startMs = Date.UTC(year, first.month - 1, first.day) - first.offset * dayMs;\n    if (new Date(startMs).getUTCDay() !== 1 || anchors.some(anchor => {\n        const date = new Date(startMs + anchor.offset * dayMs);\n        return date.getUTCMonth() + 1 !== anchor.month || date.getUTCDate() !== anchor.day;\n    })) throw new Error(\"教学周历日期不一致，无法确定开学日期。\");\n    return { semesterStartDate: new Date(startMs).toISOString().slice(0, 10), semesterTotalWeeks: totalWeeks };\n}\n\nasync function hzuRunImportFlow() {\n    const bridge = window.shiguangBridge;\n    const api = window.shiguangBridgePromise;\n    if (!bridge || !api) throw new Error(\"未检测到拾光桥接接口，请在软件或测试插件中运行。\");\n    const requiredMethods = [\"showAlert\", \"showSingleSelection\", \"saveCourseConfig\",\n        \"savePresetTimeSlots\", \"saveComboSchedule\", \"saveImportedCourses\"];\n    if (requiredMethods.some(method => typeof api[method] !== \"function\") ||\n        typeof bridge.showToast !== \"function\" || typeof bridge.notifyTaskCompletion !== \"function\") {\n        throw new Error(\"桥接接口不完整，请使用时光课程表 2.1.0 或新版测试插件后重试。\");\n    }\n    if (!await api.showAlert(\"菏泽学院课表导入\", \"请确认已登录教务系统。将读取所选学期的全部周课程。\", \"开始导入\")) return;\n\n    bridge.showToast(\"正在读取学期列表...\");\n    const firstDoc = await hzuFetchDocument(\"/xskb/xskb_list.do?viweType=0&zc=\");\n    const semesters = hzuSemesters(firstDoc);\n    if (!semesters.length) throw new Error(\"教务未提供可导入的学期。\");\n    const index = await api.showSingleSelection(\"选择学期\",\n        JSON.stringify(semesters.map(semester => semester.text)),\n        Math.max(0, semesters.findIndex(semester => semester.selected)));\n    if (index === null) return;\n    if (!Number.isInteger(index) || !semesters[index]) throw new Error(\"学期选择无效。\");\n    const semesterId = semesters[index].value;\n    const params = new URLSearchParams({ viweType: \"0\", zc: \"\", xnxq01id: semesterId });\n    const modeSelect = firstDoc.querySelector(\"#kbjcmsid\");\n    const mode = modeSelect && \"value\" in modeSelect ? modeSelect.value : null;\n    if (typeof mode === \"string\" && mode) params.set(\"kbjcmsid\", mode);\n    const doc = await hzuFetchDocument(\"/xskb/xskb_list.do?\" + params);\n    hzuCheckSemester(doc, semesterId);\n    const courses = hzuParseCourses(doc);\n    if (!courses.length) {\n        bridge.showToast(\"该学期暂无已排课课程，未修改原有课表。\");\n        return;\n    }\n\n    let config = null;\n    try {\n        config = hzuCalendar(await hzuFetchDocument(\"/jxzl/jxzl_query?xnxq01id=\" +\n            encodeURIComponent(semesterId)), semesterId);\n        if (courses.some(course => course.weeks.some(week => week > config.semesterTotalWeeks))) {\n            throw new Error(\"课程周次超出教学周历。\");\n        }\n    } catch (_) {\n        config = null;\n        if (!await api.showAlert(\"教学周历不可用\",\n            \"无法确定所选学期的开学日期与总周数。继续导入后，请在课表设置中核对学期配置。\", \"继续导入\")) return;\n    }\n\n    const comboSchedule = hzuComboSchedule(semesterId);\n\n    // 只在全部读取和确认完成后写入；保存失败不能发出完成信号。\n    if (config) {\n        config.firstDayOfWeek = 1;\n        config.defaultClassDuration = 50;\n        config.defaultBreakDuration = 10;\n        if (await api.saveCourseConfig(JSON.stringify(config)) !== true) throw new Error(\"学期配置保存失败。\");\n    }\n    if (await api.savePresetTimeSlots(JSON.stringify(HZU_WINTER_TIME_SLOTS)) !== true) {\n        throw new Error(\"作息时间保存失败。\");\n    }\n    // App 要求先保存基础节次，成功后再绑定组合作息，之后不能重存基础节次。\n    if (await api.saveComboSchedule(JSON.stringify(comboSchedule)) !== true) {\n        throw new Error(\"冬夏季作息保存失败。\");\n    }\n    if (await api.saveImportedCourses(JSON.stringify(courses)) !== true) throw new Error(\"课程保存失败。\");\n    bridge.showToast(\"成功导入 \" + courses.length + \" 条上课记录\");\n    bridge.notifyTaskCompletion();\n}\n\n// Start import.\nhzuRunImportFlow().catch(error => {\n    console.error(\"HZU import failed:\", error);\n    if (typeof window.shiguangBridge?.showToast === \"function\") {\n        window.shiguangBridge.showToast(\"导入失败：\" + (error?.message || String(error)));\n    }\n});\n","HYNU_01":"// 衡阳师范学院(hynu.edu.cn) 拾光课程表适配脚本\n// 非该大学开发者适配,开发者无法及时发现问题\n// 出现问题请提联系开发者或者提交pr更改,这更加快速\n\n// 验证逻辑\n\n/**\n * 年份输入验证函数\n * @param {string} input 用户输入的年份\n * @returns {boolean|string} 验证通过返回false，失败返回错误提示\n */\nwindow.validateYearInput = function(input) {\n    return /^[0-9]{4}$/.test(input) ? false : \"请输入四位数字的学年！\";\n};\n\n// 数据解析函数\n\n/**\n * 将周次字符串解析为数字数组\n */\nfunction parseWeeks(weekStr) {\n    const weeks = [];\n    if (!weekStr) return weeks;\n    \n    // 适配 \"1-9,11-17(周)[01-02节]\" 或 \"12-15(周)\"\n    const pureWeekData = weekStr.split('(')[0]; \n    \n    pureWeekData.split(',').forEach(seg => {\n        if (seg.includes('-')) {\n            const [s, e] = seg.split('-').map(Number);\n            if (!isNaN(s) && !isNaN(e)) {\n                for (let i = s; i <= e; i++) weeks.push(i);\n            }\n        } else {\n            const w = parseInt(seg);\n            if (!isNaN(w)) weeks.push(w);\n        }\n    });\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n/**\n * 转换课程 HTML 格式为应用模型\n */\nfunction parseTimetableToModel(doc) {\n    const timetable = doc.getElementById('timetable');\n    if (!timetable) return [];\n\n    const results = [];\n    const rows = Array.from(timetable.querySelectorAll('tr')).slice(1);\n\n    rows.forEach(row => {\n        const cells = row.querySelectorAll('td');\n        if (cells.length < 7) return;\n\n        // 遍历周一到周日\n        cells.forEach((cell, dayIndex) => {\n            const day = dayIndex + 1;\n            const detailDiv = cell.querySelector('div.kbcontent[style*=\"none\"]');\n            \n            if (detailDiv) {\n                const rawHtml = detailDiv.innerHTML.trim();\n                if (rawHtml === \"\" || rawHtml === \"&nbsp;\") return;\n\n                // 拆分可能存在的多个课程块\n                const courseBlocks = rawHtml.split(/---------------------|----------------------/);\n                \n                courseBlocks.forEach(block => {\n                    if (block.replace(/&nbsp;|<br\\/?>/g, '').trim() === \"\") return;\n\n                    const tempDiv = document.createElement('div');\n                    tempDiv.innerHTML = block;\n\n                    // 提取课程名\n                    let name = \"\";\n                    for (let node of tempDiv.childNodes) {\n                        if (node.nodeType === 3 && node.textContent.trim() !== \"\") {\n                            name = node.textContent.trim();\n                            break;\n                        } else if (node.tagName === \"BR\" && name !== \"\") {\n                            break;\n                        } else if (node.nodeType === 3) {\n                            name += node.textContent.trim();\n                        }\n                    }\n\n                    // 提取教师、周次(节次)、地点\n                    const teacher = tempDiv.querySelector('font[title=\"教师\"]')?.innerText || \"未知教师\";\n                    const weekStr = tempDiv.querySelector('font[title=\"周次(节次)\"]')?.innerText || \"\";\n                    const position = tempDiv.querySelector('font[title=\"教室\"]')?.innerText || \"未知地点\";\n\n                    let start = 0, end = 0;\n                    if (weekStr) {\n                        const secMatch = weekStr.match(/\\[(\\d+)(?:-(\\d+))?节\\]/);\n                        if (secMatch) {\n                            start = parseInt(secMatch[1]);\n                            end = secMatch[2] ? parseInt(secMatch[2]) : start;\n                        }\n                    }\n\n                    if (name && weekStr && start > 0) {\n                        results.push({\n                            \"name\": name,\n                            \"teacher\": teacher,\n                            \"weeks\": parseWeeks(weekStr),\n                            \"position\": position,\n                            \"day\": day,\n                            \"startSection\": start,\n                            \"endSection\": end\n                        });\n                    }\n                });\n            }\n        });\n    });\n\n    return results;\n}\n\n/**\n * 保存课表全局配置\n */\nasync function saveAppConfig() {\n    const config = {\n        \"semesterTotalWeeks\": 20,\n        \"firstDayOfWeek\": 1\n    };\n    return await window.shiguangBridgePromise.saveCourseConfig(JSON.stringify(config));\n}\n\n/**\n * 保存时间段配置\n */\nasync function saveAppTimeSlots() {\n    const timeSlots = [\n        { \"number\": 1, \"startTime\": \"08:30\", \"endTime\": \"09:15\" },\n        { \"number\": 2, \"startTime\": \"09:25\", \"endTime\": \"10:10\" },\n        { \"number\": 3, \"startTime\": \"10:30\", \"endTime\": \"11:15\" },\n        { \"number\": 4, \"startTime\": \"11:25\", \"endTime\": \"12:10\" },\n        { \"number\": 5, \"startTime\": \"14:30\", \"endTime\": \"15:15\" },\n        { \"number\": 6, \"startTime\": \"15:25\", \"endTime\": \"16:10\" },\n        { \"number\": 7, \"startTime\": \"16:30\", \"endTime\": \"17:15\" },\n        { \"number\": 8, \"startTime\": \"17:25\", \"endTime\": \"18:10\" },\n        { \"number\": 9, \"startTime\": \"19:30\", \"endTime\": \"20:15\" },\n        { \"number\": 10, \"startTime\": \"20:25\", \"endTime\": \"21:10\" },\n        { \"number\": 11, \"startTime\": \"21:20\", \"endTime\": \"22:05\" },\n        { \"number\": 12, \"startTime\": \"22:15\", \"endTime\": \"23:00\" }\n    ];\n    return await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n}\n\n/**\n * 获取并让用户选择学期 ID\n */\nasync function getSelectedSemesterId() {\n    const currentYear = new Date().getFullYear();\n    // 绑定验证函数 validateYearInput\n    const year = await window.shiguangBridgePromise.showPrompt(\n        \"选择学年\", \"请输入要导入课程的起始学年（例如 2025-2026 应输入2025）:\", String(currentYear), \"validateYearInput\"\n    );\n    if (!year) return null;\n    \n    const semesterIndex = await window.shiguangBridgePromise.showSingleSelection(\n        \"选择学期\", JSON.stringify([\"第一学期\", \"第二学期\"]), 0\n    );\n    if (semesterIndex === null) return null;\n    \n    return `${year}-${parseInt(year) + 1}-${semesterIndex + 1}`;\n}\n\n// 流程控制\n\nasync function runImportFlow() {\n    try {\n        const confirmed = await window.shiguangBridgePromise.showAlert(\n            \"公告\",\n            \"请确保您已在当前页面成功登录教务系统，否则无法获取数据。是否继续？\",\n            \"确认已登录\"\n        );\n        if (!confirmed) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        const semesterId = await getSelectedSemesterId();\n        if (!semesterId) {\n            window.shiguangBridge.showToast(\"导入已取消\");\n            return;\n        }\n\n        window.shiguangBridge.showToast(\"正在获取教务数据...\");\n        \n        const response = await fetch(\"https://hysfjw.hynu.edu.cn/jsxsd/xskb/xskb_list.do\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n            body: `cj0701id=&zc=&demo=&xnxq01id=${semesterId}`,\n            credentials: \"include\"\n        });\n        \n        const html = await response.text();\n        const finalCourses = parseTimetableToModel(new DOMParser().parseFromString(html, \"text/html\"));\n\n        if (finalCourses.length === 0) {\n            window.shiguangBridge.showToast(\"未发现任何课程数据,检查是否登录或者学期选择是否正确\");\n            return;\n        }\n\n        // 保存数据\n        window.shiguangBridge.showToast(\"正在保存配置...\");\n        await saveAppConfig();\n        await saveAppTimeSlots();\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(finalCourses));\n        \n        window.shiguangBridge.showToast(`成功导入 ${finalCourses.length} 门课程`);\n        window.shiguangBridge.notifyTaskCompletion();\n\n    } catch (error) {\n        window.shiguangBridge.showToast(\"异常: \" + error.message);\n    }\n}\n\n// 启动导入流程\nrunImportFlow();","HLJU":"function findHljuTimetableRequest(){\n    const resources=performance.getEntriesByType(\"resource\");\n    const matches=resources.map(item=>item.name).filter(url=>url.includes(\"TimeTableNewService/GetTimeTableByStudent\"));\n    return matches.length?matches[matches.length-1]:null;\n}\n\nasync function fetchHljuTimetable(){\n    const url=findHljuTimetableRequest();\n    if(!url){\n        throw new Error(\"没有找到课表请求，请先打开黑龙江大学课表并查询。\");\n    }\n    const response=await fetch(url,{\n        method:\"GET\",\n        credentials:\"include\",\n        headers:{\n            \"Accept\":\"application/json, text/javascript, */*; q=0.01\",\n            \"X-Requested-With\":\"XMLHttpRequest\"\n        }\n    });\n    if(!response.ok){\n        throw new Error(`课表请求失败 HTTP ${response.status}`);\n    }\n    const data=await response.json();\n    if(!Array.isArray(data)){\n        throw new Error(\"课表接口返回格式错误\");\n    }\n    return data;\n}\n\nfunction parseSections(text){\n    if(!text)return null;\n    const match=text.match(/(\\d+)\\s*(?:,|，|-|~|～|至)\\s*(\\d+)/);\n    if(!match)return null;\n    return {\n        start:Number(match[1]),\n        end:Number(match[2])\n    };\n}\n\nfunction parseWeeks(text){\n    if(!text)return [];\n    const weeks=new Set();\n    const regex=/(\\d+)\\s*[-~～至]\\s*(\\d+)/g;\n    let match;\n    while((match=regex.exec(text))!==null){\n        const start=Number(match[1]);\n        const end=Number(match[2]);\n        for(let i=start;i<=end;i++){\n            weeks.add(i);\n        }\n    }\n    return Array.from(weeks).sort((a,b)=>a-b);\n}\n\nfunction parseMultiTeacherWeeks(text){\n    const result=[];\n    if(!text)return result;\n    const regex=/(\\d+(?:[-~～]\\d+)?)\\(([^)]+)\\)/g;\n    let match;\n    while((match=regex.exec(text))!==null){\n        result.push({\n            teacher:match[2].trim(),\n            weeks:parseWeeks(match[1])\n        });\n    }\n    return result;\n}\n\nfunction getField(lines,name){\n    for(const line of lines){\n        const match=line.match(new RegExp(\"^\"+name+\"\\\\s*[:：](.*)$\"));\n        if(match)return match[1].trim();\n    }\n    return \"\";\n}\n\nfunction parseCourseBlock(block,weekday,sections){\n    const lines=block.split(/\\r?\\n/).map(x=>x.trim()).filter(x=>x);\n    if(lines.length<1)return [];\n\n    const name=lines[0];\n    const weekText=getField(lines,\"周次\");\n    const position=getField(lines,\"地点\");\n\n    const multi=parseMultiTeacherWeeks(weekText);\n    const courses=[];\n\n    if(multi.length){\n        for(const item of multi){\n            courses.push({\n                name:name,\n                teacher:item.teacher,\n                position:position,\n                day:weekday,\n                startSection:sections.start,\n                endSection:sections.end,\n                weeks:item.weeks,\n                isCustomTime:false\n            });\n        }\n        return courses;\n    }\n\n    const teacherLine=lines[1]||\"\";\n    const teacher=teacherLine.split(/\\s+/)[0].trim();\n    const weeks=parseWeeks(weekText);\n\n    if(!weeks.length)return [];\n\n    courses.push({\n        name:name,\n        teacher:teacher,\n        position:position,\n        day:weekday,\n        startSection:sections.start,\n        endSection:sections.end,\n        weeks:weeks,\n        isCustomTime:false\n    });\n\n    return courses;\n}\n\nfunction parseCourseCell(content,weekday,sections){\n    if(!content||typeof content!==\"string\")return [];\n    const text=content.replace(/\\r\\n/g,\"\\n\").replace(/\\r/g,\"\\n\").trim();\n    if(!text)return [];\n\n    const blocks=text.split(/\\n\\s*\\n+/).map(x=>x.trim()).filter(x=>x);\n\n    let result=[];\n\n    for(const block of blocks){\n        result.push(...parseCourseBlock(block,weekday,sections));\n    }\n\n    return result;\n}\nfunction parseHljuTimetable(data){\n    const weekdayFields=[\n        {field:\"Monday\",day:1},\n        {field:\"Tuesday\",day:2},\n        {field:\"Wednesday\",day:3},\n        {field:\"Thursday\",day:4},\n        {field:\"Friday\",day:5},\n        {field:\"Saturday\",day:6},\n        {field:\"Sunday\",day:7}\n    ];\n\n    const courses=[];\n\n    for(const row of data){\n        if(!row||typeof row!==\"object\")continue;\n\n        const sections=parseSections(row.JieCi);\n\n        if(!sections){\n            console.warn(\"无法解析节次:\",row.JieCi);\n            continue;\n        }\n\n        for(const weekday of weekdayFields){\n            const content=row[weekday.field];\n\n            if(!content)continue;\n\n            const result=parseCourseCell(\n                content,\n                weekday.day,\n                sections\n            );\n\n            courses.push(...result);\n        }\n    }\n\n    return courses;\n}\n\nfunction validateCourses(courses){\n    if(!Array.isArray(courses)){\n        throw new Error(\"课程解析结果错误\");\n    }\n\n    if(courses.length===0){\n        throw new Error(\"没有解析到任何课程\");\n    }\n\n    for(const course of courses){\n        if(!course.name){\n            throw new Error(\"存在课程名称为空\");\n        }\n\n        if(!Number.isInteger(course.day)){\n            throw new Error(\n                `课程 ${course.name} 星期解析错误`\n            );\n        }\n\n        if(!Number.isInteger(course.startSection)||\n           !Number.isInteger(course.endSection)){\n            throw new Error(\n                `课程 ${course.name} 节次解析错误`\n            );\n        }\n\n        if(!Array.isArray(course.weeks)||\n           course.weeks.length===0){\n            throw new Error(\n                `课程 ${course.name} 周次解析错误`\n            );\n        }\n    }\n}\n\nfunction printCourses(courses){\n    console.log(\n        \"========== 黑龙江大学课程解析结果 ==========\"\n    );\n\n    console.table(\n        courses.map(course=>({\n            课程:course.name,\n            教师:course.teacher,\n            地点:course.position,\n            星期:course.day,\n            节次:\n            `${course.startSection}-${course.endSection}`,\n            周次:\n            course.weeks.join(\",\")\n        }))\n    );\n\n    console.log(\n        \"完整课程数据:\",\n        courses\n    );\n\n    console.log(\n        \"==========================================\"\n    );\n}\n\nasync function saveHljuCourses(courses){\n    try{\n        await window.AndroidBridgePromise.saveImportedCourses(\n            JSON.stringify(courses)\n        );\n\n        AndroidBridge.showToast(\n            `成功导入 ${courses.length} 个课程时段`\n        );\n\n        return true;\n\n    }catch(error){\n\n        console.error(\n            \"保存课程失败:\",\n            error\n        );\n\n        AndroidBridge.showToast(\n            \"课程保存失败:\"+error.message\n        );\n\n        return false;\n    }\n}\n\nasync function runImportFlow(){\n    try{\n        AndroidBridge.showToast(\n            \"正在获取黑龙江大学课表...\"\n        );\n\n        const timetable=\n            await fetchHljuTimetable();\n\n        console.log(\n            \"黑龙江大学原始数据:\",\n            timetable\n        );\n\n        const courses=\n            parseHljuTimetable(\n                timetable\n            );\n\n        validateCourses(\n            courses\n        );\n\n        printCourses(\n            courses\n        );\n\n        const success=\n            await saveHljuCourses(\n                courses\n            );\n\n        if(!success){\n            return;\n        }\n\n        AndroidBridge.showToast(\n            \"黑龙江大学课表导入成功\"\n        );\n\n        AndroidBridge.notifyTaskCompletion();\n\n    }catch(error){\n\n        console.error(\n            \"========== 导入失败 ==========\",\n            error\n        );\n\n        AndroidBridge.showToast(\n            \"导入失败:\"+error.message\n        );\n    }\n}\n\nrunImportFlow();\n","HLJU_BACHELOR":"// 黑龙江大学本科选课系统（xsxk.hlju.edu.cn）拾光课表导入适配脚本\n// 课表接口：/xszykb/queryxszykbzong（JSON 数组）\n//   字段：SKSJ 课程文本、KEY(xqN_jcM 星期_大节)、KSJC/JSJC 起止节次、ZC 周次位图\n//   课程文本格式：课程名【001】\\n[教师]\\n[周次][地点]\\n第X-Y节（节次行可能缺失）\n// 作息：12 节（接口 /component/queryxqkjsj 获取）\n\n// 黑龙江大学作息时间（2026-2027 第一学期）\nconst HLJU_BACHELOR_TIME_SLOTS = [\n    { number: 1, startTime: \"08:00\", endTime: \"08:45\" },\n    { number: 2, startTime: \"08:50\", endTime: \"09:35\" },\n    { number: 3, startTime: \"10:00\", endTime: \"10:45\" },\n    { number: 4, startTime: \"10:50\", endTime: \"11:35\" },\n    { number: 5, startTime: \"13:30\", endTime: \"14:15\" },\n    { number: 6, startTime: \"14:20\", endTime: \"15:05\" },\n    { number: 7, startTime: \"15:30\", endTime: \"16:15\" },\n    { number: 8, startTime: \"16:20\", endTime: \"17:05\" },\n    { number: 9, startTime: \"18:30\", endTime: \"19:15\" },\n    { number: 10, startTime: \"19:20\", endTime: \"20:05\" },\n    { number: 11, startTime: \"20:10\", endTime: \"20:55\" },\n    { number: 12, startTime: \"21:00\", endTime: \"21:45\" }\n];\n\nfunction getErrorMessage(error) {\n    if (error && typeof error.message === \"string\" && error.message.trim()) return error.message;\n    if (typeof error === \"string\" && error.trim()) return error;\n    try {\n        const serialized = JSON.stringify(error);\n        if (serialized && serialized !== \"{}\") return serialized;\n    } catch (_) {\n        // Ignore serialization failures.\n    }\n    return \"未知错误\";\n}\n\n// 从 performance 资源中查找课表请求 URL（queryxszykbzong）\nfunction findScheduleRequest() {\n    const resources = performance.getEntriesByType(\"resource\");\n    const matches = resources.map(item => item.name).filter(url => url.indexOf(\"queryxszykbzong\") !== -1);\n    return matches.length ? matches[matches.length - 1] : null;\n}\n\n// 获取当前学期（xn=2026-2027&xq=1），从 queryxnxqdata 接口取 SFDQXQ=1 的学期\nasync function fetchCurrentSemester() {\n    const response = await fetch(\"/component/queryxnxqdata\", {\n        method: \"POST\",\n        credentials: \"include\",\n        headers: {\n            \"Accept\": \"application/json, text/javascript, */*; q=0.01\",\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        }\n    });\n    if (!response.ok) throw new Error(`学期接口请求失败（HTTP ${response.status}）`);\n    const data = await response.json();\n    const list = Array.isArray(data) ? data : (Array.isArray(data.content) ? data.content : []);\n    const current = list.find(item => String(item.SFDQXQ) === \"1\");\n    if (!current || !current.XN || !current.XQ) {\n        throw new Error(\"未获取到当前学期信息\");\n    }\n    return { xn: current.XN, xq: String(current.XQ) };\n}\n\nasync function fetchSchedule() {\n    const semester = await fetchCurrentSemester();\n    const url = findScheduleRequest() || \"/xszykb/queryxszykbzong\";\n    const response = await fetch(url, {\n        method: \"POST\",\n        credentials: \"include\",\n        headers: {\n            \"Accept\": \"application/json, text/javascript, */*; q=0.01\",\n            \"Content-Type\": \"application/x-www-form-urlencoded; charset=UTF-8\",\n            \"X-Requested-With\": \"XMLHttpRequest\"\n        },\n        body: `xn=${encodeURIComponent(semester.xn)}&xq=${encodeURIComponent(semester.xq)}`\n    });\n    if (!response.ok) throw new Error(`课表接口请求失败（HTTP ${response.status}）`);\n    const data = await response.json();\n    if (!data || typeof data !== \"object\") throw new Error(\"课表接口返回格式异常\");\n    const list = Array.isArray(data) ? data : (Array.isArray(data.content) ? data.content : null);\n    if (!list) throw new Error(\"课表接口返回格式异常\");\n    return list;\n}\n\n// 解析周次文本：支持带/不带方括号\n//   \"1-17周\" 或 \"[1-17周]\" → 1..17\n//   \"1,4-8双,9,12-16双周\" → 1,4,6,8,9,12,14,16\nfunction parseWeeksText(weekStr) {\n    const text = String(weekStr || \"\").replace(/\\s+/g, \"\").replace(/^\\[|\\]$/g, \"\");\n    if (!text) return [];\n    const body = text.replace(/周/g, \"\");\n    const weeks = [];\n    const parts = body.split(\",\");\n    for (const part of parts) {\n        const pm = part.match(/^(\\d+)(?:-(\\d+))?(单|双)?$/);\n        if (!pm) continue;\n        const start = Number(pm[1]);\n        const end = pm[2] ? Number(pm[2]) : start;\n        const parity = pm[3]; // \"单\" / \"双\" / undefined\n        for (let w = start; w <= end; w++) {\n            if (parity === \"单\" && w % 2 === 0) continue;\n            if (parity === \"双\" && w % 2 === 1) continue;\n            weeks.push(w);\n        }\n    }\n    return [...new Set(weeks)].sort((a, b) => a - b);\n}\n\n// 解析课程文本：课程名【001】\\n[教师]\\n[周次][地点]\\n第X-Y节（节次行可能缺失）\nfunction parseCourseText(sksj) {\n    const lines = String(sksj || \"\").split(/\\r?\\n/).map(l => l.trim()).filter(l => l);\n    if (lines.length < 2) return null;\n\n    // 考试记录（以【...考试】开头）跳过\n    if (lines[0].indexOf(\"考试】\") !== -1) return null;\n\n    const name = lines[0];\n\n    // 教师：第二行固定为 [教师名]\n    let teacher = \"\";\n    if (/^\\[[^\\]]+\\]$/.test(lines[1])) {\n        teacher = lines[1].slice(1, -1);\n    }\n\n    // 周次与地点：从第 3 行起，含\"周\"的 [..] 为周次，其后 [..] 为地点\n    // 地点可能含嵌套方括号（如 [4号楼-[617]计算机5机房分室2]），用平衡括号匹配\n    let weekStr = \"\";\n    let position = \"\";\n    for (let i = 2; i < lines.length; i++) {\n        const line = lines[i];\n        const m = line.match(/\\[([^\\]]*周[^\\]]*)\\]/);\n        if (m) {\n            if (!weekStr) weekStr = m[1];\n            const rest = line.slice(line.indexOf(m[0]) + m[0].length).trim();\n            if (rest.startsWith(\"[\") && !position) {\n                position = rest.slice(1, -1);\n            }\n            continue;\n        }\n        const posM = line.match(/^\\[(.+)\\]$/);\n        if (posM && !position && posM[1].indexOf(\"周\") === -1) {\n            position = posM[1];\n        }\n    }\n\n    const weeks = parseWeeksText(weekStr);\n    if (weeks.length === 0) return null;\n\n    return { name, teacher: teacher || \"未知\", position: position || \"待定\", weeks };\n}\n\nfunction parseSchedule(data) {\n    const courses = [];\n\n    for (const row of data) {\n        if (!row || typeof row !== \"object\") continue;\n\n        const key = String(row.KEY || \"\");\n        // 劳动教育等无位置排布的记录（KEY=bz 或无节次）跳过\n        if (key === \"bz\" || !key) continue;\n\n        const dayMatch = key.match(/xq(\\d+)/);\n        if (!dayMatch) continue;\n        const day = Number(dayMatch[1]);\n        if (!(day >= 1 && day <= 7)) continue;\n\n        // 起止节次：KSJC/JSJC 字段优先\n        const startSection = Number(row.KSJC);\n        const endSection = Number(row.JSJC);\n        if (!startSection || !endSection || startSection > endSection) continue;\n\n        const parsed = parseCourseText(row.SKSJ);\n        if (!parsed) continue;\n\n        courses.push({\n            name: parsed.name,\n            teacher: parsed.teacher,\n            position: parsed.position,\n            day,\n            startSection,\n            endSection,\n            weeks: parsed.weeks\n        });\n    }\n\n    return courses;\n}\n\n// 合并同课程同时间同教室的条目\nfunction mergeCourses(courses) {\n    const merged = new Map();\n    for (const c of courses) {\n        const key = `${c.name}|${c.teacher}|${c.position}|${c.day}|${c.startSection}|${c.endSection}`;\n        const holder = merged.get(key);\n        if (holder) {\n            holder.weeks = Array.from(new Set([...holder.weeks, ...c.weeks])).sort((a, b) => a - b);\n        } else {\n            merged.set(key, { ...c, weeks: [...c.weeks].sort((a, b) => a - b) });\n        }\n    }\n    return Array.from(merged.values()).sort(\n        (a, b) => a.day - b.day || a.startSection - b.startSection || a.name.localeCompare(b.name)\n    );\n}\n\n// 保存作息时间\nasync function saveTimeSlots(timeSlots) {\n    try {\n        await window.shiguangBridgePromise.savePresetTimeSlots(JSON.stringify(timeSlots));\n    } catch (error) {\n        console.error(\"JS: 作息时间保存失败\", error);\n    }\n}\n\nasync function runImportFlow() {\n    const alertConfirmed = await window.shiguangBridgePromise.showAlert(\n        \"课表导入\",\n        \"导入前请确保已登录选课系统并打开课表查询页面。\",\n        \"好的，开始导入\"\n    );\n    if (!alertConfirmed) {\n        window.shiguangBridge.showToast(\"用户取消了导入。\");\n        return;\n    }\n\n    window.shiguangBridge.showToast(\"正在获取课表数据...\");\n    try {\n        const data = await fetchSchedule();\n        const courses = parseSchedule(data);\n        if (courses.length === 0) throw new Error(\"课表中未解析到有效课程，请确认当前学期有课。\");\n\n        const merged = mergeCourses(courses);\n\n        window.shiguangBridge.showToast(`正在保存 ${merged.length} 门课程...`);\n        await window.shiguangBridgePromise.saveImportedCourses(JSON.stringify(merged, null, 2));\n        await saveTimeSlots(HLJU_BACHELOR_TIME_SLOTS);\n\n        window.shiguangBridge.showToast(`课程导入成功，共导入 ${merged.length} 门课程！`);\n        window.shiguangBridge.notifyTaskCompletion();\n    } catch (error) {\n        window.shiguangBridge.showToast(`导入失败：${getErrorMessage(error)}`);\n        console.error(\"JS: Import Error\", error);\n    }\n}\n\nrunImportFlow();\n"};
